const e={id:"s08",unidad:1,semana:8,kind:"aprendizaje",temaGenerador:"Datos confiables para ahorrar energía",title:"Datos confiables para ahorrar energía",subtitle:"Medimos, aproximamos y publicamos sin ocultar la fuente ni los límites de los datos",icon:"ChartNoAxesCombined",color:"var(--area-cnt)",contexto:"Esta semana trabajas con el paquete “Caso escolar simulado; no describe tu escuela”. Aprenderás a conservar el dato exacto al aproximar, distinguir evidencia de afirmaciones sin respaldo, explicar transformaciones de energía y publicar información legible. El cierre reúne Matemáticas, L1, Ciencias Naturales y Expresión Artística en un panel de papel con datos honestos y recomendaciones prácticas.",ejes:["tecnologia","sostenible","vida-ciudadana","multiculturalidad","equidad"],media:{id:"s08-portada",kind:"video",title:"Del dato al panel",aspect:"16:9",duration:55,alt:"Una estudiante lee una ficha simulada de consumo, conserva el valor exacto, calcula una aproximación y ordena un panel de ahorro energético.",brief:"Video animado 2D de 55 s, 1920×1080. Mostrar una ficha grande rotulada “Caso escolar simulado; no describe tu escuela”, el valor 12,468 kWh, su aproximación 12,000 kWh, una gráfica de barras y tres recomendaciones con razón científica. Usar texto de alto contraste, narración en español de Guatemala, subtítulos completos y pausa final de 3 s. No presentar edificios, recibos ni personas como pertenecientes a una escuela real. Target: public/media/s08-portada.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},badge:{id:"medalla-s08",name:"Datos con respaldo",icon:"BadgeCheck",desc:"Completaste la semana 8 y superaste su reto"},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:4.1.6"],prompt:"Construye el numeral maya de **642**.",type:"maya-number",props:{mode:"build",target:642,levels:3},id:"s08-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:8.2.7"],prompt:"¿Qué nota sirve mejor para un informe breve?",type:"choice",props:{options:[{id:"a",text:"LED: usa menos electricidad para producir luz; fuente: ficha técnica suministrada"},{id:"b",text:"Los LED son buenos, según alguien"},{id:"c",text:"Copiar toda la ficha sin fuente"}],correct:["a"]},id:"s08-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:8.2.1"],prompt:"Dos grupos siguen el mismo protocolo y obtienen valores cercanos, no idénticos. ¿Qué conclusión es adecuada?",type:"choice",props:{options:[{id:"a",text:"Los resultados compatibles apoyan revisar y repetir el procedimiento"},{id:"b",text:"Solo sirven si son idénticos"},{id:"c",text:"La evidencia demuestra cualquier explicación"}],correct:["a"]},id:"s08-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:8.4.1"],prompt:"Aplica la jerarquía de normas fiscales: una guía técnica cambia la tasa fijada por decreto. ¿Qué decisión corresponde?",type:"choice",props:{options:[{id:"a",text:"Mantener la tasa de la norma superior y corregir la guía técnica"},{id:"b",text:"Dar prioridad automática a la guía"},{id:"c",text:"Tratar ambas como consejos voluntarios"}],correct:["a"]},id:"s08-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:5.1.2"],prompt:"En “la claridad del informe”, ¿qué clase de sustantivo es **claridad**?",type:"choice",props:{options:[{id:"a",text:"Abstracto"},{id:"b",text:"Concreto"},{id:"c",text:"Propio"}],correct:["a"]},id:"s08-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:5.2.2"],prompt:"Completa una nueva mini-biografía.",type:"fill-blank",props:{text:"Maya [[studied]] science and later wrote two books.",distractors:["study","studies"]},id:"s08-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:5.2.1"],prompt:"Usa dos tarjetas nuevas del paquete atribuido a la CEH para localizar pueblos y departamentos, sin inferir gravedad.",type:"match",props:{leftTitle:"Pueblo",rightTitle:"Departamento indicado",pairs:[{id:"a",left:"Chuj",right:"Huehuetenango"},{id:"b",left:"Poqomchí",right:"Alta Verapaz"}]},id:"s08-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:4.3.2"],prompt:"Publica y comparte otra ficha biográfica en el diario. Paquete nuevo: **Tomás Ajú, grabador ficticio; obra: Senderos, 2021; fuente: Archivo didáctico simulado de arte**. Redacta una tarjeta breve con obra, aporte y fuente visible.",type:"short-answer",props:{minWords:24,placeholder:"Tarjeta biográfica visible…",model:"Tarjeta biográfica visible: Tomás Ajú, grabador ficticio, creó Senderos en 2021. La serie representa caminos comunitarios mediante líneas y texturas. Fuente visible: Archivo didáctico simulado de arte.",rubric:["Publico la tarjeta biográfica","Registro obra y año","Explico un aporte prudente","Mantengo visible la fuente"]},id:"s08-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:4.2.3"],prompt:"Simulación individual nueva: dirige una rutina respiratoria, da una instrucción, abre por igual los roles a mujeres y hombres, adapta el movimiento, rota responsabilidades y verifica la respuesta del equipo-avatar.",type:"leadership-simulation",props:{scenario:"Una mujer y un hombre avatares practican respiración con elevación suave de brazos y deben alternar dirección y observación.",instructions:[{id:"bi1",text:"Inhalen una vez, eleven brazos sin dolor y pausen con mi señal",correct:!0},{id:"bi2",text:"Sigan sin explicación ni pausa",correct:!1}],rolePlans:[{id:"br1",text:"Ambos acceden a dirigir y observar, y luego intercambian roles",correct:!0},{id:"br2",text:"Solo la mujer observa y solo el hombre dirige",correct:!1}],adaptations:[{id:"ba1",text:"Permitir brazos bajos o práctica sentada y detener ante mareo",correct:!0},{id:"ba2",text:"Mantener brazos altos aunque incomode",correct:!1}],sequences:[{id:"bs1",text:"Explicar, demostrar, practicar, intercambiar roles y verificar",correct:!0},{id:"bs2",text:"Practicar, omitir rotación y salir",correct:!1}],response:"El equipo-avatar completa la rutina, intercambia roles y confirma acceso igual y adaptación segura."},id:"s08-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:5.5.2"],prompt:"Banco revisable: describe otra práctica que **realmente conoces desde tu familia, comunidad o cultura**, identifica el recurso natural y realiza ahora una adaptación voluntaria con el modo de baja actividad. Registra antes, acción y después. Si necesitas consulta, identifica a quién o qué fuente y por qué; esa ruta no acredita dominio.",type:"cultural-conservation-practice",props:{minWords:30,consultationMinWords:8,requiresLiveAction:!0,rubric:["Práctica propia identificada","Recurso natural explicado","Acción local realizada","Registro antes, acción y después"],example:{culturalPractice:"En mi familia conozco aprovechar ventilación natural antes de encender un aparato.",naturalResource:"La práctica cuida recursos naturales asociados con producir electricidad.",beforeAction:"Antes comprobé el estado de sonido y movimiento.",actionReport:"Realicé ahora la adaptación de baja actividad.",afterAction:"Después verifiqué los dos ajustes y decidí conservarlos."}},id:"s08-banco-10"}]},a=JSON.parse(`[{"missionId":"s08","version":"cnb-sexto-3612c04cd4a9725f","lesson":{"id":"s08-ccss-2","title":"Impuestos: una responsabilidad de todos","icon":"Landmark","minutes":15,"gancho":"Cuando compras un cuaderno de Q10, una parte de ese dinero no es para la librería. ¿Para quién es? ¿Y quién decidió que así fuera?","objetivos":["Clasificar y aplicar normas fiscales y responsabilidades ciudadanas en casos suministrados"],"resumen":["Los impuestos son pagos obligatorios que la población y las empresas hacen al Estado para financiar servicios públicos: escuelas, hospitales, carreteras, seguridad.","Las normas jurídicas tienen un orden: la Constitución Política (la ley suprema) establece el deber de contribuir a los gastos públicos y que solo el Congreso puede crear impuestos; las leyes (como la del IVA y la del ISR) y el Código Tributario los desarrollan; los reglamentos explican cómo aplicarlas. Las municipalidades cobran impuestos como el IUSI.","El IVA es el 12 % del valor de lo que se compra y casi siempre ya viene incluido en el precio. El ISR se paga sobre los ingresos. La SAT es la institución que recauda los impuestos.","Pedir factura, no evadir impuestos y cuidar los bienes públicos son responsabilidades ciudadanas; también lo es vigilar que el dinero público se use bien. Los tratados comerciales también fijan reglas sobre los impuestos a las importaciones."],"media":{"id":"s08-ccss-2-ruta","kind":"animation","title":"El viaje de un quetzal de impuestos","aspect":"16:9","duration":45,"alt":"Animación que sigue una moneda desde la compra de un cuaderno con factura hasta el presupuesto del Estado y de ahí a una escuela, un centro de salud y una carretera.","brief":"Animación 2D de 45 s. Una niña compra un cuaderno y recibe su factura. Una moneda con la etiqueta \\"IVA\\" sale de la caja registradora, viaja por una flecha hasta un edificio rotulado \\"SAT\\", luego a un cofre \\"Presupuesto del Estado aprobado por el Congreso\\", y de ahí se reparte en tres flechas hacia una escuela con pupitres nuevos, un centro de salud con medicinas y una carretera en construcción. Al final aparece la frase \\"Tus impuestos regresan en servicios. Pide tu factura\\". Narración en español con subtítulos. Sin logos oficiales reales. Target: public/media/s08-ccss-2-ruta.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Impuestos y responsabilidad","prompt":"Lee el principio que organiza esta lección.","type":"explain","props":{"icon":"Receipt","body":"Los impuestos financian servicios públicos. La Constitución, las leyes y los reglamentos establecen quién puede crearlos y cómo se aplican."},"id":"s08-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","prompt":"La escuela pública, el centro de salud y la carretera de tu municipio cuestan mucho dinero. ¿De dónde sale principalmente ese dinero?","explain":"Sale principalmente de los **impuestos** que pagamos todas las personas y empresas. El Estado no \\"tiene\\" dinero propio: administra lo que la población aporta.","type":"choice","props":{"options":[{"id":"a","text":"De los impuestos que pagan las personas y las empresas","icon":"Coins"},{"id":"b","text":"El gobierno lo imprime cuando quiere","icon":"Banknote","feedback":"Imprimir dinero sin respaldo hace que los precios suban. Los servicios públicos se pagan principalmente con impuestos."},{"id":"c","text":"Lo regalan otros países cada año","icon":"Gift","feedback":"A veces hay donaciones, pero la mayor parte sale de los impuestos de la población."}],"correct":["a"]},"id":"s08-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"¿Qué son los impuestos?","prompt":"Los **impuestos** (o tributos) son pagos **obligatorios** que se hacen al Estado, establecidos por la ley. Toca cada tarjeta.","type":"explain","props":{"icon":"Landmark","body":"La **SAT** (Superintendencia de Administración Tributaria) recauda los impuestos nacionales. El **Congreso** aprueba cada año el **presupuesto**, que dice en qué se gastará ese dinero.","reveal":[{"icon":"ShoppingCart","front":"IVA","back":"**Impuesto al Valor Agregado**: el **12 %** de lo que se compra o de un servicio. Lo pagamos todos, aunque seamos niños, y **casi siempre ya viene incluido** en el precio."},{"icon":"Wallet","front":"ISR","back":"**Impuesto Sobre la Renta**: se paga sobre los **ingresos** de personas y empresas."},{"icon":"Home","front":"IUSI","back":"**Impuesto Único Sobre Inmuebles**: lo pagan los dueños de terrenos y casas, y lo cobra la **municipalidad**."},{"icon":"FileText","front":"La factura","back":"Es el comprobante de una compra. Pedirla ayuda a que el IVA que pagaste **llegue al Estado** y no se quede en manos de quien vende."}]},"id":"s08-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Las normas jurídicas tienen un orden","prompt":"Las **normas jurídicas** son las reglas obligatorias de un país. No todas tienen el mismo nivel: se ordenan como una **pirámide**. Toca cada tarjeta, de arriba hacia abajo.","media":{"id":"s08-ccss-2-piramide","kind":"diagram","title":"La pirámide de las normas fiscales","aspect":"3:4","alt":"Pirámide de tres niveles: arriba la Constitución, en medio las leyes del Congreso y el Código Tributario, abajo los reglamentos; a un lado, las normas municipales.","brief":"Diagrama de pirámide con tres niveles de colores. Punta: \\"Constitución Política de la República (1985)\\" con la nota \\"deber de contribuir a los gastos públicos; solo el Congreso crea impuestos\\". Centro: \\"Leyes del Congreso (decretos)\\": Ley del IVA, Ley del ISR, Código Tributario. Base: \\"Reglamentos del Organismo Ejecutivo: explican cómo aplicar las leyes\\". A un lado, un recuadro \\"Municipalidades: IUSI y arbitrios, según la ley\\" y otro \\"Tratados internacionales aprobados por el Congreso (p. ej., impuestos a las importaciones)\\". Flecha lateral: \\"ninguna norma puede contradecir a la de arriba\\". Texto grande, íconos simples. Target: public/media/s08-ccss-2-piramide.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"Layers","body":"Regla de oro: **ninguna norma puede contradecir a otra de nivel más alto**. Si una ley contradice la Constitución, la **Corte de Constitucionalidad** puede anularla.","reveal":[{"icon":"ScrollText","front":"Constitución Política","back":"La **ley suprema**. Establece que es **deber** de los guatemaltecos **contribuir a los gastos públicos** según la ley, y que **solo el Congreso** puede crear impuestos (principio de legalidad)."},{"icon":"Gavel","front":"Leyes ordinarias","back":"Las aprueba el **Congreso** como decretos. Ejemplos: la **Ley del IVA**, la del **ISR** y el **Código Tributario**, que da las reglas generales para pagar y cobrar tributos."},{"icon":"FileText","front":"Reglamentos","back":"Los emite el **Organismo Ejecutivo** para explicar **cómo** aplicar una ley. No pueden crear impuestos nuevos."},{"icon":"Building","front":"Normas municipales","back":"Las municipalidades cobran impuestos como el **IUSI** y tasas por servicios (agua, mercado, basura), siempre según lo que permite la ley."},{"icon":"Handshake","front":"Tratados internacionales","back":"Guatemala también firma **tratados** con otros países. Cuando el **Congreso** los aprueba, se vuelven obligatorios en el país. Los **tratados comerciales** (recuerda la semana 3) fijan, por ejemplo, cuánto impuesto pagan los productos que se importan."}]},"id":"s08-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Clasifica cada norma o afirmación según su **nivel** en la pirámide.","hint":"Lo más general y superior está en la Constitución; los impuestos concretos, en leyes del Congreso; los detalles de cómo aplicarlas, en reglamentos.","explain":"La Constitución manda el deber de contribuir; las leyes crean cada impuesto; los reglamentos dicen cómo cumplirlas.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución","icon":"ScrollText","color":"var(--area-ccss)"},{"id":"ley","label":"Ley del Congreso","icon":"Gavel","color":"var(--c-maiz-strong)"},{"id":"reg","label":"Reglamento","icon":"FileText","color":"var(--c-ok)"}],"items":[{"id":"n1","text":"Es deber de los guatemaltecos contribuir a los gastos públicos","bucket":"con"},{"id":"n2","text":"Ley del IVA: el impuesto es del 12 %","bucket":"ley"},{"id":"n3","text":"Detalle de cómo llenar un formulario para declarar un impuesto","bucket":"reg"},{"id":"n4","text":"Solo el Congreso puede crear impuestos","bucket":"con"},{"id":"n5","text":"Código Tributario: reglas generales para pagar tributos","bucket":"ley"}]},"id":"s08-ccss-2-5"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.4.1"],"ambito":"hacer","title":"Ejemplo resuelto: ¿cuánto IVA pago?","prompt":"El IVA es el 12 % del valor del producto. Mira dos casos con precios supuestos.","type":"worked-example","props":{"icon":"Calculator","problem":"Caso 1: una mochila vale **Q50 sin IVA**. ¿Cuánto IVA se paga y cuál es el precio final? Caso 2: en una tienda pagas **Q112** por unos zapatos, **con el IVA ya incluido**. ¿Cuánto de eso es IVA?","steps":[{"text":"Caso 1: 12 % de 50 = 50 × 12 ÷ 100 = 600 ÷ 100 = **Q6** de IVA.","why":"\\"Por ciento\\" significa \\"de cada 100\\": 12 de cada 100 quetzales."},{"text":"Precio final: 50 + 6 = **Q56**."},{"text":"Caso 2: si el precio sin IVA fuera Q100, el IVA sería Q12 y el total Q112. Entonces, de Q112, **Q12 son IVA**.","why":"Cuando el IVA está incluido, el precio es el 112 % del valor sin impuesto."}],"answer":"Caso 1: **Q6** de IVA y precio final **Q56**. Caso 2: **Q12** de los Q112 son IVA.","tip":"En las tiendas de Guatemala el precio que ves casi siempre ya incluye el IVA. Por eso, pide factura."},"id":"s08-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"hacer","prompt":"Aplica la jerarquía fiscal: clasifica cada decisión del caso suministrado según la norma o responsabilidad que corresponde.","explain":"La Constitución reserva al Congreso la creación de impuestos; la ley crea el tributo; el reglamento detalla su aplicación; pedir factura es responsabilidad ciudadana.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución"},{"id":"ley","label":"Ley"},{"id":"reg","label":"Reglamento"},{"id":"res","label":"Responsabilidad ciudadana"}],"items":[{"id":"a1","text":"Solo el Congreso puede crear un impuesto nacional","bucket":"con"},{"id":"a2","text":"El decreto establece el IVA","bucket":"ley"},{"id":"a3","text":"Una disposición explica cómo presentar el formulario","bucket":"reg"},{"id":"a4","text":"La persona compradora pide factura","bucket":"res"}]},"id":"s08-ccss-2-7"},{"fase":"aplicar","areas":["ccss","fc"],"cnb":["ccss:8.4.1"],"ambito":"ser","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Store","text":"Compras útiles escolares por Q84. El vendedor te dice: \\"Si no te doy factura, te lo dejo en Q80\\"."},"options":[{"id":"a","icon":"FileText","text":"Pido la factura y pago el precio completo","consequence":"El IVA que pagaste llega al Estado y se convierte en servicios públicos. Cumpliste con tu responsabilidad ciudadana.","values":["responsabilidad","honestidad"],"constructive":true},{"id":"b","icon":"MessageCircle","text":"Pido la factura y le explico a mi familia por qué es importante","consequence":"Además de cumplir, ayudas a que otros entiendan que la factura protege el dinero de todos.","values":["responsabilidad","solidaridad"],"constructive":true},{"id":"c","icon":"Coins","text":"Acepto el descuento sin factura","consequence":"Ahorras Q4, pero el vendedor no reporta la venta y ese impuesto no llega a escuelas ni hospitales. Es una forma de evasión.","values":[],"constructive":false}]},"id":"s08-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Aplica la Constitución, la ley o el reglamento y decide la responsabilidad fiscal: un reglamento intenta crear un impuesto nuevo sin ley del Congreso. ¿Qué corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Señalo que contradice el principio constitucional: un reglamento no crea impuestos"},{"id":"b","text":"Lo acepto porque cualquier reglamento está sobre la Constitución"},{"id":"c","text":"Lo trato como una decisión privada sin efecto legal"}],"correct":["a"]},"id":"s08-ccss-2-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Aplica la Constitución, la ley o el reglamento y decide la responsabilidad fiscal: una venta incluye IVA pero ofrece omitir la factura. ¿Qué corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Pedir la factura y conservar el comprobante"},{"id":"b","text":"Aceptar porque pagar menos reemplaza la norma"},{"id":"c","text":"Inventar un reglamento personal"}],"correct":["a"]},"id":"s08-ccss-2-10"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s08","version":"cnb-sexto-4ca64ff3489d3e03","lesson":{"id":"s08-pyd-1","title":"Una práctica local de baja actividad","icon":"Gauge","minutes":13,"gancho":"¿Qué ajuste voluntario puedes aplicar ahora mismo para reducir actividad opcional del dispositivo?","objetivos":["Relacionar una práctica voluntaria de conservación conocida en la familia, comunidad o cultura con el recurso natural que protege, y ejecutar su adaptación en el modo de baja actividad"],"resumen":["El modo de baja actividad desactiva el sonido opcional y activa movimiento reducido; ambos cambios quedan guardados en este dispositivo.","Es una práctica voluntaria, local, accesible y reversible que reduce actividad opcional de la app; no garantiza ni cuantifica ahorro de energía.","Las prácticas de conservación varían entre familias, comunidades y culturas. Para evidenciar el indicador se describe solo una práctica que realmente se conoce; el ejemplo didáctico suministrado enseña, pero no acredita dominio.","Una práctica explica qué recurso natural cuida y qué principio aplica. El modo de baja actividad es una adaptación contemporánea modesta de evitar actividad innecesaria.","Verificar el estado después de actuar distingue una práctica ejecutada de una intención o un autorreporte.","Si el modo ya está activo al entrar, mantenerlo voluntariamente durante 25 segundos y comprobar su estado constituye la práctica alternativa.","Restaurar devuelve exactamente el estado previo de esos dos ajustes sin cambiar los demás."],"media":{"id":"s08-pyd-1-modo-baja-actividad","kind":"diagram","title":"Antes, después y restauración","aspect":"16:9","alt":"Tres estados de ajustes: antes con sonido opcional activo y movimiento reducido inactivo; después con sonido apagado y movimiento reducido activo; restauración con los valores iniciales.","brief":"Diagrama de interfaz en tres columnas conectadas por flechas: “Antes”, “Modo de baja actividad” y “Restaurado”. Mostrar controles accesibles de sonido opcional y movimiento reducido con iconos Lucide Volume2, VolumeX, Accessibility y RotateCcw, además de texto Activado/Desactivado para no depender del color. Incluir la nota “Práctica modesta; no cuantifica ahorro”. Target: public/media/s08-pyd-1-modo-baja-actividad.svg. Producción: SVG con viewBox 0 0 1600 900 y versión PNG de respaldo 1600×900 px. Accesibilidad: contraste AA, orden de lectura izquierda a derecha y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"conocer","title":"Conservar sin inventar tradiciones","prompt":"Lee el marco respetuoso para vincular cultura, recurso natural y acción.","type":"explain","props":{"icon":"Leaf","body":"Una práctica de conservación puede ser conocida en tu **familia, comunidad o cultura**, pero no todas las personas comparten las mismas. Nombra una que realmente conozcas o usa esta alternativa: **“Ejemplo didáctico suministrado: aprovechar la luz natural y apagar una lámpara que no se necesita”**. Este ejemplo evita uso innecesario de recursos naturales e insumos empleados para generar electricidad; no afirmes que es tradición de tu familia o comunidad."},"id":"s08-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Del principio a una adaptación contemporánea","prompt":"Aprende el procedimiento antes de ejecutar la práctica.","type":"explain","props":{"icon":"ListChecks","body":"**Identifica** una práctica real o el ejemplo suministrado, **explica** qué recurso natural protege, **conecta** su principio de evitar actividad innecesaria con el modo de baja actividad y después **ejecuta y verifica** la ruta que muestre la app."},"id":"s08-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Modelo con ejemplo suministrado","prompt":"Observa cómo Ana usa el ejemplo sin atribuírselo a su cultura.","type":"worked-example","props":{"icon":"Gauge","problem":"Ana elige el ejemplo didáctico suministrado sobre aprovechar luz natural.","steps":[{"text":"Lo rotula como **ejemplo suministrado**, no como costumbre de su familia."},{"text":"Explica que cuida recursos naturales e insumos usados para generar electricidad al evitar actividad innecesaria."},{"text":"Lo adapta de forma contemporánea: activa el **modo de baja actividad** y verifica sus dos ajustes."},{"text":"Decide conservarlo o restaurarlo sin prometer ni calcular una cantidad de ahorro."}],"answer":"La evidencia une procedencia honesta, recurso protegido, principio de conservación y acción comprobada.","tip":"Identificar → explicar recurso → adaptar → ejecutar y verificar."},"id":"s08-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Selecciona las **dos rutas honestas** antes de crear tu evidencia cultural de conservación.","hint":"Una ruta demuestra práctica propia, recurso y acción segura; la otra reconoce qué consulta falta sin fingir dominio.","explain":"La evidencia elegible parte de una práctica genuinamente conocida, nombra el recurso natural y realiza una acción voluntaria segura. Si falta ese conocimiento, la ruta correcta es identificar a quién o qué fuente consultar y por qué; permite continuar, pero no acredita dominio.","type":"choice","props":{"multiple":true,"options":[{"id":"known","text":"Conozco una práctica de mi familia, nombro el recurso natural y realizo ahora una acción voluntaria segura"},{"id":"consult","text":"Aún no conozco una práctica propia: indico a quién o qué fuente consultaré y por qué","icon":"MessagesSquare"},{"id":"borrowed","text":"Copio el ejemplo suministrado y afirmo que es tradición de mi comunidad","feedback":"Un ejemplo didáctico enseña, pero no demuestra procedencia cultural propia."},{"id":"unsafe","text":"Conozco una práctica, pero ejecuto una acción riesgosa para demostrarla","feedback":"La acción debe ser voluntaria, segura, accesible y verificable."}],"correct":["known","consult"]},"id":"s08-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Repasa qué revisará la persona docente en la evidencia compuesta.","type":"flashcards","props":{"cards":[{"icon":"Home","front":"Procedencia","back":"Una práctica que realmente conoces desde tu familia, comunidad o cultura; no una tradición inventada."},{"icon":"Leaf","front":"Recurso","back":"El recurso natural que la práctica ayuda a proteger."},{"icon":"ListChecks","front":"Acción comprobada","back":"Qué observaste antes, qué hiciste ahora y qué verificaste después."}]},"id":"s08-pyd-1-5"},{"id":"s08-pyd-1-6","fase":"aplicar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Crea evidencia **desde tu cultura**: identifica una práctica de conservación que realmente conoces en tu familia o comunidad, nombra el recurso natural, registra antes, ejecuta ahora la adaptación voluntaria del **modo de baja actividad**, verifica sus ajustes y registra acción y después. Si aún no conoces una práctica propia, escribe **“necesito consultar”**: no afirmes dominio. Queda pendiente de revisión docente.","type":"cultural-conservation-practice","props":{"minWords":30,"consultationMinWords":8,"requiresLiveAction":true,"rubric":["La práctica es genuinamente conocida en mi contexto","Nombro el recurso natural","Realicé una acción segura ahora","Registro antes, acción y después sin inventar ahorro"],"example":{"culturalPractice":"En mi familia aprovechamos la luz natural antes de encender una lámpara.","naturalResource":"Cuidamos agua y otros recursos usados para generar electricidad.","beforeAction":"Antes, el sonido opcional estaba activo.","actionReport":"Activé voluntariamente el modo de baja actividad ahora.","afterAction":"Después verifiqué sonido apagado y movimiento reducido activo."}}},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Antes de las salidas","prompt":"Distingue qué registrarás según la ruta que elegiste.","type":"explain","props":{"icon":"Route","body":"Si conoces la práctica, conserva **procedencia, recurso natural, antes, acción segura y después**. Si necesitas consulta, registra **a quién o qué fuente consultarás y por qué**; no marques criterios que todavía no puedes demostrar."},"id":"s08-pyd-1-7"},{"id":"s08-pyd-1-salida-a","fase":"comprobar","areas":["pyd"],"cnb":["pyd:5.5.2"],"prompt":"Salida revisable: registra una práctica que realmente conoces desde familia, comunidad o cultura, el recurso natural y **antes → acción voluntaria segura realizada → después**. Si necesitas consulta, elige esa ruta, indica a quién o qué fuente consultar y por qué; podrás continuar sin recibir dominio todavía.","type":"cultural-conservation-practice","props":{"minWords":18,"consultationMinWords":8,"requiresLiveAction":false,"rubric":["Identifico procedencia cultural propia","Nombro recurso natural","Registro acción ejecutada","Incluyo antes y después"],"example":{"culturalPractice":"En mi familia apagamos lámparas que quedan sin uso.","naturalResource":"La práctica protege recursos naturales usados para producir electricidad.","beforeAction":"Antes observé una actividad opcional encendida.","actionReport":"Realicé una adaptación voluntaria y segura.","afterAction":"Después verifiqué el estado cambiado."}}},{"id":"s08-pyd-1-salida-b","fase":"comprobar","areas":["pyd"],"cnb":["pyd:5.5.2"],"prompt":"Segunda salida revisable: explica otra decisión de conservación desde una práctica realmente conocida en tu cultura, familia o comunidad; nombra el recurso natural y registra **antes, acción segura y después**. Si no conoces otra, usa la ruta de consulta y explica la fuente o persona que necesitas y por qué, sin afirmar dominio.","type":"cultural-conservation-practice","props":{"minWords":18,"consultationMinWords":8,"requiresLiveAction":false,"rubric":["Vinculo práctica cultural propia","Nombro recurso natural","Diferencio antes, acción y después","Justifico la decisión voluntaria"],"example":{"culturalPractice":"En mi comunidad conozco aprovechar ventilación natural.","naturalResource":"La práctica cuida recursos naturales asociados con la electricidad.","beforeAction":"Antes comprobé el estado disponible.","actionReport":"Elegí una acción accesible y voluntaria.","afterAction":"Después verifiqué el resultado y decidí conservarlo."}}},{"fase":"reflexionar","areas":["pyd"],"cnb":[],"ambito":"ser","prompt":"Cierra sin calificar: reconoce con honestidad si tu vínculo cultural necesita conversación o revisión adicional.","type":"reflection","props":{"statements":["Describí solo una práctica que realmente conozco","Diferencié evidencia propia y ejemplo suministrado"],"commitments":["Consultaré con respeto si todavía no conozco una práctica de mi contexto"]},"id":"s08-pyd-1-10"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s08","version":"cnb-sexto-b6b6c30b096ec478","lesson":{"id":"s08-l1-4","title":"El informe: del primer borrador a la composición","icon":"FileText","minutes":15,"gancho":"Ya tienes preguntas, fuentes y notas. ¿Cómo se convierten en un texto que otros puedan leer?","objetivos":["Reconocer las partes de un informe escrito"],"resumen":["Partes del informe: título, introducción (tema, pregunta y por qué), desarrollo (un párrafo por pregunta clave), conclusión (respuesta y lo aprendido) y lista de fuentes.","Cada párrafo tiene una oración principal (la idea) y oraciones de apoyo (datos de tus notas, con su fuente).","El primer borrador es una versión de trabajo: lo importante es poner las ideas en orden; se corrige después.","Componer es transformar las notas en oraciones completas y unirlas con conectores: primero, además, por eso, finalmente."],"media":{"id":"s08-l1-4-partes","kind":"diagram","title":"Las partes de un informe","aspect":"3:4","alt":"Una hoja de informe con cinco bloques de colores: título, introducción, desarrollo con tres párrafos, conclusión y fuentes. Flechas desde las notas del cuaderno hasta los párrafos del desarrollo.","brief":"Diagrama vertical: a la izquierda, una hoja de cuaderno con notas agrupadas por preguntas 1, 2 y 3; a la derecha, la página del informe con bloques de color: TÍTULO (arriba, centrado), INTRODUCCIÓN (qué investigué, mi pregunta y por qué), DESARROLLO (tres párrafos numerados que reciben flechas desde las notas 1, 2 y 3), CONCLUSIÓN (respuesta a la pregunta y lo aprendido), FUENTES (lista). Etiquetas claras, colores suaves. Target: public/media/s08-l1-4-partes.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":[],"ambito":"conocer","prompt":"Antes de leer el modelo, reconoce qué parte de un informe ya puedes identificar.","type":"reflection","props":{"statements":["Distingo un título de un párrafo","Busco una fuente antes de confiar en un dato"],"commitments":["Comprobaré cada parte en el modelo suministrado"]},"id":"s08-l1-4-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Las partes de un informe","prompt":"Un **informe** comunica lo que investigaste de forma ordenada. Mira el diagrama y toca cada parte.","type":"explain","props":{"icon":"FileText","body":"El informe responde a tu **pregunta de investigación** con información de tus **fuentes**.","reveal":[{"icon":"Heading","front":"Título","back":"Breve y claro: \\"Datos para usar mejor la iluminación\\". Con nombre, grado y fecha."},{"icon":"DoorOpen","front":"Introducción","back":"Un párrafo: **qué** investigaste, **tu pregunta** y **por qué** es importante."},{"icon":"Layers","front":"Desarrollo","back":"**Un párrafo por cada pregunta clave**, con los datos de tus notas y sus fuentes (\\"según…\\")."},{"icon":"Flag","front":"Conclusión","back":"Responde la pregunta en pocas líneas y di **qué aprendiste** o qué propones."},{"icon":"List","front":"Fuentes","back":"La lista de todas las fuentes que usaste, en orden alfabético."}]},"id":"s08-l1-4-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Cómo se construye un párrafo","prompt":"Componer es convertir tus notas en **párrafos**. Toca cada tarjeta.","type":"explain","props":{"icon":"AlignLeft","body":"Un párrafo = **una idea**. Si cambias de idea, empieza otro párrafo.","reveal":[{"icon":"Target","front":"Oración principal","back":"Dice la idea del párrafo, casi siempre al inicio: \\"El paquete permite recomendar un uso más cuidadoso de la iluminación\\"."},{"icon":"Layers","front":"Oraciones de apoyo","back":"Explican la idea con **datos de tus notas** y su fuente: \\"Según la Ficha B, una lámpara usó 9 W y otra 60 W en condiciones comparables\\"."},{"icon":"Link","front":"Conectores","back":"Unen las oraciones: _primero, además, también, por eso, sin embargo, finalmente_."},{"icon":"PenLine","front":"Borrador","back":"En el primer borrador **no te detengas** a corregir cada palabra: pon las ideas en orden. Deja espacio entre líneas para corregir después."}]},"id":"s08-l1-4-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","prompt":"Lee este **primer borrador**, escrito solo con el paquete suministrado. Identifica sus partes y responde.","hint":"Busca introducción, desarrollo, conclusión y fuentes; luego identifica la idea principal y sus apoyos.","explain":"El informe organiza una pregunta y datos atribuidos: la introducción presenta, el desarrollo explica con evidencia, la conclusión responde y la lista identifica las fuentes.","type":"reading","props":{"genre":"Informe escolar (borrador)","heading":"Datos para usar mejor la iluminación","passage":"Introducción. Este informe responde: ¿qué recomendación de ahorro permite sostener el paquete suministrado? El caso es simulado y no describe nuestra escuela.\\n\\nEl paquete presenta datos que deben comunicarse con su contexto. Según la Ficha A, el escenario registra exactamente 12,468 kWh y lo aproxima a 12,000 kWh. Ambos números conservan la unidad y el rótulo de caso simulado.\\n\\nLa iluminación ofrece una acción concreta. Según la Ficha B, una lámpara usó 9 W y otra 60 W en condiciones comparables. Además, la guía recomienda apagar luces de espacios vacíos. La ficha no demuestra cuánto ahorró una escuela real.\\n\\nConclusión. La evidencia permite recomendar apagar luces innecesarias y publicar los datos con fuente, unidad y contexto. No permite prometer una reducción exacta del recibo.\\n\\nFuentes: Ficha A, escenario escolar simulado. Ficha B, guía de iluminación suministrada.","questions":[{"q":"¿Qué dice la introducción?","options":[{"id":"a","text":"Por qué el tema es importante y cuál es la pregunta de investigación"},{"id":"b","text":"Solo la comparación de lámparas"},{"id":"c","text":"La lista de fuentes"}],"correct":"a","why":"Presenta el tema, explica por qué importa y formula la pregunta."},{"q":"¿Cuál es la **oración principal** del tercer párrafo?","options":[{"id":"a","text":"La iluminación ofrece una acción concreta."},{"id":"b","text":"Una lámpara usó 9 W."},{"id":"c","text":"La ficha no demuestra un ahorro real."}],"correct":"a","why":"Es la idea general del párrafo; las demás oraciones la apoyan con datos."},{"q":"¿Cómo muestra Sofía su **honestidad intelectual** en el borrador?","options":[{"id":"a","text":"Nombra las fichas, conserva unidades y declara que el caso es simulado"},{"id":"b","text":"Escribe todo sin fuentes"},{"id":"c","text":"Inventa datos para que el informe sea más largo"}],"correct":"a","why":"Nombra las fichas, conserva las unidades, declara el escenario y enumera las fuentes."},{"q":"¿Qué parte falta en la versión final?","options":[{"id":"a","text":"Agregar nombre, grado y fecha, y revisar la legibilidad"},{"id":"b","text":"Quitar la conclusión"},{"id":"c","text":"Borrar las fuentes"}],"correct":"a","why":"La tarea pedía un dibujo, y un informe lleva nombre, grado y fecha. Eso se agrega al editar."}]},"id":"s08-l1-4-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: de la nota al párrafo","prompt":"Mira cómo se compone el tercer párrafo a partir de las notas suministradas.","type":"worked-example","props":{"icon":"PenLine","problem":"Nota: “iluminación → acción concreta · LED 9 W / incand. 60 W (comparable) · apagar luces vacías · ≠ ahorro real (Ficha B)”.","steps":[{"text":"Escribo la **oración principal**: “La iluminación ofrece una acción concreta”."},{"text":"Convierto el dato en oración: “Según la Ficha B, una lámpara usó 9 W y otra 60 W en condiciones comparables”."},{"text":"Agrego la recomendación con un conector: “**Además**, la guía recomienda apagar luces de espacios vacíos”."},{"text":"Cierro con el límite: “La ficha no demuestra cuánto ahorró una escuela real”.","why":"Una conclusión honesta no excede la evidencia."}],"answer":"Un párrafo con una idea principal, tres oraciones de apoyo, dos fuentes nombradas y un conector.","tip":"Cada pregunta clave de tus notas = un párrafo del desarrollo."},"id":"s08-l1-4-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Ordena las oraciones para formar un **párrafo** sobre el dato exacto y aproximado.","explain":"Primero la oración principal, luego los datos en orden y un conector para cerrar.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"d1","text":"El escenario debe publicar el dato con precisión y contexto."},{"id":"d2","text":"Según la Ficha A, el valor exacto es 12,468 kWh."},{"id":"d3","text":"Para una lectura rápida, puede escribirse aproximadamente 12,000 kWh."},{"id":"d4","text":"Finalmente, ambos valores deben conservar la unidad y el rótulo de caso simulado."}]},"id":"s08-l1-4-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Con las Fichas A y B ya suministradas, escribe la **introducción** y **un párrafo de desarrollo**. Incluye “según…”, una unidad y el rótulo de caso simulado. No agregues mediciones, recibos ni entrevistas.","type":"short-answer","props":{"minWords":45,"placeholder":"Título: …\\nIntroducción breve: …\\nDesarrollo (un párrafo): …","model":"Título: Datos para usar mejor la iluminación\\nIntroducción: Este informe analiza un caso escolar simulado; no describe nuestra escuela. La pregunta es qué recomendación permite sostener el paquete.\\nDesarrollo: Según la Ficha B, una lámpara usó 9 W y otra 60 W bajo condiciones comparables. Además, la guía recomienda apagar las luces de espacios vacíos. Estos datos no muestran cuánto ahorró una escuela real.","rubric":["Mi introducción dice qué investigué, mi pregunta y por qué es importante","Mi párrafo tiene una oración principal y oraciones de apoyo","Usé datos de mis notas con su fuente (\\"según…\\")","Usé al menos un conector (primero, además, luego, finalmente)"]},"id":"s08-l1-4-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Une cada parte del informe con lo que contiene.","type":"match","props":{"leftTitle":"Parte","rightTitle":"Contiene","pairs":[{"id":"p1","left":"Introducción","right":"El tema, la pregunta y por qué es importante"},{"id":"p2","left":"Desarrollo","right":"Un párrafo por cada pregunta clave, con datos"},{"id":"p3","left":"Conclusión","right":"La respuesta a la pregunta y lo aprendido"},{"id":"p4","left":"Fuentes","right":"La lista de libros, sitios y personas consultadas"}]},"id":"s08-l1-4-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"¿Qué es un **primer borrador**?","type":"choice","props":{"options":[{"id":"a","text":"Una primera versión del texto con las ideas en orden, que después se revisa y corrige"},{"id":"b","text":"La versión final, lista para entregar"},{"id":"c","text":"La lista de fuentes"}],"correct":["a"]},"id":"s08-l1-4-9"}],"kind":"materia","area":"l1","day":4}},{"missionId":"s08","version":"cnb-sexto-a033a82309246503","lesson":{"id":"s08-l1-1","title":"Honestidad intelectual: datos, fuentes y citas","icon":"ShieldCheck","minutes":14,"gancho":"Si copias un texto de otra persona y le pones tu nombre, ¿de quién es realmente ese trabajo?","objetivos":["Explicar qué es la honestidad intelectual y por qué importa"],"resumen":["Honestidad intelectual es decir la verdad sobre de dónde viene lo que sabes y lo que escribes.","Tres compromisos: 1) no presentar como tuyo lo que escribió otra persona (plagio), 2) no inventar ni cambiar datos, 3) decir siempre de dónde tomaste la información (citar la fuente).","Usar ideas de otros está bien, y es parte de investigar, siempre que digas de quién son.","La honestidad hace que los demás confíen en tu trabajo y te permite aprender de verdad."],"media":{"id":"s08-l1-1-honestidad","kind":"image","title":"Tres compromisos honestos","aspect":"16:9","alt":"Tres paneles: una niña escribe con sus propias palabras junto a un libro abierto; un niño anota en una tabla los datos reales de una encuesta; una niña escribe al final de su informe la lista de fuentes.","brief":"Ilustración en tres paneles con estilo de cómic suave. Panel 1 \\"Escribo con mis palabras\\": niña que lee un libro y escribe en su cuaderno. Panel 2 \\"No invento datos\\": niño que anota con cuidado los resultados de una encuesta en una tabla, aunque no son los que esperaba (cara pensativa). Panel 3 \\"Digo de dónde lo saqué\\": niña que escribe \\"Fuentes:\\" al final de su informe. Personajes diversos de Guatemala, fondo de aula. Target: public/media/s08-l1-1-honestidad.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","title":"La fuente sostiene la confianza","prompt":"Lee este principio antes de decidir cómo usar datos ajenos.","type":"explain","props":{"icon":"ShieldCheck","body":"La honestidad intelectual exige conservar el dato, distinguir palabras propias y ajenas, y nombrar la **fuente**."},"id":"s08-l1-1-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","title":"¿Qué es la honestidad intelectual?","prompt":"La **honestidad intelectual** es decir la verdad sobre **de dónde viene** lo que sabes y lo que escribes. Mira la imagen y toca cada tarjeta.","type":"explain","props":{"icon":"ShieldCheck","body":"Investigar es como una conversación con otras personas que saben: honrarlas es decir sus nombres.","reveal":[{"icon":"Copy","front":"1. No plagiar","back":"**Plagio** es presentar como propio lo que escribió, dibujó o descubrió otra persona. Copiar y pegar sin decir de dónde es, es plagio."},{"icon":"BarChart3","front":"2. No inventar ni cambiar datos","back":"Si tu encuesta dio 12 respuestas, escribes 12, aunque esperabas 20. Inventar o \\"arreglar\\" datos engaña a quien lee."},{"icon":"Quote","front":"3. Citar la fuente","back":"Cada vez que uses información de otra persona o de un libro, **di de dónde la tomaste**: en el texto y en la lista de fuentes."},{"icon":"Heart","front":"¿Por qué importa?","back":"Respetas el trabajo de otros, los demás pueden **confiar** en ti y, sobre todo, **aprendes** de verdad: copiar no deja nada en tu cabeza."}]},"id":"s08-l1-1-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"Lee lo que le pasó a Diego y responde.","type":"reading","props":{"genre":"Relato","heading":"Los números de Diego","passage":"Diego y su grupo investigaban cuántas familias de su cuadra separan la basura. Preguntaron casa por casa y anotaron las respuestas: de 25 familias, solo 6 separaban la basura.\\n\\n—Seis es muy poquito —dijo Diego—. Si ponemos 20, el cartel se va a ver mejor y la maestra nos va a felicitar.\\n\\nKarla no estuvo de acuerdo:\\n\\n—Si cambiamos el número, el cartel dirá una mentira. Y además, el dato real es importante: muestra que hay que hacer algo.\\n\\nEl grupo escribió el dato verdadero: 6 de 25 familias. Debajo agregaron una propuesta: repartir hojas con consejos para separar la basura. Cuando presentaron, la directora les pidió copias del cartel para llevarlas a la reunión de padres. \\"Gracias a su investigación\\", dijo, \\"sabemos que tenemos trabajo por hacer\\".\\n\\nDiego sonrió. Entendió que un dato honesto, aunque no sea el que uno quiere, puede ser el que más ayuda.","questions":[{"q":"¿Cuántas familias separaban la basura, según la investigación?","options":[{"id":"a","text":"6 de 25"},{"id":"b","text":"20 de 25"},{"id":"c","text":"25 de 25"}],"correct":"a","why":"Es el dato real que anotaron al preguntar casa por casa."},{"q":"¿Qué quería hacer Diego con el dato?","options":[{"id":"a","text":"Cambiarlo por un número mayor para que el cartel se viera mejor"},{"id":"b","text":"Borrarlo del cartel"},{"id":"c","text":"Preguntar a más familias"}],"correct":"a","why":"Diego propuso poner 20 en lugar de 6: eso es alterar un dato."},{"q":"¿Por qué fue útil que el grupo usara el dato verdadero?","options":[{"id":"a","text":"Porque mostró un problema real y la escuela pudo actuar"},{"id":"b","text":"Porque así el cartel se veía más bonito"},{"id":"c","text":"Porque la maestra no revisa los datos"}],"correct":"a","why":"La directora usó el dato para trabajar con los padres: un dato falso habría escondido el problema."}]},"id":"s08-l1-1-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: la prueba de honestidad","prompt":"Antes de entregar, Sofía revisa su texto con tres preguntas.","type":"worked-example","props":{"icon":"ClipboardCheck","problem":"Párrafo de Sofía: “El caso registra 12,468 kWh. Según la Ficha A, el valor aproximado es 12,000 kWh. Una lámpara LED siempre elimina por completo el consumo de electricidad”.","steps":[{"text":"**¿Son mis palabras?** Sí, pero las afirmaciones todavía necesitan fuente."},{"text":"**¿Dije de dónde sale cada dato?** El redondeo sí; el valor exacto también debe atribuirse a la Ficha A."},{"text":"**¿La conclusión respeta la evidencia?** No: una LED sigue usando energía y la palabra “siempre” no está respaldada."},{"text":"Corrige: _Según la Ficha B, una LED de 9 W usa menos potencia que la lámpara de 60 W comparada en el caso simulado._"}],"answer":"Ahora el párrafo es honesto: distingue las afirmaciones propias y atribuye los datos a las Fichas A y B suministradas.","tip":"Tres preguntas: ¿son mis palabras?, ¿dije de dónde viene?, ¿el dato es el real?"},"id":"s08-l1-1-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"Clasifica cada acción: ¿es **honesta** o **deshonesta**?","hint":"Aplica los tres compromisos: no copiar como propio, no inventar datos, decir de dónde viene.","explain":"Una práctica es honesta cuando conserva los datos, distingue las palabras ajenas y hace visible la fuente; alterar, inventar u ocultar el origen rompe la confianza.","type":"sort","props":{"buckets":[{"id":"hon","label":"Honesta","icon":"ShieldCheck","color":"var(--c-ok)"},{"id":"des","label":"Deshonesta","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"h1","text":"Escribir la lista de fuentes al final del informe","bucket":"hon"},{"id":"h2","text":"Copiar y pegar un texto de internet con mi nombre","bucket":"des"},{"id":"h3","text":"Poner entre comillas una frase de un libro y decir de cuál es","bucket":"hon"},{"id":"h4","text":"Inventar la respuesta de una entrevista que no hice","bucket":"des"},{"id":"h5","text":"Explicar con mis palabras lo que leí y nombrar la fuente","bucket":"hon"},{"id":"h6","text":"Redondear 18 respuestas a \\"casi todos\\" cuando eran 18 de 40","bucket":"des","feedback":"18 de 40 es menos de la mitad: decir \\"casi todos\\" cambia el sentido del dato."}]},"id":"s08-l1-1-5"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Laptop","text":"Es de noche y el informe es para mañana. En internet encuentras un texto perfecto sobre el tema. Tu compañero **Óscar** dice: \\"Cópialo y pégalo, nadie se va a dar cuenta\\"."},"options":[{"id":"a","icon":"Copy","text":"Copiarlo completo y ponerle mi nombre","consequence":"La maestra reconoce el texto. Pierdes la confianza del grado y no aprendiste nada.","values":["deshonestidad"],"constructive":false},{"id":"b","icon":"PenLine","text":"Leerlo, escribir las ideas con mis palabras y anotar de dónde las saqué","consequence":"Tu informe es más sencillo, pero es tuyo y es honesto. La maestra valora que citaste la fuente.","values":["honestidad intelectual","responsabilidad"],"constructive":true},{"id":"c","icon":"Quote","text":"Copiar solo una frase importante entre comillas, con el nombre del autor y del sitio","consequence":"Usaste bien una cita: dejaste claro que esas palabras no son tuyas.","values":["honestidad intelectual","respeto al trabajo de otros"],"constructive":true}]},"id":"s08-l1-1-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"La ficha no indica cuánto dinero se ahorró. ¿Qué escribes en el informe?","explain":"Si un dato no aparece, se reconoce el límite. Inventar una cantidad, aunque parezca posible, altera la información.","type":"choice","props":{"options":[{"id":"a","text":"“El paquete no informa un ahorro monetario”."},{"id":"b","text":"“Se ahorraron Q500”, porque parece razonable","feedback":"Sería un dato inventado."},{"id":"c","text":"“Se eliminó todo el gasto de electricidad”","feedback":"Es una exageración sin respaldo."}],"correct":["a"]},"id":"s08-l1-1-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Qué es el **plagio**?","type":"choice","props":{"options":[{"id":"a","text":"Presentar como propio lo que escribió o hizo otra persona"},{"id":"b","text":"Escribir la lista de fuentes"},{"id":"c","text":"Explicar una idea con tus palabras y decir de quién es"}],"correct":["a"]},"id":"s08-l1-1-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Usar ideas de otras personas está bien si dices de quién son.","answer":true},{"text":"Si un dato no me gusta, puedo cambiarlo un poco.","answer":false,"why":"Cambiar datos es deshonesto: el dato real es el que se escribe."},{"text":"La honestidad intelectual ayuda a que los demás confíen en tu trabajo.","answer":true}]},"id":"s08-l1-1-9"}],"kind":"materia","area":"l1","day":1}},{"missionId":"s08","version":"cnb-sexto-1c6d2a29baea0910","lesson":{"id":"s08-ccss-1","title":"Los grandes problemas del mundo, en datos","icon":"BarChart3","minutes":15,"gancho":"Todos los días escuchas noticias sobre sequías, migración, precios altos o contaminación. ¿Son problemas solo de Guatemala o de todo el planeta? ¿Cómo sabemos qué tan grandes son?","objetivos":["Usar aportes de las Ciencias Sociales, fuentes y datos fechados para comprender un problema mundial sin exagerar conclusiones"],"resumen":["Problemas mundiales actuales: pobreza y hambre, desigualdad, cambio climático, falta de agua potable, pérdida de bosques y biodiversidad, contaminación, migración forzada, conflictos armados, enfermedades y falta de acceso a la educación.","Los organismos publican informes con fuente, fecha, método y unidad. En esta lección, cualquier cifra sin referencia completa se presenta como dato didáctico simulado, no como estadística mundial actual.","Las Ciencias Sociales aportan preguntas, conceptos, fuentes y métodos para relacionar decisiones humanas, instituciones y condiciones de vida; no sustituyen la evidencia con opiniones.","Para leer un informe: identifica el tema, la fuente y la fecha; lee título, unidades y escalas de las gráficas; compara datos y saca conclusiones sin exagerar.","En 2015, los países de la ONU acordaron 17 Objetivos de Desarrollo Sostenible (Agenda 2030) para enfrentar juntos estos problemas. Lo global también se vive y se resuelve en lo local."],"media":{"id":"s08-ccss-1-ods","kind":"image","title":"Un planeta, muchos retos","aspect":"16:9","alt":"Ilustración de un globo terráqueo rodeado de íconos de problemas mundiales: una mazorca seca, una gota de agua tachada, un termómetro alto, un árbol cortado, una mochila de migrante y un libro cerrado.","brief":"Ilustración central de la Tierra rodeada de 8 íconos grandes y amables, cada uno con una etiqueta breve: Hambre (plato vacío), Agua (gota con signo de interrogación), Cambio climático (termómetro alto), Bosques (tocón de árbol), Contaminación (bolsa plástica en el mar), Migración forzada (familia con mochilas), Educación (libro cerrado), Desigualdad (balanza inclinada). Debajo: \\"La ONU mide estos problemas con informes y datos\\". Estilo plano, colores suaves, sin fotos de personas reales ni imágenes dolorosas. Target: public/media/s08-ccss-1-ods.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"Problemas sociales con datos","prompt":"Lee cómo las Ciencias Sociales estudian un problema mundial.","type":"explain","props":{"icon":"Globe2","body":"Las Ciencias Sociales estudian problemas mundiales y aportan preguntas, fuentes fechadas, comparaciones y conclusiones cuidadosas."},"id":"s08-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Caso didáctico simulado; no describe una situación actual: en una temporada ficticia, la lluvia llegó tarde y se perdieron milpas en una comunidad del Corredor Seco. El mismo paquete simula sequías en partes de África y Asia. ¿Qué permite comparar?","explain":"Algunos problemas **no respetan fronteras**: el cambio climático, el hambre o la contaminación afectan a muchos países a la vez. Son **problemas mundiales**.","type":"choice","props":{"options":[{"id":"a","text":"Que hay problemas que afectan a muchos países a la vez","icon":"Globe"},{"id":"b","text":"Que es pura casualidad y no tiene relación","icon":"Dice5","feedback":"Cuando algo se repite en muchos lugares, conviene investigar si hay causas comunes, como el cambio del clima."},{"id":"c","text":"Que solo Guatemala tiene problemas","icon":"MapPin","feedback":"La sequía también ocurre en otros continentes: es un problema compartido."}],"correct":["a"]},"id":"s08-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"La problemática mundial actual","prompt":"Los informes de la ONU y de otros organismos describen varios problemas que enfrenta la humanidad hoy. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Las **Ciencias Sociales** ayudan a comprender estos problemas al comparar fuentes, fechas, actores, decisiones e instituciones. Una relación entre datos orienta preguntas, pero no prueba por sí sola una causa.","reveal":[{"icon":"Wheat","front":"Pobreza y hambre","back":"Caso didáctico simulado: un informe regional registra **9 de cada 100 personas** con alimentación insuficiente. La cifra no representa un dato mundial actual."},{"icon":"Droplets","front":"Agua","back":"Caso didáctico simulado: una tabla compara hogares con servicio gestionado de forma segura. Tener tubería no demuestra por sí solo que el agua sea potable."},{"icon":"Thermometer","front":"Cambio climático","back":"El planeta se calienta por los gases que producen la quema de combustibles y la tala de bosques. Hay sequías y tormentas más fuertes."},{"icon":"TreePine","front":"Bosques y biodiversidad","back":"Se pierden bosques y muchas especies de plantas y animales están en peligro."},{"icon":"Route","front":"Migración forzada","back":"Millones de personas dejan su hogar por pobreza, violencia, conflictos o desastres."},{"icon":"BookOpen","front":"Educación","back":"Millones de niñas y niños en el mundo no van a la escuela, sobre todo en zonas pobres o con conflictos."},{"icon":"Target","front":"Una respuesta común: los ODS","back":"En **2015**, los países de la ONU acordaron **17 Objetivos de Desarrollo Sostenible** (la **Agenda 2030**): metas comunes como acabar con el hambre, dar educación de calidad, agua limpia y cuidar el clima."}]},"id":"s08-ccss-1-3"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","title":"Cómo leer un informe estadístico","prompt":"Los **datos estadísticos** son números que describen un problema. Para leerlos bien, sigue estos pasos. Toca cada tarjeta.","media":{"id":"s08-ccss-1-grafica","kind":"diagram","title":"Partes de una gráfica","aspect":"4:3","alt":"Gráfica de barras con flechas que señalan sus partes: título, fuente, eje de categorías, eje de valores con unidades y la barra más alta.","brief":"Gráfica de barras de ejemplo con datos hipotéticos rotulados \\"Ejemplo\\" y flechas que señalan: (1) Título: \\"Hogares con agua entubada en cuatro aldeas (supuesto)\\"; (2) Fuente y año, en letra pequeña abajo; (3) Eje horizontal con los nombres de las aldeas; (4) Eje vertical con la unidad \\"%\\" y escala de 0 a 100 de 20 en 20; (5) la barra más alta y la más baja resaltadas. Colores claros, textos grandes. Target: public/media/s08-ccss-1-grafica.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"BarChart3","body":"Un buen lector de datos no exagera: dice **lo que muestran los números** y aclara si son **aproximados** o **supuestos**.","reveal":[{"icon":"FileText","front":"1. Tema, fuente y fecha","back":"¿De qué trata? ¿Quién lo publicó (ONU, INE, municipalidad)? ¿De qué año son los datos? Una fuente confiable dice cómo obtuvo sus datos."},{"icon":"Ruler","front":"2. Unidades y escala","back":"¿Son personas, porcentajes (%) o millones? ¿De cuánto en cuánto sube la escala?"},{"icon":"Search","front":"3. Comparar","back":"¿Cuál es el dato mayor y el menor? ¿Aumentó o disminuyó con el tiempo?"},{"icon":"Lightbulb","front":"4. Concluir","back":"Escribe una conclusión que salga de los datos: \\"La aldea C tiene la menor cobertura de agua\\"."}]},"id":"s08-ccss-1-4"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","prompt":"Como práctica guiada de **Ciencias Sociales**, construye la gráfica de este informe hipotético sobre acceso al agua, un **problema mundial** observado aquí a escala municipal.","hint":"Lee cada dato de la tabla y sube la barra hasta ese número. La escala va de 10 en 10.","explain":"La gráfica muestra de un vistazo que la aldea Los Pinos tiene la menor cobertura: allí debería priorizarse un proyecto de agua.","type":"chart-builder","props":{"categories":[{"id":"a","label":"El Llano","icon":"Home"},{"id":"b","label":"San José","icon":"Home"},{"id":"c","label":"Los Pinos","icon":"Home"},{"id":"d","label":"La Cumbre","icon":"Home"}],"data":[80,60,30,50],"max":100,"step":10,"unit":"%","source":"Informe municipal (datos supuestos): El Llano 80 %, San José 60 %, Los Pinos 30 %, La Cumbre 50 %"},"id":"s08-ccss-1-5"},{"fase":"aplicar","areas":["ccss","l1"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","prompt":"Lee este fragmento de un informe **hipotético** y usa aportes de las Ciencias Sociales para relacionar fuente, fecha, decisiones y condiciones de vida.","type":"reading","props":{"genre":"Informe (datos supuestos)","heading":"Informe regional sobre niñez y educación","passage":"Supongamos que un organismo internacional estudió cuatro países de una región durante 10 años. Estos son algunos resultados.\\n\\nEn 2014, **20 de cada 100** niñas y niños en edad de primaria no asistían a la escuela. En 2024, la cifra bajó a **12 de cada 100**. La mejora fue mayor en las ciudades que en las áreas rurales.\\n\\nEl informe señala tres causas principales de la falta de asistencia: la **pobreza** (las familias necesitan que los niños trabajen), la **distancia** a la escuela y la **migración** de las familias. Recomienda becas, transporte escolar y escuelas cercanas en el área rural.","questions":[{"q":"¿Qué pasó con la asistencia escolar entre 2014 y 2024?","options":[{"id":"a","text":"Mejoró: los que no asistían bajaron de 20 a 12 de cada 100"},{"id":"b","text":"Empeoró: subieron de 12 a 20 de cada 100"},{"id":"c","text":"No cambió nada"}],"correct":"a"},{"q":"¿Cuántos niños de cada 100 **dejaron** de estar fuera de la escuela en esos 10 años?","options":[{"id":"a","text":"8"},{"id":"b","text":"12"},{"id":"c","text":"32"}],"correct":"a","why":"20 − 12 = 8 de cada 100."},{"q":"¿Qué conclusión está **mejor apoyada** por los datos?","options":[{"id":"a","text":"Hubo avances, pero el área rural necesita más apoyo"},{"id":"b","text":"El problema ya está resuelto en todas partes"},{"id":"c","text":"La educación no tiene relación con la pobreza"}],"correct":"a","why":"El informe dice que la mejora fue menor en el área rural y que la pobreza es una causa."}]},"id":"s08-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Un mismo problema mundial se vive también en escala local. Clasifica cada situación suministrada según el **problema mundial** al que pertenece.","explain":"Pensar globalmente y actuar localmente: entender el problema mundial ayuda a actuar donde vivimos.","type":"sort","props":{"buckets":[{"id":"cli","label":"Cambio climático y ambiente","icon":"Thermometer","color":"var(--c-ok)"},{"id":"pob","label":"Pobreza y hambre","icon":"Wheat","color":"var(--c-maiz-strong)"},{"id":"mig","label":"Migración","icon":"Route","color":"var(--area-ccss)"}],"items":[{"id":"l1","text":"La lluvia llega tarde y se pierde la cosecha","bucket":"cli"},{"id":"l2","text":"Un joven se va a otro país a buscar trabajo","bucket":"mig"},{"id":"l3","text":"Familias que no alcanzan a comprar la canasta básica","bucket":"pob"},{"id":"l4","text":"Basura plástica en el río del pueblo","bucket":"cli"},{"id":"l5","text":"Niños con desnutrición en la aldea","bucket":"pob"}]},"id":"s08-ccss-1-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"En 2015, los países de la ONU acordaron los **17 Objetivos de Desarrollo Sostenible** (ODS). ¿Para qué sirven?","explain":"Los ODS son metas comunes para el año 2030: acabar con la pobreza y el hambre, garantizar educación, agua, igualdad de género, cuidar el clima y más. Cada país, municipio y persona puede aportar.","type":"choice","props":{"options":[{"id":"a","text":"Son metas comunes para enfrentar juntos los grandes problemas del mundo"},{"id":"b","text":"Son reglas de un deporte internacional","feedback":"No: son metas de desarrollo que los países acordaron en la ONU."},{"id":"c","text":"Son impuestos que se pagan a la ONU","feedback":"No son impuestos: son objetivos que guían las políticas de los países."}],"correct":["a"]},"id":"s08-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"¿Qué opción usa un aporte de las Ciencias Sociales para comprender un **problema mundial actual**?","type":"choice","props":{"options":[{"id":"a","text":"Comparar fuentes fechadas sobre cambio climático, decisiones públicas y condiciones de vida"},{"id":"b","text":"La construcción de pirámides en Egipto"},{"id":"c","text":"La invención de la imprenta"}],"correct":["a"]},"id":"s08-ccss-1-9"},{"fase":"comprobar","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"Un informe de **Ciencias Sociales** sobre el problema mundial de acceso a energía indica que en 2010 **30 de cada 100** hogares del caso no tenían luz eléctrica y en 2020 eran **18 de cada 100**. ¿En cuántos hogares de cada 100 cambió el indicador?","type":"number-input","props":{"answer":12,"unit":"de cada 100"},"id":"s08-ccss-1-10"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s08","version":"cnb-sexto-0c1e416a2fbef306","lesson":{"id":"s08-art-1","title":"La vida de un artista: investigar una biografía","icon":"Search","minutes":15,"preparatory":true,"gancho":"Cada lunes cantas el Himno Nacional. ¿Sabes quién compuso su música, dónde nació y cómo fue su vida?","objetivos":["Plantear preguntas guía para investigar la vida y la obra de un artista"],"resumen":["Una biografía cuenta la vida de una persona: dónde y cuándo nació, cómo se formó, sus obras más importantes, su aporte y datos que la hacen única.","Fuentes primarias: vienen directamente de la persona o de su tiempo (entrevistas, cartas, partituras, fotos). Fuentes secundarias: explican o resumen (libros, enciclopedias, artículos).","Una fuente es confiable si dice quién la escribió, es de una institución seria o de un libro reconocido, y coincide con otras fuentes. Siempre anota tus fuentes.","Ejemplos: Rafael Álvarez Ovalle (San Juan Comalapa, 1858-1946) compuso la música del Himno Nacional de Guatemala; Humberto Ak’abal (Momostenango, 1952-2019) fue un poeta k’iche’ que escribió en k’iche’ y en español."],"media":{"id":"s08-art-1-investigar","kind":"animation","title":"Detectives de biografías","aspect":"16:9","duration":50,"alt":"Una niña con una lupa reúne pistas sobre un compositor: una partitura antigua, un libro de la biblioteca, una entrevista con su maestro y una línea de tiempo que se va llenando.","brief":"Animación 2D de 50 s, estilo cuaderno de detective. Una niña (de rasgos mayas, uniforme escolar) investiga a un compositor guatemalteco del siglo XIX (figura genérica, sin retrato real). Aparecen tarjetas: \\"¿Dónde y cuándo nació?\\", \\"¿Qué estudió?\\", \\"¿Qué obras creó?\\", \\"¿Cuál fue su aporte?\\". Luego tres fuentes: libro de biblioteca (secundaria), partitura antigua (primaria), entrevista grabada con un maestro de música (primaria). Al final, una línea de tiempo con tres hitos. Narración en español, subtítulos. No usar fotografías reales de personas. Target: public/media/s08-art-1-investigar.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["art"],"cnb":[],"ambito":"conocer","title":"Investigar vida y obra","prompt":"Lee esta preparación para la publicación biográfica de la siguiente lección.","type":"explain","props":{"icon":"Palette","body":"Una biografía artística organiza origen, formación, obras, aporte y fuentes verificables."},"id":"s08-art-1-1"},{"fase":"construir","areas":["art"],"cnb":[],"ambito":"conocer","prompt":"¿Quién compuso la **música** del Himno Nacional de Guatemala?","explain":"La música es de **Rafael Álvarez Ovalle**, nacido en **San Juan Comalapa**, Chimaltenango. La letra es del poeta **José Joaquín Palma**. Hoy aprenderás a investigar la vida de artistas como ellos.","type":"choice","props":{"options":[{"id":"a","text":"Rafael Álvarez Ovalle","icon":"Music"},{"id":"b","text":"José Joaquín Palma","icon":"PenLine","feedback":"Palma escribió la **letra**. La **música** es de otra persona."},{"id":"c","text":"Ludwig van Beethoven","icon":"Globe","feedback":"Beethoven fue un compositor alemán; no compuso nuestro himno."}],"correct":["a"]},"id":"s08-art-1-2"},{"fase":"construir","areas":["art"],"cnb":[],"ambito":"conocer","title":"Preguntas guía de una biografía","prompt":"Una **biografía** cuenta la vida de una persona. Para investigar, empieza con **preguntas guía**. Toca cada tarjeta.","type":"explain","props":{"icon":"ClipboardList","body":"Investigar a un artista es como armar un rompecabezas: cada pregunta es una pieza.","reveal":[{"icon":"MapPin","front":"Origen","back":"¿**Dónde** y **cuándo** nació? ¿Cómo era su familia y su comunidad?"},{"icon":"GraduationCap","front":"Formación","back":"¿Cómo aprendió su arte? ¿Quién le enseñó? ¿Qué dificultades enfrentó?"},{"icon":"Music","front":"Obras","back":"¿Cuáles son sus **obras** más importantes (canciones, poemas, pinturas, tejidos)? ¿Cuándo las creó?"},{"icon":"Star","front":"Aporte","back":"¿Por qué es importante para su comunidad, el país o el mundo? ¿Qué cambió gracias a su obra?"}]},"id":"s08-art-1-3"},{"fase":"construir","areas":["art"],"cnb":[],"ambito":"conocer","title":"Fuentes confiables","prompt":"Cada dato de tu biografía debe venir de una **fuente**. No todas son iguales. Toca cada tarjeta.","type":"explain","props":{"icon":"Library","body":"Una buena investigación usa **al menos dos fuentes** y compara si dicen lo mismo.","reveal":[{"icon":"FileText","front":"Fuente primaria","back":"Viene directamente de la persona o de su época: una **entrevista** con ella o con quien la conoció, sus **cartas**, **partituras**, **fotos** o documentos."},{"icon":"BookOpen","front":"Fuente secundaria","back":"Alguien más la escribió para explicar: **libros**, **enciclopedias**, artículos de periódico o de instituciones culturales."},{"icon":"ShieldCheck","front":"¿Es confiable?","back":"Dice **quién** la escribió, es de una **institución** o libro reconocido, y **coincide** con otras fuentes. Desconfía de mensajes sin autor que circulan por redes."},{"icon":"PenLine","front":"Anota siempre","back":"Escribe de dónde sacaste cada dato: título del libro, nombre de la persona entrevistada y fecha. Así otras personas pueden comprobarlo."}]},"id":"s08-art-1-4"},{"fase":"construir","areas":["art","ccss"],"cnb":[],"ambito":"hacer","title":"Ejemplo resuelto: la ficha de Rafael Álvarez Ovalle","prompt":"Mira cómo Mariela organiza lo que investigó con las preguntas guía.","type":"worked-example","props":{"icon":"NotebookPen","problem":"Mariela consultó un libro de historia de la música guatemalteca en la biblioteca municipal y entrevistó a su maestro de música. ¿Cómo arma su ficha?","steps":[{"text":"**Origen:** nació en **1858** en **San Juan Comalapa**, Chimaltenango."},{"text":"**Formación:** aprendió música desde joven; fue músico, maestro y director de bandas. (Fuente: libro de la biblioteca.)"},{"text":"**Obras:** su obra más conocida es la **música del Himno Nacional de Guatemala**, que se estrenó en **1897**. También compuso otras piezas."},{"text":"**Aporte:** dio al país una melodía que nos une en los actos cívicos. Murió en **1946**."},{"text":"**Fuentes:** \\"Libro de historia de la música, biblioteca municipal\\" y \\"entrevista a mi maestro de música, 3 de marzo\\".","why":"Sin fuentes, nadie puede comprobar los datos."}],"answer":"Una ficha biográfica responde **origen, formación, obras y aporte**, y termina con las **fuentes**.","tip":"Si dos fuentes dan fechas distintas, anótalo y consulta una tercera."},"id":"s08-art-1-5"},{"fase":"construir","areas":["art"],"cnb":[],"ambito":"conocer","prompt":"Clasifica cada fuente: ¿es **primaria** o **secundaria**?","hint":"Primaria = viene directamente de la persona o de su época. Secundaria = alguien más lo explica después.","explain":"Entrevistas, cartas y partituras originales son primarias. Libros, enciclopedias y artículos son secundarios.","type":"sort","props":{"buckets":[{"id":"p","label":"Primaria","icon":"FileText","color":"var(--area-art)"},{"id":"s","label":"Secundaria","icon":"BookOpen","color":"var(--area-l1)"}],"items":[{"id":"f1","text":"Entrevista a la marimbista cuya vida investigas","bucket":"p"},{"id":"f2","text":"Enciclopedia de arte guatemalteco","bucket":"s"},{"id":"f3","text":"Una partitura escrita a mano por el compositor","bucket":"p"},{"id":"f4","text":"Un artículo de periódico sobre un poeta","bucket":"s"},{"id":"f5","text":"Una carta que escribió una pintora","bucket":"p"}]},"id":"s08-art-1-6"},{"fase":"aplicar","areas":["art"],"cnb":[],"ambito":"hacer","prompt":"Recuerdas el **\\"Himno a la alegría\\"** de la semana 2. Es de **Ludwig van Beethoven**, compositor alemán. Ordena los hechos de su vida en una **línea de tiempo**.","explain":"Beethoven nació en Bonn en 1770, se mudó a Viena en 1792, empezó a perder el oído a finales de esa década, estrenó su Novena Sinfonía (que incluye el \\"Himno a la alegría\\") en 1824, ya casi sordo, y murió en Viena en 1827.","type":"order","props":{"items":[{"id":"a","text":"1770: nace en Bonn (Alemania)"},{"id":"b","text":"1792: se muda a Viena para estudiar y trabajar"},{"id":"c","text":"Finales de la década de 1790: empieza a perder el oído"},{"id":"d","text":"1824: estrena la Novena Sinfonía, con el \\"Himno a la alegría\\""},{"id":"e","text":"1827: muere en Viena"}],"labels":{"start":"Primero","end":"Después"}},"id":"s08-art-1-7"},{"fase":"aplicar","areas":["art"],"cnb":[],"ambito":"hacer","prompt":"Para investigar al poeta **Humberto Ak’abal**, Ana encontró tres fuentes. ¿Cuál es la **más confiable**?","explain":"Un libro publicado o una institución cultural reconocida, con autor identificado, es más confiable que un mensaje sin autor o un rumor.","type":"choice","props":{"options":[{"id":"a","text":"Un libro de poesía guatemalteca publicado por una editorial, con datos del autor"},{"id":"b","text":"Un mensaje reenviado en un chat, sin autor","feedback":"No sabes quién lo escribió ni de dónde sacó los datos."},{"id":"c","text":"Lo que le contó un compañero que \\"lo leyó en algún lado\\"","feedback":"Es un rumor: no se puede comprobar."}],"correct":["a"]},"id":"s08-art-1-8"},{"fase":"aplicar","areas":["art"],"cnb":[],"ambito":"hacer","prompt":"Aplica las preguntas guía al paquete suministrado de Ana López, artista ficticia: une cada dato con su sección biográfica.","explain":"Una investigación breve conserva el origen, la formación, la obra y el aporte, y deja visible qué ficha suministrada respalda cada dato.","type":"match","props":{"leftTitle":"Dato suministrado","rightTitle":"Sección","pairs":[{"id":"a1","left":"Nació en Totonicapán en 1978","right":"Origen"},{"id":"a2","left":"Aprendió grabado en un taller escolar","right":"Formación"},{"id":"a3","left":"Creó la serie Bosques de tinta","right":"Obra"},{"id":"a4","left":"Enseñó técnicas de impresión a jóvenes","right":"Aporte"}]},"id":"s08-art-1-9"},{"fase":"comprobar","areas":["art"],"cnb":[],"prompt":"¿Cuál de estas es una **fuente primaria** para la biografía de una tejedora?","type":"choice","props":{"options":[{"id":"a","text":"Una entrevista con la tejedora"},{"id":"b","text":"Un resumen en una enciclopedia"},{"id":"c","text":"Lo que dice un anuncio publicitario"}],"correct":["a"]},"id":"s08-art-1-10"},{"fase":"comprobar","areas":["art"],"cnb":[],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En una biografía conviene anotar de dónde sale cada dato.","answer":true},{"text":"Rafael Álvarez Ovalle compuso la música del Himno Nacional de Guatemala.","answer":true},{"text":"Un mensaje sin autor en redes sociales es una fuente muy confiable.","answer":false,"why":"Sin autor no se puede comprobar; hay que buscar fuentes reconocidas."}]},"id":"s08-art-1-11"}],"kind":"materia","area":"art","day":1}},{"missionId":"s08","version":"cnb-sexto-d726ffac94c427b3","lesson":{"id":"s08-l1-2","title":"Citar y parafrasear","icon":"Quote","minutes":15,"gancho":"Hay dos formas honestas de usar lo que dijo otra persona: con sus palabras exactas o con las tuyas. ¿Sabes cuándo usar cada una?","objetivos":["Escribir una cita textual con comillas y fuente"],"resumen":["Cita textual: copias las palabras exactas entre comillas y dices de quién son. Úsala para frases cortas e importantes.","Paráfrasis: explicas la idea con tus propias palabras y dices de dónde la tomaste. Es la forma más usada en un informe.","Para parafrasear: lee, cierra el libro, escribe lo que entendiste y compara para no cambiar el sentido.","Lista de fuentes (al final): autor, año, título y editorial o sitio de cada fuente usada, en orden alfabético."],"media":{"id":"s08-l1-2-citar","kind":"animation","title":"Cita o paráfrasis","aspect":"16:9","duration":50,"alt":"Una frase de un libro se copia entre comillas con una etiqueta de la fuente (cita textual); luego la misma idea se transforma en otras palabras con la etiqueta \\"Según…\\" (paráfrasis).","brief":"Animación tipográfica de 50 s. Arriba, un libro abierto con la frase resaltada: \\"En las hidroeléctricas, la fuerza del agua de los ríos hace girar unas máquinas llamadas turbinas.\\" Camino 1 (izquierda): la frase viaja igual al cuaderno, aparecen comillas grandes y una etiqueta \\"(Ciencias Naturales 6)\\". Título: CITA TEXTUAL. Camino 2 (derecha): el libro se cierra, la frase se desarma y se rearma: \\"Según el libro de Ciencias Naturales 6, las hidroeléctricas usan el movimiento del agua de los ríos para mover turbinas.\\" Título: PARÁFRASIS. Narración en español, subtítulos. Target: public/media/s08-l1-2-citar.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"conocer","title":"Dos maneras de atribuir","prompt":"Una cita conserva palabras exactas; una paráfrasis conserva la idea con palabras nuevas.","type":"explain","props":{"icon":"Quote","body":"La **cita textual** usa comillas y fuente. La **paráfrasis** no usa comillas, pero también nombra la fuente."},"id":"s08-l1-2-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"conocer","title":"Dos formas honestas de usar una fuente","prompt":"Observa la animación y toca cada tarjeta.","type":"explain","props":{"icon":"Quote","body":"En las dos formas **siempre** dices de dónde viene la idea.","reveal":[{"icon":"Quote","front":"Cita textual","back":"Copias las **palabras exactas** entre **comillas** y dices la fuente: _Como explica el libro de Ciencias Naturales 6, \\"la fuerza del agua de los ríos hace girar unas máquinas llamadas turbinas\\"._ Úsala solo para frases **cortas** e importantes."},{"icon":"RefreshCw","front":"Paráfrasis","back":"Explicas la idea **con tus palabras**, sin comillas, y dices la fuente: _Según el libro de Ciencias Naturales 6, en las hidroeléctricas el agua de los ríos mueve unas máquinas llamadas turbinas._"},{"icon":"MessageCircle","front":"Frases para citar","back":"“Según la Ficha A…”, “Como explica la guía…”, “De acuerdo con el paquete suministrado…”."},{"icon":"AlertTriangle","front":"Paráfrasis falsa","back":"Cambiar solo una o dos palabras del original **no** es parafrasear. Hay que reescribir la idea completa."}]},"id":"s08-l1-2-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: parafrasear en cuatro pasos","prompt":"Mira cómo Mateo parafrasea un fragmento de su fuente sobre la electricidad.","type":"worked-example","props":{"icon":"RefreshCw","problem":"Original (libro de Ciencias Naturales 6): \\"En algunos ingenios, se quema el bagazo, que es lo que sobra de la caña de azúcar después de exprimirla.\\"","steps":[{"text":"**Leo** el fragmento dos veces hasta entenderlo."},{"text":"**Cierro** el libro y me pregunto: ¿qué dice? → que la caña exprimida se usa como combustible.","why":"Si no ves el original, no puedes copiarlo sin querer."},{"text":"**Escribo** con mis palabras: \\"Los restos de la caña de azúcar, llamados bagazo, se usan como combustible en algunos ingenios\\"."},{"text":"**Comparo** con el original: ¿cambié el sentido? No. ¿Copié frases? No. Agrego la fuente al inicio: \\"Según el libro de Ciencias Naturales 6…\\"."}],"answer":"\\"Según el libro de Ciencias Naturales 6, los restos de la caña de azúcar, llamados bagazo, se usan como combustible en algunos ingenios.\\"","tip":"Una palabra técnica (bagazo, turbina) puedes conservarla: no tiene sinónimo exacto."},"id":"s08-l1-2-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","prompt":"Original: \\"_Las raíces de la ceiba agarran la tierra y evitan que la lluvia se la lleve._\\" ¿Cuál es una **buena paráfrasis**?","hint":"Busca la que dice la misma idea con otras palabras, sin cambiar el sentido, y que nombra la fuente.","explain":"La opción correcta reescribe toda la idea, conserva el sentido (las raíces protegen el suelo) y dice la fuente.","type":"choice","props":{"options":[{"id":"a","text":"Según el texto \\"La ceiba: raíces que sostienen\\", las raíces de este árbol sujetan el suelo y lo protegen de la erosión que causa la lluvia."},{"id":"b","text":"Las raíces de la ceiba agarran la tierra y evitan que el agua se la lleve.","feedback":"Solo cambió \\"lluvia\\" por \\"agua\\": es casi una copia y no dice la fuente."},{"id":"c","text":"Según el texto, las raíces de la ceiba hacen que llueva más.","feedback":"Cambió el sentido: el original no dice eso."}],"correct":["a"]},"id":"s08-l1-2-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","prompt":"Completa la **cita textual** de la guía suministrada.","hint":"Una cita textual reproduce palabras exactas entre comillas y nombra la fuente.","explain":"La oración nombra la Ficha B, usa un verbo introductor y conserva las palabras exactas entre comillas.","type":"fill-blank","props":{"text":"La [[Ficha B]] [[indica]]: \\"Apaga las luces de espacios vacíos\\". Las palabras exactas van entre [[comillas]].","distractors":["alcalde","inventó","paréntesis"]},"id":"s08-l1-2-5"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4","l1:8.2.7"],"ambito":"conocer","title":"La lista de fuentes","prompt":"Al final del informe va la **lista de fuentes**: todas las que usaste, con sus datos. Es la ficha de la semana pasada, puesta en limpio. Toca cada tarjeta.","type":"explain","props":{"icon":"List","body":"Una forma sencilla: **Autor (año). _Título_. Editorial o sitio.** Se ordenan alfabéticamente por el autor.","reveal":[{"icon":"BookOpen","front":"Libro","back":"Autor o institución (año). _Título del libro_. Editorial. Copia los datos reales de la portada y de la página legal de tu libro."},{"icon":"Monitor","front":"Sitio web","back":"Nombre de la institución (año). _Título del artículo_. Nombre del sitio. Consultado el 10 de marzo."},{"icon":"FileText","front":"Ficha suministrada","back":"Equipo didáctico (2026). _Ficha B: Iluminación y uso racional_. Paquete de aula."},{"icon":"ListOrdered","front":"Orden alfabético","back":"Ordena por la primera palabra de cada fuente (apellido o institución), como en un diccionario."}]},"id":"s08-l1-2-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","prompt":"Ordena alfabéticamente esta **lista de fuentes** (son fuentes de ejemplo).","explain":"Se ordena por la primera palabra: Asociación, Equipo, Instituto, Morales.","type":"order","props":{"labels":{"start":"Primera","end":"Última"},"items":[{"id":"l1","text":"Asociación de Caficultores (2022). Guía del café de altura."},{"id":"l3","text":"Equipo didáctico (2026). Ficha B: Iluminación y uso racional."},{"id":"l2","text":"Instituto de Historia Local (2021). Mi municipio ayer y hoy."},{"id":"l4","text":"Morales, Ana (2020). Ciencias Naturales 6."}]},"id":"s08-l1-2-7"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","prompt":"Parafrasea este fragmento con tus palabras y nombra la fuente:\\n\\n\\"_Para los pueblos mayas, la ceiba es un árbol sagrado. En su visión del mundo, sus raíces llegan al inframundo, su tronco está en la tierra de los humanos y sus ramas tocan el cielo._\\" (Texto: \\"La ceiba: raíces que sostienen\\").","type":"short-answer","props":{"minWords":25,"placeholder":"Según…","model":"Según el texto \\"La ceiba: raíces que sostienen\\", los pueblos mayas consideran sagrada a la ceiba porque, en su forma de ver el mundo, une tres niveles: el inframundo, con sus raíces; la tierra donde vivimos, con su tronco; y el cielo, con sus ramas.","rubric":["Nombré la fuente (\\"Según…\\")","Escribí la idea con mis palabras, no cambiando solo una o dos","No cambié el sentido del original","No usé comillas (porque es paráfrasis)"]},"id":"s08-l1-2-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Cuál es una **cita textual** correcta?","type":"choice","props":{"options":[{"id":"a","text":"Mi abuela Juana dijo: \\"Tejí este güipil cuando tenía quince años\\"."},{"id":"b","text":"Tejí este güipil cuando tenía quince años."},{"id":"c","text":"Alguien dijo algo sobre un güipil."}],"correct":["a"]},"id":"s08-l1-2-9"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Parafrasear es explicar una idea con tus palabras y decir de dónde la tomaste.","answer":true},{"text":"Si cambio una palabra de un texto copiado, ya es una paráfrasis.","answer":false,"why":"Hay que reescribir la idea completa con tus palabras."},{"text":"La lista de fuentes va al final del informe.","answer":true}]},"id":"s08-l1-2-10"}],"kind":"materia","area":"l1","day":2}},{"missionId":"s08","version":"cnb-sexto-7cf4ac9e49ba9052","lesson":{"id":"s08-ef-1","title":"Juegos tradicionales: jugar como jugaban nuestros abuelos","icon":"Sparkles","minutes":15,"gancho":"Antes de los celulares, tus abuelos jugaban con un trompo, un capirucho, unos cincos o una cuerda. ¿Crees que esos juegos todavía pueden hacerte sudar y reír?","objetivos":["Conocer juegos tradicionales de Guatemala y sus reglas"],"resumen":["Los juegos tradicionales se transmiten de generación en generación, de abuelos a nietos. Usan materiales sencillos y muchas veces reutilizados.","Ejemplos en Guatemala: trompo, capirucho, cincos (canicas), tenta, salta cuerda, ronda con palmas y barrilete. Cada comunidad puede tener sus propios nombres y reglas.","Desarrollan habilidades: el capirucho y los cincos, la coordinación ojo-mano y la precisión; la tenta, la velocidad y los cambios de dirección; la cuerda, el ritmo y la resistencia; ronda con palmas, la fuerza y la cooperación.","Valorarlos es jugarlos, aprenderlos de las personas mayores, enseñarlos a los más pequeños y respetar sus reglas, que se acuerdan antes de jugar."],"media":{"id":"s08-ef-1-juegos","kind":"video","title":"Juegos de ayer y de hoy","aspect":"16:9","duration":60,"alt":"Un abuelo enseña a una niña a lanzar un trompo; niños juegan cincos en un círculo dibujado en la tierra; un grupo salta cuerda cantando; otro juega ronda con palmas sentados en fila.","brief":"Video de 60 s en un patio escolar despejado, con intérpretes autorizados. Escenas de 10 s con rótulo: (1) trompo con pita; (2) capirucho; (3) cincos en un círculo; (4) tenta con bases amplias; (5) cuerda individual e imaginaria; (6) ronda con palmas, con participantes de pie y sentados, separados por un brazo. Cierre con barriletes de papel exhibidos sin elevarlos cerca de cables. Música de marimba suave. Target: public/media/s08-ef-1-juegos.mp4. Accesibilidad: subtítulos completos, transcripción, demostración a velocidad lenta y descripción de cada adaptación."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Reglas de juegos tradicionales","prompt":"Lee qué se practica en estos juegos.","type":"explain","props":{"icon":"History","body":"Trompo, capirucho, cincos, tenta, cuerda y ronda con palmas conservan reglas culturales y practican habilidades motrices."},"id":"s08-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"¿Qué tienen en común el trompo, el capirucho y los cincos?","explain":"Son **juegos tradicionales**: se han jugado por generaciones, se aprenden de las personas mayores y usan materiales sencillos. Además, ¡todos entrenan tu precisión y coordinación!","type":"choice","props":{"options":[{"id":"a","text":"Son juegos tradicionales que se aprenden de generación en generación","icon":"History"},{"id":"b","text":"Son juegos electrónicos","icon":"Smartphone","feedback":"No necesitan electricidad: solo madera, pita, vidrio o barro."},{"id":"c","text":"Son deportes olímpicos","icon":"Medal","feedback":"No son deportes olímpicos: son juegos de la tradición popular."}],"correct":["a"]},"id":"s08-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Juegos tradicionales de Guatemala","prompt":"Mira el video y la lámina, y toca cada juego. Compara sus reglas con las tarjetas suministradas.","media":{"id":"s08-ef-1-objetos","kind":"image","title":"Los objetos de los juegos tradicionales","aspect":"4:3","alt":"Sobre un petate: un trompo de madera con su pita, un capirucho (palito y carrete unidos con pita), un puñado de cincos de vidrio, una cuerda larga y un barrilete pequeño de papel de china.","brief":"Fotografía cenital o ilustración realista sobre un petate: trompo de madera pintado con su pita enrollada, capirucho de madera (palito y carrete unidos con pita), cinco o seis cincos (canicas) de vidrio de colores, una cuerda de saltar larga enrollada y un barrilete pequeño de papel de china con cola de trapo. Cada objeto con su nombre en letra grande. Sin marcas comerciales. Target: public/media/s08-ef-1-objetos.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"History","body":"Cada comunidad tiene sus juegos. Estos son algunos de los más conocidos en Guatemala.","reveal":[{"icon":"RotateCw","front":"Trompo","back":"Se enrolla una pita en el trompo y se lanza para que **baile** en el suelo. Retos: que dure mucho, levantarlo bailando en la mano o sacar otros trompos de un círculo."},{"icon":"Target","front":"Capirucho","back":"Un carrete de madera unido con una pita a un palito. Se balancea el carrete para **embocarlo** en el palito. Entrena la **coordinación ojo-mano**."},{"icon":"CircleDot","front":"Cincos","back":"Canicas. Desde una línea, se impulsan con el pulgar para **sacar** los cincos de otros jugadores de un círculo dibujado en la tierra. Pide **precisión**."},{"icon":"Footprints","front":"Tenta","back":"Una persona \\"la lleva\\" y persigue a las demás; a quien toca, le pasa la tenta. Hay \\"bases\\" donde no te pueden tocar. Entrena **velocidad** y **cambios de dirección**."},{"icon":"Repeat","front":"Salta cuerda","back":"Dos personas dan vuelta a una cuerda larga y las demás entran a saltar, muchas veces **cantando** y contando. Entrena **ritmo** y **resistencia**."},{"icon":"Wind","front":"Barrilete","back":"Se construye con papel de china, varas y pita, y se vuela corriendo contra el viento. En noviembre, en Sumpango y Santiago Sacatepéquez se elevan **barriletes gigantes**."}]},"id":"s08-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","title":"¿Por qué valorarlos?","prompt":"Los juegos tradicionales son mucho más que pasar el rato. Toca cada tarjeta.","type":"explain","props":{"icon":"Heart","body":"Valorar un juego tradicional es **jugarlo, aprenderlo y enseñarlo**, para que no se pierda.","reveal":[{"icon":"Users","front":"Unen generaciones","back":"Abuelos, padres, madres y nietos pueden jugar juntos y compartir historias."},{"icon":"Landmark","front":"Son cultura","back":"Guardan canciones, palabras y formas de convivir de nuestros pueblos. Son parte de nuestra **identidad**."},{"icon":"Recycle","front":"Materiales sencillos","back":"Se hacen con madera, pita, papel, costales o piedritas: no hace falta dinero y se puede reutilizar."},{"icon":"Activity","front":"Mueven el cuerpo","back":"Correr, saltar, lanzar, equilibrarse: usan las mismas habilidades que aprendiste en esta unidad."}]},"id":"s08-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: jugar ronda con palmas de forma segura","prompt":"Mira cómo el grupo de Juan organiza el juego de **ronda con palmas** que le enseñó su abuela.","type":"worked-example","props":{"icon":"Music","problem":"Son 8 niñas y niños en un patio despejado. ¿Cómo hacen una ronda con palmas segura y adaptable?","steps":[{"text":"**Despejan el espacio:** retiran mochilas y dejan un brazo de distancia entre participantes."},{"text":"**Acuerdan una secuencia:** dos palmas propias, dos palmas al aire y un paso lateral."},{"text":"**Ensayan despacio:** nadie toma, empuja ni jala a otra persona.","why":"Cada participante controla su propio movimiento."},{"text":"**Cambian el liderazgo:** una persona marca cuatro pulsos y luego cede el turno."},{"text":"**Adaptan:** la secuencia puede hacerse de pie o sentada, con pasos, gestos o palmas suaves; cualquiera puede decir “alto”."}],"answer":"La ronda practica **ritmo, atención y cooperación** sin contacto riesgoso.","tip":"El ritmo se adapta a cada participante; la velocidad nunca vale más que el control."},"id":"s08-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"Une cada juego tradicional con la habilidad que más desarrolla.","hint":"Piensa en lo que el cuerpo tiene que hacer en cada juego.","explain":"Todos los juegos mueven el cuerpo, pero cada uno destaca una habilidad.","type":"match","props":{"leftTitle":"Juego","rightTitle":"Habilidad","pairs":[{"id":"c","left":"Capirucho","right":"Coordinación ojo-mano"},{"id":"t","left":"Tenta","right":"Velocidad y cambios de dirección"},{"id":"s","left":"Salta cuerda","right":"Ritmo y resistencia"},{"id":"a","left":"Ronda con palmas","right":"Ritmo y cooperación"}]},"id":"s08-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","prompt":"¡Feria de juegos tradicionales! **Calentamiento:** trote suave y rotaciones. **Estación 1 – Tenta (2 min):** con bases acordadas. **Estación 2 – Salta cuerda:** entra y salta 10 veces contando o cantando; si estás solo, cuerda individual. **Estación 3 – Precisión:** capirucho, trompo o cincos (si no tienes, lanza tapitas a un círculo dibujado en el suelo). **Poco espacio:** cuerda individual o imaginaria y tapitas a un círculo. **Adaptación:** en la tenta, quien use silla de ruedas puede \\"tentar\\" tocando con una pelota suave; en la cuerda, se puede pasar la cuerda por debajo de las ruedas o dar vuelta a la cuerda. **Vuelta a la calma:** estira y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la tenta","exercise":{"name":"Tenta con bases","icon":"Footprints","seconds":90}},{"label":"Después de salta cuerda y precisión","exercise":{"name":"Salta cuerda y juego de precisión","icon":"Repeat","seconds":90}}]},"id":"s08-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Tu abuelo te enseña a lanzar el trompo, pero tu primo dice: \\"Eso es de antes, es aburrido\\". ¿Qué respuesta muestra **valoración** de los juegos tradicionales?","explain":"Valorar es reconocer lo que el juego aporta (habilidad, cultura, convivencia) e invitar a otros a probarlo, con respeto por los gustos de cada quien.","type":"choice","props":{"options":[{"id":"a","text":"\\"Pruébalo: lanzar el trompo pide mucha precisión y así aprendemos lo que jugaba el abuelo\\""},{"id":"b","text":"\\"Tienes razón, los juegos viejos no sirven\\"","feedback":"Los juegos tradicionales siguen desarrollando habilidades y son parte de la cultura."},{"id":"c","text":"\\"Si no te gusta, eres un aburrido\\"","feedback":"Se puede invitar sin burlarse de los gustos de la otra persona."}],"correct":["a"]},"id":"s08-ef-1-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Lee la ficha suministrada de **Doña Blanca** sobre el juego tradicional de ronda con palmas y escribe una adaptación segura para poco espacio: regla, movimiento, señal de pausa y habilidad que conserva.","type":"short-answer","props":{"minWords":24,"placeholder":"Regla adaptada... Movimiento... Señal de pausa... Conserva la habilidad de...","model":"El grupo marca el círculo sin jalarse. Camina cuatro pasos con palmas y se detiene al oír “pausa”. Quien está afuera señala un espacio sin empujar. Conserva ritmo, orientación y cooperación.","rubric":["No incluye jalones ni empujones","Define señal de pausa","Explica la habilidad practicada"]},"id":"s08-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Cuál es un juego tradicional de Guatemala que desarrolla la **coordinación ojo-mano**?","type":"choice","props":{"options":[{"id":"a","text":"El capirucho"},{"id":"b","text":"Un videojuego de carreras"},{"id":"c","text":"Ver televisión"}],"correct":["a"]},"id":"s08-ef-1-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Los juegos tradicionales se transmiten de generación en generación.","answer":true},{"text":"En la ronda con palmas conviene empujar o jalar para seguir el ritmo.","answer":false,"why":"Cada persona controla sus movimientos y mantiene distancia; no se empuja ni se jala."},{"text":"Un mismo juego puede tener distintos nombres o reglas según la comunidad.","answer":true}]},"id":"s08-ef-1-11"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s08","version":"cnb-sexto-dcaecca8b40afd91","lesson":{"id":"s08-l2-1","title":"Sustantivo, adjetivo y verbo","icon":"Blocks","minutes":14,"gancho":"En \\"La abuela amable teje un güipil\\", cada palabra hace un trabajo distinto: una nombra, otra describe y otra dice la acción. ¿Cuál es cuál?","objetivos":["Clasificar sustantivos, adjetivos y verbos en observaciones y recomendaciones de un panel de energía"],"resumen":["Sustantivo: nombra personas, animales, lugares, cosas o ideas. Prueba: puedes ponerle \\"el, la, un, una\\" delante (la abuela, un güipil).","Adjetivo: dice cómo es el sustantivo. Prueba: responde \\"¿cómo es?\\" (amable, colorido). Concuerda con el sustantivo en género y número.","Verbo: dice la acción o el estado. Prueba: cambia con el tiempo (tejo, tejí, tejeré) y con la persona (yo tejo, ella teje).","Una misma palabra puede cambiar de clase según su oficio: \\"el canto\\" (sustantivo) / \\"yo canto\\" (verbo)."],"media":{"id":"s08-l2-1-oficios","kind":"animation","title":"Cada palabra tiene su oficio","aspect":"16:9","duration":45,"alt":"Una oración se arma con fichas de colores: los sustantivos en azul, los adjetivos en verde y los verbos en naranja.","brief":"Animación 2D de 45 s. Aparece la oración \\"La abuela amable teje un güipil colorido\\" en fichas separadas. Una lupa pasa por cada ficha: \\"abuela\\" y \\"güipil\\" se pintan de azul con el rótulo \\"SUSTANTIVO: nombra\\"; \\"amable\\" y \\"colorido\\" de verde con \\"ADJETIVO: dice cómo es\\"; \\"teje\\" de naranja con \\"VERBO: dice la acción\\". Luego \\"teje\\" cambia a \\"tejió\\" y \\"tejerá\\" para mostrar que el verbo cambia con el tiempo. Ilustración de una abuela tejiendo en telar de cintura, sin reproducir diseños sagrados específicos. Narración en español de Guatemala con subtítulos. Target: public/media/s08-l2-1-oficios.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Palabras con oficio en el panel","prompt":"Lee cómo clasificar palabras de una observación energética.","type":"explain","props":{"icon":"Tags","body":"En una observación de energía, el **sustantivo** nombra, el **adjetivo** describe y el **verbo** expresa acción o estado."},"id":"s08-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","prompt":"Lee esta observación del panel: _\\"La lámpara eficiente **ilumina** el aula.\\"_ ¿Qué trabajo hace **ilumina**?","explain":"\\"Ilumina\\" expresa la acción de la lámpara: es un verbo. En las observaciones del panel, los sustantivos nombran, los adjetivos describen y los verbos expresan acciones o estados.","type":"choice","props":{"options":[{"id":"a","text":"Expresa una acción","icon":"Zap"},{"id":"b","text":"Nombra el objeto","icon":"Lightbulb","feedback":"El sustantivo que nombra el objeto es “lámpara”."},{"id":"c","text":"Describe el objeto","icon":"Palette","feedback":"El adjetivo que describe la lámpara es “eficiente”."}],"correct":["a"]},"id":"s08-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Tres clases de palabras","prompt":"Para reconocer cada clase, usa su **prueba**. Toca cada tarjeta.","type":"explain","props":{"icon":"Blocks","body":"Fíjate en el **oficio** de la palabra en la oración: ¿nombra, describe o dice la acción?","reveal":[{"icon":"Tag","front":"Sustantivo","back":"**Nombra** personas, animales, lugares, cosas o ideas: abuela, perro, Cobán, mesa, alegría. **Prueba:** puedes decir \\"el, la, un, una\\" delante: la mesa, un perro."},{"icon":"Palette","front":"Adjetivo","back":"**Dice cómo es** el sustantivo: alto, amable, colorido, dulce. **Prueba:** responde \\"¿cómo es?\\". ¿Cómo es el güipil? Colorido."},{"icon":"Zap","front":"Verbo","back":"**Dice la acción** o el estado: corre, teje, duerme, está. **Prueba:** cambia con el tiempo (tejo, tejí, tejeré) y puedes decir \\"yo\\" o \\"ella\\" delante."},{"icon":"Languages","front":"Comparación responsable","back":"Los idiomas mayas tienen estructuras propias que deben revisarse con materiales validados y hablantes competentes. Esta actividad trabaja únicamente el corpus suministrado en español."}]},"id":"s08-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Lucía analiza una oración aplicando las pruebas.","type":"worked-example","props":{"icon":"Search","problem":"Oración: _\\"El volcán alto humea en la mañana.\\"_ ¿Cuáles son los sustantivos, el adjetivo y el verbo?","steps":[{"text":"**volcán**: puedo decir \\"el volcán\\" y nombra un lugar → **sustantivo**."},{"text":"**alto**: ¿cómo es el volcán? Alto → **adjetivo**.","why":"Acompaña al sustantivo \\"volcán\\" y dice cómo es."},{"text":"**humea**: puedo cambiarla de tiempo (humeó, humeará) → **verbo**."},{"text":"**mañana**: puedo decir \\"la mañana\\" → **sustantivo**.","why":"\\"El\\" y \\"la\\" (artículos) y \\"en\\" (preposición) son palabras de enlace: hoy no las clasificamos."}],"answer":"Sustantivos: **volcán, mañana**. Adjetivo: **alto**. Verbo: **humea**.","tip":"Si dudas, prueba: ¿le puedo poner \\"el/la\\"? ¿responde \\"¿cómo es?\\"? ¿cambia con el tiempo?"},"id":"s08-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: clasifica cada palabra según su clase.","hint":"Usa las pruebas: \\"el/la\\" delante → sustantivo; \\"¿cómo es?\\" → adjetivo; cambia con el tiempo → verbo.","explain":"Sustantivos: mercado, tomate, amistad. Adjetivos: maduro, generoso. Verbos: vender, cocinamos.","type":"sort","props":{"buckets":[{"id":"s","label":"Sustantivo","icon":"Tag","color":"var(--area-l2)"},{"id":"a","label":"Adjetivo","icon":"Palette","color":"var(--c-ok)"},{"id":"v","label":"Verbo","icon":"Zap","color":"var(--c-maiz-strong)"}],"items":[{"id":"w1","text":"mercado","bucket":"s"},{"id":"w2","text":"maduro","bucket":"a"},{"id":"w3","text":"vender","bucket":"v"},{"id":"w4","text":"tomate","bucket":"s"},{"id":"w5","text":"generoso","bucket":"a"},{"id":"w6","text":"cocinamos","bucket":"v"},{"id":"w7","text":"amistad","bucket":"s","feedback":"No se toca, pero puedes decir \\"la amistad\\": nombra una idea. Es sustantivo."}]},"id":"s08-l2-1-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Dos secretos de las clases de palabras","prompt":"Estas dos ideas te ayudarán a hablar y escribir mejor el español. Toca cada tarjeta.","type":"explain","props":{"icon":"Key","body":"El adjetivo es como la sombra del sustantivo: lo sigue en **género** y **número**.","reveal":[{"icon":"Link","front":"Concordancia","back":"El adjetivo cambia para ir con su sustantivo: **niño alto**, **niña alta**, **niños altos**, **niñas altas**. Error frecuente: \\"las casas bonito\\" → lo correcto es **\\"las casas bonitas\\"**."},{"icon":"RefreshCw","front":"La misma palabra, otro oficio","back":"\\"El **canto** del pájaro\\" → sustantivo (lleva \\"el\\"). \\"Yo **canto** en el coro\\" → verbo (dice la acción). Mira siempre el oficio en la oración."}]},"id":"s08-l2-1-6"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Toca todos los **verbos** de este texto.","hint":"Busca las palabras que dicen qué hace alguien. Son 5. Prueba cambiarlas de tiempo.","explain":"Llega, lleva, vende, compran y regresa dicen acciones. Si cambias el tiempo: llegó, llevó, vendió, compraron, regresó.","type":"highlight","props":{"target":"verbos","text":"El equipo {observa} el medidor del caso, {registra} la unidad, {compara} dos lecturas, {escribe} la fuente y {recomienda} apagar una lámpara innecesaria."},"id":"s08-l2-1-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Completa observaciones del panel con el **adjetivo** que concuerda.","explain":"Lámparas (femenino plural) → eficientes; medidor (masculino singular) → visible; lecturas (femenino plural) → comparables.","type":"fill-blank","props":{"text":"Las lámparas [[eficientes]] iluminan. El medidor [[visible]] registra datos. Las lecturas [[comparables]] usan la misma unidad.","distractors":["eficiente","visibles","comparable"]},"id":"s08-l2-1-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Toca todos los **adjetivos** de esta observación del panel de energía.","explain":"Encendida, vacío, exacta y visible describen lámpara, salón, lectura y fuente.","type":"highlight","props":{"target":"adjetivos","text":"Una lámpara {encendida} quedó en el salón {vacío}. La lectura {exacta} aparece junto a una fuente {visible}."},"id":"s08-l2-1-9"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Compara en el panel: _\\"El **registro** tiene fuente\\"_ y _\\"Yo **registro** la medición\\"_. ¿Qué clase de palabra es cada una?","explain":"\\"El registro\\" lleva artículo y nombra: sustantivo. \\"Registro la medición\\" expresa una acción: verbo.","type":"choice","props":{"options":[{"id":"a","text":"El primer “registro” es sustantivo y el segundo es verbo"},{"id":"b","text":"Las dos son verbos","feedback":"Mira la palabra que va antes del primer “registro”: “el”. Eso indica sustantivo."},{"id":"c","text":"El primero es adjetivo y el segundo es sustantivo","feedback":"El primer “registro” nombra y el segundo expresa la acción de registrar."}],"correct":["a"]},"id":"s08-l2-1-10"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Escribe dos observaciones para un panel de energía. Usa al menos **dos adjetivos** y **dos verbos**; clasifícalos al final.","type":"short-answer","props":{"minWords":20,"placeholder":"La lámpara eficiente... Adjetivos: ... Verbos: ...","model":"La lámpara eficiente ilumina el salón. El medidor visible registra una lectura exacta. Adjetivos: eficiente, visible, exacta. Verbos: ilumina, registra.","rubric":["Escribí observaciones del panel de energía","Usé dos adjetivos concordantes","Usé dos verbos","Clasifiqué las palabras correctamente"]},"id":"s08-l2-1-11"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.1"],"prompt":"En la observación del panel _\\"La lectura exacta muestra el consumo\\"_, ¿cuál es el **adjetivo**?","type":"choice","props":{"options":[{"id":"a","text":"lectura"},{"id":"b","text":"exacta"},{"id":"c","text":"muestra"},{"id":"d","text":"consumo"}],"correct":["b"]},"id":"s08-l2-1-12"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.1"],"prompt":"Clasifica palabras de nuevas observaciones del panel de energía: ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En “las lámparas eficientes”, lámparas es sustantivo y eficientes es adjetivo.","answer":true},{"text":"En “el equipo compara lecturas”, compara es un adjetivo.","answer":false,"why":"“Compara” expresa la acción: es verbo."},{"text":"En “fuentes visibles”, el adjetivo concuerda en plural con el sustantivo.","answer":true}]},"id":"s08-l2-1-13"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s08","version":"cnb-sexto-d4659c49ec4cd6f9","lesson":{"id":"s08-l1-3","title":"Tomar notas que sirvan","icon":"NotebookPen","minutes":14,"gancho":"Si copias toda la página en tu cuaderno, ¿estás tomando notas… o haciendo una fotocopia a mano?","objetivos":["Identificar la información que responde a una pregunta clave"],"resumen":["Tomar notas es escribir, con pocas palabras, solo la información importante que responde a tus preguntas clave.","Técnicas: palabras clave en lugar de oraciones completas, abreviaturas (aprox., pág.) y símbolos (→ produce, = es igual, + además).","Organiza tus notas por pregunta clave y anota siempre la fuente y la página.","Si copias una frase exacta, ponla entre comillas en tus notas para no confundirla después con tus palabras."],"media":{"id":"s08-l1-3-notas","kind":"image","title":"Una página de buenas notas","aspect":"3:4","alt":"Página de cuaderno dividida por preguntas clave; debajo de cada una hay pocas palabras, flechas y abreviaturas, y al margen la fuente y la página.","brief":"Ilustración de una página de cuaderno escrita a mano, ordenada. Título: \\"Notas del paquete: uso de lámparas\\". Tres bloques: \\"Dato exacto\\" → \\"12,468 kWh\\"; \\"Comparación\\" → \\"LED 9 W / incandescente 60 W\\"; \\"Recomendación\\" → \\"apagar luces sin uso\\". En el margen: \\"Ficha A, caso escolar simulado\\" y \\"Ficha B, guía científica suministrada\\". Una frase exacta entre comillas está marcada con un asterisco. Letra clara. Target: public/media/s08-l1-3-notas.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Notas que responden una pregunta","prompt":"Una nota útil conserva la idea, el dato y la fuente con pocas palabras.","type":"explain","props":{"icon":"NotebookPen","body":"Ejemplo: **geotermia = calor bajo tierra → electricidad (Ficha B)**. No copia todo ni pierde la idea central."},"id":"s08-l1-3-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Cómo tomar notas","prompt":"Las notas son tu **puente** entre las fuentes y tu informe. Mira la página modelo y toca cada tarjeta.","type":"explain","props":{"icon":"NotebookPen","body":"Toma notas **pensando en tus preguntas clave**: si una información no responde a ninguna, no la anotes.","reveal":[{"icon":"Key","front":"Palabras clave","back":"Escribe sustantivos, verbos y datos importantes, no oraciones completas: _luces vacías → apagar → menos consumo_."},{"icon":"Zap","front":"Símbolos","back":"**→** produce, lleva a · **=** es igual, significa · **+** además · **≠** es diferente · **c/** cada."},{"icon":"Scissors","front":"Abreviaturas","back":"_aprox._ (aproximadamente), _pág._ (página), _ej._ (ejemplo), _Guate._ (Guatemala). Usa siempre las mismas."},{"icon":"FolderOpen","front":"Ordénalas","back":"Una sección para **cada pregunta clave**. Al margen, la **fuente** y la **página**."},{"icon":"Quote","front":"Frases exactas","back":"Si copias una frase porque quieres citarla, ponla **entre comillas** en tus notas. Así, al escribir, sabrás que no son tus palabras."}]},"id":"s08-l1-3-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7","l1:8.2.7"],"ambito":"conocer","prompt":"Lee la **Ficha B del paquete de energía suministrado** pensando en esta pregunta: **\\"¿Qué recomendación está respaldada por la fuente?\\"**","media":{"id":"s08-l1-3-folleto-audio","kind":"audio","title":"Lectura: Iluminación y uso racional","duration":55,"alt":"Voz juvenil que lee la ficha suministrada sobre iluminación y ahorro de energía.","brief":"Audio de 55 s: voz juvenil, español de Guatemala, ritmo pausado, lee exactamente la ficha \\"Iluminación y uso racional\\" incluida en la lección. Hace una pausa después de cada dato. Sin música. Target: public/media/s08-l1-3-folleto-audio.mp3. Accesibilidad: transcripción completa visible junto al control y opción de repetir la pista."},"type":"reading","props":{"genre":"Ficha informativa suministrada","heading":"Ficha B: Iluminación y uso racional","passage":"Caso escolar simulado; no describe tu escuela. En una prueba preparada, una lámpara incandescente usó 60 W y una lámpara LED usó 9 W para una iluminación comparable. La potencia indica la rapidez con que un aparato usa energía; no equivale al consumo total de un mes.\\n\\nLa guía científica suministrada recomienda apagar las luces de espacios vacíos y aprovechar la luz natural cuando sea suficiente y seguro. También indica que una comparación debe mantener condiciones semejantes y registrar la unidad.\\n\\nEstos datos permiten recomendar revisar qué luces permanecen encendidas sin necesidad. No permiten afirmar cuánto ahorró una escuela real ni prometer una reducción exacta en su recibo.","questions":[{"q":"¿Qué recomendación está respaldada directamente por la ficha?","options":[{"id":"a","text":"Apagar las luces de espacios vacíos"},{"id":"b","text":"Afirmar que la escuela ya redujo su recibo"},{"id":"c","text":"Cambiar todas las instalaciones sin revisión"}],"correct":"a","why":"La ficha recomienda esa acción y no informa ahorros reales de una escuela."},{"q":"¿Qué comparación presenta la prueba preparada?","options":[{"id":"a","text":"60 W y 9 W con iluminación comparable"},{"id":"b","text":"Dos recibos reales de la escuela"},{"id":"c","text":"Dos meses con igual consumo"}],"correct":"a","why":"Son potencias de dos lámparas en un escenario suministrado."},{"q":"¿Qué no puede concluirse con estos datos?","options":[{"id":"a","text":"Cuánto ahorró una escuela real"},{"id":"b","text":"Que la unidad registrada es W"},{"id":"c","text":"Que se compararon dos lámparas"}],"correct":"a","why":"La ficha es simulada y no contiene mediciones ni recibos reales."}]},"id":"s08-l1-3-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Toma una **nota guiada**: toca solo la evidencia y el límite que respaldan la recomendación “apagar luces que no se usan”.","hint":"Marca la acción y el límite de lo que los datos permiten afirmar.","explain":"La ficha respalda apagar luces vacías y aclara que no demuestra un ahorro real o exacto.","type":"highlight","props":{"target":"evidencia y límite","text":"La guía recomienda {apagar las luces de espacios vacíos}. Estos datos {no permiten afirmar cuánto ahorró una escuela real} ni prometer una reducción exacta."},"id":"s08-l1-3-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: de la lectura a la nota","prompt":"Mira cómo Sofía convierte lo que marcó en una nota útil.","type":"worked-example","props":{"icon":"NotebookPen","problem":"Información marcada: “apagar luces de espacios vacíos” y “no permite afirmar un ahorro real”. Dato relacionado: LED 9 W / incandescente 60 W.","steps":[{"text":"Escribe la pregunta: **¿Qué recomendación respalda la fuente?**"},{"text":"Anota con palabras clave: **espacio vacío → apagar luz → evita uso innecesario**."},{"text":"Agrega el dato: **LED 9 W / incand. 60 W (condiciones comparables)**."},{"text":"Registra el límite: **≠ ahorro real medido**.","why":"Evita convertir un escenario didáctico en un resultado de la escuela."},{"text":"Al margen, cita: **Ficha B, paquete suministrado de energía**."}],"answer":"Luces vacías → apagar → evita uso innecesario · LED 9 W / incand. 60 W · ≠ ahorro real medido (Fuente: Ficha B suministrada)","tip":"Una buena nota se entiende una semana después. Léela en voz alta: si no la entiendes, agrégale una palabra."},"id":"s08-l1-3-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Une cada oración de una fuente con su **nota** abreviada.","explain":"Cada nota conserva los datos esenciales con palabras clave y símbolos.","type":"match","props":{"leftTitle":"Oración","rightTitle":"Nota","pairs":[{"id":"n1","left":"En las hidroeléctricas, el agua de los ríos mueve turbinas que producen electricidad.","right":"hidroeléctrica: agua ríos → turbinas → electricidad"},{"id":"n2","left":"El bagazo es lo que sobra de la caña de azúcar después de exprimirla.","right":"bagazo = restos caña exprimida"},{"id":"n3","left":"La ficha simulada registra 12,468 kWh en un mes.","right":"caso sim.: 12,468 kWh/mes"},{"id":"n4","left":"Los paneles solares y los aerogeneradores usan el sol y el viento.","right":"solar + viento → paneles y aerogeneradores"}]},"id":"s08-l1-3-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Toma **notas** de la Ficha B para: **\\"¿Qué podemos recomendar y qué no podemos afirmar?\\"** Usa palabras clave, al menos **dos símbolos** y anota la fuente.","type":"short-answer","props":{"minWords":15,"placeholder":"Recomendación → …\\nLímite ≠ …\\nFuente: …","model":"Recomendación → apagar luces en espacios vacíos + usar luz natural segura\\ncomparación: 60 W / 9 W con luz comparable\\n≠ ahorro real ni reducción exacta del recibo\\nFuente: Ficha B, paquete suministrado de energía.","rubric":["Anoté solo información que responde la pregunta","Usé palabras clave, no oraciones copiadas","Usé al menos dos símbolos (→, +, =)","Escribí la fuente"]},"id":"s08-l1-3-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"¿Qué **no** debe hacerse al tomar notas?","type":"choice","props":{"options":[{"id":"a","text":"Copiar párrafos completos sin comillas"},{"id":"b","text":"Usar símbolos como → o +"},{"id":"c","text":"Anotar la fuente y la página"}],"correct":["a"]},"id":"s08-l1-3-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"En unas notas nuevas, une cada símbolo o abreviatura con su significado.","type":"match","props":{"leftTitle":"Símbolo","rightTitle":"Significa","pairs":[{"id":"s1","left":"→","right":"produce, lleva a"},{"id":"s2","left":"=","right":"es igual, significa"},{"id":"s3","left":"pág.","right":"página"},{"id":"s4","left":"aprox.","right":"aproximadamente"}]},"id":"s08-l1-3-9"}],"kind":"materia","area":"l1","day":3}},{"missionId":"s08","version":"cnb-sexto-525d8de93168976e","lesson":{"id":"s08-ccss-3","title":"Resolver problemas y organizar una contribución simulada","icon":"Handshake","minutes":15,"gancho":"Dos grados quieren usar la cancha a la misma hora. Una aldea discute quién arregla el camino. ¿Existe un \\"método\\" para resolver problemas sin pelear?","objetivos":["Aplicar un procedimiento para resolver problemas con diálogo"],"resumen":["Procedimiento para resolver problemas: 1) identificar con claridad el problema, 2) escuchar a todas las partes, 3) proponer varias alternativas, 4) elegir juntos la mejor, 5) cumplir el acuerdo, 6) evaluar si funcionó.","Habilidades de la cultura de paz: escucha activa, empatía (ponerse en el lugar del otro), expresar lo que sientes sin herir (\\"yo me siento… cuando… porque…\\") y buscar soluciones en las que todos ganen.","Una contribución organizativa simulada permite practicar objetivos, responsabilidades y acuerdos dentro del aula sin afirmar un servicio externo realizado.","Las Ciencias Sociales ayudan a comprender problemas; el diálogo, la organización y la participación responsable ayudan a proponer respuestas."],"media":{"id":"s08-ccss-3-dialogo","kind":"video","title":"Mediación en el recreo","aspect":"16:9","duration":60,"alt":"Animación de dos grupos de estudiantes que discuten por la cancha; una compañera mediadora los ayuda a seguir los seis pasos y llegan a un acuerdo de horarios.","brief":"Animación 2D de 60 s. Escena 1: dos grupos de sexto grado discuten por usar la cancha a la hora del recreo. Escena 2: una compañera mediadora con un distintivo propone sentarse en círculo; en pantalla aparecen los pasos numerados mientras ocurren: identificar el problema, escuchar a cada grupo (burbujas de diálogo con frases \\"yo me siento… cuando…\\"), proponer alternativas (turnos por día, dividir la cancha, jugar juntos), elegir juntos, cumplir y evaluar una semana después. Escena 3: un calendario pegado en la pared con los turnos y ambos grupos jugando. Personajes diversos, narración en español con subtítulos. Target: public/media/s08-ccss-3-dialogo.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Resolver un caso con diálogo","prompt":"Lee el procedimiento antes de tomar una decisión.","type":"explain","props":{"icon":"MessagesSquare","body":"En una simulación suministrada se define el problema, se escuchan posiciones, se comparan alternativas y se registra un acuerdo."},"id":"s08-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Seis pasos para resolver problemas","prompt":"Este **procedimiento** sirve igual para un problema del recreo que para uno de la comunidad o del país. Toca cada tarjeta.","type":"explain","props":{"icon":"ListOrdered","body":"La clave es el **diálogo**: hablar y escuchar con respeto para llegar a un acuerdo que todos acepten.","reveal":[{"icon":"Search","front":"1. Identificar el problema","back":"Decir con claridad qué pasa, sin culpar: \\"Los dos grados queremos la cancha a la misma hora\\"."},{"icon":"Ear","front":"2. Escuchar a todas las partes","back":"Cada quien explica qué necesita y cómo se siente, sin interrupciones."},{"icon":"Lightbulb","front":"3. Proponer alternativas","back":"Pensar **varias** soluciones posibles, sin descartar ninguna al inicio."},{"icon":"Vote","front":"4. Elegir juntos","back":"Escoger la alternativa que sea más justa y posible para todos."},{"icon":"Handshake","front":"5. Cumplir el acuerdo","back":"Cada parte hace lo que se comprometió."},{"icon":"ClipboardCheck","front":"6. Evaluar","back":"Después de un tiempo, revisar: ¿se resolvió? Si no, volver a dialogar."}]},"id":"s08-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"En la aldea, dos familias discuten porque el agua de lluvia de un terreno se mete al otro. Ordena el **procedimiento** para resolverlo.","hint":"Primero entender, luego escuchar, después buscar opciones, decidir, cumplir y revisar.","explain":"El orden importa: si se elige una solución antes de escuchar a todos, alguna parte no la aceptará.","type":"order","props":{"items":[{"id":"r1","text":"Identificar el problema sin culpar"},{"id":"r2","text":"Escuchar a las dos partes con respeto"},{"id":"r3","text":"Proponer alternativas y elegir un acuerdo justo"},{"id":"r4","text":"Registrar responsabilidades y un criterio de revisión"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Habilidades para la cultura de paz","prompt":"Para dialogar bien se necesitan **habilidades sociales** que se practican como un deporte. Toca cada tarjeta.","type":"explain","props":{"icon":"HeartHandshake","body":"Nadie nace sabiendo dialogar: se aprende practicando en la casa, la escuela y la comunidad.","reveal":[{"icon":"Ear","front":"Escucha activa","back":"Mirar a quien habla, no interrumpir y repetir lo que entendiste: \\"Entonces tú dices que…\\"."},{"icon":"Heart","front":"Empatía","back":"**Ponerte en el lugar del otro**: ¿cómo me sentiría yo si me pasara eso?"},{"icon":"MessageCircle","front":"Mensaje \\"yo\\"","back":"Expresar lo que sientes sin atacar: \\"**Yo me siento** triste **cuando** no me dejan jugar **porque** también quiero participar\\". En vez de: \\"¡Ustedes son unos egoístas!\\"."},{"icon":"Handshake","front":"Ganar-ganar","back":"Buscar soluciones en las que **todas las partes** obtengan algo, no una que gana y otra que pierde."}]},"id":"s08-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"Tu hermano usó tu cuaderno sin permiso y lo manchó. ¿Cuál es un buen **mensaje \\"yo\\"**?","hint":"Un mensaje \\"yo\\" habla de lo que **tú sientes**, cuándo y por qué, sin insultar.","explain":"El mensaje \\"yo\\" dice cómo te sientes y por qué, sin atacar a la otra persona. Así es más fácil que te escuche y que lleguen a un acuerdo.","type":"choice","props":{"options":[{"id":"a","text":"\\"Me siento molesto cuando usas mis cosas sin pedirlas, porque las cuido mucho\\""},{"id":"b","text":"\\"¡Eres un desordenado y siempre arruinas todo!\\"","feedback":"Es un mensaje \\"tú\\" que ataca. Tu hermano se defenderá en vez de escucharte."},{"id":"c","text":"No decir nada y esconder todos mis cuadernos","feedback":"Callar guarda el enojo y el problema se repite. Es mejor expresarlo con respeto."}],"correct":["a"]},"id":"s08-ccss-3-5"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"emprender","title":"Del conflicto al acuerdo organizativo","prompt":"Una contribución organizativa puede practicarse con diálogo en un caso suministrado, sin intervenir fuera del aula.","type":"explain","props":{"icon":"HandHeart","body":"**Caso simulado; no describe tu escuela.** Dos grupos necesitan compartir la cancha y preparar un rótulo de ahorro de energía. Primero escuchan sus necesidades; luego acuerdan turnos y responsabilidades en papel.","reveal":[{"icon":"Users","front":"Dialogar y acordar","back":"Definir el conflicto, escuchar a ambos grupos, comparar alternativas y repartir tareas aceptadas."},{"icon":"ShieldCheck","front":"Ser honesto","back":"Registrar “simulación de aula” y no afirmar que el acuerdo ya se aplicó fuera de la lección."}]},"id":"s08-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"emprender","prompt":"**Caso suministrado: simulación de aula.** Organiza en papel la contribución del grupo para resolver el uso simultáneo de la cancha y preparar un rótulo de ahorro. No observes un problema local, no consultes personas ni realices un servicio externo.","type":"project","props":{"goal":"Completar una contribución organizativa simulada mediante diálogo y reparto justo de tareas.","steps":[{"title":"Define","detail":"Escribe el problema y las necesidades de ambos grupos dadas en la tarjeta."},{"title":"Acuerda","detail":"Elige turnos justos y asigna quién redacta, quién revisa y quién coloca el rótulo solo dentro del escenario."},{"title":"Registra","detail":"Marca el producto como propuesta simulada y anota un criterio para revisarlo en clase."}],"evidence":"Hoja revisable con problema suministrado, acuerdo, responsabilidades y rótulo de simulación.","rubric":["Usé solo el caso suministrado","Distribuí responsabilidades con justicia","No afirmé un servicio externo realizado"]},"id":"s08-ccss-3-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"En la simulación, dos personas rechazan la tarea asignada. ¿Qué decisión organizativa tomas?","type":"dilemma","props":{"scene":{"icon":"Users","text":"Una persona no puede dibujar el rótulo y otra prefiere no exponer oralmente. El acuerdo debe ofrecer tareas accesibles."},"options":[{"id":"a","icon":"MessagesSquare","text":"Escuchar y reasignar revisión, escritura o lectura según posibilidades","consequence":"El acuerdo conserva el objetivo y permite una contribución accesible.","values":["diálogo","empatía","cooperación"],"constructive":true},{"id":"b","icon":"Megaphone","text":"Obligar a mantener las tareas iniciales","consequence":"La organización ignora necesidades y debilita el acuerdo.","values":[],"constructive":false}]},"id":"s08-ccss-3-8"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"Completa de manera independiente la contribución organizativa del caso simulado: ordena las decisiones del acuerdo.","explain":"Definir el problema, escuchar, acordar responsabilidades accesibles y registrar que es una simulación produce evidencia realizable en clase.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"a1","text":"Definir el problema suministrado sin culpar","icon":"Search"},{"id":"a2","text":"Escuchar las necesidades de las partes del caso","icon":"Ear"},{"id":"a3","text":"Acordar turnos y responsabilidades accesibles","icon":"Handshake"},{"id":"a4","text":"Registrar “contribución organizativa simulada”","icon":"FileText"}]},"id":"s08-ccss-3-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.2.1"],"prompt":"Ordena los pasos para resolver un problema con diálogo.","type":"order","props":{"items":[{"id":"p1","text":"Identificar el problema"},{"id":"p2","text":"Escuchar a todas las partes"},{"id":"p3","text":"Proponer alternativas"},{"id":"p4","text":"Elegir juntos una solución"},{"id":"p5","text":"Cumplir el acuerdo"},{"id":"p6","text":"Evaluar el resultado"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-ccss-3-10"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.2.1"],"prompt":"Caso simulado: dos equipos necesitan la misma mesa para terminar sus paneles y surge un conflicto. ¿Qué acción aplica el procedimiento de diálogo para llegar a un acuerdo?","type":"choice","props":{"options":[{"id":"a","text":"Escuchar qué necesita cada equipo, proponer dos turnos y acordar responsabilidades"},{"id":"b","text":"Dar la mesa al equipo que hable más fuerte sin escuchar al otro"},{"id":"c","text":"Cancelar ambos paneles sin identificar el problema"}],"correct":["a"]},"id":"s08-ccss-3-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ccss"],"cnb":[],"type":"reflection","props":{"statements":["Leo datos para identificar problemas mundiales","Explico por qué pagar impuestos y pedir factura es una responsabilidad ciudadana","Resuelvo problemas con diálogo y sé organizar una actividad de servicio"],"commitments":["Registraré con honestidad cuándo una contribución es simulada","Usaré un mensaje \\"yo\\" la próxima vez que dialogue","Pediré factura cuando acompañe a mi familia a comprar"]},"id":"s08-ccss-3-12"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s08","version":"cnb-sexto-a7bf23f9ddbafa7c","lesson":{"id":"s08-l3-2","title":"Helen Keller: a life of courage","icon":"HandHeart","minutes":15,"gancho":"Imagina que no puedes ver ni oír. ¿Cómo relacionarías una palabra con lo que tocas? Helen Keller logró esa comprensión con la mano.","objetivos":["Leer y comprender la biografía de Helen Keller"],"resumen":["Helen Keller nació en 1880 en Alabama, Estados Unidos. Cuando era bebé, una enfermedad la dejó sin poder ver ni oír.","Su maestra, Anne Sullivan, le enseñó a comunicarse deletreando letras en la palma. El momento de “water” fue un avance conceptual: comprendió que las palabras nombran las cosas.","En 1904 se graduó de la universidad (Radcliffe College). Escribió libros y viajó por el mundo apoyando a personas con discapacidad. Murió en 1968.","El inglés se habla en muchos países: Estados Unidos, Reino Unido, Canadá, Australia, Irlanda… y en Belice, nuestro vecino."],"media":{"id":"s08-l3-2-water","kind":"image","title":"Water!","aspect":"4:3","alt":"Ilustración de una niña de unos 6 años con la mano bajo el chorro de una bomba de agua; su maestra le escribe letras en la otra mano.","brief":"Ilustración cálida estilo libro infantil, época de 1880 (vestidos largos, jardín con una bomba de agua manual). Una niña de unos 6 años con los ojos cerrados y una expresión de descubrimiento pone una mano bajo el chorro de agua; una maestra joven, arrodillada a su lado, le forma letras con los dedos en la palma de la otra mano. Letras W-A-T-E-R flotando suavemente sobre la escena. Ilustración original, no basada en fotografías reales. Target: public/media/s08-l3-2-water.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"A life in chronological order","prompt":"Read the supplied chronology before answering.","type":"explain","props":{"icon":"CalendarDays","body":"Use the supplied fact card to locate birth, learning, achievements and death before answering about a biography."},"id":"s08-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","prompt":"Mira la imagen de la lección. La maestra forma letras en la mano de la niña mientras el agua cae en su otra mano. ¿Qué crees que le está enseñando?","explain":"Le enseña que las letras **W-A-T-E-R** forman el nombre de lo que siente en la mano: **water** (agua). Esa niña era Helen Keller, y hoy leerás su biografía.","type":"choice","props":{"options":[{"id":"a","text":"Que las letras que siente forman la palabra \\"agua\\"","icon":"Droplets"},{"id":"b","text":"A lavarse las manos","icon":"Hand","feedback":"Es una buena idea, pero fíjate en las letras que forma la maestra en su mano."},{"id":"c","text":"A dibujar","icon":"Pencil","feedback":"No hay lápiz ni papel: la maestra usa la mano de la niña para formar letras."}],"correct":["a"]},"id":"s08-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"English around the world","prompt":"Neil Armstrong y Helen Keller nacieron en los Estados Unidos. Pero el inglés se habla en muchos lugares. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Aprender inglés te permite leer las historias de personas de muchas culturas… ¡y contar las nuestras!","reveal":[{"icon":"Globe","front":"Países donde es idioma principal","back":"Estados Unidos, Reino Unido, Canadá (junto con el francés), Australia, Irlanda y Nueva Zelanda, entre otros."},{"icon":"MapPin","front":"Muy cerca de Guatemala","back":"En **Belice**, nuestro país vecino, el idioma oficial es el **inglés**, y también se hablan español, kriol, garífuna y idiomas mayas."},{"icon":"Users","front":"Muchas culturas","back":"Cada país tiene sus propios personajes famosos: científicos, escritoras, deportistas, artistas. Sus biografías cuentan cómo vivían y qué lograron."}]},"id":"s08-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"Key words","prompt":"Estas palabras te ayudarán a leer la biografía. Léelas en voz alta y voltea cada tarjeta.","type":"flashcards","props":{"cards":[{"icon":"EyeOff","front":"blind","back":"ciega/o: que no puede ver"},{"icon":"VolumeX","front":"deaf","back":"sorda/o: que no puede oír"},{"icon":"Pill","front":"illness","back":"enfermedad"},{"icon":"Hand","front":"palm","back":"palma de la mano"},{"icon":"PenLine","front":"to spell","back":"deletrear, formar una palabra letra por letra"},{"icon":"GraduationCap","front":"to graduate","back":"graduarse"},{"icon":"HandHeart","front":"disability","back":"discapacidad"}]},"id":"s08-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","title":"Biography","prompt":"Escucha y lee la biografía. Usa las tarjetas si olvidas una palabra.","media":{"id":"s08-l3-2-keller","kind":"audio","title":"Helen Keller (biography)","duration":55,"alt":"Una voz en inglés lee la biografía de Helen Keller.","brief":"Audio de 55 s. Voz adulta femenina, inglés claro y lento, tono cálido, sin música. Leer los años como en inglés (eighteen eighty, eighteen eighty-seven, nineteen oh-four, nineteen sixty-eight). Texto exacto: \\"Helen Keller was born in 1880 in Alabama, in the United States. When she was a baby, an illness left her blind and deaf. She could not see or hear. In 1887, a teacher named Anne Sullivan came to live with her family. Anne spelled words into Helen's palm. One day, Anne put Helen's hand under running water and spelled W-A-T-E-R. Helen understood: everything has a name! Helen studied very hard. In 1904, she graduated from college. She wrote books and traveled around the world to help people with disabilities. She died in 1968. Her life shows that courage and good teachers can change the world.\\" Target: public/media/s08-l3-2-keller.mp3. Accesibilidad: transcripción completa disponible después de responder y control para repetir la pista."},"type":"reading","props":{"genre":"Biography","heading":"Helen Keller","passage":"Helen Keller was born in 1880 in Alabama, in the United States. When she was a baby, an illness left her blind and deaf. She could not see or hear.\\n\\nIn 1887, a teacher named Anne Sullivan came to live with her family. Anne spelled words into Helen's palm. One day, Anne put Helen's hand under running water and spelled W-A-T-E-R. Helen understood: everything has a name!\\n\\nHelen studied very hard. In 1904, she graduated from college. She wrote books and traveled around the world to help people with disabilities. She died in 1968.\\n\\nHer life shows that courage and good teachers can change the world.","questions":[{"q":"Where was Helen Keller born?","options":[{"id":"a","text":"In Alabama, in the United States"},{"id":"b","text":"In Ohio"},{"id":"c","text":"In England"}],"correct":"a"},{"q":"Who was Anne Sullivan?","options":[{"id":"a","text":"Helen's teacher"},{"id":"b","text":"Helen's sister"},{"id":"c","text":"A doctor"}],"correct":"a"},{"q":"¿Qué descubrió Helen el día del agua?","options":[{"id":"a","text":"Que cada cosa tiene un nombre, y que las letras en su mano lo formaban"},{"id":"b","text":"Que ya podía ver"},{"id":"c","text":"Que no le gustaba el agua"}],"correct":"a","why":"\\"Helen understood: everything has a name!\\" Descubrió que las palabras nombran las cosas."},{"q":"¿Qué enseñanza deja su vida, según el texto?","options":[{"id":"a","text":"Con valentía y buenos maestros se pueden lograr grandes cosas"},{"id":"b","text":"Las personas con discapacidad no pueden estudiar"},{"id":"c","text":"Es mejor no ir a la universidad"}],"correct":"a","why":"La última oración lo dice: \\"courage and good teachers can change the world\\". Helen estudió, se graduó y ayudó a otros."}]},"id":"s08-l3-2-5"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ordena la línea de tiempo de Helen Keller.","hint":"Mira los años del texto: 1880, 1887, 1904, 1968. El día del agua pasó después de que llegó Anne.","explain":"Nació (1880) → enfermedad cuando era bebé → llegó Anne Sullivan (1887) → aprendió \\"water\\" → se graduó (1904) → murió (1968).","type":"order","props":{"labels":{"start":"First","end":"Last"},"items":[{"id":"o1","text":"Helen was born in Alabama.","icon":"Baby"},{"id":"o2","text":"An illness left her blind and deaf.","icon":"EyeOff"},{"id":"o3","text":"Anne Sullivan came to live with her family.","icon":"User"},{"id":"o4","text":"Helen learned the word \\"water\\".","icon":"Droplets"},{"id":"o5","text":"She graduated from college.","icon":"GraduationCap"},{"id":"o6","text":"She died in 1968.","icon":"Flower"}]},"id":"s08-l3-2-6"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","title":"Worked example: a mini-biography","prompt":"Con las frases de las biografías puedes escribir la historia de alguien que admiras. Mira cómo lo hace Isabel sobre su abuela.","type":"worked-example","props":{"icon":"PenLine","problem":"Isabel quiere escribir una mini-biografía de su abuela Juana, que nació en Totonicapán en 1958, fue maestra y es famosa en su aldea por enseñar a leer a muchos adultos.","steps":[{"text":"Nacimiento: **My grandmother Juana was born in Totonicapán in 1958.**","why":"Was born in + lugar + año."},{"text":"Lo que llegó a ser: **She became a teacher.**"},{"text":"Por qué es admirada: **She is famous in our village for teaching many adults to read.**"},{"text":"Cierre con tu opinión: **I admire her because she is kind and brave.**","why":"Admire = admirar. Because = porque."}],"answer":"**My grandmother Juana was born in Totonicapán in 1958. She became a teacher. She is famous in our village for teaching many adults to read. I admire her because she is kind and brave.**","tip":"Nacimiento → qué llegó a ser → por qué es importante → por qué la admiras."},"id":"s08-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"According to the biography, true or false?","type":"true-false","props":{"statements":[{"text":"Helen Keller was blind and deaf.","answer":true},{"text":"Anne Sullivan spelled words into Helen's palm.","answer":true},{"text":"Helen never went to college.","answer":false,"why":"\\"In 1904, she graduated from college.\\""},{"text":"Helen helped people with disabilities.","answer":true}]},"id":"s08-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"Usa esta **fact card ficticia suministrada**: Elena Cruz, persona ficticia · born in Quetzaltenango, 1986 · became an electrical engineer, 2010 · designed school solar projects · received a teaching award, 2022. Escribe una mini-biografía en inglés de 3 oraciones. No agregues fechas que no aparecen.","type":"short-answer","props":{"minWords":20,"placeholder":"Elena Cruz, persona ficticia, was born... She became...","model":"Elena Cruz, persona ficticia, was born in Quetzaltenango in 1986. She became an electrical engineer in 2010 and designed school solar projects. She received a teaching award in 2022.","rubric":["Uso solo los hechos suministrados","Escribo tres oraciones en orden","Uso was born y became correctamente"]},"id":"s08-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:5.2.2"],"prompt":"Boleto de salida: ¿quién le enseñó a Helen Keller a comunicarse?","type":"choice","props":{"options":[{"id":"a","text":"Anne Sullivan, su maestra"},{"id":"b","text":"Neil Armstrong"},{"id":"c","text":"Su hermano"}],"correct":["a"]},"id":"s08-l3-2-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:5.2.2"],"prompt":"Completa en inglés: \\"Helen Keller nació en 1880. Se graduó de la universidad en 1904.\\"","type":"fill-blank","props":{"text":"Helen Keller [[was born]] in 1880. She [[graduated]] from college in 1904.","distractors":["died","became"]},"id":"s08-l3-2-11"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"We finished the unit! ¿Cómo te fue?","type":"reflection","props":{"statements":["Leo y comprendo una biografía sencilla en inglés","Leo años en inglés","Escribo una mini-biografía con was born, became y is famous for","En esta unidad aprendí a ubicar cosas, comprar, contar lo que viví, seguir instrucciones y describir el pasado en inglés"],"commitments":["Leeré la biografía de otra persona famosa de un país donde se habla inglés","Compartiré con mi familia la mini-biografía que escribí","Seguiré practicando inglés un poco cada día"]},"id":"s08-l3-2-12"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s08","version":"cnb-sexto-7ec4e2250a1fdf44","lesson":{"id":"s08-art-2","title":"Publicar lo investigado: periódico mural y foro","icon":"Newspaper","minutes":15,"gancho":"Ya investigaste la vida de un artista. Si esa información se queda en tu cuaderno, solo tú la conoces. ¿Cómo la compartirías con toda la escuela y la comunidad?","objetivos":["Publicar y compartir una ficha biográfica breve, verificable y legible"],"resumen":["Publicar es dar a conocer una investigación. Formas escolares: ficha biográfica, periódico mural, foro o presentación oral.","Una ficha biográfica tiene: nombre, imagen o dibujo, origen, formación, obras, aporte, un dato curioso y fuentes.","Un periódico mural tiene un título grande, secciones ordenadas, textos breves, imágenes con pie de foto y las fuentes de cada texto. Se aplican las reglas del cartel: contraste, letras legibles y espacio libre.","En un foro, cada persona presenta en poco tiempo, habla claro, escucha sin interrumpir y responde preguntas con respeto. Se publica solo lo que la persona entrevistada autorizó."],"media":{"id":"s08-art-2-periodico","kind":"image","title":"Un periódico mural de artistas","aspect":"4:3","alt":"Un periódico mural en el corredor de una escuela con el título \\"Artistas de nuestra tierra\\", cuatro fichas biográficas con dibujos, pies de foto y una franja de fuentes abajo.","brief":"Ilustración de un periódico mural escolar sobre un tablero de corcho en un corredor de escuela pública guatemalteca. Título grande \\"Artistas de nuestra tierra\\" con letras recortadas. Cuatro fichas con dibujos (no fotos reales): un marimbista de pueblo, una tejedora, un poeta, un compositor del siglo XIX. Cada ficha con subtítulos (Origen, Obras, Aporte), un pie de foto y un recuadro \\"Fuentes\\". Una sección \\"¿Sabías que…?\\" y un buzón de preguntas. Colores con buen contraste, orden en columnas, espacio libre entre fichas. Target: public/media/s08-art-2-periodico.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","title":"Publicar una biografía artística","prompt":"Lee el propósito de una ficha biográfica.","type":"explain","props":{"icon":"Newspaper","body":"Una ficha biográfica publica vida, obra, aporte e imagen con pie, y mantiene visibles las fuentes."},"id":"s08-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","prompt":"Observa el periódico mural. ¿Qué elemento permite a los lectores **comprobar** que la información es cierta?","explain":"La franja de **fuentes**. Publicar con fuentes demuestra un trabajo serio y respetuoso.","type":"choice","props":{"options":[{"id":"a","text":"El título grande","icon":"Type","feedback":"El título atrae la atención, pero no permite comprobar los datos."},{"id":"b","text":"Los dibujos de colores","icon":"Palette","feedback":"Los dibujos ilustran, pero no dicen de dónde salió la información."},{"id":"c","text":"Las fuentes al pie de cada ficha","icon":"BookOpen"}],"correct":["c"]},"id":"s08-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","title":"Tres formas de publicar","prompt":"**Publicar** es dar a conocer tu investigación a otras personas. En la escuela puedes hacerlo de tres formas. Toca cada tarjeta.","type":"explain","props":{"icon":"Megaphone","body":"Elige la forma según tu público y tu espacio. Pueden combinarse.","reveal":[{"icon":"FileText","front":"Ficha biográfica","back":"Una hoja con **nombre, imagen, origen, formación, obras, aporte, dato curioso y fuentes**. Es la base de las otras dos."},{"icon":"Newspaper","front":"Periódico mural","back":"Varias fichas y textos organizados en un tablero o pared, con **título**, **secciones** e **imágenes con pie de foto**."},{"icon":"MessagesSquare","front":"Foro","back":"Una reunión donde cada persona **presenta** brevemente su investigación y el público **pregunta** y comenta con respeto."}]},"id":"s08-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"hacer","title":"Cómo armar el periódico mural","prompt":"Un periódico mural es también una **obra gráfica**: usa lo que aprendiste sobre carteles. Toca cada paso.","type":"explain","props":{"icon":"Newspaper","body":"Recuerda las reglas del cartel: **contraste**, **letras legibles** y **espacio libre**.","reveal":[{"icon":"Type","front":"1. Título","back":"Grande, arriba y legible de lejos: \\"Artistas de nuestra tierra\\"."},{"icon":"LayoutGrid","front":"2. Secciones","back":"Organiza en columnas: artistas de la **comunidad**, del **país** y del **mundo**. Deja espacio entre fichas."},{"icon":"Image","front":"3. Imágenes","back":"Dibujos o fotos **con permiso**, cada una con un **pie de foto**: quién es y qué hace."},{"icon":"BookOpen","front":"4. Fuentes","back":"Debajo de cada ficha, la lista de fuentes. Así cualquier persona puede comprobar."},{"icon":"MessageCircle","front":"5. Participación","back":"Agrega un buzón o una hoja de \\"Preguntas y comentarios\\" para que el público participe."}]},"id":"s08-art-2-4"},{"fase":"construir","areas":["art","l1"],"cnb":["art:4.3.2"],"ambito":"hacer","title":"Ejemplo resuelto: de las notas a la ficha publicada","prompt":"Mira cómo Pedro transforma las notas de su entrevista en una ficha para el periódico mural. (La artista es un ejemplo inventado.)","type":"worked-example","props":{"icon":"NotebookPen","problem":"Supongamos que Pedro entrevistó a **doña Tomasa**, marimbista de su aldea, de 68 años. Sus notas están desordenadas y muy largas. ¿Cómo las convierte en una ficha?","steps":[{"text":"**Pide permiso** otra vez: \\"¿Puedo publicar su nombre, su edad y un dibujo suyo en la escuela?\\". Doña Tomasa acepta, pero pide que no se ponga su dirección.","why":"Se publica solo lo que la persona autoriza."},{"text":"**Selecciona** lo más importante: aprendió marimba a los 10 años con su padre; toca en las fiestas patronales desde hace 50 años; enseña gratis a niñas y niños los sábados."},{"text":"**Redacta** en oraciones cortas bajo cada subtítulo: Origen, Formación, Obras, Aporte, ¿Sabías que…?"},{"text":"**Ilustra** con un dibujo de doña Tomasa tocando, con pie de foto: \\"Doña Tomasa en la fiesta patronal\\"."},{"text":"**Cierra** con la fuente: \\"Entrevista a doña Tomasa, marimbista, 12 de marzo\\"."}],"answer":"Una ficha **breve, ordenada, ilustrada, con fuente y con permiso** de la persona.","tip":"Pide a alguien que lea tu ficha antes de publicarla: si entiende todo en un minuto, está lista."},"id":"s08-art-2-5"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"hacer","prompt":"Ordena los pasos para **publicar** una investigación biográfica.","hint":"Primero se investiga, luego se organiza, después se comparte.","explain":"Investigar con permiso → seleccionar y redactar → ilustrar y citar fuentes → montar el periódico mural → presentar en el foro.","type":"order","props":{"items":[{"id":"a","text":"Investigar con preguntas guía y pedir permiso"},{"id":"b","text":"Seleccionar lo más importante y redactar la ficha"},{"id":"c","text":"Ilustrar y agregar las fuentes"},{"id":"d","text":"Montar el periódico mural"},{"id":"e","text":"Presentar en el foro y responder preguntas"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-art-2-6"},{"fase":"aplicar","areas":["art","fc"],"cnb":[],"ambito":"convivir","prompt":"Antes del foro biográfico, elige cómo escucharás una obra o trayectoria distinta de tus gustos sin calificar esta reflexión.","type":"reflection","props":{"statements":["Escucharé la presentación completa antes de opinar","Comentaré con respeto y razones"],"commitments":["Cuidaré que el foro no convierta una preferencia en burla"]},"id":"s08-art-2-7"},{"fase":"aplicar","areas":["art","l1"],"cnb":["art:4.3.2"],"ambito":"hacer","prompt":"Publica una **ficha biográfica con obra y fuente visible**, y guárdala para compartirla como evidencia docente. Usa solo el paquete suministrado: Humberto Ak’abal · nació en Momostenango en 1952 · poeta k’iche’ · escribió en k’iche’ y español · murió en 2019. No afirmes una exposición externa.","type":"short-answer","props":{"minWords":24,"placeholder":"Humberto Ak’abal… Obra… Aporte… Fuente: paquete suministrado…","model":"Humberto Ak’abal nació en Momostenango en 1952. Fue poeta k’iche’ y escribió en k’iche’ y español. Su obra difundió esa poesía. Fuente: paquete biográfico suministrado.","rubric":["Publico origen, obra y aporte","Uso solo el paquete suministrado","Dejo visible la fuente"]},"id":"s08-art-2-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","prompt":"¿Qué jerarquía visual ayuda a leer la ficha biográfica sin convertir la decoración en evidencia?","explain":"El nombre funciona como título; los hitos y la obra se agrupan en bloques breves; la fuente queda visible. La decoración no reemplaza los datos.","type":"choice","props":{"options":[{"id":"a","text":"Nombre destacado, hitos ordenados, imagen con pie y fuente visible"},{"id":"b","text":"Un título decorativo enorme y todos los datos en letra mínima","feedback":"La información queda subordinada a la decoración y no puede leerse."},{"id":"c","text":"Una imagen sin pie y hechos sin fuente","feedback":"La ficha pierde contexto y verificabilidad."}],"correct":["a"]},"id":"s08-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:4.3.2"],"prompt":"Publica y guarda una ficha biográfica con obra y fuente: ordena el procedimiento para una artista ficticia con datos verificados.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"e1","text":"Seleccionar un hecho respaldado por el paquete"},{"id":"e2","text":"Redactar origen, obra y aporte con claridad"},{"id":"e3","text":"Agregar la fuente visible"},{"id":"e4","text":"Guardar la ficha para compartirla como evidencia docente"}]},"id":"s08-art-2-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:4.3.2"],"prompt":"Al publicar y compartir otra ficha biográfica con obra y fuente visible, ¿qué decisión evita convertir decoración en evidencia?","type":"choice","props":{"options":[{"id":"a","text":"Guardar origen, obra, aporte y fuente en campos legibles"},{"id":"b","text":"Compartir solo un dibujo sin datos"},{"id":"c","text":"Ocultar la fuente para ganar espacio"}],"correct":["a"]},"id":"s08-art-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:4.3.2"],"type":"reflection","props":{"statements":["Investigo la vida de un artista con preguntas guía y fuentes confiables","Publico una ficha biográfica clara y con fuentes","Presento y escucho con respeto en un foro"],"commitments":["Publicaré mi ficha en el periódico mural","Agradeceré a la persona que entrevisté","Seguiré descubriendo artistas de mi comunidad"]},"id":"s08-art-2-12"}],"kind":"materia","area":"art","day":4}},{"missionId":"s08","version":"cnb-sexto-36da2b14baec4532","lesson":{"id":"s08-l2-2","title":"Familias de sustantivos","icon":"Tag","minutes":15,"gancho":"\\"Pedro\\", \\"niño\\", \\"grupo\\" y \\"amistad\\" son sustantivos. Pero ¿verdad que no se parecen mucho? Cada uno pertenece a una familia distinta.","objetivos":["Clasificar sustantivos de fuentes, mediciones y recomendaciones en tres pares de familias"],"resumen":["Común: nombra cualquier ser de su clase (río, niña). Propio: nombra a uno en particular y se escribe con mayúscula (Motagua, Rosa).","Individual: nombra a uno solo (oveja). Colectivo: en singular nombra a un grupo (rebaño).","Concreto: se percibe con los sentidos (tortilla, lluvia). Abstracto: nombra ideas o sentimientos que no se tocan (paz, alegría).","Un mismo sustantivo pertenece a varias familias a la vez: \\"rebaño\\" es común, colectivo y concreto."],"media":{"id":"s08-l2-2-familias","kind":"diagram","title":"Tres parejas de familias","aspect":"16:9","alt":"Tres columnas: común y propio (río / Motagua), individual y colectivo (oveja / rebaño), concreto y abstracto (tortilla / alegría), cada una con un dibujo.","brief":"Infografía horizontal en tres columnas de colores suaves. Columna 1 \\"¿A cualquiera o a uno en particular?\\": dibujo de un río genérico con la palabra \\"río\\" (común) y el mismo río con un cartel \\"Motagua\\" en mayúscula destacada (propio). Columna 2 \\"¿Uno o un grupo?\\": una oveja sola \\"oveja\\" (individual) y un grupo de ovejas con un pastor \\"rebaño\\" (colectivo). Columna 3 \\"¿Se percibe con los sentidos?\\": una tortilla humeante con íconos de ojo, mano y nariz \\"tortilla\\" (concreto) y dos niños abrazándose con un corazón \\"alegría\\" (abstracto). Letras grandes y legibles, fondo claro. Target: public/media/s08-l2-2-familias.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","title":"Familias de sustantivos del informe","prompt":"Lee cómo clasificar los sustantivos del corpus energético.","type":"explain","props":{"icon":"Tags","body":"Los sustantivos de fuentes, mediciones y recomendaciones pueden ser común o propio, individual o colectivo, concreto o abstracto."},"id":"s08-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","prompt":"Tu amigo escribió: _\\"ayer visité el lago de atitlán con mi prima rosa.\\"_ ¿Qué palabras deberían llevar **mayúscula**?","explain":"\\"Atitlán\\" y \\"Rosa\\" nombran a un lago y a una persona **en particular**: son sustantivos **propios** y se escriben con mayúscula. \\"Ayer\\" también, por ir al inicio de la oración. Hoy conocerás las familias de los sustantivos.","type":"choice","props":{"options":[{"id":"a","text":"Ayer, Atitlán y Rosa","icon":"CaseSensitive"},{"id":"b","text":"Lago y prima","icon":"Type","feedback":"\\"Lago\\" y \\"prima\\" pueden nombrar a cualquier lago o prima: no llevan mayúscula."},{"id":"c","text":"Ninguna","icon":"X","feedback":"Los nombres de personas y lugares en particular siempre llevan mayúscula."}],"correct":["a"]},"id":"s08-l2-2-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","title":"Las familias de los sustantivos","prompt":"Los sustantivos se agrupan en **parejas de familias**. Mira el diagrama de la lección y toca cada tarjeta.","type":"explain","props":{"icon":"Tag","body":"Para cada pareja hay una pregunta que te ayuda a decidir.","reveal":[{"icon":"Users","front":"Común o propio","back":"**¿Nombra a cualquiera o a uno en particular?** Común: río, ciudad, niña. Propio (con **mayúscula**): Motagua, Antigua Guatemala, Rosa."},{"icon":"Layers","front":"Individual o colectivo","back":"**¿Nombra a uno o a un grupo?** Individual: oveja, abeja, árbol. Colectivo (grupo, aunque esté en singular): **rebaño**, **enjambre**, **bosque**."},{"icon":"Hand","front":"Concreto o abstracto","back":"**¿Lo puedo ver, tocar, oír, oler o saborear?** Concreto: tortilla, lluvia, marimba. Abstracto (ideas y sentimientos): **paz, alegría, amistad, honestidad**."},{"icon":"Languages","front":"Corpus validado","back":"Para comparar posesión en un idioma maya se necesita una fuente lingüística validada. Aquí no se piden traducciones familiares ni se inventan equivalencias."}]},"id":"s08-l2-2-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Andrés clasifica un sustantivo en sus tres parejas.","type":"worked-example","props":{"icon":"ListChecks","problem":"Clasifica el sustantivo **enjambre** en las tres parejas de familias.","steps":[{"text":"¿Cualquiera o uno en particular? Puede ser cualquier enjambre y va con minúscula → **común**."},{"text":"¿Uno o un grupo? En singular nombra a **muchas abejas** juntas → **colectivo**.","why":"Su individual es \\"abeja\\"."},{"text":"¿Se percibe con los sentidos? Sí: se ve y se oye su zumbido → **concreto**."}],"answer":"**Enjambre** es un sustantivo común, colectivo y concreto.","tip":"Hazte las tres preguntas en orden: particular, grupo, sentidos."},"id":"s08-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Con ayuda, une cada sustantivo individual con su colectivo léxico.","hint":"El colectivo es una palabra singular que nombra un grupo.","explain":"Árbol–bosque, abeja–enjambre y oveja–rebaño son pares individual–colectivo.","type":"match","props":{"leftTitle":"Individual","rightTitle":"Colectivo","pairs":[{"id":"c1","left":"árbol","right":"bosque"},{"id":"c2","left":"abeja","right":"enjambre"},{"id":"c3","left":"oveja","right":"rebaño"}]},"id":"s08-l2-2-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"¿**Concreto** o **abstracto**? Clasifica sustantivos de fuentes, mediciones y recomendaciones.","hint":"Pregúntate: ¿lo puedo ver, tocar, oír, oler o saborear?","explain":"Medidor, lámpara y ficha se perciben; ahorro, confianza y recomendación nombran ideas.","type":"sort","props":{"buckets":[{"id":"c","label":"Concreto","icon":"Hand","color":"var(--area-l2)"},{"id":"a","label":"Abstracto","icon":"Brain","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"medidor","bucket":"c"},{"id":"x2","text":"ahorro","bucket":"a"},{"id":"x3","text":"lámpara","bucket":"c"},{"id":"x4","text":"confianza","bucket":"a"},{"id":"x5","text":"ficha","bucket":"c"},{"id":"x6","text":"recomendación","bucket":"a"}]},"id":"s08-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"En esta nota del panel, toca los sustantivos **propios** que identifican escenario y fuente.","explain":"Escuela Luz y Ficha B identifican un caso y una fuente particulares; lámpara, medición y recomendación son comunes.","type":"highlight","props":{"target":"sustantivos propios","text":"En el caso simulado {Escuela Luz}, la {Ficha B} informa una medición de lámpara y una recomendación."},"id":"s08-l2-2-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Clasifica sustantivos de una fuente, una medición y una recomendación según el tipo que mejor los distingue.","explain":"Ficha A es propio; equipo es colectivo; ahorro es abstracto; medidor es concreto.","type":"match","props":{"leftTitle":"Sustantivo","rightTitle":"Tipo","pairs":[{"id":"s1","left":"Ficha A","leftIcon":"FileText","right":"Propio"},{"id":"s2","left":"equipo","leftIcon":"Users","right":"Colectivo"},{"id":"s3","left":"ahorro","leftIcon":"Heart","right":"Abstracto"},{"id":"s4","left":"medidor","leftIcon":"Gauge","right":"Concreto"}]},"id":"s08-l2-2-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","title":"Corpus del panel de energía","prompt":"Lee la fuente suministrada y clasifica sus sustantivos.","type":"reading","props":{"genre":"Ficha informativa simulada","heading":"Fuente, medición y recomendación","passage":"Caso escolar simulado; no describe tu escuela. La Ficha C registra una medición de 18 lámparas. El equipo observa el alumbrado y propone una recomendación: apagar lámparas innecesarias. La confianza depende de mostrar la fuente y la unidad.","questions":[{"q":"¿Qué sustantivo **colectivo** nombra al grupo que observa?","options":[{"id":"a","text":"equipo"},{"id":"b","text":"fuente"},{"id":"c","text":"lámpara"}],"correct":"a","why":"Equipo, en singular, nombra a varias personas."},{"q":"¿Qué sustantivo de la ficha es **abstracto**?","options":[{"id":"a","text":"confianza"},{"id":"b","text":"lámparas"},{"id":"c","text":"Ficha C"}],"correct":"a","why":"La confianza es un sentimiento: no se puede ver ni tocar."},{"q":"¿Cuál es el sustantivo propio que identifica la fuente?","options":[{"id":"a","text":"Ficha C"},{"id":"b","text":"medición"},{"id":"c","text":"recomendación"}],"correct":"a","why":"Ficha C nombra una fuente particular."}]},"id":"s08-l2-2-9"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Completa las oraciones del panel con el sustantivo correcto para la fuente, la medición y la recomendación.","explain":"La ficha identifica la fuente, el conjunto reúne datos y el ahorro nombra la idea buscada por la recomendación.","type":"fill-blank","props":{"text":"La [[ficha]] identifica la fuente. El [[conjunto]] reúne mediciones. El [[ahorro]] orienta la recomendación.","distractors":["lámpara","dato","medidor"]},"id":"s08-l2-2-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.2"],"prompt":"En una nueva recomendación del panel, ¿qué sustantivo es **abstracto**?","type":"choice","props":{"options":[{"id":"a","text":"lámpara"},{"id":"b","text":"eficiencia"},{"id":"c","text":"Ficha D"},{"id":"d","text":"medidor"}],"correct":["b"]},"id":"s08-l2-2-11"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.2"],"prompt":"Clasifica fuentes, mediciones y recomendaciones de otro panel: ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"“Ficha D” es propio porque identifica una fuente particular.","answer":true},{"text":"“Bosque” es colectivo porque en singular nombra un grupo de árboles.","answer":true},{"text":"“Recomendación” es concreto porque se puede tocar.","answer":false,"why":"Recomendación nombra una idea; es un sustantivo abstracto."}]},"id":"s08-l2-2-12"},{"fase":"reflexionar","areas":["l2"],"cnb":[],"ambito":"ser","prompt":"Terminamos la unidad. ¿Cómo te fue?","type":"reflection","props":{"statements":["Distingo sustantivos, adjetivos y verbos","Hago que el adjetivo concuerde con el sustantivo","Reconozco sustantivos comunes, propios, colectivos y abstractos","Uso en mi español lo que aprendí en la unidad: escuchar, respetar, leer señales, recitar y hablar con claridad"],"commitments":["Revisaré las mayúsculas de los nombres propios cuando escriba","Buscaré sustantivos colectivos en lo que leo","Le enseñaré a alguien de mi familia las tres pruebas de las clases de palabras"]},"id":"s08-l2-2-13"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s08","version":"cnb-sexto-3d8e4b6b186c134f","lesson":{"id":"s08-mat-5","title":"Numerales mayas para comparar datos de energía","icon":"Gauge","minutes":15,"gancho":"Un archivo cultural anota con numerales mayas los conteos de dos jornadas didácticas sobre energía. ¿Puedes leer, sumar y comprobar esos registros?","objetivos":["Resolver una situación coherente de datos energéticos y representar el resultado con numerales mayas"],"resumen":["Para resolver un problema con numerales mayas: lee cada numeral en decimal, opera y vuelve a escribir el resultado en maya.","Para comparar: el numeral con más niveles es mayor; con los mismos niveles, compara desde el nivel de arriba.","Un registro honesto conserva la unidad, el dato decimal y la comprobación del numeral maya."],"media":{"id":"s08-mat-5-pizarra","kind":"image","title":"La pizarra de la semana","aspect":"4:3","alt":"Una pizarra del caso simulado muestra 145 minutos de iluminación innecesaria en un pasillo, 230 minutos en un salón y un total por completar con numeral maya.","brief":"Ilustración de una pizarra escolar con el rótulo “Caso escolar simulado; no describe tu escuela”. Tres columnas: “pasillo: 145 min”, “salón: 230 min” y “total: ?”, con numerales mayas de dos niveles junto a los datos decimales. Incluir iconos descriptivos de reloj, pasillo iluminado y salón vacío; no representar minutos como consumo eléctrico. Target: public/media/s08-mat-5-pizarra.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"ambito":"conocer","title":"Numerales mayas para datos de energía","prompt":"Esta lección integra símbolos, niveles y comparación en un solo registro simulado de energía.","type":"explain","props":{"icon":"Zap","body":"Primero se lee el numeral maya por niveles; después se compara u opera el dato de energía y se comprueba en decimal con su unidad."},"id":"s08-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5"],"ambito":"conocer","title":"Resolver problemas con numerales mayas","prompt":"En el caso simulado, los numerales mayas registran minutos de iluminación innecesaria. Para resolver un problema, sigue estos pasos.","type":"explain","props":{"icon":"ListChecks","body":"**Leo** en decimal → **opero** → **escribo** el resultado en maya → **compruebo**.","reveal":[{"icon":"Eye","front":"1. Leo","back":"Convierto cada numeral a decimal: nivel de arriba × 20 + nivel de abajo."},{"icon":"Calculator","front":"2. Opero","back":"Sumo, resto o multiplico como siempre."},{"icon":"PenLine","front":"3. Escribo en maya","back":"Divido el resultado entre 20 (o 400) para repartirlo en niveles."},{"icon":"Scale","front":"Comparar","back":"Más niveles = mayor. Con los mismos niveles, compara desde arriba; si empatan, baja al siguiente nivel."}]},"id":"s08-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"ambito":"hacer","title":"Ejemplo resuelto: un solo registro de energía","prompt":"Suma, representa y comprueba los minutos del caso simulado.","type":"worked-example","props":{"icon":"Gauge","problem":"El registro indica 145 minutos de iluminación innecesaria en un pasillo y 230 minutos en un salón vacío. ¿Cuál es el total y cómo se representa en maya?","steps":[{"text":"Sumo minutos de la misma unidad: 145 + 230 = **375 min**."},{"text":"375 ÷ 20 = **18**, sobran **15**."},{"text":"Nivel del 20: 18; nivel del 1: 15."},{"text":"Compruebo: 18 × 20 + 15 = **375 min**; el numeral es mayor que cada registro parcial."}],"answer":"Total: 375 min = **18 | 15**. Son minutos registrados, no una medida de energía consumida."},"id":"s08-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6"],"ambito":"hacer","prompt":"Construye con apoyo el total del caso: **375 minutos**.","hint":"375 = 18 × 20 + 15.","explain":"Arriba 18 (tres barras y tres puntos); abajo 15 (tres barras). La unidad sigue siendo minutos.","type":"maya-number","props":{"mode":"build","target":375,"levels":2,"scaffold":true},"id":"s08-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.7"],"prompt":"¿Qué **numeral maya** del registro de iluminación innecesaria es mayor?","hint":"Compara desde el nivel de 20 y conserva la unidad minutos.","explain":"230 min = 11 × 20 + 10 y 145 min = 7 × 20 + 5; por eso 230 minutos es mayor.","type":"choice","props":{"options":[{"id":"a","text":"Pasillo: 145 min = nivel del 20: 7 · nivel del 1: 5","feedback":"145 es menor que 230."},{"id":"b","text":"Salón: 230 min = nivel del 20: 11 · nivel del 1: 10"}],"correct":["b"]},"id":"s08-mat-5-5"},{"fase":"construir","areas":["mat"],"cnb":[],"ambito":"conocer","title":"Lo que construimos en la unidad","prompt":"Antes de resolver el caso energético, revisa qué debe conservar un registro matemático confiable.","type":"explain","props":{"icon":"ClipboardCheck","body":"El numeral maya y el decimal deben representar la misma cantidad y mantener la unidad del caso.","reveal":[{"icon":"Hash","front":"Dato decimal","back":"Permite operar y comprobar la cantidad."},{"icon":"Shell","front":"Representación maya","back":"Distribuye la misma cantidad en niveles de ×1, ×20 y ×400."},{"icon":"Gauge","front":"Unidad","back":"Indica si se cuentan focos, minutos o registros; no se mezclan unidades."},{"icon":"BadgeCheck","front":"Comprobación","back":"Multiplica cada nivel por su valor y suma."}]},"id":"s08-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.5"],"prompt":"Lee el numeral maya del primer registro de iluminación innecesaria: **145 minutos**.","explain":"7 × 20 + 5 = 145 minutos.","type":"maya-number","props":{"mode":"read","target":145,"levels":2},"id":"s08-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6"],"prompt":"El primer registro equivale a **145** minutos y el segundo a **230** minutos. ¿Cuál es el total que luego representarás en maya?","explain":"145 + 230 = 375 minutos.","type":"number-input","props":{"answer":375,"unit":"minutos"},"id":"s08-mat-5-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Representa en numeral maya el total de **375** minutos del caso.","type":"maya-number","props":{"mode":"build","target":375,"levels":2},"id":"s08-mat-5-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"¿Qué comprobación respalda el numeral maya construido para **375 minutos de iluminación**?","type":"choice","props":{"options":[{"id":"a","text":"18 × 20 + 15 = 375"},{"id":"b","text":"15 × 20 + 18 = 318"},{"id":"c","text":"18 + 15 = 33"}],"correct":["a"]},"id":"s08-mat-5-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"prompt":"En un registro nuevo de iluminación, hay **160 minutos** en biblioteca y **220 minutos** en laboratorio. Construye en maya el total y verifica que sea mayor que cada parte.","type":"maya-number","props":{"mode":"build","target":380,"levels":2},"id":"s08-mat-5-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"prompt":"Otro registro de iluminación suma **185 minutos + 210 minutos**. Lee en maya el total correcto y decide si supera los 375 minutos anteriores.","type":"maya-number","props":{"mode":"read","target":395,"levels":2},"id":"s08-mat-5-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Aproximo cantidades a la cifra que me piden","Leo y escribo numerales mayas","Convierto números del sistema decimal al maya","Ordeno series mayas de 20 en 20 y de 100 en 100"],"commitments":["Enseñaré a un familiar a escribir su edad con numerales mayas","Anotaré en maya lo que se compra en casa durante una semana","Buscaré cantidades grandes en una noticia y las aproximaré"]},"id":"s08-mat-5-13"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s08","version":"cnb-sexto-2d105df2fddd5e0b","lesson":{"id":"s08-l1-5","title":"Revisar un fragmento con precisión","icon":"ClipboardCheck","minutes":15,"gancho":"Una sola frase exagerada puede volver poco confiable un informe. ¿Qué cambiarías primero?","objetivos":["Revisar un fragmento breve para que conserve la fuente, el dato y una redacción clara"],"resumen":["En una revisión breve se compara el borrador con la fuente suministrada.","Primero se corrige el sentido: fuente visible, dato fiel y ninguna conclusión exagerada.","Después se corrige una forma concreta: concordancia, tilde, mayúscula o puntuación.","La tarea termina con el fragmento corregido; no exige rehacer un informe completo."],"media":{"id":"s08-l1-5-revision","kind":"animation","title":"Una revisión acotada","aspect":"16:9","duration":35,"alt":"Un fragmento breve se compara con una ficha de energía; una lupa marca una fuente ausente, un dato exagerado y un error de concordancia antes de mostrar dos oraciones corregidas.","brief":"Animación 2D de 35 s. A la izquierda aparece la Ficha B suministrada con “LED: 9 W”, “incandescente: 60 W” y “caso escolar simulado”. A la derecha, un borrador de dos oraciones. Una lupa marca solo tres problemas: falta atribución, aparece la exageración “elimina todo el consumo” y falta concordancia. El fragmento corregido conserva dos oraciones; no se agregan título, diagrama ni recopia. Narración en español. Target: public/media/s08-l1-5-revision.mp4. Accesibilidad: subtítulos completos, transcripción y pausas para leer ambos textos."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Paquete suministrado para revisar","prompt":"Lee la fuente y el borrador antes de cambiar una palabra.","type":"explain","props":{"icon":"FileSearch","body":"**Ficha B, paquete suministrado:** en condiciones comparables, una lámpara LED usa 9 W y una incandescente 60 W. Apagar luces en espacios vacíos evita uso innecesario. **Caso escolar simulado; no describe tu escuela.**\\n\\n**Borrador:** “Las lámparas LED usa 9 W y elimina todo el consumo”."},"id":"s08-l1-5-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Tres comprobaciones","prompt":"Observa la animación y abre las tarjetas.","type":"explain","props":{"icon":"ClipboardCheck","body":"Una revisión acotada corrige el contenido necesario y una forma lingüística, sin convertir la actividad en un informe nuevo.","reveal":[{"icon":"Quote","front":"1. Fuente","back":"Nombra la ficha: “Según la Ficha B…”. Así el lector sabe de dónde procede el dato."},{"icon":"Gauge","front":"2. Fidelidad","back":"Conserva 9 W y las condiciones comparables. Quita “elimina todo el consumo”, porque la fuente no lo afirma."},{"icon":"SpellCheck","front":"3. Claridad","back":"Corrige una forma concreta: “una lámpara LED **usa**” o “las lámparas LED **usan**”."}]},"id":"s08-l1-5-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","title":"Modelo: corregir solo lo necesario","prompt":"Compara el borrador inicial con la Ficha B suministrada.","type":"worked-example","props":{"icon":"Eraser","problem":"Borrador: “Las lámparas LED usa 9 W y elimina todo el consumo”.","steps":[{"text":"Agrego la atribución: **Según la Ficha B**."},{"text":"Mantengo el dato y su condición: **una lámpara LED usa 9 W en la comparación suministrada**."},{"text":"Quito “elimina todo el consumo”: excede la fuente."}],"answer":"“Según la Ficha B, una lámpara LED usa 9 W en la comparación suministrada”.","tip":"Fuente, fidelidad y claridad: tres comprobaciones sobre un fragmento breve."},"id":"s08-l1-5-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"En el borrador de la Ficha B, toca las partes que deben revisarse.","hint":"Busca la fuente ausente, la concordancia y una afirmación que la ficha no respalda.","explain":"Se agrega “Según la Ficha B”, se cambia “usa” por “usan” si el sujeto permanece plural y se elimina la afirmación absoluta.","type":"highlight","props":{"target":"partes por revisar","text":"{Las lámparas LED} {usa} 9 W y {elimina todo el consumo}."},"id":"s08-l1-5-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"La Ficha A dice: “Caso escolar simulado: 12,468 kWh; aproximado a millares: 12,000 kWh”. ¿Cuál revisión es fiel?","hint":"La revisión debe nombrar la fuente, conservar la unidad y no convertir el caso en un dato real.","explain":"La opción correcta atribuye ambos valores y mantiene el rótulo de caso simulado.","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha A, el caso escolar simulado registra 12,468 kWh, aproximadamente 12,000 kWh."},{"id":"b","text":"Nuestra escuela gastó exactamente 12,000 kWh.","feedback":"Convierte el caso en un dato real y presenta un valor redondeado como exacto."},{"id":"c","text":"La electricidad bajó mucho.","feedback":"No conserva el dato, la unidad ni la fuente."}],"correct":["a"]},"id":"s08-l1-5-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Revisa de forma independiente este borrador: “El dato de 60 W demuestra cuánto dinero ahorró la escuela”. La Ficha B solo compara potencia y no informa ahorro monetario.","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha B, una lámpara usa 60 W en la comparación; la ficha no informa ahorro monetario."},{"id":"b","text":"La escuela ahorró mucho dinero con 60 W."},{"id":"c","text":"La electricidad ya no cuesta nada."}],"correct":["a"]},"id":"s08-l1-5-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Haz una revisión breve del borrador: “las luces vacías gasta energía y apagarlas garantiza un ahorro de Q500”. Usa solo la Ficha B suministrada: apagar luces en espacios vacíos evita uso innecesario; no informa dinero ahorrado.","type":"short-answer","props":{"minWords":18,"placeholder":"Según la Ficha B, … La ficha no informa …","model":"Según la Ficha B, las luces encendidas en espacios vacíos usan energía innecesariamente y conviene apagarlas. La ficha no informa cuánto dinero se ahorraría.","rubric":["Nombré la Ficha B","Conservé la recomendación suministrada","Quité la cantidad de dinero no respaldada","Corregí la concordancia del fragmento"]},"id":"s08-l1-5-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Revisa este borrador con una fuente nueva. La Ficha C dice: “Dos lámparas comparadas usan 11 W cada una”. ¿Cuál versión conserva fuente, dato y concordancia?","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha C, las dos lámparas comparadas usan 11 W cada una."},{"id":"b","text":"Las lámparas usa 11 W y son las mejores del país."},{"id":"c","text":"Una fuente dice que no consumen energía."}],"correct":["a"]},"id":"s08-l1-5-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Revisa el borrador de una fuente distinta. Completa la versión fiel de la Ficha D: “Caso simulado: tres ventiladores usan 45 W cada uno”.","type":"fill-blank","props":{"text":"Según la [[Ficha D]], los tres ventiladores [[usan]] 45 [[W]] cada uno en el caso [[simulado]].","distractors":["usa","reales","Q","Ficha B"]},"id":"s08-l1-5-9"},{"fase":"reflexionar","areas":["l1"],"cnb":[],"ambito":"ser","prompt":"¿Qué comprobación te ayudó más al revisar el fragmento?","type":"reflection","props":{"statements":["Comparé el borrador con la fuente suministrada","Conservé el dato y su unidad","Quité una afirmación que la fuente no respaldaba","Corregí una forma lingüística concreta"],"commitments":["Revisaré primero el sentido y después la forma","Nombraré la fuente de cada dato"]},"id":"s08-l1-5-10"}],"kind":"materia","area":"l1","day":5}},{"missionId":"s08","version":"cnb-sexto-40fe770bfcd0c8a8","lesson":{"id":"s08-cnt-3","title":"Cómo investiga la ciencia","icon":"FlaskConical","minutes":15,"gancho":"Tu abuelo dice que el frijol crece mejor con abono de hojas, y tu vecina dice que no hace diferencia. ¿Cómo podrías averiguar quién tiene razón?","objetivos":["Identificar los tipos de investigación: documental, de campo y de laboratorio"],"resumen":["Investigación documental: se buscan datos en libros, documentos, informes y fuentes confiables. De campo: se observa, mide o entrevista en el lugar donde ocurre el fenómeno. De laboratorio: se hacen experimentos en condiciones controladas.","El conocimiento científico busca mediciones precisas, afirmaciones respaldadas y procedimientos demostrables: al repetirlos se esperan resultados compatibles dentro de un margen explicado, no copias idénticas.","Pasos de una investigación: observar, preguntar, plantear una hipótesis, experimentar o recoger datos, analizar y concluir. La ciencia se corrige cuando aparecen pruebas nuevas."],"media":{"id":"s08-cnt-3-investigar","kind":"image","title":"Tres maneras de investigar","aspect":"16:9","alt":"Tres escenas: una niña consulta libros en la biblioteca municipal; un grupo mide la temperatura del agua de un río con un termómetro; dos niños comparan plantas de frijol en vasos en la mesa del aula.","brief":"Ilustración en tres paneles con estudiantes guatemaltecos de sexto grado (niñas y niños de distintos pueblos): (1) \\"Documental\\": una niña en la biblioteca municipal con libros e informes, tomando notas. (2) \\"De campo\\": un grupo junto a un río con un termómetro, una libreta y una cinta métrica; una niña entrevista a un agricultor. (3) \\"De laboratorio\\": en el aula, vasos con frijoles germinando, etiquetas \\"con luz\\" y \\"sin luz\\", una regla y una tabla de datos. Estilo cálido, colores claros. Target: public/media/s08-cnt-3-investigar.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","title":"Tres tipos de investigación","prompt":"Lee de dónde obtiene evidencia cada tipo de investigación.","type":"explain","props":{"icon":"Search","body":"La investigación puede ser **documental**, **de campo** o **de laboratorio**, según dónde y cómo obtiene evidencia."},"id":"s08-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","title":"Tres tipos de investigación","prompt":"Según **dónde** y **cómo** se busca la información, hay tres tipos de investigación. Observa la imagen de la lección y toca las tarjetas.","type":"explain","props":{"icon":"Search","body":"Muchas investigaciones combinan los tres tipos: primero se lee, luego se observa en el campo y se hacen pruebas.","reveal":[{"icon":"BookOpen","front":"Documental","back":"Se buscan datos en **libros, documentos, informes, mapas** o sitios confiables. Ejemplo: leer los informes del centro de salud sobre enfermedades del municipio."},{"icon":"MapPin","front":"De campo","back":"Se va **al lugar** donde ocurre el fenómeno para **observar, medir o entrevistar**. Ejemplo: medir la temperatura de un río cada día o entrevistar a agricultores."},{"icon":"FlaskConical","front":"De laboratorio","back":"Se hacen **experimentos** en **condiciones controladas**: se cambia una sola cosa y se mide qué pasa. Ejemplo: germinar frijoles con y sin luz."}]},"id":"s08-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","prompt":"Clasifica cada investigación según su tipo.","hint":"¿Se lee (documental), se va al lugar (campo) o se hace un experimento controlado (laboratorio)?","explain":"Documental: libros e informes. De campo: en el lugar real. De laboratorio: experimentos controlados.","type":"sort","props":{"buckets":[{"id":"doc","label":"Documental","icon":"BookOpen","color":"var(--area-l1)"},{"id":"cam","label":"De campo","icon":"MapPin","color":"var(--c-ok)"},{"id":"lab","label":"De laboratorio","icon":"FlaskConical","color":"var(--area-cnt)"}],"items":[{"id":"i1","text":"Revisar informes de lluvia con fuente","bucket":"doc"},{"id":"i2","text":"Medir la temperatura en el lugar del caso","bucket":"cam"},{"id":"i3","text":"Comparar en el aula dos bandejas bajo condiciones controladas","bucket":"lab"}]},"id":"s08-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","title":"Características del conocimiento científico","prompt":"No todo lo que se dice es conocimiento científico. Para serlo, debe cumplir tres características. Toca las tarjetas.","type":"explain","props":{"icon":"BadgeCheck","body":"Un rumor, una opinión o una creencia pueden ser importantes para las personas, pero **no** son conocimiento científico si no cumplen estas características.","reveal":[{"icon":"Ruler","front":"Exacto","back":"Usa **medidas precisas** con unidades: \\"la planta creció **4.5 cm** en 7 días\\", no \\"creció bastante\\"."},{"icon":"ShieldCheck","front":"Verdadero","back":"**Coincide con la realidad** que se observó y se comprobó. Si aparecen pruebas nuevas que lo contradicen, se **corrige**."},{"icon":"RefreshCw","front":"Demostrable","back":"Otras personas pueden **repetir** la investigación con el mismo protocolo y obtener **resultados compatibles** dentro de un margen explicado."}]},"id":"s08-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Une cada situación con la característica del conocimiento científico que muestra.","hint":"¿Hay una medida precisa? ¿Otros lo repitieron? ¿Se comprobó con la realidad?","explain":"Medir con unidades = exacto. Repetir y obtener lo mismo = demostrable. Comprobar con observaciones reales = verdadero.","type":"match","props":{"leftTitle":"Situación","rightTitle":"Característica","pairs":[{"id":"e","left":"Anotar que el agua del río estaba a 18 °C","leftIcon":"Thermometer","right":"Exacto"},{"id":"d","left":"Otro grado repite el protocolo y obtiene resultados compatibles","leftIcon":"RefreshCw","right":"Demostrable"},{"id":"v","left":"Lo que se afirma coincide con lo que se observó y comprobó en la realidad","leftIcon":"ShieldCheck","right":"Verdadero"}]},"id":"s08-cnt-3-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1","cnt:8.2.1"],"ambito":"hacer","title":"Ejemplo: una investigación de principio a fin","prompt":"Mira cómo el grupo de Andrea responde la pregunta del abono con una investigación. Los datos son **hipotéticos**.","media":{"id":"s08-cnt-3-frijoles","kind":"video","title":"El experimento de los frijoles","aspect":"16:9","duration":45,"alt":"Video en el aula: dos grupos de macetas iguales con frijol, unas con abono de hojas y otras sin él; durante tres semanas los estudiantes riegan igual, miden con regla y anotan en una tabla.","brief":"Video de 45 s (o animación en cámara rápida) en un aula guatemalteca: 10 macetas recicladas con frijol, 5 rotuladas \\"con abono de hojas\\" y 5 \\"sin abono\\"; misma luz, misma agua (vaso medidor). Cámara rápida de tres semanas de crecimiento. Estudiantes miden con regla y anotan en una tabla de cartulina. Al final, la tabla con promedios y la frase \\"Otro grado repitió el experimento\\". Narración en español con subtítulos. Materiales seguros: tierra, semillas, agua, regla. Target: public/media/s08-cnt-3-frijoles.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"type":"worked-example","props":{"icon":"FlaskConical","problem":"¿Crece más el frijol con abono de hojas que sin abono?","steps":[{"text":"**Documental e hipótesis**: leen una fuente y plantean que las plantas con abono crecerán más."},{"text":"**Experimento de laboratorio**: 5 macetas con abono y 5 sin abono; **todo lo demás igual** (semillas, luz, agua).","why":"Si cambiaran varias cosas a la vez, no sabrían cuál causó la diferencia."},{"text":"**Datos y conclusión**: miden 18 cm y 12 cm; otro grupo repite el protocolo y obtiene resultados compatibles, por lo que la evidencia es demostrable."}],"answer":"En este experimento, el frijol con abono creció en promedio **6 cm más**. El conocimiento es exacto (medido), verdadero (comprobado) y demostrable (repetido).","tip":"Una buena investigación cambia **una sola cosa** a la vez y mide con cuidado."},"id":"s08-cnt-3-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"hacer","prompt":"Ordena los pasos de una investigación científica.","hint":"Todo empieza con algo que te llama la atención y termina con una conclusión.","explain":"Observar → preguntar → hipótesis → experimentar o recoger datos → analizar → concluir.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"q1","text":"Observar algo que llama la atención","icon":"Eye"},{"id":"q2","text":"Hacer una pregunta","icon":"HelpCircle"},{"id":"q3","text":"Plantear una hipótesis (posible respuesta)","icon":"Lightbulb"},{"id":"q4","text":"Experimentar o recoger datos","icon":"FlaskConical"},{"id":"q5","text":"Analizar los resultados","icon":"BarChart3"},{"id":"q6","text":"Sacar una conclusión y compartirla","icon":"Megaphone"}]},"id":"s08-cnt-3-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Dos estudiantes reportan su experimento. Mario escribe: \\"La planta creció un montón\\". Lucía escribe: \\"La planta creció 4.5 cm en 7 días\\". ¿Qué característica del conocimiento científico cumple mejor el reporte de Lucía?","explain":"Lucía usa una **medida precisa con unidades y tiempo**: su dato es **exacto** y otros pueden compararlo.","type":"choice","props":{"options":[{"id":"a","text":"Exacto","icon":"Ruler"},{"id":"b","text":"Opinable","icon":"MessageCircle","feedback":"\\"Opinable\\" no es una característica del conocimiento científico."},{"id":"c","text":"Secreto","icon":"Lock","feedback":"La ciencia se comparte para que otros la comprueben."}],"correct":["a"]},"id":"s08-cnt-3-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Repaso de la unidad: ¿es **conocimiento científico** o una **opinión o rumor**?","explain":"El conocimiento científico se basa en mediciones y pruebas que otros pueden repetir. Las opiniones y los rumores no se basan en pruebas, y algunos, como que los zancudos transmiten el VIH, la ciencia ya comprobó que son falsos.","type":"sort","props":{"buckets":[{"id":"cie","label":"Conocimiento científico","icon":"BadgeCheck","color":"var(--area-cnt)"},{"id":"opi","label":"Opinión o rumor","icon":"MessageCircle","color":"var(--c-maiz-strong)"}],"items":[{"id":"k1","text":"La mayoría de las células del cuerpo humano tienen 46 cromosomas; los gametos tienen 23","bucket":"cie"},{"id":"k2","text":"\\"Dicen que los zancudos transmiten el VIH\\"","bucket":"opi","feedback":"Es un rumor falso: la ciencia comprobó que los zancudos no transmiten el VIH."},{"id":"k3","text":"La Tierra se formó hace unos 4,500 millones de años, según mediciones de rocas","bucket":"cie"},{"id":"k4","text":"\\"El maíz morado es el más bonito\\"","bucket":"opi"},{"id":"k5","text":"En el experimento, el suelo con grama retuvo más agua que el suelo desnudo","bucket":"cie"}]},"id":"s08-cnt-3-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","prompt":"Repaso de la semana 7: el grupo de Ixchel comparó en el aula dos bandejas de tierra, una con grama y otra sin ella, regándolas con la misma cantidad de agua. ¿Qué tipo de investigación hizo?","explain":"Hizo un **experimento controlado**: cambió una sola cosa (la grama) y mantuvo todo lo demás igual. Es una investigación **de laboratorio**.","type":"choice","props":{"options":[{"id":"a","text":"Documental","feedback":"No leyeron documentos: hicieron una prueba."},{"id":"b","text":"De campo","feedback":"No fueron a la montaña: recrearon el fenómeno en el aula, en condiciones controladas."},{"id":"c","text":"De laboratorio"}],"correct":["c"]},"id":"s08-cnt-3-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.1.1","cnt:8.2.1"],"prompt":"Un grupo mide en el río **18 °C** cada día con el mismo protocolo. ¿Qué tipo de investigación hace y qué vuelve exacta su evidencia?","type":"choice","props":{"options":[{"id":"a","text":"Documental; consultar una opinión"},{"id":"b","text":"De campo; registrar medida, unidad y protocolo"},{"id":"c","text":"De laboratorio; votar el resultado"}],"correct":["b"]},"id":"s08-cnt-3-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.2.1","cnt:8.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Si otras personas repiten un protocolo y obtienen resultados compatibles dentro del margen esperado, la evidencia es demostrable.","answer":true},{"text":"Leer informes y libros en la biblioteca es una investigación de laboratorio.","answer":false,"why":"Es una investigación documental."},{"text":"El conocimiento científico se corrige con pruebas nuevas y un buen experimento controla las variables.","answer":true}]},"id":"s08-cnt-3-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":[],"type":"reflection","props":{"statements":["Distingo las manifestaciones de la energía y sé cómo ahorrar electricidad","Explico las causas del calentamiento global y cómo ayudan los satélites","Diferencio investigación documental, de campo y de laboratorio","Reconozco un conocimiento exacto, verdadero y demostrable"],"commitments":["Seré \\"guardián de la energía\\" en mi casa","Haré un pequeño experimento y anotaré mis mediciones","Revisaré si lo que escucho es un dato comprobado o un rumor"]},"id":"s08-cnt-3-13"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s08","version":"cnb-sexto-badc2021c019a46e","lesson":{"id":"s08-fc-2","title":"Pueblos y departamentos en el mapa de la CEH","icon":"MapPinned","minutes":15,"gancho":"¿Cómo se localiza información histórica sin convertir un color del mapa en una competencia de sufrimiento?","objetivos":["Localizar pueblos y departamentos afectados por la violencia usando un paquete atribuido a la CEH"],"resumen":["El paquete didáctico atribuye sus datos a la Comisión para el Esclarecimiento Histórico (CEH) y localiza departamentos y pueblos documentados.","Quiché, Huehuetenango, Chimaltenango, Alta Verapaz y Baja Verapaz aparecen en la ficha; también pueblos ixil, k’iche’, q’anjob’al, chuj, mam, achi, q’eqchi’ y kaqchikel.","Los colores solo ayudan a localizar categorías de la leyenda. No ordenan gravedad, sufrimiento ni cantidad de víctimas."],"media":{"id":"s08-fc-2-mural","kind":"image","title":"Paquete cartográfico atribuido a la CEH","aspect":"16:9","alt":"Mapa didáctico de Guatemala junto a tarjetas de departamentos y pueblos mayas, con fuente CEH y una leyenda que aclara que el color no mide sufrimiento.","brief":"Imagen didáctica 1600×900, trauma-aware y sin escenas de violencia. Mostrar un mapa esquemático de Guatemala y tarjetas separadas: Quiché–ixil/k’iche’, Huehuetenango–q’anjob’al/chuj/mam, Baja Verapaz–achi, Alta Verapaz–q’eqchi’, Chimaltenango–kaqchikel. Encabezado: “Síntesis didáctica basada en CEH, Guatemala: memoria del silencio (1999)”. Leyenda visible: “El color localiza; no mide gravedad, sufrimiento ni número de víctimas”. Alto contraste y patrones además del color. Target: public/media/s08-fc-2-mural.jpg. Accesibilidad: formato final 1600×900 px, patrones distinguibles, texto grande y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":[],"ambito":"ser","prompt":"Antes de abrir el paquete CEH, elige una disposición respetuosa para leer memoria histórica.","type":"reflection","props":{"statements":["Puedo pausar si el tema me incomoda","Localizar no significa comparar sufrimiento"],"commitments":["Usaré nombres, fuente y leyenda con respeto"]},"id":"s08-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","title":"Paquete suministrado CEH","prompt":"Lee los pueblos y departamentos incluidos en la fuente.","type":"explain","props":{"icon":"Map","body":"**Departamentos:** Quiché, Huehuetenango, Chimaltenango, Alta Verapaz y Baja Verapaz. **Pueblos:** ixil, k’iche’, q’anjob’al, chuj, mam, achi, q’eqchi’ y kaqchikel."},"id":"s08-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","title":"Cómo leer la leyenda","prompt":"Localiza con nombre, región y fuente; no conviertas el color en una jerarquía.","type":"explain","props":{"icon":"Palette","body":"El color y el patrón distinguen fichas del mapa. **No representan ranking, gravedad, severidad, sufrimiento ni cantidad de víctimas.**"},"id":"s08-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Guía: localiza cada pueblo en el departamento indicado por el paquete CEH.","hint":"Usa solo las tres tarjetas visibles del paquete.","explain":"El paquete ubica ixil en Quiché, achi en Baja Verapaz y q’eqchi’ en Alta Verapaz; no compara sufrimiento.","type":"match","props":{"leftTitle":"Pueblo","rightTitle":"Departamento","pairs":[{"id":"g1","left":"Pueblo ixil (CEH)","right":"Quiché"},{"id":"g2","left":"Pueblo achi (CEH)","right":"Baja Verapaz"},{"id":"g3","left":"Pueblo q’eqchi’ (CEH)","right":"Alta Verapaz"}]},"id":"s08-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","title":"Ejemplo resuelto: localizar sin jerarquizar","prompt":"Mira cómo se redacta una ubicación cuidadosa.","type":"worked-example","props":{"icon":"MapPinned","problem":"La tarjeta CEH nombra al pueblo achi y a Baja Verapaz.","steps":[{"text":"Nombra la fuente: **según la síntesis didáctica basada en la CEH (1999)**."},{"text":"Localiza: **el pueblo achi aparece asociado con Baja Verapaz**."},{"text":"Aclara el límite: **el color no permite comparar gravedad ni sufrimiento**."}],"answer":"Según la ficha CEH, el pueblo achi se localiza en Baja Verapaz; el mapa no establece un ranking de afectación.","tip":"Fuente → pueblo → departamento → límite de la leyenda."},"id":"s08-fc-2-5"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","prompt":"Aplicación: localiza tarjetas nuevas del paquete CEH por departamento.","explain":"La ficha localiza k’iche’ en Quiché, mam en Huehuetenango y kaqchikel en Chimaltenango.","type":"sort","props":{"buckets":[{"id":"qui","label":"Quiché","icon":"MapPin"},{"id":"hue","label":"Huehuetenango","icon":"MapPin"},{"id":"chi","label":"Chimaltenango","icon":"MapPin"}],"items":[{"id":"a1","text":"Pueblo k’iche’ — fuente CEH","bucket":"qui"},{"id":"a2","text":"Pueblo mam — fuente CEH","bucket":"hue"},{"id":"a3","text":"Pueblo kaqchikel — fuente CEH","bucket":"chi"}]},"id":"s08-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"emprender","prompt":"Escribe una oración que localice un pueblo y un departamento del paquete CEH, cite la fuente y aclare que el color no mide sufrimiento.","type":"short-answer","props":{"minWords":22,"placeholder":"Según la ficha CEH… El color…","model":"Según la síntesis didáctica basada en la CEH, el pueblo chuj aparece en Huehuetenango. El color ayuda a localizar y no mide gravedad ni sufrimiento.","rubric":["Nombra pueblo y departamento","Atribuye a la CEH","Aclara el límite del color"]},"id":"s08-fc-2-7"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Según otra tarjeta del paquete CEH, ¿dónde localizas al pueblo q’anjob’al?","type":"choice","props":{"options":[{"id":"a","text":"Huehuetenango"},{"id":"b","text":"Baja Verapaz"},{"id":"c","text":"Chimaltenango"}],"correct":["a"]},"id":"s08-fc-2-8"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Salida final: localiza dos pueblos con tarjetas CEH nuevas.","type":"match","props":{"leftTitle":"Pueblo","rightTitle":"Departamento","pairs":[{"id":"e1","left":"Pueblo chuj (CEH)","right":"Huehuetenango"},{"id":"e2","left":"Pueblo kaqchikel (CEH)","right":"Chimaltenango"}]},"id":"s08-fc-2-9"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:5.2.1"],"type":"reflection","props":{"statements":["Localizo pueblos y departamentos con el paquete CEH","Cito la fuente sin jerarquizar el sufrimiento"],"commitments":["Leeré mapas históricos con cuidado y respeto"]},"id":"s08-fc-2-10"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s08","version":"cnb-sexto-e2d2fb766d667d58","lesson":{"id":"s08-ef-2","title":"Liderar con igualdad: todas y todos jugamos","icon":"Flag","minutes":15,"gancho":"En el recreo alguien dice: \\"Las niñas no juegan fútbol\\" o \\"Los niños no saltan cuerda\\". ¿Es justo? ¿Qué harías si tú fueras quien organiza el juego?","objetivos":["Dirigir una rutina breve con secuencia segura, igualdad de oportunidades y roles complementarios para mujeres y hombres"],"resumen":["Un buen líder explica las reglas con claridad, escucha, organiza turnos y equipos justos, anima a todos y da el ejemplo con juego limpio. Liderar es servir al grupo, no mandar a gritos.","Niñas y niños tienen los mismos derechos y oportunidades para jugar cualquier juego o deporte y para ser capitanas, capitanes, árbitras o árbitros.","La Declaración Universal de Derechos Humanos dice que todos los seres humanos nacen libres e iguales en dignidad y derechos. La Constitución de Guatemala (artículo 4) establece que el hombre y la mujer tienen iguales oportunidades y responsabilidades.","Complementariedad: cada persona aporta habilidades distintas; un equipo diverso es más fuerte. Equipos justos: contar 1-2, mezclar habilidades y rotar el liderazgo."],"media":{"id":"s08-ef-2-liderazgo","kind":"image","title":"Capitanas y capitanes","aspect":"16:9","alt":"En un patio escolar, una niña capitana explica las reglas a un equipo mixto en círculo; al lado, un niño arbitra un juego de salta cuerda donde saltan niñas y niños juntos.","brief":"Ilustración luminosa de un patio de escuela pública guatemalteca. Escena izquierda: una niña (brazalete de capitana) explica las reglas a un equipo mixto en círculo, todos atentos. Escena derecha: un niño con silbato arbitra salta cuerda; saltan niñas y niños juntos. Al fondo, un cartel \\"Todas y todos jugamos\\". Diversidad de pueblos (maya, garífuna, xinka, mestizo) y una niña en silla de ruedas participando. Sin estereotipos de colores por género. Target: public/media/s08-ef-2-liderazgo.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y liderazgo","prompt":"Lee cómo se organiza una actividad física justa.","type":"explain","props":{"icon":"Users","body":"Niñas y niños, mujeres y hombres tienen iguales oportunidades para jugar y liderar. Rechazar estereotipos, abrir los mismos roles y combinar aportes complementarios protege sus derechos."},"id":"s08-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","prompt":"¿Pueden las niñas jugar fútbol y ser capitanas? ¿Pueden los niños saltar cuerda?","explain":"**Sí, todas y todos.** Mujeres y hombres, niñas y niños tienen los mismos derechos e igualdad de oportunidades para jugar y liderar; los roles no dependen de estereotipos.","type":"choice","props":{"options":[{"id":"a","text":"Sí: cualquier persona puede jugar y liderar cualquier juego","icon":"Users"},{"id":"b","text":"No: cada juego es solo para niñas o solo para niños","icon":"X","feedback":"Esa idea es un estereotipo: limita a las personas y no tiene base."}],"correct":["a"]},"id":"s08-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","title":"¿Qué hace un buen líder en el juego?","prompt":"Liderar no es mandar: es **ayudar al grupo** a jugar mejor. Toca cada tarjeta.","type":"explain","props":{"icon":"Flag","body":"Cualquier persona puede aprender a liderar. Se practica **rotando** el papel de capitán, árbitro u organizador.","reveal":[{"icon":"MessageCircle","front":"Explica con claridad","back":"Cuenta las reglas en pocas palabras, muestra un ejemplo y pregunta: \\"¿Quedó claro?\\"."},{"icon":"Ear","front":"Escucha","back":"Toma en cuenta las ideas del grupo y a quienes hablan menos."},{"icon":"Scale","front":"Organiza con justicia","back":"Forma **equipos parejos**, da **turnos** a todos y cuida que nadie quede fuera."},{"icon":"ThumbsUp","front":"Anima y da el ejemplo","back":"Felicita el esfuerzo, anima a quien se equivoca y juega limpio. El grupo imita lo que ve."}]},"id":"s08-ef-2-3"},{"fase":"construir","areas":["ef","fc"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y derechos en el juego","prompt":"La igualdad en el juego no es solo \\"buena onda\\": es un **derecho**. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Cuando alguien queda fuera de un juego por ser niña, niño, de otro pueblo o por tener una discapacidad, se vulnera su derecho a jugar y a participar.","reveal":[{"icon":"Globe","front":"Derechos humanos","back":"La **Declaración Universal de Derechos Humanos** (artículo 1) dice: todos los seres humanos **nacen libres e iguales en dignidad y derechos**."},{"icon":"Landmark","front":"Constitución de Guatemala","back":"El **artículo 4** dice que en Guatemala todos los seres humanos son libres e iguales en dignidad y derechos, y que **el hombre y la mujer tienen iguales oportunidades y responsabilidades**."},{"icon":"Puzzle","front":"Complementariedad","back":"Cada persona aporta algo distinto: velocidad, puntería, estrategia, ánimo. Un equipo **diverso** se complementa y es más fuerte."},{"icon":"Users","front":"Igualdad de oportunidades","back":"Todas y todos pueden jugar, ser capitanes, arbitrar, elegir juego y recibir el balón. Si alguien necesita una adaptación, se hace."}]},"id":"s08-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","title":"Ejemplo resuelto: formar equipos justos","prompt":"Siempre que eligen equipos, las mismas personas quedan de últimas. Mira cómo lo resuelve Andrea, la capitana de turno.","type":"worked-example","props":{"icon":"Users","problem":"Hay 16 estudiantes (8 niñas y 8 niños) y van a jugar balonmano. Antes, los \\"mejores\\" escogían y siempre quedaban de últimas las mismas niñas y un niño que corre más lento.","steps":[{"text":"Andrea propone **contar 1-2** en la fila: los \\"1\\" forman un equipo y los \\"2\\" el otro.","why":"Nadie \\"escoge\\" a nadie: se evita que alguien se sienta rechazado."},{"text":"Revisa que cada equipo quede **mixto** y con habilidades mezcladas; si no, cambia a dos personas."},{"text":"Acuerda una regla nueva: **antes de lanzar a gol, el balón debe pasar por al menos 3 personas** del equipo.","why":"Así todas y todos tocan el balón, no solo los más rápidos."},{"text":"Nombra **capitanes rotativos**: cada 5 minutos, otra persona es capitana o capitán."}],"answer":"Con **conteo 1-2**, **equipos mixtos**, la regla de **3 pases** y **capitanes rotativos**, el juego es justo y todos participan.","tip":"Un buen líder pregunta al final: \\"¿Todos jugaron? ¿Qué podemos mejorar la próxima vez?\\"."},"id":"s08-ef-2-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","prompt":"Clasifica cada acción de un capitán o capitana: ¿es **buen liderazgo** o **no**?","hint":"Un buen líder incluye, escucha, organiza con justicia y da el ejemplo.","explain":"Liderar bien abre los mismos roles a mujeres y hombres: niñas y niños aportan habilidades complementarias; excluir por estereotipos no es liderazgo.","type":"sort","props":{"buckets":[{"id":"si","label":"Buen liderazgo","icon":"Flag","color":"var(--c-ok)"},{"id":"no","label":"No es buen liderazgo","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Explicar las reglas y preguntar si quedaron claras","bucket":"si"},{"id":"x2","text":"Decidir solo, a gritos, sin escuchar a nadie","bucket":"no"},{"id":"x3","text":"Formar equipos mixtos contando 1-2","bucket":"si"},{"id":"x4","text":"Dejar fuera a las niñas \\"porque no saben\\"","bucket":"no"},{"id":"x5","text":"Animar a quien se equivocó","bucket":"si"},{"id":"x6","text":"Pasar el balón siempre a sus mejores amigos","bucket":"no"}]},"id":"s08-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","prompt":"Dirige una rutina breve sin equipo: explica “cuatro palmas suaves, cuatro gestos al frente y pausa”, comprueba el espacio y ofrece hacerla de pie o sentado. **Ruta grupal opcional:** una persona dirige y otra confirma la señal de alto. **Ruta individual completa:** di o lee las instrucciones, modela la secuencia y usa tú mismo la señal de pausa. No afirmes que hubo rotación si trabajaste a solas.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"Antes de dirigir"},{"label":"Después de explicar y modelar","exercise":{"name":"Palmas y gestos dirigidos","icon":"Flag","seconds":45}},{"label":"Después de adaptar y cerrar","exercise":{"name":"Secuencia adaptable con pausa","icon":"Users","seconds":45}}]},"id":"s08-ef-2-7"},{"fase":"aplicar","areas":["ef","fc"],"cnb":["ef:4.1.12","ef:4.2.3"],"ambito":"convivir","prompt":"¿Qué harías si fueras quien organiza?","type":"dilemma","props":{"scene":{"icon":"Flag","text":"En el recreo organizan una **chamusca**. Un niño dice: \\"Las niñas no pueden jugar y tampoco pueden ser capitanas\\". **Lucía** y **Marta** querían jugar con los niños. Tú eres quien organiza hoy."},"options":[{"id":"a","icon":"EyeOff","text":"Quedarme callado para no tener problemas","consequence":"Lucía y Marta se quedan fuera. El grupo aprende que excluir \\"no pasa nada\\", y la injusticia se repite.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"Users","text":"Decir que todas y todos pueden jugar, formar equipos mixtos contando 1-2 y proponer que Lucía sea capitana de un equipo","consequence":"Se juega con equipos parejos. Lucía organiza bien a su equipo y varios compañeros se dan cuenta de que su idea era un estereotipo.","values":["Igualdad","Liderazgo","Derechos humanos"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Hablar con calma con el compañero: explicarle que la igualdad es un derecho e invitarlo a jugar en un equipo mixto","consequence":"El compañero no cambia de idea de inmediato, pero acepta jugar. Al final reconoce que el partido fue más parejo y divertido.","values":["Diálogo","Respeto","Igualdad"],"constructive":true}]},"id":"s08-ef-2-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"conocer","prompt":"Aplica el liderazgo y rechaza el estereotipo: ordena una rutina donde mujeres y hombres, niñas y niños tengan igualdad de oportunidades para asumir roles y aportar habilidades complementarias.","explain":"Un liderazgo justo abre todos los roles, explica la secuencia, ofrece adaptación segura y combina aportes complementarios.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"a","text":"Abrir por igual a una niña o un niño el rol de dirigir"},{"id":"b","text":"Explicar dos pasos laterales y ofrecer gestos sentados"},{"id":"c","text":"Combinar a quien modela con quien cuida la señal de alto"},{"id":"d","text":"Dirigir dos repeticiones y cambiar los roles"}]},"id":"s08-ef-2-9"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"hacer","prompt":"Guarda evidencia de cómo dirigiste la rutina: escribe la instrucción, la adaptación segura, tu rol y el orden usado. Indica si elegiste ruta individual o grupal.","explain":"La evidencia describe liderazgo realmente practicado en la lección, sin afirmar una rotación no observada.","type":"short-answer","props":{"minWords":22,"placeholder":"Ruta… Mi instrucción… Adaptación… Secuencia…","model":"Elegí la ruta individual. Expliqué cuatro palmas y cuatro gestos. Ofrecí hacerlos sentado, modelé la secuencia y terminé con la señal de pausa.","rubric":["Indico la ruta","Escribo una instrucción","Incluyo adaptación segura","Describo rol y secuencia"]},"id":"s08-ef-2-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y roles claros. Un niño afirma que solo los hombres deben dirigir. Para rechazar ese estereotipo y defender los derechos humanos, ¿qué instrucción da igualdad de oportunidades a mujeres y hombres y usa aportes complementarios?","type":"choice","props":{"options":[{"id":"a","text":"“Una niña y un niño alternan el rol de líder; una persona modela y otra cuida la señal. Cada aporte complementa al otro y se puede hacer sentado”"},{"id":"b","text":"“Los hombres lideran y las mujeres observan”"},{"id":"c","text":"“Todas hacen lo mismo, sin roles ni adaptación”"}],"correct":["a"]},"id":"s08-ef-2-11"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y una secuencia de roles. Ordénala para rechazar el estereotipo, proteger derechos humanos y dar igualdad de oportunidades a mujeres y hombres con participación complementaria.","type":"order","props":{"labels":{"start":"Inicio","end":"Cierre"},"items":[{"id":"e1","text":"Explicar que niñas y niños pueden asumir por igual cualquier rol"},{"id":"e2","text":"Asignar a una mujer el modelado y a un hombre la señal, con cambio posterior de roles"},{"id":"e3","text":"Ofrecer movimiento de pie o sentado para complementar capacidades"},{"id":"e4","text":"Dirigir dos repeticiones y cerrar con una señal segura"}]},"id":"s08-ef-2-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:4.2.3"],"type":"reflection","props":{"statements":["Juego y valoro juegos tradicionales de mi comunidad","Lidero un juego explicando reglas y formando equipos justos","Defiendo que todas y todos tengan las mismas oportunidades de jugar"],"commitments":["Enseñaré un juego tradicional a alguien más pequeño","Me ofreceré a ser líder o árbitro en el recreo","Invitaré a jugar a quien se queda fuera"]},"id":"s08-ef-2-13"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s08","version":"cnb-sexto-6366892d2b4b356c","lesson":{"id":"s08-d5-taller","kind":"taller","day":5,"title":"Panel de energía de nuestra escuela","icon":"Presentation","minutes":19,"gancho":"¿Cómo puede un panel llamar la atención sin convertir una estimación en un dato inventado?","objetivos":["Construir en una hoja un panel legible que conserve dato exacto, aproximación, fuente, escenario y recomendaciones justificadas"],"resumen":["Caso escolar simulado; no describe tu escuela.","El dato exacto permite verificar; el redondeado ayuda a comunicar y se presenta como aproximado.","Una recomendación responsable une una acción posible con una razón científica sin prometer ahorros inventados.","El panel se construye en papel o cuaderno; la actividad registra decisiones y criterios, no afirma guardar dibujos o archivos."],"media":{"id":"s08-taller-paquete","kind":"image","title":"Paquete y hoja para el panel","aspect":"16:9","alt":"Ficha simulada con consumo exacto, conteos de auditoría y fuente, junto a una hoja dividida en titular, gráfica, fuente y recomendaciones.","brief":"Imagen didáctica 1600×900. A la izquierda, paquete rotulado exactamente “Caso escolar simulado; no describe tu escuela”, fuente “Dossier didáctico Energía 8, edición 2026”, consumo 12,468 kWh y conteos simulados: aula 8, pasillo 5, biblioteca 3. A la derecha, hoja en blanco con cuatro zonas: titular, gráfica, fuente/escenario y recomendaciones. Texto grande y contraste AA; no incluir respuestas marcadas ni logos reales. Target: public/media/s08-taller-paquete.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"construir","areas":["mat","l1","cnt","art"],"cnb":["mat:4.1.4","l1:8.2.4","cnt:8.2.1"],"title":"1 min · Encargo y cuatro secciones","prompt":"En una hoja o cuaderno traza cuatro zonas con jerarquía visual: titular con dato, gráfica, fuente y escenario, y recomendaciones con razón científica.","type":"explain","props":{"icon":"LayoutPanelTop","body":"Trabajarás solo con el paquete suministrado. El rótulo **Caso escolar simulado; no describe tu escuela** debe quedar visible. No midas, entrevistes ni inventes información externa.","reveal":[{"icon":"Sigma","front":"Dato","back":"Conserva 12,468 kWh y comunica también su aproximación."},{"icon":"ChartColumn","front":"Visual","back":"Representa los conteos simulados sin cambiar la escala."},{"icon":"BookOpenCheck","front":"Fuente","back":"Dossier didáctico Energía 8, edición 2026."},{"icon":"Lightbulb","front":"Acción","back":"Relaciona cada consejo con la transformación o el uso racional de energía."}]},"id":"s08-d5-taller-1"},{"fase":"construir","areas":["l1","cnt"],"cnb":["l1:8.2.4","cnt:8.2.1"],"title":"2 min · Qué afirma el paquete","prompt":"Clasifica cada frase antes de usarla. Una afirmación confiable distingue medición simulada, fuente y algo que todavía no está respaldado.","hint":"Busca unidad, procedencia y alcance.","explain":"La etiqueta de escenario impide que el lector confunda datos didácticos con mediciones de su escuela.","type":"sort","props":{"buckets":[{"id":"med","label":"Dato del caso","icon":"Gauge"},{"id":"fue","label":"Fuente o alcance","icon":"BookOpenCheck"},{"id":"sin","label":"Sin respaldo","icon":"CircleHelp"}],"items":[{"id":"a","text":"Consumo anual simulado: 12,468 kWh","bucket":"med"},{"id":"b","text":"Dossier didáctico Energía 8, edición 2026","bucket":"fue"},{"id":"c","text":"No describe tu escuela","bucket":"fue"},{"id":"d","text":"La escuela ahorrará exactamente Q3,000","bucket":"sin"}]},"id":"s08-d5-taller-2"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.4"],"title":"2 min · Dato exacto y aproximado","prompt":"El caso registra **12,468 kWh**. Aproxima al millar para el titular.","hint":"Mira la cifra de las centenas.","explain":"La centena es 4: 12,468 kWh se aproxima a **12,000 kWh**. Conserva ambos valores.","type":"number-input","props":{"answer":12000,"unit":"kWh"},"id":"s08-d5-taller-3"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.4"],"title":"1 min · Titular honesto","prompt":"¿Qué titular comunica la aproximación sin ocultar el dato exacto?","type":"choice","props":{"options":[{"id":"a","text":"Caso simulado: aproximadamente 12,000 kWh (dato exacto: 12,468 kWh)"},{"id":"b","text":"Nuestra escuela gasta exactamente 12,000 kWh"},{"id":"c","text":"Ahorramos miles de quetzales"}],"correct":["a"]},"id":"s08-d5-taller-4"},{"fase":"aplicar","areas":["mat","art"],"cnb":["mat:4.1.4"],"title":"2 min · Gráfica del caso","prompt":"Construye una gráfica con los conteos **simulados** de luces encendidas. Copia después la forma general en tu hoja con título y rótulos visibles.","hint":"Mantén la misma escala para las tres barras y destaca primero el dato principal.","explain":"La gráfica permite comparar sin convertir el conteo en consumo eléctrico; la jerarquía visual guía la lectura.","type":"chart-builder","props":{"categories":[{"id":"a","label":"Aula","icon":"School"},{"id":"b","label":"Pasillo","icon":"Footprints"},{"id":"c","label":"Biblioteca","icon":"Library"}],"data":[8,5,3],"max":10,"step":1,"unit":"luces","source":"Caso escolar simulado; conteos didácticos, no mediciones reales"},"id":"s08-d5-taller-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.2.1"],"title":"1 min · Acción y razón","prompt":"Relaciona cada recomendación con una razón demostrable. Ninguna pareja promete una cantidad de ahorro.","explain":"La electricidad se transforma en luz, movimiento o calor; evitar usos innecesarios reduce la energía demandada.","type":"match","props":{"pairs":[{"id":"a","left":"Apagar una luz cuando hay iluminación natural suficiente","leftIcon":"Sun","right":"Evita una transformación eléctrica-lumínica innecesaria"},{"id":"b","left":"Apagar el ventilador al salir","leftIcon":"Fan","right":"Evita movimiento sin una persona que lo necesite"},{"id":"c","left":"Revisar el sello del refrigerador","leftIcon":"Refrigerator","right":"Reduce pérdidas de frío que obligan al motor a trabajar más"}]},"id":"s08-d5-taller-6"},{"fase":"aplicar","areas":["mat","l1","cnt","art"],"cnb":["mat:4.1.4","l1:8.2.4","cnt:8.2.1"],"title":"3 min · Componer el panel","prompt":"En tu hoja escribe el titular, el dato exacto con unidad y el rótulo completo del escenario. Usa tamaño, posición y contraste para ordenar la lectura.","type":"project","props":{"goal":"Dejar visibles la diferencia entre exacto y aproximado y la procedencia del caso.","steps":[{"title":"Titular","detail":"Escribe “aproximadamente 12,000 kWh”."},{"title":"Dato verificable","detail":"Añade “dato exacto: 12,468 kWh”."},{"title":"Alcance y fuente","detail":"Copia “Caso escolar simulado; no describe tu escuela” y “Dossier didáctico Energía 8, edición 2026”."}],"evidence":"Panel de papel con los cuatro textos legibles.","rubric":["Exacto y aproximado no se confunden","La unidad kWh aparece","Escenario y fuente son visibles"]},"id":"s08-d5-taller-7"},{"fase":"aplicar","areas":["mat","l1","cnt","art"],"cnb":["mat:4.1.4","l1:8.2.7","cnt:8.2.1"],"title":"2 min · Visual y recomendaciones","prompt":"Añade a la hoja una gráfica pequeña y dos recomendaciones con su razón científica; conserva una jerarquía visual clara.","type":"project","props":{"goal":"Completar el panel sin afirmar mediciones ni ahorros que el paquete no contiene.","steps":[{"title":"Gráfica","detail":"Dibuja tres barras proporcionales: 8, 5 y 3 luces."},{"title":"Recomendaciones","detail":"Escribe dos acciones posibles y, junto a cada una, por qué evita un uso innecesario."}],"evidence":"Gráfica rotulada y dos pares acción-razón en la hoja.","rubric":["La escala permite comparar","Las recomendaciones son prácticas","No prometo ahorro exacto"]},"id":"s08-d5-taller-8"},{"fase":"aplicar","areas":["l1","art"],"cnb":["l1:8.2.7"],"title":"1 min · Revisión final","prompt":"Revisa tu hoja con un criterio a la vez, incluida la jerarquía visual.","explain":"Una revisión breve puede detectar exageraciones y problemas de legibilidad.","type":"sort","props":{"buckets":[{"id":"si","label":"Listo","icon":"BadgeCheck"},{"id":"aj","label":"Ajustar","icon":"PencilRuler"}],"items":[{"id":"a","text":"El exacto y el aproximado tienen etiqueta distinta","bucket":"si"},{"id":"b","text":"La fuente aparece en letra imposible de leer","bucket":"aj"},{"id":"c","text":"Las barras parten de la misma base","bucket":"si"},{"id":"d","text":"Una recomendación promete Q500 sin cálculo","bucket":"aj"}]},"id":"s08-d5-taller-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.4"],"title":"1 min · Salida de aproximación","prompt":"Otro caso registra **15,672 kWh**. Aproxima al millar.","type":"number-input","props":{"answer":16000,"unit":"kWh"},"id":"s08-d5-taller-10"},{"fase":"comprobar","areas":["l1","art"],"cnb":["l1:8.2.4"],"title":"1 min · Salida de publicación","prompt":"¿Qué ajuste de fuente y jerarquía visual hace más confiable y legible un panel?","type":"choice","props":{"options":[{"id":"a","text":"Poner fuente y escenario junto al dato, con contraste suficiente"},{"id":"b","text":"Quitar “aproximadamente” para acortar el titular"},{"id":"c","text":"Esconder el dato exacto debajo de una imagen"}],"correct":["a"]},"id":"s08-d5-taller-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat","l1","cnt","art"],"cnb":["mat:4.1.4","l1:8.2.4","cnt:8.2.1"],"type":"reflection","props":{"statements":["Distingo dato exacto y aproximado","Hago visible la fuente","Justifico recomendaciones sin inventar ahorros"],"commitments":["Antes de publicar, comprobaré dato, unidad, fuente y alcance"]},"id":"s08-d5-taller-12"}]}},{"missionId":"s08","version":"cnb-sexto-08306d1b795172b5","lesson":{"id":"s08-d5-reto","kind":"reto","day":5,"title":"Reto de la semana 8","icon":"Trophy","minutes":14,"objetivos":["Resolver situaciones nuevas de las diez áreas"],"resumen":["Apliqué aproximación, fuentes, investigación, ciudadanía, gramática, inglés, memoria, publicación, juego inclusivo y conservación."],"media":{"id":"s08-d5-reto","kind":"image","title":"Mesa de datos confiables","aspect":"16:9","alt":"Mesa con fichas de números mayas, fuentes, energía, historia, lenguas, arte, actividad física y conservación.","brief":"Imagen 1600×900 para evaluación. Mostrar diez fichas nuevas sin respuestas marcadas: número para redondear, numeral maya, nota con fuente, protocolo de investigación, dato mundial fechado, oración gramatical, fact card en inglés, mapa CEH atribuido, ficha biográfica artística, secuencia de juego y acción voluntaria. Alto contraste y texto legible; no usar datos de una escuela real. Target: public/media/s08-d5-reto.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.4"],"prompt":"Aproxima **28,731** a la unidad de millar.","type":"number-input","props":{"answer":29000},"id":"s08-d5-reto-1"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"Una tabla viene del “Dossier didáctico 2026”. ¿Qué pie conserva la honestidad intelectual?","type":"choice","props":{"options":[{"id":"a","text":"Fuente: Dossier didáctico 2026; datos simulados"},{"id":"b","text":"Medición de nuestra escuela"},{"id":"c","text":"Datos comprobados por todos"}],"correct":["a"]},"id":"s08-d5-reto-2"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.1.1"],"prompt":"Clasifica tres protocolos nuevos por el lugar donde obtienen evidencia.","type":"sort","props":{"buckets":[{"id":"doc","label":"Documental"},{"id":"cam","label":"Campo"},{"id":"lab","label":"Laboratorio"}],"items":[{"id":"a","text":"Comparar mapas satelitales publicados y sus fichas técnicas","bucket":"doc"},{"id":"b","text":"Registrar sombra y temperatura en tres patios","bucket":"cam"},{"id":"c","text":"Controlar material y tiempo en una prueba de aislamiento","bucket":"lab"}]},"id":"s08-d5-reto-3"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Aplica una norma fiscal y una responsabilidad: un comercio cobró IVA, pero rechaza entregar comprobante. ¿Qué procede?","type":"choice","props":{"options":[{"id":"a","text":"Solicitar el comprobante y conservarlo como respaldo de la operación"},{"id":"b","text":"Aceptar que el comercio sustituya la obligación con una promesa"},{"id":"c","text":"Crear una regla privada para eliminar el tributo"}],"correct":["a"]},"id":"s08-d5-reto-4"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.1"],"prompt":"Clasifica las palabras de “El medidor portátil registra”.","type":"sort","props":{"buckets":[{"id":"s","label":"Sustantivo"},{"id":"a","label":"Adjetivo"},{"id":"v","label":"Verbo"}],"items":[{"id":"1","text":"medidor","bucket":"s"},{"id":"2","text":"portátil","bucket":"a"},{"id":"3","text":"registra","bucket":"v"}]},"id":"s08-d5-reto-5"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:5.2.2"],"prompt":"Caso ficticio: completa la biografía con la fact card suministrada de Elena Cruz, persona ficticia.","type":"fill-blank","props":{"text":"In 2010, Elena Cruz, persona ficticia, [[became]] an electrical engineer.","distractors":["become","born"]},"id":"s08-d5-reto-6"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Una tarjeta del paquete CEH nombra un pueblo y su departamento. ¿Qué acción lo localiza correctamente en el mapa?","type":"choice","props":{"options":[{"id":"a","text":"Colocar la etiqueta del pueblo dentro del departamento nombrado y conservar la atribución CEH"},{"id":"b","text":"Elegir el color más oscuro para afirmar que sufrió más"},{"id":"c","text":"Quitar el nombre del departamento y la fuente"}],"correct":["a"]},"id":"s08-d5-reto-7"},{"fase":"comprobar","areas":["art"],"cnb":["art:4.3.2"],"prompt":"Publica y comparte en el diario una ficha biográfica nueva. Paquete suministrado: **Lucía Méndez, ceramista ficticia; creó Vasijas del bosque en 2022; fuente: Catálogo escolar simulado 2026**. Escribe nombre, obra, aporte prudente y fuente; indica que queda visible para el curso.","type":"short-answer","props":{"minWords":26,"placeholder":"Ficha biográfica publicada…","model":"Ficha biográfica publicada para el curso: Lucía Méndez, ceramista ficticia, creó Vasijas del bosque en 2022. Su obra explora formas vegetales. Fuente: Catálogo escolar simulado 2026.","rubric":["Publico una ficha biográfica","Incluyo nombre y obra","Dejo visible la fuente","Rotulo el caso ficticio"]},"id":"s08-d5-reto-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.3"],"prompt":"En una **simulación individual**, dirige una rutina nueva: elige la instrucción, asigna acceso igual a roles para mujeres y hombres, adapta con seguridad, rota la secuencia y verifica la respuesta de los avatares.","type":"leadership-simulation","props":{"scenario":"Dos avatares, una mujer y un hombre, realizarán gestos laterales y alternarán modelado y señal de pausa.","instructions":[{"id":"i1","text":"Dos gestos laterales suaves y pausa con mano abierta","correct":true},{"id":"i2","text":"Muévanse rápido sin señal","correct":false}],"rolePlans":[{"id":"r1","text":"Mujer y hombre pueden modelar y cuidar la señal; alternan ambos roles","correct":true},{"id":"r2","text":"El hombre dirige siempre y la mujer observa","correct":false}],"adaptations":[{"id":"a1","text":"Ofrecer gestos pequeños de pie o sentado y detener ante molestia","correct":true},{"id":"a2","text":"Exigir la misma amplitud aunque haya dolor","correct":false}],"sequences":[{"id":"s1","text":"Explicar, modelar, ejecutar, rotar roles y verificar bienestar","correct":true},{"id":"s2","text":"Ejecutar sin explicar y terminar sin comprobar","correct":false}],"response":"Los avatares siguen la señal, alternan los roles y confirman que la adaptación es segura."},"id":"s08-d5-reto-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:5.5.2"],"prompt":"Reto revisable: usa una práctica de conservación que **realmente conoces desde tu familia, comunidad o cultura**, nombra el recurso natural y ejecuta ahora el modo de baja actividad. Registra antes, acción y después. Si no conoces una práctica propia, elige **necesito consultar** y explica a quién o qué fuente consultarás y por qué; podrás continuar, pero no acreditar dominio.","type":"cultural-conservation-practice","props":{"minWords":30,"consultationMinWords":8,"requiresLiveAction":true,"rubric":["Procedencia cultural propia y honesta","Recurso natural identificado","Acción ejecutada ahora","Antes, acción y después verificables"],"example":{"culturalPractice":"En mi comunidad conozco la práctica de apagar luces que no se necesitan.","naturalResource":"Ayuda a cuidar agua y recursos usados para generar electricidad.","beforeAction":"Antes observé sonido opcional activo.","actionReport":"Activé ahora el modo de baja actividad voluntario.","afterAction":"Después verifiqué sonido apagado y movimiento reducido activo."}},"id":"s08-d5-reto-10"}]}},{"missionId":"s08","version":"cnb-sexto-e697b014c34843d8","lesson":{"id":"s08-ccss-2","title":"Impuestos: una responsabilidad de todos","icon":"Landmark","minutes":15,"gancho":"Cuando compras un cuaderno de Q10, una parte de ese dinero no es para la librería. ¿Para quién es? ¿Y quién decidió que así fuera?","objetivos":["Clasificar y aplicar normas fiscales y responsabilidades ciudadanas en casos suministrados"],"resumen":["Los impuestos son pagos obligatorios que la población y las empresas hacen al Estado para financiar servicios públicos: escuelas, hospitales, carreteras, seguridad.","Las normas jurídicas tienen un orden: la Constitución Política (la ley suprema) establece el deber de contribuir a los gastos públicos y que solo el Congreso puede crear impuestos; las leyes (como la del IVA y la del ISR) y el Código Tributario los desarrollan; los reglamentos explican cómo aplicarlas. Las municipalidades cobran impuestos como el IUSI.","El IVA es el 12 % del valor de lo que se compra y casi siempre ya viene incluido en el precio. El ISR se paga sobre los ingresos. La SAT es la institución que recauda los impuestos.","Pedir factura, no evadir impuestos y cuidar los bienes públicos son responsabilidades ciudadanas; también lo es vigilar que el dinero público se use bien. Los tratados comerciales también fijan reglas sobre los impuestos a las importaciones."],"media":{"id":"s08-ccss-2-ruta","kind":"animation","title":"El viaje de un quetzal de impuestos","aspect":"16:9","duration":45,"alt":"Animación que sigue una moneda desde la compra de un cuaderno con factura hasta el presupuesto del Estado y de ahí a una escuela, un centro de salud y una carretera.","brief":"Animación 2D de 45 s. Una niña compra un cuaderno y recibe su factura. Una moneda con la etiqueta \\"IVA\\" sale de la caja registradora, viaja por una flecha hasta un edificio rotulado \\"SAT\\", luego a un cofre \\"Presupuesto del Estado aprobado por el Congreso\\", y de ahí se reparte en tres flechas hacia una escuela con pupitres nuevos, un centro de salud con medicinas y una carretera en construcción. Al final aparece la frase \\"Tus impuestos regresan en servicios. Pide tu factura\\". Narración en español con subtítulos. Sin logos oficiales reales. Target: public/media/s08-ccss-2-ruta.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Impuestos y responsabilidad","prompt":"Lee el principio que organiza esta lección.","type":"explain","props":{"icon":"Receipt","body":"Los impuestos financian servicios públicos. La Constitución, las leyes y los reglamentos establecen quién puede crearlos y cómo se aplican."},"id":"s08-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","prompt":"La escuela pública, el centro de salud y la carretera de tu municipio cuestan mucho dinero. ¿De dónde sale principalmente ese dinero?","explain":"Sale principalmente de los **impuestos** que pagamos todas las personas y empresas. El Estado no \\"tiene\\" dinero propio: administra lo que la población aporta.","type":"choice","props":{"options":[{"id":"a","text":"De los impuestos que pagan las personas y las empresas","icon":"Coins"},{"id":"b","text":"El gobierno lo imprime cuando quiere","icon":"Banknote","feedback":"Imprimir dinero sin respaldo hace que los precios suban. Los servicios públicos se pagan principalmente con impuestos."},{"id":"c","text":"Lo regalan otros países cada año","icon":"Gift","feedback":"A veces hay donaciones, pero la mayor parte sale de los impuestos de la población."}],"correct":["a"]},"id":"s08-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"¿Qué son los impuestos?","prompt":"Los **impuestos** (o tributos) son pagos **obligatorios** que se hacen al Estado, establecidos por la ley. Toca cada tarjeta.","type":"explain","props":{"icon":"Landmark","body":"La **SAT** (Superintendencia de Administración Tributaria) recauda los impuestos nacionales. El **Congreso** aprueba cada año el **presupuesto**, que dice en qué se gastará ese dinero.","reveal":[{"icon":"ShoppingCart","front":"IVA","back":"**Impuesto al Valor Agregado**: el **12 %** de lo que se compra o de un servicio. Lo pagamos todos, aunque seamos niños, y **casi siempre ya viene incluido** en el precio."},{"icon":"Wallet","front":"ISR","back":"**Impuesto Sobre la Renta**: se paga sobre los **ingresos** de personas y empresas."},{"icon":"Home","front":"IUSI","back":"**Impuesto Único Sobre Inmuebles**: lo pagan los dueños de terrenos y casas, y lo cobra la **municipalidad**."},{"icon":"FileText","front":"La factura","back":"Es el comprobante de una compra. Pedirla ayuda a que el IVA que pagaste **llegue al Estado** y no se quede en manos de quien vende."}]},"id":"s08-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Las normas jurídicas tienen un orden","prompt":"Las **normas jurídicas** son las reglas obligatorias de un país. No todas tienen el mismo nivel: se ordenan como una **pirámide**. Toca cada tarjeta, de arriba hacia abajo.","media":{"id":"s08-ccss-2-piramide","kind":"diagram","title":"La pirámide de las normas fiscales","aspect":"3:4","alt":"Pirámide de tres niveles: arriba la Constitución, en medio las leyes del Congreso y el Código Tributario, abajo los reglamentos; a un lado, las normas municipales.","brief":"Diagrama de pirámide con tres niveles de colores. Punta: \\"Constitución Política de la República (1985)\\" con la nota \\"deber de contribuir a los gastos públicos; solo el Congreso crea impuestos\\". Centro: \\"Leyes del Congreso (decretos)\\": Ley del IVA, Ley del ISR, Código Tributario. Base: \\"Reglamentos del Organismo Ejecutivo: explican cómo aplicar las leyes\\". A un lado, un recuadro \\"Municipalidades: IUSI y arbitrios, según la ley\\" y otro \\"Tratados internacionales aprobados por el Congreso (p. ej., impuestos a las importaciones)\\". Flecha lateral: \\"ninguna norma puede contradecir a la de arriba\\". Texto grande, íconos simples. Target: public/media/s08-ccss-2-piramide.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"Layers","body":"Regla de oro: **ninguna norma puede contradecir a otra de nivel más alto**. Si una ley contradice la Constitución, la **Corte de Constitucionalidad** puede anularla.","reveal":[{"icon":"ScrollText","front":"Constitución Política","back":"La **ley suprema**. Establece que es **deber** de los guatemaltecos **contribuir a los gastos públicos** según la ley, y que **solo el Congreso** puede crear impuestos (principio de legalidad)."},{"icon":"Gavel","front":"Leyes ordinarias","back":"Las aprueba el **Congreso** como decretos. Ejemplos: la **Ley del IVA**, la del **ISR** y el **Código Tributario**, que da las reglas generales para pagar y cobrar tributos."},{"icon":"FileText","front":"Reglamentos","back":"Los emite el **Organismo Ejecutivo** para explicar **cómo** aplicar una ley. No pueden crear impuestos nuevos."},{"icon":"Building","front":"Normas municipales","back":"Las municipalidades cobran impuestos como el **IUSI** y tasas por servicios (agua, mercado, basura), siempre según lo que permite la ley."},{"icon":"Handshake","front":"Tratados internacionales","back":"Guatemala también firma **tratados** con otros países. Cuando el **Congreso** los aprueba, se vuelven obligatorios en el país. Los **tratados comerciales** (recuerda la semana 3) fijan, por ejemplo, cuánto impuesto pagan los productos que se importan."}]},"id":"s08-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Clasifica cada norma o afirmación según su **nivel** en la pirámide.","hint":"Lo más general y superior está en la Constitución; los impuestos concretos, en leyes del Congreso; los detalles de cómo aplicarlas, en reglamentos.","explain":"La Constitución manda el deber de contribuir; las leyes crean cada impuesto; los reglamentos dicen cómo cumplirlas.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución","icon":"ScrollText","color":"var(--area-ccss)"},{"id":"ley","label":"Ley del Congreso","icon":"Gavel","color":"var(--c-maiz-strong)"},{"id":"reg","label":"Reglamento","icon":"FileText","color":"var(--c-ok)"}],"items":[{"id":"n1","text":"Es deber de los guatemaltecos contribuir a los gastos públicos","bucket":"con"},{"id":"n2","text":"Ley del IVA: el impuesto es del 12 %","bucket":"ley"},{"id":"n3","text":"Detalle de cómo llenar un formulario para declarar un impuesto","bucket":"reg"},{"id":"n4","text":"Solo el Congreso puede crear impuestos","bucket":"con"},{"id":"n5","text":"Código Tributario: reglas generales para pagar tributos","bucket":"ley"}]},"id":"s08-ccss-2-5"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.4.1"],"ambito":"hacer","title":"Ejemplo resuelto: ¿cuánto IVA pago?","prompt":"El IVA es el 12 % del valor del producto. Mira dos casos con precios supuestos.","type":"worked-example","props":{"icon":"Calculator","problem":"Caso 1: una mochila vale **Q50 sin IVA**. ¿Cuánto IVA se paga y cuál es el precio final? Caso 2: en una tienda pagas **Q112** por unos zapatos, **con el IVA ya incluido**. ¿Cuánto de eso es IVA?","steps":[{"text":"Caso 1: 12 % de 50 = 50 × 12 ÷ 100 = 600 ÷ 100 = **Q6** de IVA.","why":"\\"Por ciento\\" significa \\"de cada 100\\": 12 de cada 100 quetzales."},{"text":"Precio final: 50 + 6 = **Q56**."},{"text":"Caso 2: si el precio sin IVA fuera Q100, el IVA sería Q12 y el total Q112. Entonces, de Q112, **Q12 son IVA**.","why":"Cuando el IVA está incluido, el precio es el 112 % del valor sin impuesto."}],"answer":"Caso 1: **Q6** de IVA y precio final **Q56**. Caso 2: **Q12** de los Q112 son IVA.","tip":"En las tiendas de Guatemala el precio que ves casi siempre ya incluye el IVA. Por eso, pide factura."},"id":"s08-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"hacer","prompt":"Aplica la jerarquía fiscal: clasifica cada decisión del caso suministrado según la norma o responsabilidad que corresponde.","explain":"La Constitución reserva al Congreso la creación de impuestos; la ley crea el tributo; el reglamento detalla su aplicación; pedir factura es responsabilidad ciudadana.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución"},{"id":"ley","label":"Ley"},{"id":"reg","label":"Reglamento"},{"id":"res","label":"Responsabilidad ciudadana"}],"items":[{"id":"a1","text":"Solo el Congreso puede crear un impuesto nacional","bucket":"con"},{"id":"a2","text":"El decreto establece el IVA","bucket":"ley"},{"id":"a3","text":"Una disposición explica cómo presentar el formulario","bucket":"reg"},{"id":"a4","text":"La persona compradora pide factura","bucket":"res"}]},"id":"s08-ccss-2-7"},{"fase":"aplicar","areas":["ccss","fc"],"cnb":["ccss:8.4.1"],"ambito":"ser","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Store","text":"Compras útiles escolares por Q84. El vendedor te dice: \\"Si no te doy factura, te lo dejo en Q80\\"."},"options":[{"id":"a","icon":"FileText","text":"Pido la factura y pago el precio completo","consequence":"El IVA que pagaste llega al Estado y se convierte en servicios públicos. Cumpliste con tu responsabilidad ciudadana.","values":["responsabilidad","honestidad"],"constructive":true},{"id":"b","icon":"MessageCircle","text":"Pido la factura y le explico a mi familia por qué es importante","consequence":"Además de cumplir, ayudas a que otros entiendan que la factura protege el dinero de todos.","values":["responsabilidad","solidaridad"],"constructive":true},{"id":"c","icon":"Coins","text":"Acepto el descuento sin factura","consequence":"Ahorras Q4, pero el vendedor no reporta la venta y ese impuesto no llega a escuelas ni hospitales. Es una forma de evasión.","values":[],"constructive":false}]},"id":"s08-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Aplica la Constitución, la ley o el reglamento y decide la responsabilidad fiscal: un reglamento intenta crear un impuesto nuevo sin ley del Congreso. ¿Qué corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Señalo que contradice el principio constitucional: un reglamento no crea impuestos"},{"id":"b","text":"Lo acepto porque cualquier reglamento está sobre la Constitución"},{"id":"c","text":"Lo trato como una decisión privada sin efecto legal"}],"correct":["a"]},"id":"s08-ccss-2-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Una venta incluye IVA pero el vendedor ofrece omitir la factura. ¿Cómo cumples tu responsabilidad ciudadana?","type":"choice","props":{"options":[{"id":"a","text":"Pedir la factura y conservar el comprobante"},{"id":"b","text":"Aceptar porque pagar menos reemplaza la norma"},{"id":"c","text":"Inventar un reglamento personal"}],"correct":["a"]},"id":"s08-ccss-2-10"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s08","version":"cnb-sexto-a80ea1204c3bd13f","lesson":{"id":"s08-pyd-1","title":"Una práctica local de baja actividad","icon":"Gauge","minutes":13,"gancho":"¿Qué ajuste voluntario puedes aplicar ahora mismo para reducir actividad opcional del dispositivo?","objetivos":["Relacionar una práctica voluntaria de conservación conocida en la familia, comunidad o cultura con el recurso natural que protege, y ejecutar su adaptación en el modo de baja actividad"],"resumen":["El modo de baja actividad desactiva el sonido opcional y activa movimiento reducido; ambos cambios quedan guardados en este dispositivo.","Es una práctica voluntaria, local, accesible y reversible que reduce actividad opcional de la app; no garantiza ni cuantifica ahorro de energía.","Las prácticas de conservación varían entre familias, comunidades y culturas. Para evidenciar el indicador se describe solo una práctica que realmente se conoce; el ejemplo didáctico suministrado enseña, pero no acredita dominio.","Una práctica explica qué recurso natural cuida y qué principio aplica. El modo de baja actividad es una adaptación contemporánea modesta de evitar actividad innecesaria.","Verificar el estado después de actuar distingue una práctica ejecutada de una intención o un autorreporte.","Si el modo ya está activo al entrar, mantenerlo voluntariamente durante 25 segundos y comprobar su estado constituye la práctica alternativa.","Restaurar devuelve exactamente el estado previo de esos dos ajustes sin cambiar los demás."],"media":{"id":"s08-pyd-1-modo-baja-actividad","kind":"diagram","title":"Antes, después y restauración","aspect":"16:9","alt":"Tres estados de ajustes: antes con sonido opcional activo y movimiento reducido inactivo; después con sonido apagado y movimiento reducido activo; restauración con los valores iniciales.","brief":"Diagrama de interfaz en tres columnas conectadas por flechas: “Antes”, “Modo de baja actividad” y “Restaurado”. Mostrar controles accesibles de sonido opcional y movimiento reducido con iconos Lucide Volume2, VolumeX, Accessibility y RotateCcw, además de texto Activado/Desactivado para no depender del color. Incluir la nota “Práctica modesta; no cuantifica ahorro”. Target: public/media/s08-pyd-1-modo-baja-actividad.svg. Producción: SVG con viewBox 0 0 1600 900 y versión PNG de respaldo 1600×900 px. Accesibilidad: contraste AA, orden de lectura izquierda a derecha y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"conocer","title":"Conservar sin inventar tradiciones","prompt":"Lee el marco respetuoso para vincular cultura, recurso natural y acción.","type":"explain","props":{"icon":"Leaf","body":"Una práctica de conservación puede ser conocida en tu **familia, comunidad o cultura**, pero no todas las personas comparten las mismas. Nombra una que realmente conozcas o usa esta alternativa: **“Ejemplo didáctico suministrado: aprovechar la luz natural y apagar una lámpara que no se necesita”**. Este ejemplo evita uso innecesario de recursos naturales e insumos empleados para generar electricidad; no afirmes que es tradición de tu familia o comunidad."},"id":"s08-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Del principio a una adaptación contemporánea","prompt":"Aprende el procedimiento antes de ejecutar la práctica.","type":"explain","props":{"icon":"ListChecks","body":"**Identifica** una práctica real o el ejemplo suministrado, **explica** qué recurso natural protege, **conecta** su principio de evitar actividad innecesaria con el modo de baja actividad y después **ejecuta y verifica** la ruta que muestre la app."},"id":"s08-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Modelo con ejemplo suministrado","prompt":"Observa cómo Ana usa el ejemplo sin atribuírselo a su cultura.","type":"worked-example","props":{"icon":"Gauge","problem":"Ana elige el ejemplo didáctico suministrado sobre aprovechar luz natural.","steps":[{"text":"Lo rotula como **ejemplo suministrado**, no como costumbre de su familia."},{"text":"Explica que cuida recursos naturales e insumos usados para generar electricidad al evitar actividad innecesaria."},{"text":"Lo adapta de forma contemporánea: activa el **modo de baja actividad** y verifica sus dos ajustes."},{"text":"Decide conservarlo o restaurarlo sin prometer ni calcular una cantidad de ahorro."}],"answer":"La evidencia une procedencia honesta, recurso protegido, principio de conservación y acción comprobada.","tip":"Identificar → explicar recurso → adaptar → ejecutar y verificar."},"id":"s08-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Selecciona las **dos rutas honestas** antes de crear tu evidencia cultural de conservación.","hint":"Una ruta demuestra práctica propia, recurso y acción segura; la otra reconoce qué consulta falta sin fingir dominio.","explain":"La evidencia elegible parte de una práctica genuinamente conocida, nombra el recurso natural y realiza una acción voluntaria segura. Si falta ese conocimiento, la ruta correcta es identificar a quién o qué fuente consultar y por qué; permite continuar, pero no acredita dominio.","type":"choice","props":{"multiple":true,"options":[{"id":"known","text":"Conozco una práctica de mi familia, nombro el recurso natural y realizo ahora una acción voluntaria segura"},{"id":"consult","text":"Aún no conozco una práctica propia: indico a quién o qué fuente consultaré y por qué","icon":"MessagesSquare"},{"id":"borrowed","text":"Copio el ejemplo suministrado y afirmo que es tradición de mi comunidad","feedback":"Un ejemplo didáctico enseña, pero no demuestra procedencia cultural propia."},{"id":"unsafe","text":"Conozco una práctica, pero ejecuto una acción riesgosa para demostrarla","feedback":"La acción debe ser voluntaria, segura, accesible y verificable."}],"correct":["known","consult"]},"id":"s08-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Repasa qué revisará la persona docente en la evidencia compuesta.","type":"flashcards","props":{"cards":[{"icon":"Home","front":"Procedencia","back":"Una práctica que realmente conoces desde tu familia, comunidad o cultura; no una tradición inventada."},{"icon":"Leaf","front":"Recurso","back":"El recurso natural que la práctica ayuda a proteger."},{"icon":"ListChecks","front":"Acción comprobada","back":"Qué observaste antes, qué hiciste ahora y qué verificaste después."}]},"id":"s08-pyd-1-5"},{"id":"s08-pyd-1-6","fase":"aplicar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","prompt":"Crea evidencia **desde tu cultura**: identifica una práctica de conservación que realmente conoces en tu familia o comunidad, nombra el recurso natural, registra antes, ejecuta ahora la adaptación voluntaria del **modo de baja actividad**, verifica sus ajustes y registra acción y después. Si aún no conoces una práctica propia, escribe **“necesito consultar”**: no afirmes dominio. Tu maestra o maestro revisará lo que hiciste.","type":"cultural-conservation-practice","props":{"minWords":30,"consultationMinWords":8,"requiresLiveAction":true,"rubric":["La práctica es genuinamente conocida en mi contexto","Nombro el recurso natural","Realicé una acción segura ahora","Registro antes, acción y después sin inventar ahorro"],"example":{"culturalPractice":"En mi familia aprovechamos la luz natural antes de encender una lámpara.","naturalResource":"Cuidamos agua y otros recursos usados para generar electricidad.","beforeAction":"Antes, el sonido opcional estaba activo.","actionReport":"Activé voluntariamente el modo de baja actividad ahora.","afterAction":"Después verifiqué sonido apagado y movimiento reducido activo."}}},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:5.5.2"],"ambito":"hacer","title":"Antes de las salidas","prompt":"Distingue qué registrarás según la ruta que elegiste.","type":"explain","props":{"icon":"Route","body":"Si conoces la práctica, conserva **procedencia, recurso natural, antes, acción segura y después**. Si necesitas consulta, registra **a quién o qué fuente consultarás y por qué**; no marques criterios que todavía no puedes demostrar."},"id":"s08-pyd-1-7"},{"id":"s08-pyd-1-salida-a","fase":"comprobar","areas":["pyd"],"cnb":["pyd:5.5.2"],"prompt":"Salida revisable: registra una práctica que realmente conoces desde familia, comunidad o cultura, el recurso natural y **antes → acción voluntaria segura realizada → después**. Si necesitas consulta, elige esa ruta, indica a quién o qué fuente consultar y por qué; podrás continuar sin recibir dominio todavía.","type":"cultural-conservation-practice","props":{"minWords":18,"consultationMinWords":8,"requiresLiveAction":false,"rubric":["Identifico procedencia cultural propia","Nombro recurso natural","Registro acción ejecutada","Incluyo antes y después"],"example":{"culturalPractice":"En mi familia apagamos lámparas que quedan sin uso.","naturalResource":"La práctica protege recursos naturales usados para producir electricidad.","beforeAction":"Antes observé una actividad opcional encendida.","actionReport":"Realicé una adaptación voluntaria y segura.","afterAction":"Después verifiqué el estado cambiado."}}},{"id":"s08-pyd-1-salida-b","fase":"comprobar","areas":["pyd"],"cnb":["pyd:5.5.2"],"prompt":"Segunda salida revisable: explica otra decisión de conservación desde una práctica realmente conocida en tu cultura, familia o comunidad; nombra el recurso natural y registra **antes, acción segura y después**. Si no conoces otra, usa la ruta de consulta y explica la fuente o persona que necesitas y por qué, sin afirmar dominio.","type":"cultural-conservation-practice","props":{"minWords":18,"consultationMinWords":8,"requiresLiveAction":false,"rubric":["Vinculo práctica cultural propia","Nombro recurso natural","Diferencio antes, acción y después","Justifico la decisión voluntaria"],"example":{"culturalPractice":"En mi comunidad conozco aprovechar ventilación natural.","naturalResource":"La práctica cuida recursos naturales asociados con la electricidad.","beforeAction":"Antes comprobé el estado disponible.","actionReport":"Elegí una acción accesible y voluntaria.","afterAction":"Después verifiqué el resultado y decidí conservarlo."}}},{"fase":"reflexionar","areas":["pyd"],"cnb":[],"ambito":"ser","prompt":"Cierra sin calificar: reconoce con honestidad si tu vínculo cultural necesita conversación o revisión adicional.","type":"reflection","props":{"statements":["Describí solo una práctica que realmente conozco","Diferencié evidencia propia y ejemplo suministrado"],"commitments":["Consultaré con respeto si todavía no conozco una práctica de mi contexto"]},"id":"s08-pyd-1-10"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s08","version":"cnb-sexto-8ab639ae315bfa92","lesson":{"id":"s08-l1-4","title":"El informe: del primer borrador a la composición","icon":"FileText","minutes":15,"gancho":"Ya tienes preguntas, fuentes y notas. ¿Cómo se convierten en un texto que otros puedan leer?","objetivos":["Reconocer las partes de un informe escrito"],"resumen":["Partes del informe: título, introducción (tema, pregunta y por qué), desarrollo (un párrafo por pregunta clave), conclusión (respuesta y lo aprendido) y lista de fuentes.","Cada párrafo tiene una oración principal (la idea) y oraciones de apoyo (datos de tus notas, con su fuente).","El primer borrador es una versión de trabajo: lo importante es poner las ideas en orden; se corrige después.","Componer es transformar las notas en oraciones completas y unirlas con conectores: primero, además, por eso, finalmente."],"media":{"id":"s08-l1-4-partes","kind":"diagram","title":"Las partes de un informe","aspect":"3:4","alt":"Una hoja de informe con cinco bloques de colores: título, introducción, desarrollo con tres párrafos, conclusión y fuentes. Flechas desde las notas del cuaderno hasta los párrafos del desarrollo.","brief":"Diagrama vertical: a la izquierda, una hoja de cuaderno con notas agrupadas por preguntas 1, 2 y 3; a la derecha, la página del informe con bloques de color: TÍTULO (arriba, centrado), INTRODUCCIÓN (qué investigué, mi pregunta y por qué), DESARROLLO (tres párrafos numerados que reciben flechas desde las notas 1, 2 y 3), CONCLUSIÓN (respuesta a la pregunta y lo aprendido), FUENTES (lista). Etiquetas claras, colores suaves. Target: public/media/s08-l1-4-partes.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":[],"ambito":"conocer","prompt":"Antes de leer el modelo, reconoce qué parte de un informe ya puedes identificar.","type":"reflection","props":{"statements":["Distingo un título de un párrafo","Busco una fuente antes de confiar en un dato"],"commitments":["Comprobaré cada parte en el modelo suministrado"]},"id":"s08-l1-4-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Las partes de un informe","prompt":"Un **informe** comunica lo que investigaste de forma ordenada. Mira el diagrama y toca cada parte.","type":"explain","props":{"icon":"FileText","body":"El informe responde a tu **pregunta de investigación** con información de tus **fuentes**.","reveal":[{"icon":"Heading","front":"Título","back":"Breve y claro: \\"Datos para usar mejor la iluminación\\". Con nombre, grado y fecha."},{"icon":"DoorOpen","front":"Introducción","back":"Un párrafo: **qué** investigaste, **tu pregunta** y **por qué** es importante."},{"icon":"Layers","front":"Desarrollo","back":"**Un párrafo por cada pregunta clave**, con los datos de tus notas y sus fuentes (\\"según…\\")."},{"icon":"Flag","front":"Conclusión","back":"Responde la pregunta en pocas líneas y di **qué aprendiste** o qué propones."},{"icon":"List","front":"Fuentes","back":"La lista de todas las fuentes que usaste, en orden alfabético."}]},"id":"s08-l1-4-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Cómo se construye un párrafo","prompt":"Componer es convertir tus notas en **párrafos**. Toca cada tarjeta.","type":"explain","props":{"icon":"AlignLeft","body":"Un párrafo = **una idea**. Si cambias de idea, empieza otro párrafo.","reveal":[{"icon":"Target","front":"Oración principal","back":"Dice la idea del párrafo, casi siempre al inicio: \\"El paquete permite recomendar un uso más cuidadoso de la iluminación\\"."},{"icon":"Layers","front":"Oraciones de apoyo","back":"Explican la idea con **datos de tus notas** y su fuente. Por ejemplo, puedes atribuir a la Ficha B su comparación entre lámparas de 9 W y 60 W."},{"icon":"Link","front":"Conectores","back":"Unen las oraciones: _primero, además, también, por eso, sin embargo, finalmente_."},{"icon":"PenLine","front":"Borrador","back":"En el primer borrador **no te detengas** a corregir cada palabra: pon las ideas en orden. Deja espacio entre líneas para corregir después."}]},"id":"s08-l1-4-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","prompt":"Lee este **primer borrador**, escrito solo con el paquete suministrado. Identifica sus partes y responde.","hint":"Busca introducción, desarrollo, conclusión y fuentes; luego identifica la idea principal y sus apoyos.","explain":"El informe organiza una pregunta y datos atribuidos: la introducción presenta, el desarrollo explica con evidencia, la conclusión responde y la lista identifica las fuentes.","type":"reading","props":{"genre":"Informe escolar (borrador)","heading":"Datos para usar mejor la iluminación","passage":"Introducción. Este informe responde: ¿qué recomendación de ahorro permite sostener el paquete suministrado? El caso es simulado y no describe nuestra escuela.\\n\\nEl paquete presenta datos que deben comunicarse con su contexto. Según la Ficha A, el escenario registra exactamente 12,468 kWh y lo aproxima a 12,000 kWh. Ambos números conservan la unidad y el rótulo de caso simulado.\\n\\nLa iluminación ofrece una acción concreta. Según la Ficha B, una lámpara usó 9 W y otra 60 W en condiciones comparables. Además, la guía recomienda apagar luces de espacios vacíos. La ficha no demuestra cuánto ahorró una escuela real.\\n\\nConclusión. La evidencia permite recomendar apagar luces innecesarias y publicar los datos con fuente, unidad y contexto. No permite prometer una reducción exacta del recibo.\\n\\nFuentes: Ficha A, escenario escolar simulado. Ficha B, guía de iluminación suministrada.","questions":[{"q":"¿Qué dice la introducción?","options":[{"id":"a","text":"Por qué el tema es importante y cuál es la pregunta de investigación"},{"id":"b","text":"Solo la comparación de lámparas"},{"id":"c","text":"La lista de fuentes"}],"correct":"a","why":"Presenta el tema, explica por qué importa y formula la pregunta."},{"q":"¿Cuál es la **oración principal** del tercer párrafo?","options":[{"id":"a","text":"La iluminación ofrece una acción concreta."},{"id":"b","text":"Una lámpara usó 9 W."},{"id":"c","text":"La ficha no demuestra un ahorro real."}],"correct":"a","why":"Es la idea general del párrafo; las demás oraciones la apoyan con datos."},{"q":"¿Cómo muestra Sofía su **honestidad intelectual** en el borrador?","options":[{"id":"a","text":"Nombra las fichas, conserva unidades y declara que el caso es simulado"},{"id":"b","text":"Escribe todo sin fuentes"},{"id":"c","text":"Inventa datos para que el informe sea más largo"}],"correct":"a","why":"Nombra las fichas, conserva las unidades, declara el escenario y enumera las fuentes."},{"q":"¿Qué parte falta en la versión final?","options":[{"id":"a","text":"Agregar nombre, grado y fecha, y revisar la legibilidad"},{"id":"b","text":"Quitar la conclusión"},{"id":"c","text":"Borrar las fuentes"}],"correct":"a","why":"La tarea pedía un dibujo, y un informe lleva nombre, grado y fecha. Eso se agrega al editar."}]},"id":"s08-l1-4-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: de la nota al párrafo","prompt":"Mira cómo se compone el tercer párrafo a partir de las notas suministradas.","type":"worked-example","props":{"icon":"PenLine","problem":"Nota: “iluminación → acción concreta · LED 9 W / incand. 60 W (comparable) · apagar luces vacías · ≠ ahorro real (Ficha B)”.","steps":[{"text":"Escribo la **oración principal**: “La iluminación ofrece una acción concreta”."},{"text":"Convierto el dato en oración: “La Ficha B compara un consumo de 9 W con otro de 60 W en condiciones equivalentes”."},{"text":"Agrego la recomendación con un conector: “**Además**, la guía recomienda apagar luces de espacios vacíos”."},{"text":"Cierro con el límite: “La ficha no demuestra cuánto ahorró una escuela real”.","why":"Una conclusión honesta no excede la evidencia."}],"answer":"Un párrafo con una idea principal, tres oraciones de apoyo, dos fuentes nombradas y un conector.","tip":"Cada pregunta clave de tus notas = un párrafo del desarrollo."},"id":"s08-l1-4-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Ordena las oraciones para formar un **párrafo** sobre el dato exacto y aproximado.","explain":"Primero la oración principal, luego los datos en orden y un conector para cerrar.","type":"order","props":{"labels":{"start":"Inicio","end":"Final"},"items":[{"id":"d1","text":"El escenario debe publicar el dato con precisión y contexto."},{"id":"d2","text":"Según la Ficha A, el valor exacto es 12,468 kWh."},{"id":"d3","text":"Para una lectura rápida, puede escribirse aproximadamente 12,000 kWh."},{"id":"d4","text":"Finalmente, ambos valores deben conservar la unidad y el rótulo de caso simulado."}]},"id":"s08-l1-4-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Con las Fichas A y B ya suministradas, escribe la **introducción** y **un párrafo de desarrollo**. Incluye “según…”, una unidad y el rótulo de caso simulado. No agregues mediciones, recibos ni entrevistas.","type":"short-answer","props":{"minWords":45,"placeholder":"Título: …\\nIntroducción breve: …\\nDesarrollo (un párrafo): …","model":"Título: Datos para usar mejor la iluminación\\nIntroducción: Este informe analiza un caso escolar simulado; no describe nuestra escuela. La pregunta es qué recomendación permite sostener el paquete.\\nDesarrollo: Según la Ficha B, una lámpara usó 9 W y otra 60 W bajo condiciones comparables. Además, la guía recomienda apagar las luces de espacios vacíos. Estos datos no muestran cuánto ahorró una escuela real.","rubric":["Mi introducción dice qué investigué, mi pregunta y por qué es importante","Mi párrafo tiene una oración principal y oraciones de apoyo","Usé datos de mis notas con su fuente (\\"según…\\")","Usé al menos un conector (primero, además, luego, finalmente)"]},"id":"s08-l1-4-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Une cada parte del informe con lo que contiene.","type":"match","props":{"leftTitle":"Parte","rightTitle":"Contiene","pairs":[{"id":"p1","left":"Introducción","right":"El tema, la pregunta y por qué es importante"},{"id":"p2","left":"Desarrollo","right":"Un párrafo por cada pregunta clave, con datos"},{"id":"p3","left":"Conclusión","right":"La respuesta a la pregunta y lo aprendido"},{"id":"p4","left":"Fuentes","right":"La lista de libros, sitios y personas consultadas"}]},"id":"s08-l1-4-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"¿Qué es un **primer borrador**?","type":"choice","props":{"options":[{"id":"a","text":"Una primera versión del texto con las ideas en orden, que después se revisa y corrige"},{"id":"b","text":"La versión final, lista para entregar"},{"id":"c","text":"La lista de fuentes"}],"correct":["a"]},"id":"s08-l1-4-9"}],"kind":"materia","area":"l1","day":4}},{"missionId":"s08","version":"cnb-sexto-7f9bc1ec67df6f03","lesson":{"id":"s08-l2-1","title":"Sustantivo, adjetivo y verbo","icon":"Blocks","minutes":14,"gancho":"En \\"La abuela amable teje un güipil\\", cada palabra hace un trabajo distinto: una nombra, otra describe y otra dice la acción. ¿Cuál es cuál?","objetivos":["Clasificar sustantivos, adjetivos y verbos en observaciones y recomendaciones de un panel de energía"],"resumen":["Sustantivo: nombra personas, animales, lugares, cosas o ideas. Prueba: puedes ponerle \\"el, la, un, una\\" delante (la abuela, un güipil).","Adjetivo: dice cómo es el sustantivo. Prueba: responde \\"¿cómo es?\\" (amable, colorido). Concuerda con el sustantivo en género y número.","Verbo: dice la acción o el estado. Prueba: cambia con el tiempo (tejo, tejí, tejeré) y con la persona (yo tejo, ella teje).","Una misma palabra puede cambiar de clase según su oficio: \\"el canto\\" (sustantivo) / \\"yo canto\\" (verbo)."],"media":{"id":"s08-l2-1-oficios","kind":"animation","title":"Cada palabra tiene su oficio","aspect":"16:9","duration":45,"alt":"Una oración se arma con fichas de colores: los sustantivos en azul, los adjetivos en verde y los verbos en naranja.","brief":"Animación 2D de 45 s. Aparece la oración \\"La abuela amable teje un güipil colorido\\" en fichas separadas. Una lupa pasa por cada ficha: \\"abuela\\" y \\"güipil\\" se pintan de azul con el rótulo \\"SUSTANTIVO: nombra\\"; \\"amable\\" y \\"colorido\\" de verde con \\"ADJETIVO: dice cómo es\\"; \\"teje\\" de naranja con \\"VERBO: dice la acción\\". Luego \\"teje\\" cambia a \\"tejió\\" y \\"tejerá\\" para mostrar que el verbo cambia con el tiempo. Ilustración de una abuela tejiendo en telar de cintura, sin reproducir diseños sagrados específicos. Narración en español de Guatemala con subtítulos. Target: public/media/s08-l2-1-oficios.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Palabras con oficio en el panel","prompt":"Lee cómo clasificar palabras de una observación energética.","type":"explain","props":{"icon":"Tags","body":"En una observación de energía, el **sustantivo** nombra, el **adjetivo** describe y el **verbo** expresa acción o estado."},"id":"s08-l2-1-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","prompt":"Lee esta observación del panel: _\\"La lámpara eficiente **ilumina** el aula.\\"_ ¿Qué trabajo hace **ilumina**?","explain":"\\"Ilumina\\" expresa la acción de la lámpara: es un verbo. En las observaciones del panel, los sustantivos nombran, los adjetivos describen y los verbos expresan acciones o estados.","type":"choice","props":{"options":[{"id":"a","text":"Expresa una acción","icon":"Zap"},{"id":"b","text":"Nombra el objeto","icon":"Lightbulb","feedback":"El sustantivo que nombra el objeto es “lámpara”."},{"id":"c","text":"Describe el objeto","icon":"Palette","feedback":"El adjetivo que describe la lámpara es “eficiente”."}],"correct":["a"]},"id":"s08-l2-1-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Tres clases de palabras","prompt":"Para reconocer cada clase, usa su **prueba**. Toca cada tarjeta.","type":"explain","props":{"icon":"Blocks","body":"Fíjate en el **oficio** de la palabra en la oración: ¿nombra, describe o dice la acción?","reveal":[{"icon":"Tag","front":"Sustantivo","back":"**Nombra** personas, animales, lugares, cosas o ideas: abuela, perro, Cobán, mesa, alegría. **Prueba:** puedes decir \\"el, la, un, una\\" delante: la mesa, un perro."},{"icon":"Palette","front":"Adjetivo","back":"**Dice cómo es** el sustantivo: alto, amable, colorido, dulce. **Prueba:** responde \\"¿cómo es?\\". ¿Cómo es el güipil? Colorido."},{"icon":"Zap","front":"Verbo","back":"**Dice la acción** o el estado: corre, teje, duerme, está. **Prueba:** cambia con el tiempo (tejo, tejí, tejeré) y puedes decir \\"yo\\" o \\"ella\\" delante."},{"icon":"Languages","front":"Comparación responsable","back":"Los idiomas mayas tienen estructuras propias que deben revisarse con materiales validados y hablantes competentes. Esta actividad trabaja únicamente el corpus de la lección en español."}]},"id":"s08-l2-1-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Lucía analiza una oración aplicando las pruebas.","type":"worked-example","props":{"icon":"Search","problem":"Oración: _\\"El volcán alto humea en la mañana.\\"_ ¿Cuáles son los sustantivos, el adjetivo y el verbo?","steps":[{"text":"**volcán**: puedo decir \\"el volcán\\" y nombra un lugar → **sustantivo**."},{"text":"**alto**: ¿cómo es el volcán? Alto → **adjetivo**.","why":"Acompaña al sustantivo \\"volcán\\" y dice cómo es."},{"text":"**humea**: puedo cambiarla de tiempo (humeó, humeará) → **verbo**."},{"text":"**mañana**: puedo decir \\"la mañana\\" → **sustantivo**.","why":"\\"El\\" y \\"la\\" (artículos) y \\"en\\" (preposición) son palabras de enlace: hoy no las clasificamos."}],"answer":"Sustantivos: **volcán, mañana**. Adjetivo: **alto**. Verbo: **humea**.","tip":"Si dudas, prueba: ¿le puedo poner \\"el/la\\"? ¿responde \\"¿cómo es?\\"? ¿cambia con el tiempo?"},"id":"s08-l2-1-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: clasifica cada palabra según su clase.","hint":"Usa las pruebas: \\"el/la\\" delante → sustantivo; \\"¿cómo es?\\" → adjetivo; cambia con el tiempo → verbo.","explain":"Sustantivos: mercado, tomate, amistad. Adjetivos: maduro, generoso. Verbos: vender, cocinamos.","type":"sort","props":{"buckets":[{"id":"s","label":"Sustantivo","icon":"Tag","color":"var(--area-l2)"},{"id":"a","label":"Adjetivo","icon":"Palette","color":"var(--c-ok)"},{"id":"v","label":"Verbo","icon":"Zap","color":"var(--c-maiz-strong)"}],"items":[{"id":"w1","text":"mercado","bucket":"s"},{"id":"w2","text":"maduro","bucket":"a"},{"id":"w3","text":"vender","bucket":"v"},{"id":"w4","text":"tomate","bucket":"s"},{"id":"w5","text":"generoso","bucket":"a"},{"id":"w6","text":"cocinamos","bucket":"v"},{"id":"w7","text":"amistad","bucket":"s","feedback":"No se toca, pero puedes decir \\"la amistad\\": nombra una idea. Es sustantivo."}]},"id":"s08-l2-1-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"conocer","title":"Dos secretos de las clases de palabras","prompt":"Estas dos ideas te ayudarán a hablar y escribir mejor el español. Toca cada tarjeta.","type":"explain","props":{"icon":"Key","body":"El adjetivo es como la sombra del sustantivo: lo sigue en **género** y **número**.","reveal":[{"icon":"Link","front":"Concordancia","back":"El adjetivo cambia para ir con su sustantivo: **niño alto**, **niña alta**, **niños altos**, **niñas altas**. Error frecuente: \\"las casas bonito\\" → lo correcto es **\\"las casas bonitas\\"**."},{"icon":"RefreshCw","front":"La misma palabra, otro oficio","back":"\\"El **canto** del pájaro\\" → sustantivo (lleva \\"el\\"). \\"Yo **canto** en el coro\\" → verbo (dice la acción). Mira siempre el oficio en la oración."}]},"id":"s08-l2-1-6"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Toca todos los **verbos** de este texto.","hint":"Busca las palabras que dicen qué hace alguien. Son 5. Prueba cambiarlas de tiempo.","explain":"Llega, lleva, vende, compran y regresa dicen acciones. Si cambias el tiempo: llegó, llevó, vendió, compraron, regresó.","type":"highlight","props":{"target":"verbos","text":"El equipo {observa} el medidor del caso, {registra} la unidad, {compara} dos lecturas, {escribe} la fuente y {recomienda} apagar una lámpara innecesaria."},"id":"s08-l2-1-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Completa observaciones del panel con el **adjetivo** que concuerda.","explain":"Lámparas (femenino plural) → eficientes; medidor (masculino singular) → visible; lecturas (femenino plural) → comparables.","type":"fill-blank","props":{"text":"Las lámparas [[eficientes]] iluminan. El medidor [[visible]] registra datos. Las lecturas [[comparables]] usan la misma unidad.","distractors":["eficiente","visibles","comparable"]},"id":"s08-l2-1-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Toca todos los **adjetivos** de esta observación del panel de energía.","explain":"Encendida, vacío, exacta y visible describen lámpara, salón, lectura y fuente.","type":"highlight","props":{"target":"adjetivos","text":"Una lámpara {encendida} quedó en el salón {vacío}. La lectura {exacta} aparece junto a una fuente {visible}."},"id":"s08-l2-1-9"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Compara en el panel: _\\"El **registro** tiene fuente\\"_ y _\\"Yo **registro** la medición\\"_. ¿Qué clase de palabra es cada una?","explain":"\\"El registro\\" lleva artículo y nombra: sustantivo. \\"Registro la medición\\" expresa una acción: verbo.","type":"choice","props":{"options":[{"id":"a","text":"El primer “registro” es sustantivo y el segundo es verbo"},{"id":"b","text":"Las dos son verbos","feedback":"Mira la palabra que va antes del primer “registro”: “el”. Eso indica sustantivo."},{"id":"c","text":"El primero es adjetivo y el segundo es sustantivo","feedback":"El primer “registro” nombra y el segundo expresa la acción de registrar."}],"correct":["a"]},"id":"s08-l2-1-10"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.1"],"ambito":"hacer","prompt":"Escribe dos observaciones para un panel de energía. Usa al menos **dos adjetivos** y **dos verbos**; clasifícalos al final.","type":"short-answer","props":{"minWords":20,"placeholder":"La lámpara eficiente... Adjetivos: ... Verbos: ...","model":"La lámpara eficiente ilumina el salón. El medidor visible registra una lectura exacta. Adjetivos: eficiente, visible, exacta. Verbos: ilumina, registra.","rubric":["Escribí observaciones del panel de energía","Usé dos adjetivos concordantes","Usé dos verbos","Clasifiqué las palabras correctamente"]},"id":"s08-l2-1-11"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.1"],"prompt":"En la observación del panel _\\"La lectura exacta muestra el consumo\\"_, ¿cuál es el **adjetivo**?","type":"choice","props":{"options":[{"id":"a","text":"lectura"},{"id":"b","text":"exacta"},{"id":"c","text":"muestra"},{"id":"d","text":"consumo"}],"correct":["b"]},"id":"s08-l2-1-12"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.1"],"prompt":"Clasifica palabras de nuevas observaciones del panel de energía: ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En “las lámparas eficientes”, lámparas es sustantivo y eficientes es adjetivo.","answer":true},{"text":"En “el equipo compara lecturas”, compara es un adjetivo.","answer":false,"why":"“Compara” expresa la acción: es verbo."},{"text":"En “fuentes visibles”, el adjetivo concuerda en plural con el sustantivo.","answer":true}]},"id":"s08-l2-1-13"}],"kind":"materia","area":"l2","day":2}},{"missionId":"s08","version":"cnb-sexto-fa78ba3023a02517","lesson":{"id":"s08-l2-2","title":"Familias de sustantivos","icon":"Tag","minutes":15,"gancho":"\\"Pedro\\", \\"niño\\", \\"grupo\\" y \\"amistad\\" son sustantivos. Pero ¿verdad que no se parecen mucho? Cada uno pertenece a una familia distinta.","objetivos":["Clasificar sustantivos de fuentes, mediciones y recomendaciones en tres pares de familias"],"resumen":["Común: nombra cualquier ser de su clase (río, niña). Propio: nombra a uno en particular y se escribe con mayúscula (Motagua, Rosa).","Individual: nombra a uno solo (oveja). Colectivo: en singular nombra a un grupo (rebaño).","Concreto: se percibe con los sentidos (tortilla, lluvia). Abstracto: nombra ideas o sentimientos que no se tocan (paz, alegría).","Un mismo sustantivo pertenece a varias familias a la vez: \\"rebaño\\" es común, colectivo y concreto."],"media":{"id":"s08-l2-2-familias","kind":"diagram","title":"Tres parejas de familias","aspect":"16:9","alt":"Tres columnas: común y propio (río / Motagua), individual y colectivo (oveja / rebaño), concreto y abstracto (tortilla / alegría), cada una con un dibujo.","brief":"Infografía horizontal en tres columnas de colores suaves. Columna 1 \\"¿A cualquiera o a uno en particular?\\": dibujo de un río genérico con la palabra \\"río\\" (común) y el mismo río con un cartel \\"Motagua\\" en mayúscula destacada (propio). Columna 2 \\"¿Uno o un grupo?\\": una oveja sola \\"oveja\\" (individual) y un grupo de ovejas con un pastor \\"rebaño\\" (colectivo). Columna 3 \\"¿Se percibe con los sentidos?\\": una tortilla humeante con íconos de ojo, mano y nariz \\"tortilla\\" (concreto) y dos niños abrazándose con un corazón \\"alegría\\" (abstracto). Letras grandes y legibles, fondo claro. Target: public/media/s08-l2-2-familias.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","title":"Familias de sustantivos del informe","prompt":"Lee cómo clasificar los sustantivos del corpus energético.","type":"explain","props":{"icon":"Tags","body":"Los sustantivos de fuentes, mediciones y recomendaciones pueden ser común o propio, individual o colectivo, concreto o abstracto."},"id":"s08-l2-2-1"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","prompt":"Tu amigo escribió: _\\"ayer visité el lago de atitlán con mi prima rosa.\\"_ ¿Qué palabras deberían llevar **mayúscula**?","explain":"\\"Atitlán\\" y \\"Rosa\\" nombran a un lago y a una persona **en particular**: son sustantivos **propios** y se escriben con mayúscula. \\"Ayer\\" también, por ir al inicio de la oración. Hoy conocerás las familias de los sustantivos.","type":"choice","props":{"options":[{"id":"a","text":"Ayer, Atitlán y Rosa","icon":"CaseSensitive"},{"id":"b","text":"Lago y prima","icon":"Type","feedback":"\\"Lago\\" y \\"prima\\" pueden nombrar a cualquier lago o prima: no llevan mayúscula."},{"id":"c","text":"Ninguna","icon":"X","feedback":"Los nombres de personas y lugares en particular siempre llevan mayúscula."}],"correct":["a"]},"id":"s08-l2-2-2"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"conocer","title":"Las familias de los sustantivos","prompt":"Los sustantivos se agrupan en **parejas de familias**. Mira el diagrama de la lección y toca cada tarjeta.","type":"explain","props":{"icon":"Tag","body":"Para cada pareja hay una pregunta que te ayuda a decidir.","reveal":[{"icon":"Users","front":"Común o propio","back":"**¿Nombra a cualquiera o a uno en particular?** Común: río, ciudad, niña. Propio (con **mayúscula**): Motagua, Antigua Guatemala, Rosa."},{"icon":"Layers","front":"Individual o colectivo","back":"**¿Nombra a uno o a un grupo?** Individual: oveja, abeja, árbol. Colectivo (grupo, aunque esté en singular): **rebaño**, **enjambre**, **bosque**."},{"icon":"Hand","front":"Concreto o abstracto","back":"**¿Lo puedo ver, tocar, oír, oler o saborear?** Concreto: tortilla, lluvia, marimba. Abstracto (ideas y sentimientos): **paz, alegría, amistad, honestidad**."},{"icon":"Languages","front":"Corpus validado","back":"Para comparar posesión en un idioma maya se necesita una fuente lingüística validada. Aquí no se piden traducciones familiares ni se inventan equivalencias."}]},"id":"s08-l2-2-3"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Mira cómo Andrés clasifica un sustantivo en sus tres parejas.","type":"worked-example","props":{"icon":"ListChecks","problem":"Clasifica el sustantivo **enjambre** en las tres parejas de familias.","steps":[{"text":"¿Cualquiera o uno en particular? Puede ser cualquier enjambre y va con minúscula → **común**."},{"text":"¿Uno o un grupo? En singular nombra a **muchas abejas** juntas → **colectivo**.","why":"Su individual es \\"abeja\\"."},{"text":"¿Se percibe con los sentidos? Sí: se ve y se oye su zumbido → **concreto**."}],"answer":"**Enjambre** es un sustantivo común, colectivo y concreto.","tip":"Hazte las tres preguntas en orden: particular, grupo, sentidos."},"id":"s08-l2-2-4"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Une cada sustantivo individual con su colectivo léxico.","hint":"El colectivo es una palabra singular que nombra un grupo.","explain":"Árbol–bosque, abeja–enjambre y oveja–rebaño son pares individual–colectivo.","type":"match","props":{"leftTitle":"Individual","rightTitle":"Colectivo","pairs":[{"id":"c1","left":"árbol","right":"bosque"},{"id":"c2","left":"abeja","right":"enjambre"},{"id":"c3","left":"oveja","right":"rebaño"}]},"id":"s08-l2-2-5"},{"fase":"construir","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"¿**Concreto** o **abstracto**? Clasifica sustantivos de fuentes, mediciones y recomendaciones.","hint":"Pregúntate: ¿lo puedo ver, tocar, oír, oler o saborear?","explain":"Medidor, lámpara y ficha se perciben; ahorro, confianza y recomendación nombran ideas.","type":"sort","props":{"buckets":[{"id":"c","label":"Concreto","icon":"Hand","color":"var(--area-l2)"},{"id":"a","label":"Abstracto","icon":"Brain","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"medidor","bucket":"c"},{"id":"x2","text":"ahorro","bucket":"a"},{"id":"x3","text":"lámpara","bucket":"c"},{"id":"x4","text":"confianza","bucket":"a"},{"id":"x5","text":"ficha","bucket":"c"},{"id":"x6","text":"recomendación","bucket":"a"}]},"id":"s08-l2-2-6"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"En esta nota del panel, toca los sustantivos **propios** que identifican escenario y fuente.","explain":"Escuela Luz y Ficha B identifican un caso y una fuente particulares; lámpara, medición y recomendación son comunes.","type":"highlight","props":{"target":"sustantivos propios","text":"En el caso simulado {Escuela Luz}, la {Ficha B} informa una medición de lámpara y una recomendación."},"id":"s08-l2-2-7"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Clasifica sustantivos de una fuente, una medición y una recomendación según el tipo que mejor los distingue.","explain":"Ficha A es propio; equipo es colectivo; ahorro es abstracto; medidor es concreto.","type":"match","props":{"leftTitle":"Sustantivo","rightTitle":"Tipo","pairs":[{"id":"s1","left":"Ficha A","leftIcon":"FileText","right":"Propio"},{"id":"s2","left":"equipo","leftIcon":"Users","right":"Colectivo"},{"id":"s3","left":"ahorro","leftIcon":"Heart","right":"Abstracto"},{"id":"s4","left":"medidor","leftIcon":"Gauge","right":"Concreto"}]},"id":"s08-l2-2-8"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","title":"Corpus del panel de energía","prompt":"Lee la fuente de la lección y clasifica sus sustantivos.","type":"reading","props":{"genre":"Ficha informativa simulada","heading":"Fuente, medición y recomendación","passage":"Caso escolar simulado; no describe tu escuela. La Ficha C registra una medición de 18 lámparas. El equipo observa el alumbrado y propone una recomendación: apagar lámparas innecesarias. La confianza depende de mostrar la fuente y la unidad.","questions":[{"q":"¿Qué sustantivo **colectivo** nombra al grupo que observa?","options":[{"id":"a","text":"equipo"},{"id":"b","text":"fuente"},{"id":"c","text":"lámpara"}],"correct":"a","why":"Equipo, en singular, nombra a varias personas."},{"q":"¿Qué sustantivo de la ficha es **abstracto**?","options":[{"id":"a","text":"confianza"},{"id":"b","text":"lámparas"},{"id":"c","text":"Ficha C"}],"correct":"a","why":"La confianza es un sentimiento: no se puede ver ni tocar."},{"q":"¿Cuál es el sustantivo propio que identifica la fuente?","options":[{"id":"a","text":"Ficha C"},{"id":"b","text":"medición"},{"id":"c","text":"recomendación"}],"correct":"a","why":"Ficha C nombra una fuente particular."}]},"id":"s08-l2-2-9"},{"fase":"aplicar","areas":["l2"],"cnb":["l2:5.1.2"],"ambito":"hacer","prompt":"Completa las oraciones del panel con el sustantivo correcto para la fuente, la medición y la recomendación.","explain":"La ficha identifica la fuente, el conjunto reúne datos y el ahorro nombra la idea buscada por la recomendación.","type":"fill-blank","props":{"text":"La [[ficha]] identifica la fuente. El [[conjunto]] reúne mediciones. El [[ahorro]] orienta la recomendación.","distractors":["lámpara","dato","medidor"]},"id":"s08-l2-2-10"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.2"],"prompt":"En una nueva recomendación del panel, ¿qué sustantivo es **abstracto**?","type":"choice","props":{"options":[{"id":"a","text":"lámpara"},{"id":"b","text":"eficiencia"},{"id":"c","text":"Ficha D"},{"id":"d","text":"medidor"}],"correct":["b"]},"id":"s08-l2-2-11"},{"fase":"comprobar","areas":["l2"],"cnb":["l2:5.1.2"],"prompt":"Clasifica fuentes, mediciones y recomendaciones de otro panel: ¿verdadero o falso?","type":"true-false","props":{"statements":[{"text":"“Ficha D” es propio porque identifica una fuente particular.","answer":true},{"text":"“Bosque” es colectivo porque en singular nombra un grupo de árboles.","answer":true},{"text":"“Recomendación” es concreto porque se puede tocar.","answer":false,"why":"Recomendación nombra una idea; es un sustantivo abstracto."}]},"id":"s08-l2-2-12"},{"fase":"reflexionar","areas":["l2"],"cnb":[],"ambito":"ser","prompt":"Terminamos la unidad. ¿Cómo te fue?","type":"reflection","props":{"statements":["Distingo sustantivos, adjetivos y verbos","Hago que el adjetivo concuerde con el sustantivo","Reconozco sustantivos comunes, propios, colectivos y abstractos","Uso en mi español lo que aprendí en la unidad: escuchar, respetar, leer señales, recitar y hablar con claridad"],"commitments":["Revisaré las mayúsculas de los nombres propios cuando escriba","Buscaré sustantivos colectivos en lo que leo","Le enseñaré a alguien de mi familia las tres pruebas de las clases de palabras"]},"id":"s08-l2-2-13"}],"kind":"materia","area":"l2","day":4}},{"missionId":"s08","version":"cnb-sexto-7abea51ffa787d73","lesson":{"id":"s08-ef-1","title":"Juegos tradicionales: jugar como jugaban nuestros abuelos","icon":"Sparkles","minutes":15,"gancho":"Antes de los celulares, tus abuelos jugaban con un trompo, un capirucho, unos cincos o una cuerda. ¿Crees que esos juegos todavía pueden hacerte sudar y reír?","objetivos":["Conocer juegos tradicionales de Guatemala y sus reglas"],"resumen":["Los juegos tradicionales se transmiten de generación en generación, de abuelos a nietos. Usan materiales sencillos y muchas veces reutilizados.","Ejemplos en Guatemala: trompo, capirucho, cincos (canicas), tenta, salta cuerda, ronda con palmas y barrilete. Cada comunidad puede tener sus propios nombres y reglas.","Desarrollan habilidades: el capirucho y los cincos, la coordinación ojo-mano y la precisión; la tenta, la velocidad y los cambios de dirección; la cuerda, el ritmo y la resistencia; ronda con palmas, la fuerza y la cooperación.","Valorarlos es jugarlos, aprenderlos de las personas mayores, enseñarlos a los más pequeños y respetar sus reglas, que se acuerdan antes de jugar."],"media":{"id":"s08-ef-1-juegos","kind":"video","title":"Juegos de ayer y de hoy","aspect":"16:9","duration":60,"alt":"Un abuelo enseña a una niña a lanzar un trompo; niños juegan cincos en un círculo dibujado en la tierra; un grupo salta cuerda cantando; otro juega ronda con palmas sentados en fila.","brief":"Video de 60 s en un patio escolar despejado, con intérpretes autorizados. Escenas de 10 s con rótulo: (1) trompo con pita; (2) capirucho; (3) cincos en un círculo; (4) tenta con bases amplias; (5) cuerda individual e imaginaria; (6) ronda con palmas, con participantes de pie y sentados, separados por un brazo. Cierre con barriletes de papel exhibidos sin elevarlos cerca de cables. Música de marimba suave. Target: public/media/s08-ef-1-juegos.mp4. Accesibilidad: subtítulos completos, transcripción, demostración a velocidad lenta y descripción de cada adaptación."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Reglas de juegos tradicionales","prompt":"Lee qué se practica en estos juegos.","type":"explain","props":{"icon":"History","body":"Trompo, capirucho, cincos, tenta, cuerda y ronda con palmas conservan reglas culturales y practican habilidades motrices."},"id":"s08-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"¿Qué tienen en común el trompo, el capirucho y los cincos?","explain":"Son **juegos tradicionales**: se han jugado por generaciones, se aprenden de las personas mayores y usan materiales sencillos. Además, ¡todos entrenan tu precisión y coordinación!","type":"choice","props":{"options":[{"id":"a","text":"Son juegos tradicionales que se aprenden de generación en generación","icon":"History"},{"id":"b","text":"Son juegos electrónicos","icon":"Smartphone","feedback":"No necesitan electricidad: solo madera, pita, vidrio o barro."},{"id":"c","text":"Son deportes olímpicos","icon":"Medal","feedback":"No son deportes olímpicos: son juegos de la tradición popular."}],"correct":["a"]},"id":"s08-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Juegos tradicionales de Guatemala","prompt":"Mira el video y la lámina, y toca cada juego. Compara sus reglas con las tarjetas de la lección.","media":{"id":"s08-ef-1-objetos","kind":"image","title":"Los objetos de los juegos tradicionales","aspect":"4:3","alt":"Sobre un petate: un trompo de madera con su pita, un capirucho (palito y carrete unidos con pita), un puñado de cincos de vidrio, una cuerda larga y un barrilete pequeño de papel de china.","brief":"Fotografía cenital o ilustración realista sobre un petate: trompo de madera pintado con su pita enrollada, capirucho de madera (palito y carrete unidos con pita), cinco o seis cincos (canicas) de vidrio de colores, una cuerda de saltar larga enrollada y un barrilete pequeño de papel de china con cola de trapo. Cada objeto con su nombre en letra grande. Sin marcas comerciales. Target: public/media/s08-ef-1-objetos.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"History","body":"Cada comunidad tiene sus juegos. Estos son algunos de los más conocidos en Guatemala.","reveal":[{"icon":"RotateCw","front":"Trompo","back":"Se enrolla una pita en el trompo y se lanza para que **baile** en el suelo. Retos: que dure mucho, levantarlo bailando en la mano o sacar otros trompos de un círculo."},{"icon":"Target","front":"Capirucho","back":"Un carrete de madera unido con una pita a un palito. Se balancea el carrete para **embocarlo** en el palito. Entrena la **coordinación ojo-mano**."},{"icon":"CircleDot","front":"Cincos","back":"Canicas. Desde una línea, se impulsan con el pulgar para **sacar** los cincos de otros jugadores de un círculo dibujado en la tierra. Pide **precisión**."},{"icon":"Footprints","front":"Tenta","back":"Una persona \\"la lleva\\" y persigue a las demás; a quien toca, le pasa la tenta. Hay \\"bases\\" donde no te pueden tocar. Entrena **velocidad** y **cambios de dirección**."},{"icon":"Repeat","front":"Salta cuerda","back":"Dos personas dan vuelta a una cuerda larga y las demás entran a saltar, muchas veces **cantando** y contando. Entrena **ritmo** y **resistencia**."},{"icon":"Wind","front":"Barrilete","back":"Se construye con papel de china, varas y pita, y se vuela corriendo contra el viento. En noviembre, en Sumpango y Santiago Sacatepéquez se elevan **barriletes gigantes**."}]},"id":"s08-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","title":"¿Por qué valorarlos?","prompt":"Los juegos tradicionales son mucho más que pasar el rato. Toca cada tarjeta.","type":"explain","props":{"icon":"Heart","body":"Valorar un juego tradicional es **jugarlo, aprenderlo y enseñarlo**, para que no se pierda.","reveal":[{"icon":"Users","front":"Unen generaciones","back":"Abuelos, padres, madres y nietos pueden jugar juntos y compartir historias."},{"icon":"Landmark","front":"Son cultura","back":"Guardan canciones, palabras y formas de convivir de nuestros pueblos. Son parte de nuestra **identidad**."},{"icon":"Recycle","front":"Materiales sencillos","back":"Se hacen con madera, pita, papel, costales o piedritas: no hace falta dinero y se puede reutilizar."},{"icon":"Activity","front":"Mueven el cuerpo","back":"Correr, saltar, lanzar, equilibrarse: usan las mismas habilidades que aprendiste en esta unidad."}]},"id":"s08-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: jugar ronda con palmas de forma segura","prompt":"Mira cómo el grupo de Juan organiza el juego de **ronda con palmas** que le enseñó su abuela.","type":"worked-example","props":{"icon":"Music","problem":"Son 8 niñas y niños en un patio despejado. ¿Cómo hacen una ronda con palmas segura y adaptable?","steps":[{"text":"**Despejan el espacio:** retiran mochilas y dejan un brazo de distancia entre participantes."},{"text":"**Acuerdan una secuencia:** dos palmas propias, dos palmas al aire y un paso lateral."},{"text":"**Ensayan despacio:** nadie toma, empuja ni jala a otra persona.","why":"Cada participante controla su propio movimiento."},{"text":"**Cambian el liderazgo:** una persona marca cuatro pulsos y luego cede el turno."},{"text":"**Adaptan:** la secuencia puede hacerse de pie o sentada, con pasos, gestos o palmas suaves; cualquiera puede decir “alto”."}],"answer":"La ronda practica **ritmo, atención y cooperación** sin contacto riesgoso.","tip":"El ritmo se adapta a cada participante; la velocidad nunca vale más que el control."},"id":"s08-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"Une cada juego tradicional con la habilidad que más desarrolla.","hint":"Piensa en lo que el cuerpo tiene que hacer en cada juego.","explain":"Todos los juegos mueven el cuerpo, pero cada uno destaca una habilidad.","type":"match","props":{"leftTitle":"Juego","rightTitle":"Habilidad","pairs":[{"id":"c","left":"Capirucho","right":"Coordinación ojo-mano"},{"id":"t","left":"Tenta","right":"Velocidad y cambios de dirección"},{"id":"s","left":"Salta cuerda","right":"Ritmo y resistencia"},{"id":"a","left":"Ronda con palmas","right":"Ritmo y cooperación"}]},"id":"s08-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","prompt":"¡Feria de juegos tradicionales! **Calentamiento:** trote suave y rotaciones. **Estación 1 – Tenta (2 min):** con bases acordadas. **Estación 2 – Salta cuerda:** entra y salta 10 veces contando o cantando; si estás solo, cuerda individual. **Estación 3 – Precisión:** capirucho, trompo o cincos (si no tienes, lanza tapitas a un círculo dibujado en el suelo). **Poco espacio:** cuerda individual o imaginaria y tapitas a un círculo. **Adaptación:** en la tenta, quien use silla de ruedas puede \\"tentar\\" tocando con una pelota suave; en la cuerda, se puede pasar la cuerda por debajo de las ruedas o dar vuelta a la cuerda. **Vuelta a la calma:** estira y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la tenta","exercise":{"name":"Tenta con bases","icon":"Footprints","seconds":90}},{"label":"Después de salta cuerda y precisión","exercise":{"name":"Salta cuerda y juego de precisión","icon":"Repeat","seconds":90}}]},"id":"s08-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Tu abuelo te enseña a lanzar el trompo, pero tu primo dice: \\"Eso es de antes, es aburrido\\". ¿Qué respuesta muestra **valoración** de los juegos tradicionales?","explain":"Valorar es reconocer lo que el juego aporta (habilidad, cultura, convivencia) e invitar a otros a probarlo, con respeto por los gustos de cada quien.","type":"choice","props":{"options":[{"id":"a","text":"\\"Pruébalo: lanzar el trompo pide mucha precisión y así aprendemos lo que jugaba el abuelo\\""},{"id":"b","text":"\\"Tienes razón, los juegos viejos no sirven\\"","feedback":"Los juegos tradicionales siguen desarrollando habilidades y son parte de la cultura."},{"id":"c","text":"\\"Si no te gusta, eres un aburrido\\"","feedback":"Se puede invitar sin burlarse de los gustos de la otra persona."}],"correct":["a"]},"id":"s08-ef-1-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Lee la ficha de la lección de **Doña Blanca** sobre el juego tradicional de ronda con palmas y escribe una adaptación segura para poco espacio: regla, movimiento, señal de pausa y habilidad que conserva.","type":"short-answer","props":{"minWords":24,"placeholder":"Regla adaptada... Movimiento... Señal de pausa... Conserva la habilidad de...","model":"El grupo marca el círculo sin jalarse. Camina cuatro pasos con palmas y se detiene al oír “pausa”. Quien está afuera señala un espacio sin empujar. Conserva ritmo, orientación y cooperación.","rubric":["No incluye jalones ni empujones","Define señal de pausa","Explica la habilidad practicada"]},"id":"s08-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Cuál es un juego tradicional de Guatemala que desarrolla la **coordinación ojo-mano**?","type":"choice","props":{"options":[{"id":"a","text":"El capirucho"},{"id":"b","text":"Un videojuego de carreras"},{"id":"c","text":"Ver televisión"}],"correct":["a"]},"id":"s08-ef-1-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Los juegos tradicionales se transmiten de generación en generación.","answer":true},{"text":"En la ronda con palmas conviene empujar o jalar para seguir el ritmo.","answer":false,"why":"Cada persona controla sus movimientos y mantiene distancia; no se empuja ni se jala."},{"text":"Un mismo juego puede tener distintos nombres o reglas según la comunidad.","answer":true}]},"id":"s08-ef-1-11"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s08","version":"cnb-sexto-2209e5acb05b4d7c","lesson":{"id":"s08-ef-2","title":"Liderar con igualdad: todas y todos jugamos","icon":"Flag","minutes":15,"gancho":"En el recreo alguien dice: \\"Las niñas no juegan fútbol\\" o \\"Los niños no saltan cuerda\\". ¿Es justo? ¿Qué harías si tú fueras quien organiza el juego?","objetivos":["Dirigir una rutina breve con secuencia segura, igualdad de oportunidades y roles complementarios para mujeres y hombres"],"resumen":["Un buen líder explica las reglas con claridad, escucha, organiza turnos y equipos justos, anima a todos y da el ejemplo con juego limpio. Liderar es servir al grupo, no mandar a gritos.","Niñas y niños tienen los mismos derechos y oportunidades para jugar cualquier juego o deporte y para ser capitanas, capitanes, árbitras o árbitros.","La Declaración Universal de Derechos Humanos dice que todos los seres humanos nacen libres e iguales en dignidad y derechos. La Constitución de Guatemala (artículo 4) establece que el hombre y la mujer tienen iguales oportunidades y responsabilidades.","Complementariedad: cada persona aporta habilidades distintas; un equipo diverso es más fuerte. Equipos justos: contar 1-2, mezclar habilidades y rotar el liderazgo."],"media":{"id":"s08-ef-2-liderazgo","kind":"image","title":"Capitanas y capitanes","aspect":"16:9","alt":"En un patio escolar, una niña capitana explica las reglas a un equipo mixto en círculo; al lado, un niño arbitra un juego de salta cuerda donde saltan niñas y niños juntos.","brief":"Ilustración luminosa de un patio de escuela pública guatemalteca. Escena izquierda: una niña (brazalete de capitana) explica las reglas a un equipo mixto en círculo, todos atentos. Escena derecha: un niño con silbato arbitra salta cuerda; saltan niñas y niños juntos. Al fondo, un cartel \\"Todas y todos jugamos\\". Diversidad de pueblos (maya, garífuna, xinka, mestizo) y una niña en silla de ruedas participando. Sin estereotipos de colores por género. Target: public/media/s08-ef-2-liderazgo.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y liderazgo","prompt":"Lee cómo se organiza una actividad física justa.","type":"explain","props":{"icon":"Users","body":"Niñas y niños, mujeres y hombres tienen iguales oportunidades para jugar y liderar. Rechazar estereotipos, abrir los mismos roles y combinar aportes complementarios protege sus derechos."},"id":"s08-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","prompt":"¿Pueden las niñas jugar fútbol y ser capitanas? ¿Pueden los niños saltar cuerda?","explain":"**Sí, todas y todos.** Mujeres y hombres, niñas y niños tienen los mismos derechos e igualdad de oportunidades para jugar y liderar; los roles no dependen de estereotipos.","type":"choice","props":{"options":[{"id":"a","text":"Sí: cualquier persona puede jugar y liderar cualquier juego","icon":"Users"},{"id":"b","text":"No: cada juego es solo para niñas o solo para niños","icon":"X","feedback":"Esa idea es un estereotipo: limita a las personas y no tiene base."}],"correct":["a"]},"id":"s08-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","title":"¿Qué hace un buen líder en el juego?","prompt":"Liderar no es mandar: es **ayudar al grupo** a jugar mejor. Toca cada tarjeta.","type":"explain","props":{"icon":"Flag","body":"Cualquier persona puede aprender a liderar. Se practica **rotando** el papel de capitán, árbitro u organizador.","reveal":[{"icon":"MessageCircle","front":"Explica con claridad","back":"Cuenta las reglas en pocas palabras, muestra un ejemplo y pregunta: \\"¿Quedó claro?\\"."},{"icon":"Ear","front":"Escucha","back":"Toma en cuenta las ideas del grupo y a quienes hablan menos."},{"icon":"Scale","front":"Organiza con justicia","back":"Forma **equipos parejos**, da **turnos** a todos y cuida que nadie quede fuera."},{"icon":"ThumbsUp","front":"Anima y da el ejemplo","back":"Felicita el esfuerzo, anima a quien se equivoca y juega limpio. El grupo imita lo que ve."}]},"id":"s08-ef-2-3"},{"fase":"construir","areas":["ef","fc"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y derechos en el juego","prompt":"La igualdad en el juego no es solo \\"buena onda\\": es un **derecho**. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Cuando alguien queda fuera de un juego por ser niña, niño, de otro pueblo o por tener una discapacidad, se vulnera su derecho a jugar y a participar.","reveal":[{"icon":"Globe","front":"Derechos humanos","back":"La **Declaración Universal de Derechos Humanos** (artículo 1) dice: todos los seres humanos **nacen libres e iguales en dignidad y derechos**."},{"icon":"Landmark","front":"Constitución de Guatemala","back":"El **artículo 4** dice que en Guatemala todos los seres humanos son libres e iguales en dignidad y derechos, y que **el hombre y la mujer tienen iguales oportunidades y responsabilidades**."},{"icon":"Puzzle","front":"Complementariedad","back":"Cada persona aporta algo distinto: velocidad, puntería, estrategia, ánimo. Un equipo **diverso** se complementa y es más fuerte."},{"icon":"Users","front":"Igualdad de oportunidades","back":"Todas y todos pueden jugar, ser capitanes, arbitrar, elegir juego y recibir el balón. Si alguien necesita una adaptación, se hace."}]},"id":"s08-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","title":"Ejemplo resuelto: formar equipos justos","prompt":"Siempre que eligen equipos, las mismas personas quedan de últimas. Mira cómo lo resuelve Andrea, la capitana de turno.","type":"worked-example","props":{"icon":"Users","problem":"Hay 16 estudiantes (8 niñas y 8 niños) y van a jugar balonmano. Antes, los \\"mejores\\" escogían y siempre quedaban de últimas las mismas niñas y un niño que corre más lento.","steps":[{"text":"Andrea propone **contar 1-2** en la fila: los \\"1\\" forman un equipo y los \\"2\\" el otro.","why":"Nadie \\"escoge\\" a nadie: se evita que alguien se sienta rechazado."},{"text":"Revisa que cada equipo quede **mixto** y con habilidades mezcladas; si no, cambia a dos personas."},{"text":"Acuerda una regla nueva: **antes de lanzar a gol, el balón debe pasar por al menos 3 personas** del equipo.","why":"Así todas y todos tocan el balón, no solo los más rápidos."},{"text":"Nombra **capitanes rotativos**: cada 5 minutos, otra persona es capitana o capitán."}],"answer":"Con **conteo 1-2**, **equipos mixtos**, la regla de **3 pases** y **capitanes rotativos**, el juego es justo y todos participan.","tip":"Un buen líder pregunta al final: \\"¿Todos jugaron? ¿Qué podemos mejorar la próxima vez?\\"."},"id":"s08-ef-2-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","prompt":"Clasifica cada acción de un capitán o capitana: ¿es **buen liderazgo** o **no**?","hint":"Un buen líder incluye, escucha, organiza con justicia y da el ejemplo.","explain":"Liderar bien abre los mismos roles a mujeres y hombres: niñas y niños aportan habilidades complementarias; excluir por estereotipos no es liderazgo.","type":"sort","props":{"buckets":[{"id":"si","label":"Buen liderazgo","icon":"Flag","color":"var(--c-ok)"},{"id":"no","label":"No es buen liderazgo","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Explicar las reglas y preguntar si quedaron claras","bucket":"si"},{"id":"x2","text":"Decidir solo, a gritos, sin escuchar a nadie","bucket":"no"},{"id":"x3","text":"Formar equipos mixtos contando 1-2","bucket":"si"},{"id":"x4","text":"Dejar fuera a las niñas \\"porque no saben\\"","bucket":"no"},{"id":"x5","text":"Animar a quien se equivocó","bucket":"si"},{"id":"x6","text":"Pasar el balón siempre a sus mejores amigos","bucket":"no"}]},"id":"s08-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","prompt":"Dirige una rutina breve sin equipo: explica “cuatro palmas suaves, cuatro gestos al frente y pausa”, comprueba el espacio y ofrece hacerla de pie o sentado. **Ruta grupal opcional:** una persona dirige y otra confirma la señal de alto. **Ruta individual completa:** di o lee las instrucciones, modela la secuencia y usa tú mismo la señal de pausa. No afirmes que hubo rotación si trabajaste a solas.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"Antes de dirigir"},{"label":"Después de explicar y modelar","exercise":{"name":"Palmas y gestos dirigidos","icon":"Flag","seconds":45}},{"label":"Después de adaptar y cerrar","exercise":{"name":"Secuencia adaptable con pausa","icon":"Users","seconds":45}}]},"id":"s08-ef-2-7"},{"fase":"aplicar","areas":["ef","fc"],"cnb":["ef:4.1.12","ef:4.2.3"],"ambito":"convivir","prompt":"¿Qué harías si fueras quien organiza?","type":"dilemma","props":{"scene":{"icon":"Flag","text":"En el recreo organizan una **chamusca**. Un niño dice: \\"Las niñas no pueden jugar y tampoco pueden ser capitanas\\". **Lucía** y **Marta** querían jugar con los niños. Tú eres quien organiza hoy."},"options":[{"id":"a","icon":"EyeOff","text":"Quedarme callado para no tener problemas","consequence":"Lucía y Marta se quedan fuera. El grupo aprende que excluir \\"no pasa nada\\", y la injusticia se repite.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"Users","text":"Decir que todas y todos pueden jugar, formar equipos mixtos contando 1-2 y proponer que Lucía sea capitana de un equipo","consequence":"Se juega con equipos parejos. Lucía organiza bien a su equipo y varios compañeros se dan cuenta de que su idea era un estereotipo.","values":["Igualdad","Liderazgo","Derechos humanos"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Hablar con calma con el compañero: explicarle que la igualdad es un derecho e invitarlo a jugar en un equipo mixto","consequence":"El compañero no cambia de idea de inmediato, pero acepta jugar. Al final reconoce que el partido fue más parejo y divertido.","values":["Diálogo","Respeto","Igualdad"],"constructive":true}]},"id":"s08-ef-2-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"conocer","prompt":"Aplica el liderazgo y rechaza el estereotipo: ordena una rutina donde mujeres y hombres, niñas y niños tengan igualdad de oportunidades para asumir roles y aportar habilidades complementarias.","explain":"Un liderazgo justo abre todos los roles, explica la secuencia, ofrece adaptación segura y combina aportes complementarios.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"a","text":"Abrir por igual a una niña o un niño el rol de dirigir"},{"id":"b","text":"Explicar dos pasos laterales y ofrecer gestos sentados"},{"id":"c","text":"Combinar a quien modela con quien cuida la señal de alto"},{"id":"d","text":"Dirigir dos repeticiones y cambiar los roles"}]},"id":"s08-ef-2-9"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"hacer","prompt":"Guarda evidencia de cómo dirigiste la rutina: escribe la instrucción, la adaptación segura, tu rol y el orden usado. Indica si elegiste ruta individual o grupal.","explain":"La evidencia describe liderazgo realmente practicado en la lección, sin afirmar una rotación no observada.","type":"short-answer","props":{"minWords":22,"placeholder":"Ruta… Mi instrucción… Adaptación… Secuencia…","model":"Elegí la ruta individual. Expliqué cuatro palmas y cuatro gestos. Ofrecí hacerlos sentado, modelé la secuencia y terminé con la señal de pausa.","rubric":["Indico la ruta","Escribo una instrucción","Incluyo adaptación segura","Describo rol y secuencia"]},"id":"s08-ef-2-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y roles claros. Un niño afirma que solo los hombres deben dirigir. Para rechazar ese estereotipo y defender los derechos humanos, ¿qué instrucción da igualdad de oportunidades a mujeres y hombres y usa aportes complementarios?","type":"choice","props":{"options":[{"id":"a","text":"“Una niña y un niño alternan el rol de líder; una persona modela y otra cuida la señal. Cada aporte complementa al otro y se puede hacer sentado”"},{"id":"b","text":"“Los hombres lideran y las mujeres observan”"},{"id":"c","text":"“Todas hacen lo mismo, sin roles ni adaptación”"}],"correct":["a"]},"id":"s08-ef-2-11"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y una secuencia de roles. Ordénala para rechazar el estereotipo, proteger derechos humanos y dar igualdad de oportunidades a mujeres y hombres con participación complementaria.","type":"order","props":{"labels":{"start":"Inicio","end":"Cierre"},"items":[{"id":"e1","text":"Explicar que niñas y niños pueden asumir por igual cualquier rol"},{"id":"e2","text":"Asignar a una mujer el modelado y a un hombre la señal, con cambio posterior de roles"},{"id":"e3","text":"Ofrecer movimiento de pie o sentado para complementar capacidades"},{"id":"e4","text":"Dirigir dos repeticiones y cerrar con una señal segura"}]},"id":"s08-ef-2-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:4.2.3"],"type":"reflection","props":{"statements":["Juego y valoro juegos tradicionales de mi comunidad","Lidero un juego explicando reglas y formando equipos justos","Defiendo que todas y todos tengan las mismas oportunidades de jugar"],"commitments":["Enseñaré un juego tradicional a alguien más pequeño","Me ofreceré a ser líder o árbitro en el recreo","Invitaré a jugar a quien se queda fuera"]},"id":"s08-ef-2-13"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s08","version":"cnb-sexto-3e590821c91b1f9c","lesson":{"id":"s08-ccss-1","title":"Los grandes problemas del mundo, en datos","icon":"BarChart3","minutes":15,"gancho":"Todos los días escuchas noticias sobre sequías, migración, precios altos o contaminación. ¿Son problemas solo de Guatemala o de todo el planeta? ¿Cómo sabemos qué tan grandes son?","objetivos":["Usar aportes de las Ciencias Sociales, fuentes y datos fechados para comprender un problema mundial sin exagerar conclusiones"],"resumen":["Problemas mundiales actuales: pobreza y hambre, desigualdad, cambio climático, falta de agua potable, pérdida de bosques y biodiversidad, contaminación, migración forzada, conflictos armados, enfermedades y falta de acceso a la educación.","Los organismos publican informes con fuente, fecha, método y unidad. En esta lección, cualquier cifra sin referencia completa se presenta como dato didáctico simulado, no como estadística mundial actual.","Las Ciencias Sociales aportan preguntas, conceptos, fuentes y métodos para relacionar decisiones humanas, instituciones y condiciones de vida; no sustituyen la evidencia con opiniones.","Para leer un informe: identifica el tema, la fuente y la fecha; lee título, unidades y escalas de las gráficas; compara datos y saca conclusiones sin exagerar.","En 2015, los países de la ONU acordaron 17 Objetivos de Desarrollo Sostenible (Agenda 2030) para enfrentar juntos estos problemas. Lo global también se vive y se resuelve en lo local."],"media":{"id":"s08-ccss-1-ods","kind":"image","title":"Un planeta, muchos retos","aspect":"16:9","alt":"Ilustración de un globo terráqueo rodeado de íconos de problemas mundiales: una mazorca seca, una gota de agua tachada, un termómetro alto, un árbol cortado, una mochila de migrante y un libro cerrado.","brief":"Ilustración central de la Tierra rodeada de 8 íconos grandes y amables, cada uno con una etiqueta breve: Hambre (plato vacío), Agua (gota con signo de interrogación), Cambio climático (termómetro alto), Bosques (tocón de árbol), Contaminación (bolsa plástica en el mar), Migración forzada (familia con mochilas), Educación (libro cerrado), Desigualdad (balanza inclinada). Debajo: \\"La ONU mide estos problemas con informes y datos\\". Estilo plano, colores suaves, sin fotos de personas reales ni imágenes dolorosas. Target: public/media/s08-ccss-1-ods.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"Problemas sociales con datos","prompt":"Lee cómo las Ciencias Sociales estudian un problema mundial.","type":"explain","props":{"icon":"Globe2","body":"Las Ciencias Sociales estudian problemas mundiales y aportan preguntas, fuentes fechadas, comparaciones y conclusiones cuidadosas."},"id":"s08-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Caso didáctico simulado; no describe una situación actual: en una temporada ficticia, la lluvia llegó tarde y se perdieron milpas en una comunidad del Corredor Seco. El mismo paquete simula sequías en partes de África y Asia. ¿Qué permite comparar?","explain":"Algunos problemas **no respetan fronteras**: el cambio climático, el hambre o la contaminación afectan a muchos países a la vez. Son **problemas mundiales**.","type":"choice","props":{"options":[{"id":"a","text":"Que hay problemas que afectan a muchos países a la vez","icon":"Globe"},{"id":"b","text":"Que es pura casualidad y no tiene relación","icon":"Dice5","feedback":"Cuando algo se repite en muchos lugares, conviene investigar si hay causas comunes, como el cambio del clima."},{"id":"c","text":"Que solo Guatemala tiene problemas","icon":"MapPin","feedback":"La sequía también ocurre en otros continentes: es un problema compartido."}],"correct":["a"]},"id":"s08-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"La problemática mundial actual","prompt":"Los informes de la ONU y de otros organismos describen varios problemas que enfrenta la humanidad hoy. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Las **Ciencias Sociales** ayudan a comprender estos problemas al comparar fuentes, fechas, actores, decisiones e instituciones. Una relación entre datos orienta preguntas, pero no prueba por sí sola una causa.","reveal":[{"icon":"Wheat","front":"Pobreza y hambre","back":"Caso didáctico simulado: un informe regional registra **9 de cada 100 personas** con alimentación insuficiente. La cifra no representa un dato mundial actual."},{"icon":"Droplets","front":"Agua","back":"Caso didáctico simulado: una tabla compara hogares con servicio gestionado de forma segura. Tener tubería no demuestra por sí solo que el agua sea potable."},{"icon":"Thermometer","front":"Cambio climático","back":"El planeta se calienta por los gases que producen la quema de combustibles y la tala de bosques. Hay sequías y tormentas más fuertes."},{"icon":"TreePine","front":"Bosques y biodiversidad","back":"Se pierden bosques y muchas especies de plantas y animales están en peligro."},{"icon":"Route","front":"Migración forzada","back":"Millones de personas dejan su hogar por pobreza, violencia, conflictos o desastres."},{"icon":"BookOpen","front":"Educación","back":"Millones de niñas y niños en el mundo no van a la escuela, sobre todo en zonas pobres o con conflictos."},{"icon":"Target","front":"Una respuesta común: los ODS","back":"En **2015**, los países de la ONU acordaron **17 Objetivos de Desarrollo Sostenible** (la **Agenda 2030**): metas comunes como acabar con el hambre, dar educación de calidad, agua limpia y cuidar el clima."}]},"id":"s08-ccss-1-3"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","title":"Cómo leer un informe estadístico","prompt":"Los **datos estadísticos** son números que describen un problema. Para leerlos bien, sigue estos pasos. Toca cada tarjeta.","media":{"id":"s08-ccss-1-grafica","kind":"diagram","title":"Partes de una gráfica","aspect":"4:3","alt":"Gráfica de barras con flechas que señalan sus partes: título, fuente, eje de categorías, eje de valores con unidades y la barra más alta.","brief":"Gráfica de barras de ejemplo con datos hipotéticos rotulados \\"Ejemplo\\" y flechas que señalan: (1) Título: \\"Hogares con agua entubada en cuatro aldeas (supuesto)\\"; (2) Fuente y año, en letra pequeña abajo; (3) Eje horizontal con los nombres de las aldeas; (4) Eje vertical con la unidad \\"%\\" y escala de 0 a 100 de 20 en 20; (5) la barra más alta y la más baja resaltadas. Colores claros, textos grandes. Target: public/media/s08-ccss-1-grafica.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"BarChart3","body":"Un buen lector de datos no exagera: dice **lo que muestran los números** y aclara si son **aproximados** o **supuestos**.","reveal":[{"icon":"FileText","front":"1. Tema, fuente y fecha","back":"¿De qué trata? ¿Quién lo publicó (ONU, INE, municipalidad)? ¿De qué año son los datos? Una fuente confiable dice cómo obtuvo sus datos."},{"icon":"Ruler","front":"2. Unidades y escala","back":"¿Son personas, porcentajes (%) o millones? ¿De cuánto en cuánto sube la escala?"},{"icon":"Search","front":"3. Comparar","back":"¿Cuál es el dato mayor y el menor? ¿Aumentó o disminuyó con el tiempo?"},{"icon":"Lightbulb","front":"4. Concluir","back":"Escribe una conclusión que salga de los datos: \\"La aldea C tiene la menor cobertura de agua\\"."}]},"id":"s08-ccss-1-4"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","prompt":"Como práctica guiada de **Ciencias Sociales**, construye la gráfica de este informe hipotético sobre acceso al agua, un **problema mundial** observado aquí a escala municipal.","hint":"Lee cada dato de la tabla y sube la barra hasta ese número. La escala va de 10 en 10.","explain":"La gráfica muestra de un vistazo que la aldea Los Pinos tiene la menor cobertura: allí debería priorizarse un proyecto de agua.","type":"chart-builder","props":{"categories":[{"id":"a","label":"El Llano","icon":"Home"},{"id":"b","label":"San José","icon":"Home"},{"id":"c","label":"Los Pinos","icon":"Home"},{"id":"d","label":"La Cumbre","icon":"Home"}],"data":[80,60,30,50],"max":100,"step":10,"unit":"%","source":"Informe municipal (datos supuestos): El Llano 80 %, San José 60 %, Los Pinos 30 %, La Cumbre 50 %"},"id":"s08-ccss-1-5"},{"fase":"aplicar","areas":["ccss","l1"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","prompt":"Lee este fragmento de un informe **hipotético** y usa aportes de las Ciencias Sociales para relacionar fuente, fecha, decisiones y condiciones de vida.","type":"reading","props":{"genre":"Informe (datos supuestos)","heading":"Informe regional sobre niñez y educación","passage":"Supongamos que un organismo internacional estudió cuatro países de una región durante 10 años. Estos son algunos resultados.\\n\\nEn 2014, **20 de cada 100** niñas y niños en edad de primaria no asistían a la escuela. En 2024, la cifra bajó a **12 de cada 100**. La mejora fue mayor en las ciudades que en las áreas rurales.\\n\\nEl informe señala tres causas principales de la falta de asistencia: la **pobreza** (las familias necesitan que los niños trabajen), la **distancia** a la escuela y la **migración** de las familias. Recomienda becas, transporte escolar y escuelas cercanas en el área rural.","questions":[{"q":"¿Qué pasó con la asistencia escolar entre 2014 y 2024?","options":[{"id":"a","text":"Mejoró: los que no asistían bajaron de 20 a 12 de cada 100"},{"id":"b","text":"Empeoró: subieron de 12 a 20 de cada 100"},{"id":"c","text":"No cambió nada"}],"correct":"a"},{"q":"¿Cuántos niños de cada 100 **dejaron** de estar fuera de la escuela en esos 10 años?","options":[{"id":"a","text":"8"},{"id":"b","text":"12"},{"id":"c","text":"32"}],"correct":"a","why":"20 − 12 = 8 de cada 100."},{"q":"¿Qué conclusión está **mejor apoyada** por los datos?","options":[{"id":"a","text":"Hubo avances, pero el área rural necesita más apoyo"},{"id":"b","text":"El problema ya está resuelto en todas partes"},{"id":"c","text":"La educación no tiene relación con la pobreza"}],"correct":"a","why":"El informe dice que la mejora fue menor en el área rural y que la pobreza es una causa."}]},"id":"s08-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Un mismo problema mundial se vive también en escala local. Clasifica cada situación de la lección según el **problema mundial** al que pertenece.","explain":"Pensar globalmente y actuar localmente: entender el problema mundial ayuda a actuar donde vivimos.","type":"sort","props":{"buckets":[{"id":"cli","label":"Cambio climático y ambiente","icon":"Thermometer","color":"var(--c-ok)"},{"id":"pob","label":"Pobreza y hambre","icon":"Wheat","color":"var(--c-maiz-strong)"},{"id":"mig","label":"Migración","icon":"Route","color":"var(--area-ccss)"}],"items":[{"id":"l1","text":"La lluvia llega tarde y se pierde la cosecha","bucket":"cli"},{"id":"l2","text":"Un joven se va a otro país a buscar trabajo","bucket":"mig"},{"id":"l3","text":"Familias que no alcanzan a comprar la canasta básica","bucket":"pob"},{"id":"l4","text":"Basura plástica en el río del pueblo","bucket":"cli"},{"id":"l5","text":"Niños con desnutrición en la aldea","bucket":"pob"}]},"id":"s08-ccss-1-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"En 2015, los países de la ONU acordaron los **17 Objetivos de Desarrollo Sostenible** (ODS). ¿Para qué sirven?","explain":"Los ODS son metas comunes para el año 2030: acabar con la pobreza y el hambre, garantizar educación, agua, igualdad de género, cuidar el clima y más. Cada país, municipio y persona puede aportar.","type":"choice","props":{"options":[{"id":"a","text":"Son metas comunes para enfrentar juntos los grandes problemas del mundo"},{"id":"b","text":"Son reglas de un deporte internacional","feedback":"No: son metas de desarrollo que los países acordaron en la ONU."},{"id":"c","text":"Son impuestos que se pagan a la ONU","feedback":"No son impuestos: son objetivos que guían las políticas de los países."}],"correct":["a"]},"id":"s08-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"¿Qué opción usa un aporte de las Ciencias Sociales para comprender un **problema mundial actual**?","type":"choice","props":{"options":[{"id":"a","text":"Comparar fuentes fechadas sobre cambio climático, decisiones públicas y condiciones de vida"},{"id":"b","text":"La construcción de pirámides en Egipto"},{"id":"c","text":"La invención de la imprenta"}],"correct":["a"]},"id":"s08-ccss-1-9"},{"fase":"comprobar","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"Un informe de **Ciencias Sociales** sobre el problema mundial de acceso a energía indica que en 2010 **30 de cada 100** hogares del caso no tenían luz eléctrica y en 2020 eran **18 de cada 100**. ¿En cuántos hogares de cada 100 cambió el indicador?","type":"number-input","props":{"answer":12,"unit":"de cada 100"},"id":"s08-ccss-1-10"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s08","version":"cnb-sexto-c30cc9543fd96a4a","lesson":{"id":"s08-mat-4","title":"Series mayas de 20 en 20 y de 100 en 100","icon":"TrendingUp","minutes":14,"gancho":"Contar de 20 en 20 en el sistema maya es muy fácil: solo se agrega un punto. ¿Y contar de 100 en 100?","objetivos":["Reconocer qué cambia en un numeral maya al sumar 20 o 100"],"resumen":["Sumar 20 es agregar un punto en el segundo nivel (×20). El primer nivel no cambia.","Sumar 100 es agregar una barra en el segundo nivel, porque 5 × 20 = 100.","Cuando el segundo nivel llega a 20, se cambia por un punto en el tercer nivel (×400) y queda un caracol: 400 = 1 | 0 | 0.","Para ordenar numerales mayas: más niveles = mayor. Con los mismos niveles, compara desde el nivel de arriba."],"media":{"id":"s08-mat-4-series","kind":"animation","title":"De 20 en 20 y de 100 en 100","aspect":"16:9","duration":40,"alt":"Una fila de numerales mayas crece: primero se agrega un punto arriba cada vez (de 20 en 20); luego una barra cada vez (de 100 en 100) hasta que al llegar a 400 aparece un tercer nivel.","brief":"Animación 2D de 40 s. Parte 1: aparecen en fila los numerales mayas de 20, 40, 60, 80, 100 y 120; en cada paso cae un punto nuevo en el segundo nivel (cuando hay 5 puntos se funden en una barra) y abajo se mantiene el caracol. Parte 2: la serie 100, 200, 300, 400, 500: en cada paso cae una barra en el segundo nivel; al llegar a 400 las cuatro barras suben convertidas en un punto al tercer nivel y quedan dos caracoles. Narración en español con los números en voz alta. Target: public/media/s08-mat-4-series.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:4.1.7"],"ambito":"conocer","title":"Series mayas","prompt":"Observa qué cambia al sumar **20** o **100** en un numeral maya.","type":"explain","props":{"icon":"TrendingUp","body":"Sumar 20 agrega un punto en el nivel ×20; sumar 100 agrega una barra en ese nivel. Así se forman y comparan series mayas."},"id":"s08-mat-4-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.7"],"ambito":"conocer","title":"Contar de 20 en 20 y de 100 en 100","prompt":"En las series mayas, casi todo pasa en el **segundo nivel**. Toca cada tarjeta.","type":"explain","props":{"icon":"TrendingUp","body":"**+20** = un punto más arriba · **+100** = una barra más arriba (5 × 20 = 100).","reveal":[{"icon":"Dot","front":"De 20 en 20","back":"20 (•), 40 (••), 60 (•••), 80 (••••), 100 (una barra)… en el segundo nivel, con caracol abajo."},{"icon":"Minus","front":"De 100 en 100","back":"100 (una barra), 200 (dos barras), 300 (tres barras) en el segundo nivel, con caracol abajo."},{"icon":"ArrowUp","front":"Al llegar a 400","back":"Cuatro barras serían 20 en el segundo nivel: ¡no caben! Se cambian por **un punto en el tercer nivel** y dos caracoles: 400 = 1 | 0 | 0."},{"icon":"ArrowUp","front":"Y sigue","back":"500 = 1 | 5 | 0 (un punto arriba, una barra en medio, caracol abajo)."}]},"id":"s08-mat-4-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.7"],"ambito":"hacer","title":"Ejemplo resuelto: completar una serie de 100 en 100","prompt":"Observa lo que pasa al cruzar el 400.","type":"worked-example","props":{"icon":"ListOrdered","problem":"Completa la serie: 200, 300, **?**, **?**","steps":[{"text":"200 = dos barras en el nivel del 20, caracol abajo."},{"text":"300 = tres barras en el nivel del 20, caracol abajo."},{"text":"400: una barra más serían cuatro barras = 20 en ese nivel. Se sube **un punto al tercer nivel**: 1 | 0 | 0.","why":"20 × 20 = 400: veinte del segundo nivel forman uno del tercero."},{"text":"500 = 400 + 100: un punto arriba, una barra en medio, caracol abajo: 1 | 5 | 0."}],"answer":"Siguen 400 = 1 | 0 | 0 y 500 = 1 | 5 | 0."},"id":"s08-mat-4-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"Ordena esta **serie de 20 en 20** escrita con numerales mayas, de menor a mayor.","hint":"Todos tienen caracol abajo. Compara lo que hay en el nivel del 20: cada punto vale 20.","explain":"3 puntos = 60; 4 puntos = 80; una barra = 100; una barra y un punto = 120.","type":"order","props":{"items":[{"id":"a","text":"Nivel del 20: tres puntos · Nivel del 1: caracol"},{"id":"b","text":"Nivel del 20: cuatro puntos · Nivel del 1: caracol"},{"id":"c","text":"Nivel del 20: una barra · Nivel del 1: caracol"},{"id":"d","text":"Nivel del 20: una barra y un punto · Nivel del 1: caracol"}],"labels":{"start":"Menor","end":"Mayor"}},"id":"s08-mat-4-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.7"],"ambito":"hacer","prompt":"La serie va de 20 en 20: **40, 60, 80, …** Construye el número que sigue.","hint":"80 tiene cuatro puntos en el nivel del 20. Uno más: cinco puntos forman una barra.","explain":"Sigue 100: una barra en el nivel del 20 y un caracol abajo.","type":"maya-number","props":{"mode":"build","target":100,"levels":2,"scaffold":true},"id":"s08-mat-4-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.7"],"ambito":"conocer","title":"Series que no empiezan en cero","prompt":"Si la serie empieza en un número como 15, el primer nivel **se queda igual** en todos los términos. Toca cada tarjeta.","type":"explain","props":{"icon":"Repeat","body":"Serie 15, 35, 55, 75…: abajo siempre hay **tres barras** (15); arriba se agrega un punto cada vez.","reveal":[{"icon":"Dot","front":"15","back":"Arriba: caracol · Abajo: tres barras."},{"icon":"Dot","front":"35","back":"Arriba: un punto (20) · Abajo: tres barras (15)."},{"icon":"Dot","front":"55","back":"Arriba: dos puntos (40) · Abajo: tres barras (15)."},{"icon":"Scale","front":"Para ordenar","back":"Más niveles = número mayor. Con los mismos niveles, gana el que tiene más en el nivel de arriba."}]},"id":"s08-mat-4-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"La serie va de 100 en 100: **300, 400, 500, …** Construye el número que sigue.","explain":"Sigue 600 = 400 + 200: un punto en el nivel del 400, dos barras en el nivel del 20 y un caracol abajo (1 | 10 | 0).","type":"maya-number","props":{"mode":"build","target":600,"levels":3},"id":"s08-mat-4-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"Ordena esta **serie de 100 en 100**, de menor a mayor.","explain":"200 (dos barras), 300 (tres barras), 400 (un punto en el tercer nivel), 500 (un punto arriba y una barra en medio).","type":"order","props":{"items":[{"id":"a","text":"Nivel del 20: dos barras · Nivel del 1: caracol"},{"id":"b","text":"Nivel del 20: tres barras · Nivel del 1: caracol"},{"id":"c","text":"Nivel del 400: un punto · Nivel del 20: caracol · Nivel del 1: caracol"},{"id":"d","text":"Nivel del 400: un punto · Nivel del 20: una barra · Nivel del 1: caracol"}],"labels":{"start":"Menor","end":"Mayor"}},"id":"s08-mat-4-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"En la serie de 20 en 20 que empieza en 15 (15, 35, 55, …), ¿qué número tiene **cuatro puntos** en el nivel del 20 y **tres barras** abajo?","explain":"4 × 20 + 15 = 80 + 15 = 95.","type":"number-input","props":{"answer":95,"misconceptions":[{"value":19,"msg":"Sumaste 4 + 15. Los puntos de arriba valen 20 cada uno."}]},"id":"s08-mat-4-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"Ordena esta **serie de 20 en 20**, de menor a mayor.","type":"order","props":{"items":[{"id":"a","text":"Nivel del 20: una barra y dos puntos · Nivel del 1: caracol"},{"id":"b","text":"Nivel del 20: una barra y tres puntos · Nivel del 1: caracol"},{"id":"c","text":"Nivel del 20: una barra y cuatro puntos · Nivel del 1: caracol"},{"id":"d","text":"Nivel del 20: dos barras · Nivel del 1: caracol"}],"labels":{"start":"Menor","end":"Mayor"}},"id":"s08-mat-4-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"La serie va de 100 en 100: **500, 600, 700, …** Construye el número que sigue.","type":"maya-number","props":{"mode":"build","target":800,"levels":3},"id":"s08-mat-4-11"}],"kind":"materia","area":"mat","day":4}},{"missionId":"s08","version":"cnb-sexto-070c8866284fbc34","lesson":{"id":"s08-mat-5","title":"Numerales mayas para comparar datos de energía","icon":"Gauge","minutes":15,"gancho":"Un archivo cultural anota con numerales mayas los conteos de dos jornadas didácticas sobre energía. ¿Puedes leer, sumar y comprobar esos registros?","objetivos":["Resolver una situación coherente de datos energéticos y representar el resultado con numerales mayas"],"resumen":["Para resolver un problema con numerales mayas: lee cada numeral en decimal, opera y vuelve a escribir el resultado en maya.","Para comparar: el numeral con más niveles es mayor; con los mismos niveles, compara desde el nivel de arriba.","Un registro honesto conserva la unidad, el dato decimal y la comprobación del numeral maya."],"media":{"id":"s08-mat-5-pizarra","kind":"image","title":"La pizarra de la semana","aspect":"4:3","alt":"Una pizarra del caso simulado muestra 145 minutos de iluminación innecesaria en un pasillo, 230 minutos en un salón y un total por completar con numeral maya.","brief":"Ilustración de una pizarra escolar con el rótulo “Caso escolar simulado; no describe tu escuela”. Tres columnas: “pasillo: 145 min”, “salón: 230 min” y “total: ?”, con numerales mayas de dos niveles junto a los datos decimales. Incluir iconos descriptivos de reloj, pasillo iluminado y salón vacío; no representar minutos como consumo eléctrico. Target: public/media/s08-mat-5-pizarra.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"ambito":"conocer","title":"Numerales mayas para datos de energía","prompt":"Esta lección integra símbolos, niveles y comparación en un solo registro simulado de energía.","type":"explain","props":{"icon":"Zap","body":"Primero se lee el numeral maya por niveles; después se compara u opera el dato de energía y se comprueba en decimal con su unidad."},"id":"s08-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5"],"ambito":"conocer","title":"Resolver problemas con numerales mayas","prompt":"En el caso simulado, los numerales mayas registran minutos de iluminación innecesaria. Para resolver un problema, sigue estos pasos.","type":"explain","props":{"icon":"ListChecks","body":"**Leo** en decimal → **opero** → **escribo** el resultado en maya → **compruebo**.","reveal":[{"icon":"Eye","front":"1. Leo","back":"Convierto cada numeral a decimal: nivel de arriba × 20 + nivel de abajo."},{"icon":"Calculator","front":"2. Opero","back":"Sumo, resto o multiplico como siempre."},{"icon":"PenLine","front":"3. Escribo en maya","back":"Divido el resultado entre 20 (o 400) para repartirlo en niveles."},{"icon":"Scale","front":"Comparar","back":"Más niveles = mayor. Con los mismos niveles, compara desde arriba; si empatan, baja al siguiente nivel."}]},"id":"s08-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"ambito":"hacer","title":"Ejemplo resuelto: un solo registro de energía","prompt":"Suma, representa y comprueba los minutos del caso simulado.","type":"worked-example","props":{"icon":"Gauge","problem":"El registro indica 145 minutos de iluminación innecesaria en un pasillo y 230 minutos en un salón vacío. ¿Cuál es el total y cómo se representa en maya?","steps":[{"text":"Sumo minutos de la misma unidad: 145 + 230 = **375 min**."},{"text":"375 ÷ 20 = **18**, sobran **15**."},{"text":"Nivel del 20: 18; nivel del 1: 15."},{"text":"Compruebo: 18 × 20 + 15 = **375 min**; el numeral es mayor que cada registro parcial."}],"answer":"Total: 375 min = **18 | 15**. Son minutos registrados, no una medida de energía consumida."},"id":"s08-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6"],"ambito":"hacer","prompt":"Construye con apoyo el total del caso: **375 minutos**.","hint":"375 = 18 × 20 + 15.","explain":"Arriba 18 (tres barras y tres puntos); abajo 15 (tres barras). La unidad sigue siendo minutos.","type":"maya-number","props":{"mode":"build","target":375,"levels":2,"scaffold":true},"id":"s08-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.7"],"prompt":"¿Qué **numeral maya** del registro de iluminación innecesaria es mayor?","hint":"Compara desde el nivel de 20 y conserva la unidad minutos.","explain":"230 min = 11 × 20 + 10 y 145 min = 7 × 20 + 5; por eso 230 minutos es mayor.","type":"choice","props":{"options":[{"id":"a","text":"Pasillo: 145 min = nivel del 20: 7 · nivel del 1: 5","feedback":"145 es menor que 230."},{"id":"b","text":"Salón: 230 min = nivel del 20: 11 · nivel del 1: 10"}],"correct":["b"]},"id":"s08-mat-5-5"},{"fase":"construir","areas":["mat"],"cnb":[],"ambito":"conocer","title":"Lo que construimos en la unidad","prompt":"Antes de resolver el caso energético, revisa qué debe conservar un registro matemático confiable.","type":"explain","props":{"icon":"ClipboardCheck","body":"El numeral maya y el decimal deben representar la misma cantidad y mantener la unidad del caso.","reveal":[{"icon":"Hash","front":"Dato decimal","back":"Permite operar y comprobar la cantidad."},{"icon":"Shell","front":"Representación maya","back":"Distribuye la misma cantidad en niveles de ×1, ×20 y ×400."},{"icon":"Gauge","front":"Unidad","back":"Indica si se cuentan focos, minutos o registros; no se mezclan unidades."},{"icon":"BadgeCheck","front":"Comprobación","back":"Multiplica cada nivel por su valor y suma."}]},"id":"s08-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.5"],"prompt":"Lee el numeral maya del primer registro de iluminación innecesaria: **145 minutos**.","explain":"7 × 20 + 5 = 145 minutos.","type":"maya-number","props":{"mode":"read","target":145,"levels":2},"id":"s08-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6"],"prompt":"El primer registro equivale a **145** minutos y el segundo a **230** minutos. ¿Cuál es el total que luego representarás en maya?","explain":"145 + 230 = 375 minutos.","type":"number-input","props":{"answer":375,"unit":"minutos"},"id":"s08-mat-5-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Representa en numeral maya el total de **375** minutos del caso.","type":"maya-number","props":{"mode":"build","target":375,"levels":2},"id":"s08-mat-5-9"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.7"],"prompt":"¿Qué comprobación respalda el numeral maya construido para **375 minutos de iluminación**?","type":"choice","props":{"options":[{"id":"a","text":"18 × 20 + 15 = 375"},{"id":"b","text":"15 × 20 + 18 = 318"},{"id":"c","text":"18 + 15 = 33"}],"correct":["a"]},"id":"s08-mat-5-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"prompt":"En un registro nuevo de iluminación, hay **160 minutos** en biblioteca y **220 minutos** en laboratorio. Construye en maya el total y verifica que sea mayor que cada parte.","type":"maya-number","props":{"mode":"build","target":380,"levels":2},"id":"s08-mat-5-11"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.5","mat:4.1.6","mat:4.1.7"],"prompt":"Otro registro de iluminación suma **185 minutos + 210 minutos**. Lee en maya el total correcto y decide si supera los 375 minutos anteriores.","type":"maya-number","props":{"mode":"read","target":395,"levels":2},"id":"s08-mat-5-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Aproximo cantidades a la cifra que me piden","Leo y escribo numerales mayas","Convierto números del sistema decimal al maya","Ordeno series mayas de 20 en 20 y de 100 en 100"],"commitments":["Enseñaré a un familiar a escribir su edad con numerales mayas","Anotaré en maya lo que se compra en casa durante una semana","Buscaré cantidades grandes en una noticia y las aproximaré"]},"id":"s08-mat-5-13"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s08","version":"cnb-sexto-11289f8c2903966b","lesson":{"id":"s08-l1-1","title":"Honestidad intelectual: datos, fuentes y citas","icon":"ShieldCheck","minutes":14,"gancho":"Si copias un texto de otra persona y le pones tu nombre, ¿de quién es realmente ese trabajo?","objetivos":["Explicar qué es la honestidad intelectual y por qué importa"],"resumen":["Honestidad intelectual es decir la verdad sobre de dónde viene lo que sabes y lo que escribes.","Tres compromisos: 1) no presentar como tuyo lo que escribió otra persona (plagio), 2) no inventar ni cambiar datos, 3) decir siempre de dónde tomaste la información (citar la fuente).","Usar ideas de otros está bien, y es parte de investigar, siempre que digas de quién son.","La honestidad hace que los demás confíen en tu trabajo y te permite aprender de verdad."],"media":{"id":"s08-l1-1-honestidad","kind":"image","title":"Tres compromisos honestos","aspect":"16:9","alt":"Tres paneles: una niña escribe con sus propias palabras junto a un libro abierto; un niño anota en una tabla los datos reales de una encuesta; una niña escribe al final de su informe la lista de fuentes.","brief":"Ilustración en tres paneles con estilo de cómic suave. Panel 1 \\"Escribo con mis palabras\\": niña que lee un libro y escribe en su cuaderno. Panel 2 \\"No invento datos\\": niño que anota con cuidado los resultados de una encuesta en una tabla, aunque no son los que esperaba (cara pensativa). Panel 3 \\"Digo de dónde lo saqué\\": niña que escribe \\"Fuentes:\\" al final de su informe. Personajes diversos de Guatemala, fondo de aula. Target: public/media/s08-l1-1-honestidad.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","title":"La fuente sostiene la confianza","prompt":"Lee este principio antes de decidir cómo usar datos ajenos.","type":"explain","props":{"icon":"ShieldCheck","body":"La honestidad intelectual exige conservar el dato, distinguir palabras propias y ajenas, y nombrar la **fuente**."},"id":"s08-l1-1-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","title":"¿Qué es la honestidad intelectual?","prompt":"La **honestidad intelectual** es decir la verdad sobre **de dónde viene** lo que sabes y lo que escribes. Mira la imagen y toca cada tarjeta.","type":"explain","props":{"icon":"ShieldCheck","body":"Investigar es como una conversación con otras personas que saben: honrarlas es decir sus nombres.","reveal":[{"icon":"Copy","front":"1. No plagiar","back":"**Plagio** es presentar como propio lo que escribió, dibujó o descubrió otra persona. Copiar y pegar sin decir de dónde es, es plagio."},{"icon":"BarChart3","front":"2. No inventar ni cambiar datos","back":"Si tu encuesta dio 12 respuestas, escribes 12, aunque esperabas 20. Inventar o \\"arreglar\\" datos engaña a quien lee."},{"icon":"Quote","front":"3. Citar la fuente","back":"Cada vez que uses información de otra persona o de un libro, **di de dónde la tomaste**: en el texto y en la lista de fuentes."},{"icon":"Heart","front":"¿Por qué importa?","back":"Respetas el trabajo de otros, los demás pueden **confiar** en ti y, sobre todo, **aprendes** de verdad: copiar no deja nada en tu cabeza."}]},"id":"s08-l1-1-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"Lee lo que le pasó a Diego y responde.","type":"reading","props":{"genre":"Relato","heading":"Los números de Diego","passage":"Diego y su grupo investigaban cuántas familias de su cuadra separan la basura. Preguntaron casa por casa y anotaron las respuestas: de 25 familias, solo 6 separaban la basura.\\n\\n—Seis es muy poquito —dijo Diego—. Si ponemos 20, el cartel se va a ver mejor y la maestra nos va a felicitar.\\n\\nKarla no estuvo de acuerdo:\\n\\n—Si cambiamos el número, el cartel dirá una mentira. Y además, el dato real es importante: muestra que hay que hacer algo.\\n\\nEl grupo escribió el dato verdadero: 6 de 25 familias. Debajo agregaron una propuesta: repartir hojas con consejos para separar la basura. Cuando presentaron, la directora les pidió copias del cartel para llevarlas a la reunión de padres. \\"Gracias a su investigación\\", dijo, \\"sabemos que tenemos trabajo por hacer\\".\\n\\nDiego sonrió. Entendió que un dato honesto, aunque no sea el que uno quiere, puede ser el que más ayuda.","questions":[{"q":"¿Cuántas familias separaban la basura, según la investigación?","options":[{"id":"a","text":"6 de 25"},{"id":"b","text":"20 de 25"},{"id":"c","text":"25 de 25"}],"correct":"a","why":"Es el dato real que anotaron al preguntar casa por casa."},{"q":"¿Qué quería hacer Diego con el dato?","options":[{"id":"a","text":"Cambiarlo por un número mayor para que el cartel se viera mejor"},{"id":"b","text":"Borrarlo del cartel"},{"id":"c","text":"Preguntar a más familias"}],"correct":"a","why":"Diego propuso poner 20 en lugar de 6: eso es alterar un dato."},{"q":"¿Por qué fue útil que el grupo usara el dato verdadero?","options":[{"id":"a","text":"Porque mostró un problema real y la escuela pudo actuar"},{"id":"b","text":"Porque así el cartel se veía más bonito"},{"id":"c","text":"Porque la maestra no revisa los datos"}],"correct":"a","why":"La directora usó el dato para trabajar con los padres: un dato falso habría escondido el problema."}]},"id":"s08-l1-1-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"hacer","title":"Ejemplo resuelto: la prueba de honestidad","prompt":"Antes de entregar, Sofía revisa su texto con tres preguntas.","type":"worked-example","props":{"icon":"ClipboardCheck","problem":"Párrafo de Sofía: “El caso registra 12,468 kWh. Según la Ficha A, el valor aproximado es 12,000 kWh. Una lámpara LED siempre elimina por completo el consumo de electricidad”.","steps":[{"text":"**¿Son mis palabras?** Sí, pero las afirmaciones todavía necesitan fuente."},{"text":"**¿Dije de dónde sale cada dato?** El redondeo sí; el valor exacto también debe atribuirse a la Ficha A."},{"text":"**¿La conclusión respeta la evidencia?** No: una LED sigue usando energía y la palabra “siempre” no está respaldada."},{"text":"Corrige: _Según la Ficha B, una LED de 9 W usa menos potencia que la lámpara de 60 W comparada en el caso simulado._"}],"answer":"Ahora el párrafo es honesto: distingue las afirmaciones propias y atribuye los datos a las Fichas A y B de la lección.","tip":"Tres preguntas: ¿son mis palabras?, ¿dije de dónde viene?, ¿el dato es el real?"},"id":"s08-l1-1-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"Clasifica cada acción: ¿es **honesta** o **deshonesta**?","hint":"Aplica los tres compromisos: no copiar como propio, no inventar datos, decir de dónde viene.","explain":"Una práctica es honesta cuando conserva los datos, distingue las palabras ajenas y hace visible la fuente; alterar, inventar u ocultar el origen rompe la confianza.","type":"sort","props":{"buckets":[{"id":"hon","label":"Honesta","icon":"ShieldCheck","color":"var(--c-ok)"},{"id":"des","label":"Deshonesta","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"h1","text":"Escribir la lista de fuentes al final del informe","bucket":"hon"},{"id":"h2","text":"Copiar y pegar un texto de internet con mi nombre","bucket":"des"},{"id":"h3","text":"Poner entre comillas una frase de un libro y decir de cuál es","bucket":"hon"},{"id":"h4","text":"Inventar la respuesta de una entrevista que no hice","bucket":"des"},{"id":"h5","text":"Explicar con mis palabras lo que leí y nombrar la fuente","bucket":"hon"},{"id":"h6","text":"Redondear 18 respuestas a \\"casi todos\\" cuando eran 18 de 40","bucket":"des","feedback":"18 de 40 es menos de la mitad: decir \\"casi todos\\" cambia el sentido del dato."}]},"id":"s08-l1-1-5"},{"fase":"aplicar","areas":["l1","fc"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Laptop","text":"Es de noche y el informe es para mañana. En internet encuentras un texto perfecto sobre el tema. Tu compañero **Óscar** dice: \\"Cópialo y pégalo, nadie se va a dar cuenta\\"."},"options":[{"id":"a","icon":"Copy","text":"Copiarlo completo y ponerle mi nombre","consequence":"La maestra reconoce el texto. Pierdes la confianza del grado y no aprendiste nada.","values":["deshonestidad"],"constructive":false},{"id":"b","icon":"PenLine","text":"Leerlo, escribir las ideas con mis palabras y anotar de dónde las saqué","consequence":"Tu informe es más sencillo, pero es tuyo y es honesto. La maestra valora que citaste la fuente.","values":["honestidad intelectual","responsabilidad"],"constructive":true},{"id":"c","icon":"Quote","text":"Copiar solo una frase importante entre comillas, con el nombre del autor y del sitio","consequence":"Usaste bien una cita: dejaste claro que esas palabras no son tuyas.","values":["honestidad intelectual","respeto al trabajo de otros"],"constructive":true}]},"id":"s08-l1-1-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.4"],"ambito":"ser","prompt":"La ficha no indica cuánto dinero se ahorró. ¿Qué escribes en el informe?","explain":"Si un dato no aparece, se reconoce el límite. Inventar una cantidad, aunque parezca posible, altera la información.","type":"choice","props":{"options":[{"id":"a","text":"“El paquete no informa un ahorro monetario”."},{"id":"b","text":"“Se ahorraron Q500”, porque parece razonable","feedback":"Sería un dato inventado."},{"id":"c","text":"“Se eliminó todo el gasto de electricidad”","feedback":"Es una exageración sin respaldo."}],"correct":["a"]},"id":"s08-l1-1-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Qué es el **plagio**?","type":"choice","props":{"options":[{"id":"a","text":"Presentar como propio lo que escribió o hizo otra persona"},{"id":"b","text":"Escribir la lista de fuentes"},{"id":"c","text":"Explicar una idea con tus palabras y decir de quién es"}],"correct":["a"]},"id":"s08-l1-1-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.4"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Usar ideas de otras personas está bien si dices de quién son.","answer":true},{"text":"Si un dato no me gusta, puedo cambiarlo un poco.","answer":false,"why":"Cambiar datos es deshonesto: el dato real es el que se escribe."},{"text":"La honestidad intelectual ayuda a que los demás confíen en tu trabajo.","answer":true}]},"id":"s08-l1-1-9"}],"kind":"materia","area":"l1","day":1}},{"missionId":"s08","version":"cnb-sexto-efc23d928e8c648b","lesson":{"id":"s08-ccss-1","title":"Los grandes problemas del mundo, en datos","icon":"BarChart3","minutes":15,"gancho":"Todos los días escuchas noticias sobre sequías, migración, precios altos o contaminación. ¿Son problemas solo de Guatemala o de todo el planeta? ¿Cómo sabemos qué tan grandes son?","objetivos":["Usar aportes de las Ciencias Sociales, fuentes y datos fechados para comprender un problema mundial sin exagerar conclusiones"],"resumen":["Problemas mundiales actuales: pobreza y hambre, desigualdad, cambio climático, falta de agua potable, pérdida de bosques y biodiversidad, contaminación, migración forzada, conflictos armados, enfermedades y falta de acceso a la educación.","Los organismos publican informes con fuente, fecha, método y unidad. En esta lección, cualquier cifra sin referencia completa se presenta como dato didáctico simulado, no como estadística mundial actual.","Las Ciencias Sociales aportan preguntas, conceptos, fuentes y métodos para relacionar decisiones humanas, instituciones y condiciones de vida; no sustituyen la evidencia con opiniones.","Para leer un informe: identifica el tema, la fuente y la fecha; lee título, unidades y escalas de las gráficas; compara datos y saca conclusiones sin exagerar.","En 2015, los países de la ONU acordaron 17 Objetivos de Desarrollo Sostenible (Agenda 2030) para enfrentar juntos estos problemas. Lo global también se vive y se resuelve en lo local."],"media":{"id":"s08-ccss-1-ods","kind":"image","title":"Un planeta, muchos retos","aspect":"16:9","alt":"Ilustración de un globo terráqueo rodeado de íconos de problemas mundiales: una mazorca seca, una gota de agua tachada, un termómetro alto, un árbol cortado, una mochila de migrante y un libro cerrado.","brief":"Ilustración central de la Tierra rodeada de 8 íconos grandes y amables, cada uno con una etiqueta breve: Hambre (plato vacío), Agua (gota con signo de interrogación), Cambio climático (termómetro alto), Bosques (tocón de árbol), Contaminación (bolsa plástica en el mar), Migración forzada (familia con mochilas), Educación (libro cerrado), Desigualdad (balanza inclinada). Debajo: \\"La ONU mide estos problemas con informes y datos\\". Estilo plano, colores suaves, sin fotos de personas reales ni imágenes dolorosas. Target: public/media/s08-ccss-1-ods.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"Problemas sociales con datos","prompt":"Lee cómo las Ciencias Sociales estudian un problema mundial.","type":"explain","props":{"icon":"Globe2","body":"Las Ciencias Sociales estudian problemas mundiales y aportan preguntas, fuentes fechadas, comparaciones y conclusiones cuidadosas."},"id":"s08-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Caso didáctico simulado; no describe una situación actual: en una temporada ficticia, la lluvia llegó tarde y se perdieron milpas en una comunidad del Corredor Seco. El mismo paquete simula sequías en partes de África y Asia. ¿Qué permite comparar?","explain":"Algunos problemas **no respetan fronteras**: el cambio climático, el hambre o la contaminación afectan a muchos países a la vez. Son **problemas mundiales**.","type":"choice","props":{"options":[{"id":"a","text":"Que hay problemas que afectan a muchos países a la vez","icon":"Globe"},{"id":"b","text":"Que es pura casualidad y no tiene relación","icon":"Dice5","feedback":"Cuando algo se repite en muchos lugares, conviene investigar si hay causas comunes, como el cambio del clima."},{"id":"c","text":"Que solo Guatemala tiene problemas","icon":"MapPin","feedback":"La sequía también ocurre en otros continentes: es un problema compartido."}],"correct":["a"]},"id":"s08-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","title":"La problemática mundial actual","prompt":"Los informes de la ONU y de otros organismos describen varios problemas que enfrenta la humanidad hoy. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Las **Ciencias Sociales** ayudan a comprender estos problemas al comparar fuentes, fechas, actores, decisiones e instituciones. Una relación entre datos orienta preguntas, pero no prueba por sí sola una causa.","reveal":[{"icon":"Wheat","front":"Pobreza y hambre","back":"Caso didáctico simulado: un informe regional registra **9 de cada 100 personas** con alimentación insuficiente. La cifra no representa un dato mundial actual."},{"icon":"Droplets","front":"Agua","back":"Caso didáctico simulado: una tabla compara hogares con servicio gestionado de forma segura. Tener tubería no demuestra por sí solo que el agua sea potable."},{"icon":"Thermometer","front":"Cambio climático","back":"El planeta se calienta por los gases que producen la quema de combustibles y la tala de bosques. Hay sequías y tormentas más fuertes."},{"icon":"TreePine","front":"Bosques y biodiversidad","back":"Se pierden bosques y muchas especies de plantas y animales están en peligro."},{"icon":"Route","front":"Migración forzada","back":"Millones de personas dejan su hogar por pobreza, violencia, conflictos o desastres."},{"icon":"BookOpen","front":"Educación","back":"Millones de niñas y niños en el mundo no van a la escuela, sobre todo en zonas pobres o con conflictos."},{"icon":"Target","front":"Una respuesta común: los ODS","back":"En **2015**, los países de la ONU acordaron **17 Objetivos de Desarrollo Sostenible** (la **Agenda 2030**): metas comunes como acabar con el hambre, dar educación de calidad, agua limpia y cuidar el clima."}]},"id":"s08-ccss-1-3"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","title":"Cómo leer un informe estadístico","prompt":"Los **datos estadísticos** son números que describen un problema. Para leerlos bien, sigue estos pasos. Toca cada tarjeta.","media":{"id":"s08-ccss-1-grafica","kind":"diagram","title":"Partes de una gráfica","aspect":"4:3","alt":"Gráfica de barras con flechas que señalan sus partes: título, fuente, eje de categorías, eje de valores con unidades y la barra más alta.","brief":"Gráfica de barras de ejemplo con datos hipotéticos rotulados \\"Ejemplo\\" y flechas que señalan: (1) Título: \\"Hogares con agua entubada en cuatro aldeas (supuesto)\\"; (2) Fuente y año, en letra pequeña abajo; (3) Eje horizontal con los nombres de las aldeas; (4) Eje vertical con la unidad \\"%\\" y escala de 0 a 100 de 20 en 20; (5) la barra más alta y la más baja resaltadas. Colores claros, textos grandes. Target: public/media/s08-ccss-1-grafica.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"BarChart3","body":"Quien lee datos con cuidado no exagera: dice **lo que muestran los números** y aclara si son **aproximados** o **supuestos**.","reveal":[{"icon":"FileText","front":"1. Tema, fuente y fecha","back":"¿De qué trata? ¿Quién lo publicó (ONU, INE, municipalidad)? ¿De qué año son los datos? Una fuente confiable dice cómo obtuvo sus datos."},{"icon":"Ruler","front":"2. Unidades y escala","back":"¿Son personas, porcentajes (%) o millones? ¿De cuánto en cuánto sube la escala?"},{"icon":"Search","front":"3. Comparar","back":"¿Cuál es el dato mayor y el menor? ¿Aumentó o disminuyó con el tiempo?"},{"icon":"Lightbulb","front":"4. Concluir","back":"Escribe una conclusión que salga de los datos: \\"La aldea C tiene la menor cobertura de agua\\"."}]},"id":"s08-ccss-1-4"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"hacer","prompt":"Como práctica guiada de **Ciencias Sociales**, construye la gráfica de este informe hipotético sobre acceso al agua, un **problema mundial** observado aquí a escala municipal.","hint":"Lee cada dato de la tabla y sube la barra hasta ese número. La escala va de 10 en 10.","explain":"La gráfica muestra de un vistazo que la aldea Los Pinos tiene la menor cobertura: allí debería priorizarse un proyecto de agua.","type":"chart-builder","props":{"categories":[{"id":"a","label":"El Llano","icon":"Home"},{"id":"b","label":"San José","icon":"Home"},{"id":"c","label":"Los Pinos","icon":"Home"},{"id":"d","label":"La Cumbre","icon":"Home"}],"data":[80,60,30,50],"max":100,"step":10,"unit":"%","source":"Informe municipal (datos supuestos): El Llano 80 %, San José 60 %, Los Pinos 30 %, La Cumbre 50 %"},"id":"s08-ccss-1-5"},{"fase":"aplicar","areas":["ccss","l1"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"ambito":"conocer","prompt":"Lee este fragmento de un informe **hipotético** y usa aportes de las Ciencias Sociales para relacionar fuente, fecha, decisiones y condiciones de vida.","type":"reading","props":{"genre":"Informe (datos supuestos)","heading":"Informe regional sobre niñez y educación","passage":"Supongamos que un organismo internacional estudió cuatro países de una región durante 10 años. Estos son algunos resultados.\\n\\nEn 2014, **20 de cada 100** niñas y niños en edad de primaria no asistían a la escuela. En 2024, la cifra bajó a **12 de cada 100**. La mejora fue mayor en las ciudades que en las áreas rurales.\\n\\nEl informe señala tres causas principales de la falta de asistencia: la **pobreza** (las familias necesitan que los niños trabajen), la **distancia** a la escuela y la **migración** de las familias. Recomienda becas, transporte escolar y escuelas cercanas en el área rural.","questions":[{"q":"¿Qué pasó con la asistencia escolar entre 2014 y 2024?","options":[{"id":"a","text":"Mejoró: los que no asistían bajaron de 20 a 12 de cada 100"},{"id":"b","text":"Empeoró: subieron de 12 a 20 de cada 100"},{"id":"c","text":"No cambió nada"}],"correct":"a"},{"q":"¿Cuántos niños de cada 100 **dejaron** de estar fuera de la escuela en esos 10 años?","options":[{"id":"a","text":"8"},{"id":"b","text":"12"},{"id":"c","text":"32"}],"correct":"a","why":"20 − 12 = 8 de cada 100."},{"q":"¿Qué conclusión está **mejor apoyada** por los datos?","options":[{"id":"a","text":"Hubo avances, pero el área rural necesita más apoyo"},{"id":"b","text":"El problema ya está resuelto en todas partes"},{"id":"c","text":"La educación no tiene relación con la pobreza"}],"correct":"a","why":"El informe dice que la mejora fue menor en el área rural y que la pobreza es una causa."}]},"id":"s08-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"Un mismo problema mundial se vive también en escala local. Clasifica cada situación de la lección según el **problema mundial** al que pertenece.","explain":"Pensar globalmente y actuar localmente: entender el problema mundial ayuda a actuar donde vivimos.","type":"sort","props":{"buckets":[{"id":"cli","label":"Cambio climático y ambiente","icon":"Thermometer","color":"var(--c-ok)"},{"id":"pob","label":"Pobreza y hambre","icon":"Wheat","color":"var(--c-maiz-strong)"},{"id":"mig","label":"Migración","icon":"Route","color":"var(--area-ccss)"}],"items":[{"id":"l1","text":"La lluvia llega tarde y se pierde la cosecha","bucket":"cli"},{"id":"l2","text":"Un joven se va a otro país a buscar trabajo","bucket":"mig"},{"id":"l3","text":"Familias que no alcanzan a comprar la canasta básica","bucket":"pob"},{"id":"l4","text":"Basura plástica en el río del pueblo","bucket":"cli"},{"id":"l5","text":"Niños con desnutrición en la aldea","bucket":"pob"}]},"id":"s08-ccss-1-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.3.1"],"ambito":"conocer","prompt":"En 2015, los países de la ONU acordaron los **17 Objetivos de Desarrollo Sostenible** (ODS). ¿Para qué sirven?","explain":"Los ODS son metas comunes para el año 2030: acabar con la pobreza y el hambre, garantizar educación, agua, igualdad de género, cuidar el clima y más. Cada país, municipio y persona puede aportar.","type":"choice","props":{"options":[{"id":"a","text":"Son metas comunes para enfrentar juntos los grandes problemas del mundo"},{"id":"b","text":"Son reglas de un deporte internacional","feedback":"No: son metas de desarrollo que los países acordaron en la ONU."},{"id":"c","text":"Son impuestos que se pagan a la ONU","feedback":"No son impuestos: son objetivos que guían las políticas de los países."}],"correct":["a"]},"id":"s08-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"¿Qué opción usa un aporte de las Ciencias Sociales para comprender un **problema mundial actual**?","type":"choice","props":{"options":[{"id":"a","text":"Comparar fuentes fechadas sobre cambio climático, decisiones públicas y condiciones de vida"},{"id":"b","text":"La construcción de pirámides en Egipto"},{"id":"c","text":"La invención de la imprenta"}],"correct":["a"]},"id":"s08-ccss-1-9"},{"fase":"comprobar","areas":["ccss","mat"],"cnb":["ccss:8.1.1","ccss:8.3.1"],"prompt":"Un informe de **Ciencias Sociales** sobre el problema mundial de acceso a energía indica que en 2010 **30 de cada 100** hogares del caso no tenían luz eléctrica y en 2020 eran **18 de cada 100**. ¿En cuántos hogares de cada 100 cambió el indicador?","type":"number-input","props":{"answer":12,"unit":"de cada 100"},"id":"s08-ccss-1-10"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s08","version":"cnb-sexto-7cf08aa1b4bf5b90","lesson":{"id":"s08-fc-1","title":"Un mapa para no olvidar","icon":"Map","minutes":15,"gancho":"Los mapas no solo muestran ríos y carreteras. Algunos muestran lo que vivieron las personas. ¿Qué nos puede enseñar un mapa de la memoria?","objetivos":["Explicar qué fue la Comisión para el Esclarecimiento Histórico y qué investigó"],"resumen":["El conflicto armado interno duró de 1960 a 1996. Quien más sufrió fue la población civil, sobre todo las comunidades mayas del área rural.","La Comisión para el Esclarecimiento Histórico (CEH) fue creada por los Acuerdos de Paz; en 1999 presentó su informe \\"Guatemala, memoria del silencio\\".","Según la CEH, entre los departamentos más afectados están Quiché, Huehuetenango, Chimaltenango, Alta Verapaz y Baja Verapaz, en el norte, el noroccidente y el centro del país.","La mayoría de las víctimas pertenecían a pueblos mayas, como el ixil, el k’iche’, el q’anjob’al, el chuj, el mam, el achi, el q’eqchi’ y el kaqchikel. La CEH señaló que la discriminación contra los pueblos indígenas influyó en esa violencia."],"media":{"id":"s08-fc-1-mapa-memoria","kind":"diagram","title":"Mapa de la memoria","aspect":"3:4","alt":"Mapa de Guatemala por departamentos; Quiché, Huehuetenango, Chimaltenango, Alta Verapaz y Baja Verapaz resaltados en violeta con sus nombres.","brief":"Mapa político de Guatemala con sus 22 departamentos en gris claro y nombres pequeños. Resaltar en un violeta respetuoso (no rojo) Quiché, Huehuetenango, Chimaltenango, Alta Verapaz y Baja Verapaz, con su nombre en letra más grande. Leyenda: \\"Departamentos incluidos en esta selección didáctica a partir de Guatemala: memoria del silencio, CEH, 1999. Un mismo color no establece un orden ni una clasificación entre ellos\\". Rosa de los vientos. Pequeñas flores blancas junto a la leyenda como símbolo de memoria. Sin cifras, imágenes de violencia ni armas. Target: public/media/s08-fc-1-mapa-memoria.svg. Accesibilidad: formato final 1600×900 px, contraste alto, patrón además del color y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"ser","title":"Leer un mapa atribuido a la CEH","prompt":"Lee el límite de la leyenda antes de interpretar el mapa.","type":"explain","props":{"icon":"Map","body":"El paquete ubica departamentos y pueblos documentados por la **CEH**. El color ayuda a localizar y no clasifica cuánto sufrió cada comunidad."},"id":"s08-fc-1-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","title":"Buscar la verdad después de la guerra","prompt":"Recuerda: el conflicto armado interno duró de **1960 a 1996**. Al firmar la paz, el país decidió **investigar la verdad**. Toca cada tarjeta.","type":"explain","props":{"icon":"Search","body":"Conocer la verdad no es para odiar a nadie: es para **honrar a las víctimas**, ayudar a sanar y que **nunca más** vuelva a pasar.","reveal":[{"icon":"Users","front":"¿Quiénes sufrieron más?","back":"La **población civil**: personas que no participaban en la guerra. Sobre todo, **comunidades mayas del área rural**."},{"icon":"Landmark","front":"La CEH","back":"La **Comisión para el Esclarecimiento Histórico** fue creada por los **Acuerdos de Paz**. Escuchó a miles de testigos en todo el país."},{"icon":"BookOpen","front":"Su informe","back":"En **1999** presentó el informe **\\"Guatemala, memoria del silencio\\"**, que explica qué pasó, dónde y a quiénes afectó."},{"icon":"Flower2","front":"Un día para recordar","back":"El **25 de febrero**, fecha en que se entregó el informe, es el **Día Nacional de la Dignidad de las Víctimas** del conflicto armado interno."}]},"id":"s08-fc-1-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","prompt":"Lee con respeto. Este texto recuerda a personas y comunidades que sufrieron.","media":{"id":"s08-fc-1-regiones","kind":"image","title":"Norte, noroccidente y centro","aspect":"4:3","alt":"Mapa sencillo de Guatemala dividido en regiones, con el norte, el noroccidente y el centro señalados con flechas y los cinco departamentos nombrados.","brief":"Mapa simplificado de Guatemala con contorno de departamentos. Flechas suaves y etiquetas: \\"Noroccidente: Huehuetenango y Quiché\\", \\"Norte: Alta Verapaz y Baja Verapaz\\", \\"Centro: Chimaltenango\\". Montañas del altiplano dibujadas con líneas suaves. Colores pastel, rosa de los vientos, sin cifras ni imágenes de violencia. Target: public/media/s08-fc-1-regiones.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"reading","props":{"genre":"Texto informativo","heading":"La violencia no afectó a todo el país por igual","passage":"La Comisión para el Esclarecimiento Histórico estudió **en qué lugares** hubo más violencia durante el conflicto armado interno. Su informe muestra que la violencia no afectó a todo el país por igual.\\n\\nEntre los departamentos más afectados están **Quiché** y **Huehuetenango**, en el **noroccidente**; **Alta Verapaz** y **Baja Verapaz**, en el **norte**; y **Chimaltenango**, en el **centro** del país. Muchas de esas comunidades estaban en el área rural, en montañas y valles lejos de la capital.\\n\\nLa mayoría de las víctimas pertenecían a pueblos **mayas**, como el ixil, el k’iche’, el q’anjob’al, el chuj, el mam, el achi, el q’eqchi’ y el kaqchikel. La Comisión explicó que la **discriminación** contra los pueblos indígenas influyó en que la violencia contra ellos fuera tan grave.\\n\\nHoy, muchas comunidades construyen **monumentos, murales y museos comunitarios de la memoria**. Recordar honra a las víctimas, ayuda a sus familias a sanar y enseña que los conflictos deben resolverse con diálogo y respeto a los derechos humanos.","questions":[{"q":"¿En qué región están Quiché y Huehuetenango?","options":[{"id":"a","text":"En el noroccidente"},{"id":"b","text":"En la costa sur"},{"id":"c","text":"En el oriente"}],"correct":"a"},{"q":"¿A qué pueblos pertenecían la mayoría de las víctimas?","options":[{"id":"a","text":"A pueblos mayas"},{"id":"b","text":"A pueblos de otros continentes"},{"id":"c","text":"El texto no lo dice"}],"correct":"a"},{"q":"Según la Comisión, ¿qué influyó en que la violencia contra los pueblos indígenas fuera tan grave?","options":[{"id":"a","text":"La discriminación contra los pueblos indígenas"},{"id":"b","text":"Que vivían cerca de la capital"},{"id":"c","text":"Que no tenían idiomas propios"}],"correct":"a","why":"Esto muestra por qué luchar contra la discriminación, como aprendiste en la semana 3, es también construir la paz."}]},"id":"s08-fc-1-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Según el texto que leíste, ¿cuáles están entre los **departamentos más afectados**? Marca **todos** los que aparecen en la lista.","hint":"Son cinco. Vuelve a leer el segundo párrafo: dos del noroccidente, dos del norte y uno del centro.","explain":"Quiché, Huehuetenango, Alta Verapaz, Baja Verapaz y Chimaltenango. Retalhuleu y Sacatepéquez no están en esa lista.","type":"choice","props":{"multiple":true,"layout":"grid","options":[{"id":"a","text":"Quiché","icon":"MapPin"},{"id":"b","text":"Huehuetenango","icon":"MapPin"},{"id":"c","text":"Retalhuleu","icon":"MapPin"},{"id":"d","text":"Alta Verapaz","icon":"MapPin"},{"id":"e","text":"Baja Verapaz","icon":"MapPin"},{"id":"f","text":"Chimaltenango","icon":"MapPin"},{"id":"g","text":"Sacatepéquez","icon":"MapPin"}],"correct":["a","b","d","e","f"]},"id":"s08-fc-1-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"conocer","title":"Los pueblos y sus territorios","prompt":"Cada pueblo maya vive, sobre todo, en ciertos territorios. Así se relaciona **dónde** ocurrió la violencia con **a quiénes** afectó. Toca cada departamento.","type":"explain","props":{"icon":"MapPin","body":"Estos pueblos siguen vivos: hablan sus idiomas, cultivan, tejen y enseñan a sus hijos. La memoria también es **celebrar que siguen aquí**.","reveal":[{"icon":"Mountain","front":"Quiché","back":"Territorio de los pueblos **k’iche’** e **ixil** (el área ixil incluye Nebaj, Chajul y Cotzal)."},{"icon":"MountainSnow","front":"Huehuetenango","back":"Territorio de los pueblos **mam**, **q’anjob’al** y **chuj**, entre otros."},{"icon":"Trees","front":"Alta Verapaz","back":"Territorio del pueblo **q’eqchi’**, uno de los más numerosos del país."},{"icon":"Sun","front":"Baja Verapaz","back":"Territorio del pueblo **achi**, por ejemplo en Rabinal."},{"icon":"Home","front":"Chimaltenango","back":"Territorio del pueblo **kaqchikel**."}]},"id":"s08-fc-1-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Une cada departamento con un pueblo maya que vive en él.","hint":"Revisa las tarjetas: Rabinal está en Baja Verapaz; el área ixil está en Quiché.","explain":"Ubicar a los pueblos en su territorio ayuda a entender el mapa de la memoria: la violencia se concentró en regiones donde viven comunidades mayas.","type":"match","props":{"leftTitle":"Departamento","rightTitle":"Pueblo","pairs":[{"id":"p1","left":"Baja Verapaz","leftIcon":"MapPin","right":"Achi"},{"id":"p2","left":"Alta Verapaz","leftIcon":"MapPin","right":"Q’eqchi’"},{"id":"p3","left":"Chimaltenango","leftIcon":"MapPin","right":"Kaqchikel"},{"id":"p4","left":"Quiché","leftIcon":"MapPin","right":"Ixil"},{"id":"p5","left":"Huehuetenango","leftIcon":"MapPin","right":"Chuj"}]},"id":"s08-fc-1-6"},{"fase":"construir","areas":["fc"],"cnb":["fc:5.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: leer un mapa temático","prompt":"Un **mapa temático** muestra un solo tema con colores. Mira cómo se lee el mapa de la memoria.","type":"worked-example","props":{"icon":"Map","problem":"Tienes el mapa de la memoria de esta lección. ¿Qué dice y qué podemos concluir?","steps":[{"text":"**Leo el título:** \\"Mapa de la memoria\\". Ya sé que el tema es la memoria del conflicto armado."},{"text":"**Leo la leyenda:** el violeta identifica una selección didáctica basada en el informe de la CEH (1999); no ordena ni clasifica los departamentos entre sí.","why":"La leyenda es la \\"llave\\" del mapa y también declara el límite de lo que el color permite concluir."},{"text":"**Busco los colores:** hay cinco departamentos en violeta: Quiché, Huehuetenango, Alta Verapaz, Baja Verapaz y Chimaltenango."},{"text":"**Miro la ubicación:** casi todos están en el **norte y el noroccidente**, en zonas de montaña donde viven muchas comunidades mayas."}],"answer":"Conclusión: la violencia del conflicto armado se concentró en el **norte, el noroccidente y el centro**, y afectó sobre todo a **pueblos mayas del área rural**.","tip":"Título → leyenda → colores → ubicación → conclusión."},"id":"s08-fc-1-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"En el mapa de la memoria, Huehuetenango y Quiché están en violeta. ¿Qué conclusión **correcta** puedes sacar?","explain":"El mapa muestra dónde fue más grave la violencia. No habla de las personas que viven hoy ni dice que en otros lugares no pasó nada.","type":"choice","props":{"options":[{"id":"a","text":"Que estuvieron entre los departamentos más afectados por la violencia del conflicto armado"},{"id":"b","text":"Que en el resto del país no pasó absolutamente nada","feedback":"Cuidado: el mapa marca los más afectados, pero hubo víctimas en muchos otros lugares."},{"id":"c","text":"Que las personas que viven ahí hoy son culpables","feedback":"Un mapa de la memoria nunca culpa a las comunidades; honra a las víctimas."}],"correct":["a"]},"id":"s08-fc-1-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Clasifica cada departamento más afectado según su **región**.","explain":"Noroccidente: Huehuetenango y Quiché. Norte: Alta y Baja Verapaz. Centro: Chimaltenango.","type":"sort","props":{"buckets":[{"id":"noc","label":"Noroccidente","icon":"Mountain","color":"var(--area-fc)"},{"id":"nor","label":"Norte","icon":"Trees","color":"var(--c-ok)"},{"id":"cen","label":"Centro","icon":"MapPin","color":"var(--c-maiz-strong)"}],"items":[{"id":"r1","text":"Huehuetenango","bucket":"noc"},{"id":"r2","text":"Quiché","bucket":"noc"},{"id":"r3","text":"Alta Verapaz","bucket":"nor"},{"id":"r4","text":"Baja Verapaz","bucket":"nor"},{"id":"r5","text":"Chimaltenango","bucket":"cen"}]},"id":"s08-fc-1-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"Según la Comisión para el Esclarecimiento Histórico, ¿qué población fue la **más afectada** por la violencia del conflicto armado?","type":"choice","props":{"options":[{"id":"a","text":"Comunidades mayas del área rural"},{"id":"b","text":"Personas de otros países"},{"id":"c","text":"Solo personas de la capital"}],"correct":["a"]},"id":"s08-fc-1-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:5.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Quiché y Alta Verapaz están entre los departamentos más afectados según la CEH.","answer":true},{"text":"La leyenda de un mapa explica qué significan sus colores.","answer":true},{"text":"El pueblo achi vive sobre todo en Petén.","answer":false,"why":"El pueblo achi vive sobre todo en Baja Verapaz, por ejemplo en Rabinal."},{"text":"La CEH presentó su informe \\"Guatemala, memoria del silencio\\" en 1999.","answer":true}]},"id":"s08-fc-1-11"}],"kind":"materia","area":"fc","day":2}},{"missionId":"s08","version":"cnb-sexto-7cbf444238f43ce8","lesson":{"id":"s08-ef-1","title":"Juegos tradicionales: jugar como jugaban nuestros abuelos","icon":"Sparkles","minutes":15,"gancho":"Antes de los celulares, tus abuelos jugaban con un trompo, un capirucho, unos cincos o una cuerda. ¿Crees que esos juegos todavía pueden hacerte sudar y reír?","objetivos":["Conocer juegos tradicionales de Guatemala y sus reglas"],"resumen":["Los juegos tradicionales se transmiten de generación en generación, de abuelos a nietos. Usan materiales sencillos y muchas veces reutilizados.","Ejemplos en Guatemala: trompo, capirucho, cincos (canicas), tenta, salta cuerda, ronda con palmas y barrilete. Cada comunidad puede tener sus propios nombres y reglas.","Desarrollan habilidades: el capirucho y los cincos, la coordinación ojo-mano y la precisión; la tenta, la velocidad y los cambios de dirección; la cuerda, el ritmo y la resistencia; ronda con palmas, la fuerza y la cooperación.","Valorarlos es jugarlos, aprenderlos de las personas mayores, enseñarlos a los más pequeños y respetar sus reglas, que se acuerdan antes de jugar."],"media":{"id":"s08-ef-1-juegos","kind":"video","title":"Juegos de ayer y de hoy","aspect":"16:9","duration":60,"alt":"Un abuelo enseña a una niña a lanzar un trompo; niños juegan cincos en un círculo dibujado en la tierra; un grupo salta cuerda cantando; otro juega ronda con palmas sentados en fila.","brief":"Video de 60 s en un patio escolar despejado, con intérpretes autorizados. Escenas de 10 s con rótulo: (1) trompo con pita; (2) capirucho; (3) cincos en un círculo; (4) tenta con bases amplias; (5) cuerda individual e imaginaria; (6) ronda con palmas, con participantes de pie y sentados, separados por un brazo. Cierre con barriletes de papel exhibidos sin elevarlos cerca de cables. Música de marimba suave. Target: public/media/s08-ef-1-juegos.mp4. Accesibilidad: subtítulos completos, transcripción, demostración a velocidad lenta y descripción de cada adaptación."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Reglas de juegos tradicionales","prompt":"Lee qué se practica en estos juegos.","type":"explain","props":{"icon":"History","body":"Trompo, capirucho, cincos, tenta, cuerda y ronda con palmas conservan reglas culturales y practican habilidades motrices."},"id":"s08-ef-1-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"¿Qué tienen en común el trompo, el capirucho y los cincos?","explain":"Son **juegos tradicionales**: se han jugado por generaciones, se aprenden de las personas mayores y usan materiales sencillos. Además, ¡todos entrenan tu precisión y coordinación!","type":"choice","props":{"options":[{"id":"a","text":"Son juegos tradicionales que se aprenden de generación en generación","icon":"History"},{"id":"b","text":"Son juegos electrónicos","icon":"Smartphone","feedback":"No necesitan electricidad: solo madera, pita, vidrio o barro."},{"id":"c","text":"Son deportes olímpicos","icon":"Medal","feedback":"No son deportes olímpicos: son juegos de la tradición popular."}],"correct":["a"]},"id":"s08-ef-1-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","title":"Juegos tradicionales de Guatemala","prompt":"Mira el video y la lámina, y toca cada juego. Compara sus reglas con las tarjetas de la lección.","media":{"id":"s08-ef-1-objetos","kind":"image","title":"Los objetos de los juegos tradicionales","aspect":"4:3","alt":"Sobre un petate: un trompo de madera con su pita, un capirucho (palito y carrete unidos con pita), un puñado de cincos de vidrio, una cuerda larga y un barrilete pequeño de papel de china.","brief":"Fotografía cenital o ilustración realista sobre un petate: trompo de madera pintado con su pita enrollada, capirucho de madera (palito y carrete unidos con pita), cinco o seis cincos (canicas) de vidrio de colores, una cuerda de saltar larga enrollada y un barrilete pequeño de papel de china con cola de trapo. Cada objeto con su nombre en letra grande. Sin marcas comerciales. Target: public/media/s08-ef-1-objetos.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"History","body":"Cada comunidad tiene sus juegos. Estos son algunos de los más conocidos en Guatemala.","reveal":[{"icon":"RotateCw","front":"Trompo","back":"Se enrolla una pita en el trompo y se lanza para que **baile** en el suelo. Retos: que dure mucho, levantarlo bailando en la mano o sacar otros trompos de un círculo."},{"icon":"Target","front":"Capirucho","back":"Un carrete de madera unido con una pita a un palito. Se balancea el carrete para **embocarlo** en el palito. Entrena la **coordinación ojo-mano**."},{"icon":"CircleDot","front":"Cincos","back":"Canicas. Desde una línea, se impulsan con el pulgar para **sacar** los cincos de otros jugadores de un círculo dibujado en la tierra. Pide **precisión**."},{"icon":"Footprints","front":"Tenta","back":"Una persona \\"la lleva\\" y persigue a las demás; a quien toca, le pasa la tenta. Hay \\"bases\\" donde no te pueden tocar. Entrena **velocidad** y **cambios de dirección**."},{"icon":"Repeat","front":"Salta cuerda","back":"Dos personas dan vuelta a una cuerda larga y las demás entran a saltar, muchas veces **cantando** y contando. Entrena **ritmo** y **resistencia**."},{"icon":"Wind","front":"Barrilete","back":"Se construye con papel de china, varas y pita, y se vuela corriendo contra el viento. En noviembre, en Sumpango y Santiago Sacatepéquez se elevan **barriletes gigantes**."}]},"id":"s08-ef-1-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","title":"¿Por qué valorarlos?","prompt":"Los juegos tradicionales son mucho más que pasar el rato. Toca cada tarjeta.","type":"explain","props":{"icon":"Heart","body":"Valorar un juego tradicional es **jugarlo, aprenderlo y enseñarlo**, para que no se pierda.","reveal":[{"icon":"Users","front":"Unen generaciones","back":"Abuelos, padres, madres y nietos pueden jugar juntos y compartir historias."},{"icon":"Landmark","front":"Son cultura","back":"Guardan canciones, palabras y formas de convivir de nuestros pueblos. Son parte de nuestra **identidad**."},{"icon":"Recycle","front":"Materiales sencillos","back":"Se hacen con madera, pita, papel, costales o piedritas: no hace falta dinero y se puede reutilizar."},{"icon":"Activity","front":"Mueven el cuerpo","back":"Correr, saltar, lanzar, equilibrarse: usan las mismas habilidades que aprendiste en esta unidad."}]},"id":"s08-ef-1-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","title":"Ejemplo resuelto: jugar ronda con palmas de forma segura","prompt":"Mira cómo el grupo de Juan organiza el juego de **ronda con palmas** que le enseñó su abuela.","type":"worked-example","props":{"icon":"Music","problem":"Son 8 niñas y niños en un patio despejado. ¿Cómo hacen una ronda con palmas segura y adaptable?","steps":[{"text":"**Despejan el espacio:** retiran mochilas y dejan un brazo de distancia entre participantes."},{"text":"**Acuerdan una secuencia:** dos palmas propias, dos palmas al aire y un paso lateral."},{"text":"**Ensayan despacio:** nadie toma, empuja ni jala a otra persona.","why":"Cada participante controla su propio movimiento."},{"text":"**Cambian el liderazgo:** una persona marca cuatro pulsos y luego cede el turno."},{"text":"**Adaptan:** la secuencia puede hacerse de pie o sentada, con pasos, gestos o palmas suaves; cualquiera puede decir “alto”."}],"answer":"La ronda practica **ritmo, atención y cooperación** sin contacto riesgoso.","tip":"El ritmo se adapta a cada participante; la velocidad nunca vale más que el control."},"id":"s08-ef-1-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"conocer","prompt":"Une cada juego tradicional con la habilidad que más desarrolla.","hint":"Piensa en lo que el cuerpo tiene que hacer en cada juego.","explain":"Todos los juegos mueven el cuerpo, pero cada uno destaca una habilidad.","type":"match","props":{"leftTitle":"Juego","rightTitle":"Habilidad","pairs":[{"id":"c","left":"Capirucho","right":"Coordinación ojo-mano"},{"id":"t","left":"Tenta","right":"Velocidad y cambios de dirección"},{"id":"s","left":"Salta cuerda","right":"Ritmo y resistencia"},{"id":"a","left":"Ronda con palmas","right":"Ritmo y cooperación"}]},"id":"s08-ef-1-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"hacer","prompt":"¡Feria de juegos tradicionales! **Calentamiento:** trote suave y rotaciones. **Estación 1 – Tenta (2 min):** con bases acordadas. **Estación 2 – Salta cuerda:** entra y salta 10 veces contando o cantando; si trabajas sin compañía, usa cuerda individual. **Estación 3 – Precisión:** capirucho, trompo o cincos (si no tienes, lanza tapitas a un círculo dibujado en el suelo). **Poco espacio:** cuerda individual o imaginaria y tapitas a un círculo. **Adaptación:** en la tenta, quien use silla de ruedas puede \\"tentar\\" tocando con una pelota suave; en la cuerda, se puede pasar la cuerda por debajo de las ruedas o dar vuelta a la cuerda. **Vuelta a la calma:** estira y toma agua.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después de la tenta","exercise":{"name":"Tenta con bases","icon":"Footprints","seconds":90}},{"label":"Después de salta cuerda y precisión","exercise":{"name":"Salta cuerda y juego de precisión","icon":"Repeat","seconds":90}}]},"id":"s08-ef-1-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Tu abuelo te enseña a lanzar el trompo, pero tu primo dice: \\"Eso es de antes, es aburrido\\". ¿Qué respuesta muestra **valoración** de los juegos tradicionales?","explain":"Valorar es reconocer lo que el juego aporta (habilidad, cultura, convivencia) e invitar a otros a probarlo, con respeto por los gustos de cada quien.","type":"choice","props":{"options":[{"id":"a","text":"\\"Pruébalo: lanzar el trompo pide mucha precisión y así aprendemos lo que jugaba el abuelo\\""},{"id":"b","text":"\\"Tienes razón, los juegos viejos no sirven\\"","feedback":"Los juegos tradicionales siguen desarrollando habilidades y son parte de la cultura."},{"id":"c","text":"\\"Si no te gusta, eres un aburrido\\"","feedback":"Se puede invitar sin burlarse de los gustos de la otra persona."}],"correct":["a"]},"id":"s08-ef-1-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.7"],"ambito":"convivir","prompt":"Lee la ficha de la lección de **Doña Blanca** sobre el juego tradicional de ronda con palmas y escribe una adaptación segura para poco espacio: regla, movimiento, señal de pausa y habilidad que conserva.","type":"short-answer","props":{"minWords":24,"placeholder":"Regla adaptada... Movimiento... Señal de pausa... Conserva la habilidad de...","model":"El grupo marca el círculo sin jalarse. Camina cuatro pasos con palmas y se detiene al oír “pausa”. Quien está afuera señala un espacio sin empujar. Conserva ritmo, orientación y cooperación.","rubric":["No incluye jalones ni empujones","Define señal de pausa","Explica la habilidad practicada"]},"id":"s08-ef-1-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Cuál es un juego tradicional de Guatemala que desarrolla la **coordinación ojo-mano**?","type":"choice","props":{"options":[{"id":"a","text":"El capirucho"},{"id":"b","text":"Un videojuego de carreras"},{"id":"c","text":"Ver televisión"}],"correct":["a"]},"id":"s08-ef-1-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.2.7"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Los juegos tradicionales se transmiten de generación en generación.","answer":true},{"text":"En la ronda con palmas conviene empujar o jalar para seguir el ritmo.","answer":false,"why":"Cada persona controla sus movimientos y mantiene distancia; no se empuja ni se jala."},{"text":"Un mismo juego puede tener distintos nombres o reglas según la comunidad.","answer":true}]},"id":"s08-ef-1-11"}],"kind":"materia","area":"ef","day":2}},{"missionId":"s08","version":"cnb-sexto-34b49208f05fc36b","lesson":{"id":"s08-ccss-2","title":"Impuestos: una responsabilidad de todos","icon":"Landmark","minutes":15,"gancho":"Cuando compras un cuaderno de Q10, una parte de ese dinero no es para la librería. ¿Para quién es? ¿Y quién decidió que así fuera?","objetivos":["Clasificar y aplicar normas fiscales y responsabilidades ciudadanas en casos de la lección"],"resumen":["Los impuestos son pagos obligatorios que la población y las empresas hacen al Estado para financiar servicios públicos: escuelas, hospitales, carreteras, seguridad.","Las normas jurídicas tienen un orden: la Constitución Política (la ley suprema) establece el deber de contribuir a los gastos públicos y que solo el Congreso puede crear impuestos; las leyes (como la del IVA y la del ISR) y el Código Tributario los desarrollan; los reglamentos explican cómo aplicarlas. Las municipalidades cobran impuestos como el IUSI.","El IVA es el 12 % del valor de lo que se compra y casi siempre ya viene incluido en el precio. El ISR se paga sobre los ingresos. La SAT es la institución que recauda los impuestos.","Pedir factura, no evadir impuestos y cuidar los bienes públicos son responsabilidades ciudadanas; también lo es vigilar que el dinero público se use bien. Los tratados comerciales también fijan reglas sobre los impuestos a las importaciones."],"media":{"id":"s08-ccss-2-ruta","kind":"animation","title":"El viaje de un quetzal de impuestos","aspect":"16:9","duration":45,"alt":"Animación que sigue una moneda desde la compra de un cuaderno con factura hasta el presupuesto del Estado y de ahí a una escuela, un centro de salud y una carretera.","brief":"Animación 2D de 45 s. Una niña compra un cuaderno y recibe su factura. Una moneda con la etiqueta \\"IVA\\" sale de la caja registradora, viaja por una flecha hasta un edificio rotulado \\"SAT\\", luego a un cofre \\"Presupuesto del Estado aprobado por el Congreso\\", y de ahí se reparte en tres flechas hacia una escuela con pupitres nuevos, un centro de salud con medicinas y una carretera en construcción. Al final aparece la frase \\"Tus impuestos regresan en servicios. Pide tu factura\\". Narración en español con subtítulos. Sin logos oficiales reales. Target: public/media/s08-ccss-2-ruta.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Impuestos y responsabilidad","prompt":"Lee el principio que organiza esta lección.","type":"explain","props":{"icon":"Receipt","body":"Los impuestos financian servicios públicos. La Constitución, las leyes y los reglamentos establecen quién puede crearlos y cómo se aplican."},"id":"s08-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","prompt":"La escuela pública, el centro de salud y la carretera de tu municipio cuestan mucho dinero. ¿De dónde sale principalmente ese dinero?","explain":"Sale principalmente de los **impuestos** que pagamos todas las personas y empresas. El Estado no \\"tiene\\" dinero propio: administra lo que la población aporta.","type":"choice","props":{"options":[{"id":"a","text":"De los impuestos que pagan las personas y las empresas","icon":"Coins"},{"id":"b","text":"El gobierno lo imprime cuando quiere","icon":"Banknote","feedback":"Imprimir dinero sin respaldo hace que los precios suban. Los servicios públicos se pagan principalmente con impuestos."},{"id":"c","text":"Lo regalan otros países cada año","icon":"Gift","feedback":"A veces hay donaciones, pero la mayor parte sale de los impuestos de la población."}],"correct":["a"]},"id":"s08-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"¿Qué son los impuestos?","prompt":"Los **impuestos** (o tributos) son pagos **obligatorios** que se hacen al Estado, establecidos por la ley. Toca cada tarjeta.","type":"explain","props":{"icon":"Landmark","body":"La **SAT** (Superintendencia de Administración Tributaria) recauda los impuestos nacionales. El **Congreso** aprueba cada año el **presupuesto**, que dice en qué se gastará ese dinero.","reveal":[{"icon":"ShoppingCart","front":"IVA","back":"**Impuesto al Valor Agregado**: el **12 %** de lo que se compra o de un servicio. Lo pagamos todos, aunque seamos niños, y **casi siempre ya viene incluido** en el precio."},{"icon":"Wallet","front":"ISR","back":"**Impuesto Sobre la Renta**: se paga sobre los **ingresos** de personas y empresas."},{"icon":"Home","front":"IUSI","back":"**Impuesto Único Sobre Inmuebles**: lo pagan los dueños de terrenos y casas, y lo cobra la **municipalidad**."},{"icon":"FileText","front":"La factura","back":"Es el comprobante de una compra. Pedirla ayuda a que el IVA que pagaste **llegue al Estado** y no se quede en manos de quien vende."}]},"id":"s08-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"conocer","title":"Las normas jurídicas tienen un orden","prompt":"Las **normas jurídicas** son las reglas obligatorias de un país. No todas tienen el mismo nivel: se ordenan como una **pirámide**. Toca cada tarjeta, de arriba hacia abajo.","media":{"id":"s08-ccss-2-piramide","kind":"diagram","title":"La pirámide de las normas fiscales","aspect":"3:4","alt":"Pirámide de tres niveles: arriba la Constitución, en medio las leyes del Congreso y el Código Tributario, abajo los reglamentos; a un lado, las normas municipales.","brief":"Diagrama de pirámide con tres niveles de colores. Punta: \\"Constitución Política de la República (1985)\\" con la nota \\"deber de contribuir a los gastos públicos; solo el Congreso crea impuestos\\". Centro: \\"Leyes del Congreso (decretos)\\": Ley del IVA, Ley del ISR, Código Tributario. Base: \\"Reglamentos del Organismo Ejecutivo: explican cómo aplicar las leyes\\". A un lado, un recuadro \\"Municipalidades: IUSI y arbitrios, según la ley\\" y otro \\"Tratados internacionales aprobados por el Congreso (p. ej., impuestos a las importaciones)\\". Flecha lateral: \\"ninguna norma puede contradecir a la de arriba\\". Texto grande, íconos simples. Target: public/media/s08-ccss-2-piramide.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"explain","props":{"icon":"Layers","body":"Regla de oro: **ninguna norma puede contradecir a otra de nivel más alto**. Si una ley contradice la Constitución, la **Corte de Constitucionalidad** puede anularla.","reveal":[{"icon":"ScrollText","front":"Constitución Política","back":"La **ley suprema**. Establece que es **deber** de los guatemaltecos **contribuir a los gastos públicos** según la ley, y que **solo el Congreso** puede crear impuestos (principio de legalidad)."},{"icon":"Gavel","front":"Leyes ordinarias","back":"Las aprueba el **Congreso** como decretos. Ejemplos: la **Ley del IVA**, la del **ISR** y el **Código Tributario**, que da las reglas generales para pagar y cobrar tributos."},{"icon":"FileText","front":"Reglamentos","back":"Los emite el **Organismo Ejecutivo** para explicar **cómo** aplicar una ley. No pueden crear impuestos nuevos."},{"icon":"Building","front":"Normas municipales","back":"Las municipalidades cobran impuestos como el **IUSI** y tasas por servicios (agua, mercado, basura), siempre según lo que permite la ley."},{"icon":"Handshake","front":"Tratados internacionales","back":"Guatemala también firma **tratados** con otros países. Cuando el **Congreso** los aprueba, se vuelven obligatorios en el país. Los **tratados comerciales** (recuerda la semana 3) fijan, por ejemplo, cuánto impuesto pagan los productos que se importan."}]},"id":"s08-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Clasifica cada norma o afirmación según su **nivel** en la pirámide.","hint":"Lo más general y superior está en la Constitución; los impuestos concretos, en leyes del Congreso; los detalles de cómo aplicarlas, en reglamentos.","explain":"La Constitución manda el deber de contribuir; las leyes crean cada impuesto; los reglamentos dicen cómo cumplirlas.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución","icon":"ScrollText","color":"var(--area-ccss)"},{"id":"ley","label":"Ley del Congreso","icon":"Gavel","color":"var(--c-maiz-strong)"},{"id":"reg","label":"Reglamento","icon":"FileText","color":"var(--c-ok)"}],"items":[{"id":"n1","text":"Es deber de los guatemaltecos contribuir a los gastos públicos","bucket":"con"},{"id":"n2","text":"Ley del IVA: el impuesto es del 12 %","bucket":"ley"},{"id":"n3","text":"Detalle de cómo llenar un formulario para declarar un impuesto","bucket":"reg"},{"id":"n4","text":"Solo el Congreso puede crear impuestos","bucket":"con"},{"id":"n5","text":"Código Tributario: reglas generales para pagar tributos","bucket":"ley"}]},"id":"s08-ccss-2-5"},{"fase":"construir","areas":["ccss","mat"],"cnb":["ccss:8.4.1"],"ambito":"hacer","title":"Ejemplo resuelto: ¿cuánto IVA pago?","prompt":"El IVA es el 12 % del valor del producto. Mira dos casos con precios supuestos.","type":"worked-example","props":{"icon":"Calculator","problem":"Caso 1: una mochila vale **Q50 sin IVA**. ¿Cuánto IVA se paga y cuál es el precio final? Caso 2: en una tienda pagas **Q112** por unos zapatos, **con el IVA ya incluido**. ¿Cuánto de eso es IVA?","steps":[{"text":"Caso 1: 12 % de 50 = 50 × 12 ÷ 100 = 600 ÷ 100 = **Q6** de IVA.","why":"\\"Por ciento\\" significa \\"de cada 100\\": 12 de cada 100 quetzales."},{"text":"Precio final: 50 + 6 = **Q56**."},{"text":"Caso 2: si el precio sin IVA fuera Q100, el IVA sería Q12 y el total Q112. Entonces, de Q112, **Q12 son IVA**.","why":"Cuando el IVA está incluido, el precio es el 112 % del valor sin impuesto."}],"answer":"Caso 1: **Q6** de IVA y precio final **Q56**. Caso 2: **Q12** de los Q112 son IVA.","tip":"En las tiendas de Guatemala el precio que ves casi siempre ya incluye el IVA. Por eso, pide factura."},"id":"s08-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.4.1"],"ambito":"hacer","prompt":"Aplica la jerarquía fiscal: clasifica cada decisión del caso de la lección según la norma o responsabilidad que corresponde.","explain":"La Constitución reserva al Congreso la creación de impuestos; la ley crea el tributo; el reglamento detalla su aplicación; pedir factura es responsabilidad ciudadana.","type":"sort","props":{"buckets":[{"id":"con","label":"Constitución"},{"id":"ley","label":"Ley"},{"id":"reg","label":"Reglamento"},{"id":"res","label":"Responsabilidad ciudadana"}],"items":[{"id":"a1","text":"Solo el Congreso puede crear un impuesto nacional","bucket":"con"},{"id":"a2","text":"El decreto establece el IVA","bucket":"ley"},{"id":"a3","text":"Una disposición explica cómo presentar el formulario","bucket":"reg"},{"id":"a4","text":"La persona compradora pide factura","bucket":"res"}]},"id":"s08-ccss-2-7"},{"fase":"aplicar","areas":["ccss","fc"],"cnb":["ccss:8.4.1"],"ambito":"ser","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"Store","text":"Compras útiles escolares por Q84. El vendedor te dice: \\"Si no te doy factura, te lo dejo en Q80\\"."},"options":[{"id":"a","icon":"FileText","text":"Pido la factura y pago el precio completo","consequence":"El IVA que pagaste llega al Estado y se convierte en servicios públicos. Cumpliste con tu responsabilidad ciudadana.","values":["responsabilidad","honestidad"],"constructive":true},{"id":"b","icon":"MessageCircle","text":"Pido la factura y le explico a mi familia por qué es importante","consequence":"Además de cumplir, ayudas a que otros entiendan que la factura protege el dinero de todos.","values":["responsabilidad","solidaridad"],"constructive":true},{"id":"c","icon":"Coins","text":"Acepto el descuento sin factura","consequence":"Ahorras Q4, pero el vendedor no reporta la venta y ese impuesto no llega a escuelas ni hospitales. Es una forma de evasión.","values":[],"constructive":false}]},"id":"s08-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Aplica la Constitución, la ley o el reglamento y decide la responsabilidad fiscal: un reglamento intenta crear un impuesto nuevo sin ley del Congreso. ¿Qué corresponde?","type":"choice","props":{"options":[{"id":"a","text":"Señalo que contradice el principio constitucional: un reglamento no crea impuestos"},{"id":"b","text":"Lo acepto porque cualquier reglamento está sobre la Constitución"},{"id":"c","text":"Lo trato como una decisión privada sin efecto legal"}],"correct":["a"]},"id":"s08-ccss-2-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.4.1"],"prompt":"Una venta incluye IVA pero el vendedor ofrece omitir la factura. ¿Cómo cumples tu responsabilidad ciudadana?","type":"choice","props":{"options":[{"id":"a","text":"Pedir la factura y conservar el comprobante"},{"id":"b","text":"Aceptar porque pagar menos reemplaza la norma"},{"id":"c","text":"Inventar un reglamento personal"}],"correct":["a"]},"id":"s08-ccss-2-10"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s08","version":"cnb-sexto-7db28047325c46ce","lesson":{"id":"s08-ccss-3","title":"Resolver problemas y organizar una contribución simulada","icon":"Handshake","minutes":15,"gancho":"Dos grados quieren usar la cancha a la misma hora. Una aldea discute quién arregla el camino. ¿Existe un \\"método\\" para resolver problemas sin pelear?","objetivos":["Aplicar un procedimiento para resolver problemas con diálogo"],"resumen":["Procedimiento para resolver problemas: 1) identificar con claridad el problema, 2) escuchar a todas las partes, 3) proponer varias alternativas, 4) elegir juntos la mejor, 5) cumplir el acuerdo, 6) evaluar si funcionó.","Habilidades de la cultura de paz: escucha activa, empatía (ponerse en el lugar del otro), expresar lo que sientes sin herir (\\"yo me siento… cuando… porque…\\") y buscar soluciones en las que todos ganen.","Una contribución organizativa simulada permite practicar objetivos, responsabilidades y acuerdos dentro del aula sin afirmar un servicio externo realizado.","Las Ciencias Sociales ayudan a comprender problemas; el diálogo, la organización y la participación responsable ayudan a proponer respuestas."],"media":{"id":"s08-ccss-3-dialogo","kind":"video","title":"Mediación en el recreo","aspect":"16:9","duration":60,"alt":"Animación de dos grupos de estudiantes que discuten por la cancha; una compañera mediadora los ayuda a seguir los seis pasos y llegan a un acuerdo de horarios.","brief":"Animación 2D de 60 s. Escena 1: dos grupos de sexto grado discuten por usar la cancha a la hora del recreo. Escena 2: una compañera mediadora con un distintivo propone sentarse en círculo; en pantalla aparecen los pasos numerados mientras ocurren: identificar el problema, escuchar a cada grupo (burbujas de diálogo con frases \\"yo me siento… cuando…\\"), proponer alternativas (turnos por día, dividir la cancha, jugar juntos), elegir juntos, cumplir y evaluar una semana después. Escena 3: un calendario pegado en la pared con los turnos y ambos grupos jugando. Personajes diversos, narración en español con subtítulos. Target: public/media/s08-ccss-3-dialogo.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Resolver un caso con diálogo","prompt":"Lee el procedimiento antes de tomar una decisión.","type":"explain","props":{"icon":"MessagesSquare","body":"En una simulación de la lección se define el problema, se escuchan posiciones, se comparan alternativas y se registra un acuerdo."},"id":"s08-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Seis pasos para resolver problemas","prompt":"Este **procedimiento** sirve igual para un problema del recreo que para uno de la comunidad o del país. Toca cada tarjeta.","type":"explain","props":{"icon":"ListOrdered","body":"La clave es el **diálogo**: hablar y escuchar con respeto para llegar a un acuerdo que todos acepten.","reveal":[{"icon":"Search","front":"1. Identificar el problema","back":"Decir con claridad qué pasa, sin culpar: \\"Los dos grados queremos la cancha a la misma hora\\"."},{"icon":"Ear","front":"2. Escuchar a todas las partes","back":"Cada quien explica qué necesita y cómo se siente, sin interrupciones."},{"icon":"Lightbulb","front":"3. Proponer alternativas","back":"Pensar **varias** soluciones posibles, sin descartar ninguna al inicio."},{"icon":"Vote","front":"4. Elegir juntos","back":"Escoger la alternativa que sea más justa y posible para todos."},{"icon":"Handshake","front":"5. Cumplir el acuerdo","back":"Cada parte hace lo que se comprometió."},{"icon":"ClipboardCheck","front":"6. Evaluar","back":"Después de un tiempo, revisar: ¿se resolvió? Si no, volver a dialogar."}]},"id":"s08-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"En la aldea, dos familias discuten porque el agua de lluvia de un terreno se mete al otro. Ordena el **procedimiento** para resolverlo.","hint":"Primero entender, luego escuchar, después buscar opciones, decidir, cumplir y revisar.","explain":"El orden importa: si se elige una solución antes de escuchar a todos, alguna parte no la aceptará.","type":"order","props":{"items":[{"id":"r1","text":"Identificar el problema sin culpar"},{"id":"r2","text":"Escuchar a las dos partes con respeto"},{"id":"r3","text":"Proponer alternativas y elegir un acuerdo justo"},{"id":"r4","text":"Registrar responsabilidades y un criterio de revisión"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","title":"Habilidades para la cultura de paz","prompt":"Para dialogar bien se necesitan **habilidades sociales** que se practican como un deporte. Toca cada tarjeta.","type":"explain","props":{"icon":"HeartHandshake","body":"Nadie nace sabiendo dialogar: se aprende practicando en la casa, la escuela y la comunidad.","reveal":[{"icon":"Ear","front":"Escucha activa","back":"Mirar a quien habla, no interrumpir y repetir lo que entendiste: \\"Entonces tú dices que…\\"."},{"icon":"Heart","front":"Empatía","back":"**Ponerte en el lugar del otro**: ¿cómo me sentiría yo si me pasara eso?"},{"icon":"MessageCircle","front":"Mensaje \\"yo\\"","back":"Expresar lo que sientes sin atacar: \\"**Yo me siento** triste **cuando** no me dejan jugar **porque** también quiero participar\\". En vez de: \\"¡Ustedes son unos egoístas!\\"."},{"icon":"Handshake","front":"Ganar-ganar","back":"Buscar soluciones en las que **todas las partes** obtengan algo, no una que gana y otra que pierde."}]},"id":"s08-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"Tu hermano usó tu cuaderno sin permiso y lo manchó. ¿Cuál es un buen **mensaje \\"yo\\"**?","hint":"Un mensaje \\"yo\\" habla de lo que **tú sientes**, cuándo y por qué, sin insultar.","explain":"El mensaje \\"yo\\" dice cómo te sientes y por qué, sin atacar a la otra persona. Así es más fácil que te escuche y que lleguen a un acuerdo.","type":"choice","props":{"options":[{"id":"a","text":"\\"Me siento molesto cuando usas mis cosas sin pedirlas, porque las cuido mucho\\""},{"id":"b","text":"\\"¡Eres un desordenado y siempre arruinas todo!\\"","feedback":"Es un mensaje \\"tú\\" que ataca. Tu hermano se defenderá en vez de escucharte."},{"id":"c","text":"No decir nada y esconder todos mis cuadernos","feedback":"Callar guarda el enojo y el problema se repite. Es mejor expresarlo con respeto."}],"correct":["a"]},"id":"s08-ccss-3-5"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"emprender","title":"Del conflicto al acuerdo organizativo","prompt":"Una contribución organizativa puede practicarse con diálogo en un caso de la lección, sin intervenir fuera del aula.","type":"explain","props":{"icon":"HandHeart","body":"**Caso simulado; no describe tu escuela.** Dos grupos necesitan compartir la cancha y preparar un rótulo de ahorro de energía. Primero escuchan sus necesidades; luego acuerdan turnos y responsabilidades en papel.","reveal":[{"icon":"Users","front":"Dialogar y acordar","back":"Definir el conflicto, escuchar a ambos grupos, comparar alternativas y repartir tareas aceptadas."},{"icon":"ShieldCheck","front":"Ser honesto","back":"Registrar “simulación de aula” y no afirmar que el acuerdo ya se aplicó fuera de la lección."}]},"id":"s08-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"emprender","prompt":"**Caso de la lección: simulación de aula.** Organiza en papel la contribución del grupo para resolver el uso simultáneo de la cancha y preparar un rótulo de ahorro. No observes un problema local, no consultes personas ni realices un servicio externo.","type":"project","props":{"goal":"Completar una contribución organizativa simulada mediante diálogo y reparto justo de tareas.","steps":[{"title":"Define","detail":"Escribe el problema y las necesidades de ambos grupos dadas en la tarjeta."},{"title":"Acuerda","detail":"Elige turnos justos y asigna quién redacta, quién revisa y quién coloca el rótulo solo dentro del escenario."},{"title":"Registra","detail":"Marca el producto como propuesta simulada y anota un criterio para revisarlo en clase."}],"evidence":"Hoja revisable con problema de la lección, acuerdo, responsabilidades y rótulo de simulación.","rubric":["Usé solo el caso de la lección","Distribuí responsabilidades con justicia","No afirmé un servicio externo realizado"]},"id":"s08-ccss-3-7"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"En la simulación, dos personas rechazan la tarea asignada. ¿Qué decisión organizativa tomas?","type":"dilemma","props":{"scene":{"icon":"Users","text":"Una persona no puede dibujar el rótulo y otra prefiere no exponer oralmente. El acuerdo debe ofrecer tareas accesibles."},"options":[{"id":"a","icon":"MessagesSquare","text":"Escuchar y reasignar revisión, escritura o lectura según posibilidades","consequence":"El acuerdo conserva el objetivo y permite una contribución accesible.","values":["diálogo","empatía","cooperación"],"constructive":true},{"id":"b","icon":"Megaphone","text":"Obligar a mantener las tareas iniciales","consequence":"La organización ignora necesidades y debilita el acuerdo.","values":[],"constructive":false}]},"id":"s08-ccss-3-8"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:8.2.1"],"ambito":"convivir","prompt":"Completa de manera independiente la contribución organizativa del caso simulado: ordena las decisiones del acuerdo.","explain":"Definir el problema, escuchar, acordar responsabilidades accesibles y registrar que es una simulación produce evidencia realizable en clase.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"a1","text":"Definir el problema de la lección sin culpar","icon":"Search"},{"id":"a2","text":"Escuchar las necesidades de las partes del caso","icon":"Ear"},{"id":"a3","text":"Acordar turnos y responsabilidades accesibles","icon":"Handshake"},{"id":"a4","text":"Registrar “contribución organizativa simulada”","icon":"FileText"}]},"id":"s08-ccss-3-9"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.2.1"],"prompt":"Ordena los pasos para resolver un problema con diálogo.","type":"order","props":{"items":[{"id":"p1","text":"Identificar el problema"},{"id":"p2","text":"Escuchar a todas las partes"},{"id":"p3","text":"Proponer alternativas"},{"id":"p4","text":"Elegir juntos una solución"},{"id":"p5","text":"Cumplir el acuerdo"},{"id":"p6","text":"Evaluar el resultado"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-ccss-3-10"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:8.2.1"],"prompt":"Caso simulado: dos equipos necesitan la misma mesa para terminar sus paneles y surge un conflicto. ¿Qué acción aplica el procedimiento de diálogo para llegar a un acuerdo?","type":"choice","props":{"options":[{"id":"a","text":"Escuchar qué necesita cada equipo, proponer dos turnos y acordar responsabilidades"},{"id":"b","text":"Dar la mesa al equipo que hable más fuerte sin escuchar al otro"},{"id":"c","text":"Cancelar ambos paneles sin identificar el problema"}],"correct":["a"]},"id":"s08-ccss-3-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ccss"],"cnb":[],"type":"reflection","props":{"statements":["Leo datos para identificar problemas mundiales","Explico por qué pagar impuestos y pedir factura es una responsabilidad ciudadana","Resuelvo problemas con diálogo y sé organizar una actividad de servicio"],"commitments":["Registraré con honestidad cuándo una contribución es simulada","Usaré un mensaje \\"yo\\" la próxima vez que dialogue","Pediré factura cuando acompañe a mi familia a comprar"]},"id":"s08-ccss-3-12"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s08","version":"cnb-sexto-f727a076da2778a8","lesson":{"id":"s08-l3-2","title":"Helen Keller: a life of courage","icon":"HandHeart","minutes":15,"gancho":"Imagina que no puedes ver ni oír. ¿Cómo relacionarías una palabra con lo que tocas? Helen Keller logró esa comprensión con la mano.","objetivos":["Leer y comprender la biografía de Helen Keller"],"resumen":["Helen Keller nació en 1880 en Alabama, Estados Unidos. Cuando era bebé, una enfermedad la dejó sin poder ver ni oír.","Su maestra, Anne Sullivan, le enseñó a comunicarse deletreando letras en la palma. El momento de “water” fue un avance conceptual: comprendió que las palabras nombran las cosas.","En 1904 se graduó de la universidad (Radcliffe College). Escribió libros y viajó por el mundo apoyando a personas con discapacidad. Murió en 1968.","El inglés se habla en muchos países: Estados Unidos, Reino Unido, Canadá, Australia, Irlanda… y en Belice, nuestro vecino."],"media":{"id":"s08-l3-2-water","kind":"image","title":"Water!","aspect":"4:3","alt":"Ilustración de una niña de unos 6 años con la mano bajo el chorro de una bomba de agua; su maestra le escribe letras en la otra mano.","brief":"Ilustración cálida estilo libro infantil, época de 1880 (vestidos largos, jardín con una bomba de agua manual). Una niña de unos 6 años con los ojos cerrados y una expresión de descubrimiento pone una mano bajo el chorro de agua; una maestra joven, arrodillada a su lado, le forma letras con los dedos en la palma de la otra mano. Letras W-A-T-E-R flotando suavemente sobre la escena. Ilustración original, no basada en fotografías reales. Target: public/media/s08-l3-2-water.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"A life in chronological order","prompt":"Read the supplied chronology before answering.","type":"explain","props":{"icon":"CalendarDays","body":"Use the supplied fact card to locate birth, learning, achievements and death before answering about a biography."},"id":"s08-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","prompt":"Mira la imagen de la lección. La maestra forma letras en la mano de la niña mientras el agua cae en su otra mano. ¿Qué crees que le está enseñando?","explain":"Le enseña que las letras **W-A-T-E-R** forman el nombre de lo que siente en la mano: **water** (agua). Esa niña era Helen Keller, y hoy leerás su biografía.","type":"choice","props":{"options":[{"id":"a","text":"Que las letras que siente forman la palabra \\"agua\\"","icon":"Droplets"},{"id":"b","text":"A lavarse las manos","icon":"Hand","feedback":"Es una buena idea, pero fíjate en las letras que forma la maestra en su mano."},{"id":"c","text":"A dibujar","icon":"Pencil","feedback":"No hay lápiz ni papel: la maestra usa la mano de la niña para formar letras."}],"correct":["a"]},"id":"s08-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"English around the world","prompt":"Neil Armstrong y Helen Keller nacieron en los Estados Unidos. Pero el inglés se habla en muchos lugares. Toca cada tarjeta.","type":"explain","props":{"icon":"Globe","body":"Aprender inglés te permite leer las historias de personas de muchas culturas… ¡y contar las nuestras!","reveal":[{"icon":"Globe","front":"Países donde es idioma principal","back":"Estados Unidos, Reino Unido, Canadá (junto con el francés), Australia, Irlanda y Nueva Zelanda, entre otros."},{"icon":"MapPin","front":"Muy cerca de Guatemala","back":"En **Belice**, nuestro país vecino, el idioma oficial es el **inglés**, y también se hablan español, kriol, garífuna y idiomas mayas."},{"icon":"Users","front":"Muchas culturas","back":"Cada país tiene sus propios personajes famosos: científicos, escritoras, deportistas, artistas. Sus biografías cuentan cómo vivían y qué lograron."}]},"id":"s08-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"conocer","title":"Key words","prompt":"Estas palabras te ayudarán a leer la biografía. Léelas en voz alta y voltea cada tarjeta.","type":"flashcards","props":{"cards":[{"icon":"EyeOff","front":"blind","back":"ciega/o: que no puede ver"},{"icon":"VolumeX","front":"deaf","back":"sorda/o: que no puede oír"},{"icon":"Pill","front":"illness","back":"enfermedad"},{"icon":"Hand","front":"palm","back":"palma de la mano"},{"icon":"PenLine","front":"to spell","back":"deletrear, formar una palabra letra por letra"},{"icon":"GraduationCap","front":"to graduate","back":"graduarse"},{"icon":"HandHeart","front":"disability","back":"discapacidad"}]},"id":"s08-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","title":"Biography","prompt":"Escucha y lee la biografía. Usa las tarjetas si olvidas una palabra.","media":{"id":"s08-l3-2-keller","kind":"audio","title":"Helen Keller (biography)","duration":55,"alt":"Una voz en inglés lee la biografía de Helen Keller.","brief":"Audio de 55 s. Voz adulta femenina, inglés claro y lento, tono cálido, sin música. Leer los años como en inglés (eighteen eighty, eighteen eighty-seven, nineteen oh-four, nineteen sixty-eight). Texto exacto: \\"Helen Keller was born in 1880 in Alabama, in the United States. When she was a baby, an illness left her blind and deaf. She could not see or hear. In 1887, a teacher named Anne Sullivan came to live with her family. Anne spelled words into Helen's palm. One day, Anne put Helen's hand under running water and spelled W-A-T-E-R. Helen understood: everything has a name! Helen studied very hard. In 1904, she graduated from college. She wrote books and traveled around the world to help people with disabilities. She died in 1968. Her life shows that courage and good teachers can change the world.\\" Target: public/media/s08-l3-2-keller.mp3. Accesibilidad: transcripción completa disponible después de responder y control para repetir la pista."},"type":"reading","props":{"genre":"Biography","heading":"Helen Keller","passage":"Helen Keller was born in 1880 in Alabama, in the United States. When she was a baby, an illness left her blind and deaf. She could not see or hear.\\n\\nIn 1887, a teacher named Anne Sullivan came to live with her family. Anne spelled words into Helen's palm. One day, Anne put Helen's hand under running water and spelled W-A-T-E-R. Helen understood: everything has a name!\\n\\nHelen studied very hard. In 1904, she graduated from college. She wrote books and traveled around the world to help people with disabilities. She died in 1968.\\n\\nHer life shows that courage and good teachers can change the world.","questions":[{"q":"Where was Helen Keller born?","options":[{"id":"a","text":"In Alabama, in the United States"},{"id":"b","text":"In Ohio"},{"id":"c","text":"In England"}],"correct":"a"},{"q":"Who was Anne Sullivan?","options":[{"id":"a","text":"Helen's teacher"},{"id":"b","text":"Helen's sister"},{"id":"c","text":"A doctor"}],"correct":"a"},{"q":"¿Qué descubrió Helen el día del agua?","options":[{"id":"a","text":"Que cada cosa tiene un nombre, y que las letras en su mano lo formaban"},{"id":"b","text":"Que ya podía ver"},{"id":"c","text":"Que no le gustaba el agua"}],"correct":"a","why":"\\"Helen understood: everything has a name!\\" Descubrió que las palabras nombran las cosas."},{"q":"¿Qué enseñanza deja su vida, según el texto?","options":[{"id":"a","text":"Con valentía y buenos maestros se pueden lograr grandes cosas"},{"id":"b","text":"Las personas con discapacidad no pueden estudiar"},{"id":"c","text":"Es mejor no ir a la universidad"}],"correct":"a","why":"La última oración lo dice: \\"courage and good teachers can change the world\\". Helen estudió, se graduó y ayudó a otros."}]},"id":"s08-l3-2-5"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ordena la línea de tiempo de Helen Keller.","hint":"Mira los años del texto: 1880, 1887, 1904, 1968. El día del agua pasó después de que llegó Anne.","explain":"Nació (1880) → enfermedad cuando era bebé → llegó Anne Sullivan (1887) → aprendió \\"water\\" → se graduó (1904) → murió (1968).","type":"order","props":{"labels":{"start":"First","end":"Last"},"items":[{"id":"o1","text":"Helen was born in Alabama.","icon":"Baby"},{"id":"o2","text":"An illness left her blind and deaf.","icon":"EyeOff"},{"id":"o3","text":"Anne Sullivan came to live with her family.","icon":"User"},{"id":"o4","text":"Helen learned the word \\"water\\".","icon":"Droplets"},{"id":"o5","text":"She graduated from college.","icon":"GraduationCap"},{"id":"o6","text":"She died in 1968.","icon":"Flower"}]},"id":"s08-l3-2-6"},{"fase":"construir","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","title":"Worked example: a mini-biography","prompt":"Con las frases de las biografías puedes escribir la historia de alguien que admiras. Mira cómo lo hace Isabel sobre su abuela.","type":"worked-example","props":{"icon":"PenLine","problem":"Isabel quiere escribir una mini-biografía de su abuela Juana, que nació en Totonicapán en 1958, fue maestra y es famosa en su aldea por enseñar a leer a muchos adultos.","steps":[{"text":"Nacimiento: **My grandmother Juana was born in Totonicapán in 1958.**","why":"Was born in + lugar + año."},{"text":"Lo que llegó a ser: **She became a teacher.**"},{"text":"Por qué es admirada: **She is famous in our village for teaching many adults to read.**"},{"text":"Cierre con tu opinión: **I admire her because she is kind and brave.**","why":"Admire = admirar. Because = porque."}],"answer":"**My grandmother Juana was born in Totonicapán in 1958. She became a teacher. She is famous in our village for teaching many adults to read. I admire her because she is kind and brave.**","tip":"Nacimiento → qué llegó a ser → por qué es importante → por qué la admiras."},"id":"s08-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"According to the biography, true or false?","type":"true-false","props":{"statements":[{"text":"Helen Keller was blind and deaf.","answer":true},{"text":"Anne Sullivan spelled words into Helen's palm.","answer":true},{"text":"Helen never went to college.","answer":false,"why":"\\"In 1904, she graduated from college.\\""},{"text":"Helen helped people with disabilities.","answer":true}]},"id":"s08-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:5.2.2"],"ambito":"hacer","prompt":"Usa esta **fact card ficticia de la lección**: Elena Cruz, persona ficticia · born in Quetzaltenango, 1986 · became an electrical engineer, 2010 · designed school solar projects · received a teaching award, 2022. Escribe una mini-biografía en inglés de 3 oraciones. No agregues fechas que no aparecen.","type":"short-answer","props":{"minWords":20,"placeholder":"Elena Cruz, persona ficticia, was born... She became...","model":"Elena Cruz, persona ficticia, was born in Quetzaltenango in 1986. She became an electrical engineer in 2010 and designed school solar projects. She received a teaching award in 2022.","rubric":["Uso solo los hechos de la lección","Escribo tres oraciones en orden","Uso was born y became correctamente"]},"id":"s08-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:5.2.2"],"prompt":"Boleto de salida: ¿quién le enseñó a Helen Keller a comunicarse?","type":"choice","props":{"options":[{"id":"a","text":"Anne Sullivan, su maestra"},{"id":"b","text":"Neil Armstrong"},{"id":"c","text":"Su hermano"}],"correct":["a"]},"id":"s08-l3-2-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:5.2.2"],"prompt":"Completa en inglés: \\"Helen Keller nació en 1880. Se graduó de la universidad en 1904.\\"","type":"fill-blank","props":{"text":"Helen Keller [[was born]] in 1880. She [[graduated]] from college in 1904.","distractors":["died","became"]},"id":"s08-l3-2-11"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"We finished the unit! ¿Cómo te fue?","type":"reflection","props":{"statements":["Leo y comprendo una biografía sencilla en inglés","Leo años en inglés","Escribo una mini-biografía con was born, became y is famous for","En esta unidad aprendí a ubicar cosas, comprar, contar lo que viví, seguir instrucciones y describir el pasado en inglés"],"commitments":["Leeré la biografía de otra persona famosa de un país donde se habla inglés","Compartiré con mi familia la mini-biografía que escribí","Seguiré practicando inglés un poco cada día"]},"id":"s08-l3-2-12"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s08","version":"cnb-sexto-588c6e48b229f26c","lesson":{"id":"s08-art-2","title":"Publicar lo investigado: periódico mural y foro","icon":"Newspaper","minutes":15,"gancho":"Ya investigaste la vida de un artista. Si esa información se queda en tu cuaderno, solo tú la conoces. ¿Cómo la compartirías con toda la escuela y la comunidad?","objetivos":["Publicar y compartir una ficha biográfica breve, verificable y legible"],"resumen":["Publicar es dar a conocer una investigación. Formas escolares: ficha biográfica, periódico mural, foro o presentación oral.","Una ficha biográfica tiene: nombre, imagen o dibujo, origen, formación, obras, aporte, un dato curioso y fuentes.","Un periódico mural tiene un título grande, secciones ordenadas, textos breves, imágenes con pie de foto y las fuentes de cada texto. Se aplican las reglas del cartel: contraste, letras legibles y espacio libre.","En un foro, cada persona presenta en poco tiempo, habla claro, escucha sin interrumpir y responde preguntas con respeto. Se publica solo lo que la persona entrevistada autorizó."],"media":{"id":"s08-art-2-periodico","kind":"image","title":"Un periódico mural de artistas","aspect":"4:3","alt":"Un periódico mural en el corredor de una escuela con el título \\"Artistas de nuestra tierra\\", cuatro fichas biográficas con dibujos, pies de foto y una franja de fuentes abajo.","brief":"Ilustración de un periódico mural escolar sobre un tablero de corcho en un corredor de escuela pública guatemalteca. Título grande \\"Artistas de nuestra tierra\\" con letras recortadas. Cuatro fichas con dibujos (no fotos reales): un marimbista de pueblo, una tejedora, un poeta, un compositor del siglo XIX. Cada ficha con subtítulos (Origen, Obras, Aporte), un pie de foto y un recuadro \\"Fuentes\\". Una sección \\"¿Sabías que…?\\" y un buzón de preguntas. Colores con buen contraste, orden en columnas, espacio libre entre fichas. Target: public/media/s08-art-2-periodico.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","title":"Publicar una biografía artística","prompt":"Lee el propósito de una ficha biográfica.","type":"explain","props":{"icon":"Newspaper","body":"Una ficha biográfica publica vida, obra, aporte e imagen con pie, y mantiene visibles las fuentes."},"id":"s08-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","prompt":"Observa el periódico mural. ¿Qué elemento permite a los lectores **comprobar** que la información es cierta?","explain":"La franja de **fuentes**. Publicar con fuentes demuestra un trabajo serio y respetuoso.","type":"choice","props":{"options":[{"id":"a","text":"El título grande","icon":"Type","feedback":"El título atrae la atención, pero no permite comprobar los datos."},{"id":"b","text":"Los dibujos de colores","icon":"Palette","feedback":"Los dibujos ilustran, pero no dicen de dónde salió la información."},{"id":"c","text":"Las fuentes al pie de cada ficha","icon":"BookOpen"}],"correct":["c"]},"id":"s08-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","title":"Tres formas de publicar","prompt":"**Publicar** es dar a conocer tu investigación a otras personas. En la escuela puedes hacerlo de tres formas. Toca cada tarjeta.","type":"explain","props":{"icon":"Megaphone","body":"Elige la forma según tu público y tu espacio. Pueden combinarse.","reveal":[{"icon":"FileText","front":"Ficha biográfica","back":"Una hoja con **nombre, imagen, origen, formación, obras, aporte, dato curioso y fuentes**. Es la base de las otras dos."},{"icon":"Newspaper","front":"Periódico mural","back":"Varias fichas y textos organizados en un tablero o pared, con **título**, **secciones** e **imágenes con pie de foto**."},{"icon":"MessagesSquare","front":"Foro","back":"Una reunión donde cada persona **presenta** brevemente su investigación y el público **pregunta** y comenta con respeto."}]},"id":"s08-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"hacer","title":"Cómo armar el periódico mural","prompt":"Un periódico mural es también una **obra gráfica**: usa lo que aprendiste sobre carteles. Toca cada paso.","type":"explain","props":{"icon":"Newspaper","body":"Recuerda las reglas del cartel: **contraste**, **letras legibles** y **espacio libre**.","reveal":[{"icon":"Type","front":"1. Título","back":"Grande, arriba y legible de lejos: \\"Artistas de nuestra tierra\\"."},{"icon":"LayoutGrid","front":"2. Secciones","back":"Organiza en columnas: artistas de la **comunidad**, del **país** y del **mundo**. Deja espacio entre fichas."},{"icon":"Image","front":"3. Imágenes","back":"Dibujos o fotos **con permiso**, cada una con un **pie de foto**: quién es y qué hace."},{"icon":"BookOpen","front":"4. Fuentes","back":"Debajo de cada ficha, la lista de fuentes. Así cualquier persona puede comprobar."},{"icon":"MessageCircle","front":"5. Participación","back":"Agrega un buzón o una hoja de \\"Preguntas y comentarios\\" para que el público participe."}]},"id":"s08-art-2-4"},{"fase":"construir","areas":["art","l1"],"cnb":["art:4.3.2"],"ambito":"hacer","title":"Ejemplo resuelto: de las notas a la ficha publicada","prompt":"Mira cómo Pedro transforma las notas de su entrevista en una ficha para el periódico mural. (La artista es un ejemplo inventado.)","type":"worked-example","props":{"icon":"NotebookPen","problem":"Supongamos que Pedro entrevistó a **doña Tomasa**, marimbista de su aldea, de 68 años. Sus notas están desordenadas y muy largas. ¿Cómo las convierte en una ficha?","steps":[{"text":"**Pide permiso** otra vez: \\"¿Puedo publicar su nombre, su edad y un dibujo suyo en la escuela?\\". Doña Tomasa acepta, pero pide que no se ponga su dirección.","why":"Se publica solo lo que la persona autoriza."},{"text":"**Selecciona** lo más importante: aprendió marimba a los 10 años con su padre; toca en las fiestas patronales desde hace 50 años; enseña gratis a niñas y niños los sábados."},{"text":"**Redacta** en oraciones cortas bajo cada subtítulo: Origen, Formación, Obras, Aporte, ¿Sabías que…?"},{"text":"**Ilustra** con un dibujo de doña Tomasa tocando, con pie de foto: \\"Doña Tomasa en la fiesta patronal\\"."},{"text":"**Cierra** con la fuente: \\"Entrevista a doña Tomasa, marimbista, 12 de marzo\\"."}],"answer":"Una ficha **breve, ordenada, ilustrada, con fuente y con permiso** de la persona.","tip":"Pide a alguien que lea tu ficha antes de publicarla: si entiende todo en un minuto, está lista."},"id":"s08-art-2-5"},{"fase":"construir","areas":["art"],"cnb":["art:4.3.2"],"ambito":"hacer","prompt":"Ordena los pasos para **publicar** una investigación biográfica.","hint":"Primero se investiga, luego se organiza, después se comparte.","explain":"Investigar con permiso → seleccionar y redactar → ilustrar y citar fuentes → montar el periódico mural → presentar en el foro.","type":"order","props":{"items":[{"id":"a","text":"Investigar con preguntas guía y pedir permiso"},{"id":"b","text":"Seleccionar lo más importante y redactar la ficha"},{"id":"c","text":"Ilustrar y agregar las fuentes"},{"id":"d","text":"Montar el periódico mural"},{"id":"e","text":"Presentar en el foro y responder preguntas"}],"labels":{"start":"Primero","end":"Al final"}},"id":"s08-art-2-6"},{"fase":"aplicar","areas":["art","fc"],"cnb":[],"ambito":"convivir","prompt":"Antes del foro biográfico, elige cómo escucharás una obra o trayectoria distinta de tus gustos sin calificar esta reflexión.","type":"reflection","props":{"statements":["Escucharé la presentación completa antes de opinar","Comentaré con respeto y razones"],"commitments":["Cuidaré que el foro no convierta una preferencia en burla"]},"id":"s08-art-2-7"},{"fase":"aplicar","areas":["art","l1"],"cnb":["art:4.3.2"],"ambito":"hacer","prompt":"Publica una **ficha biográfica con obra y fuente visible**, y guárdala para compartirla como evidencia docente. Usa solo el paquete de la lección: Humberto Ak’abal · nació en Momostenango en 1952 · poeta k’iche’ · escribió en k’iche’ y español · murió en 2019. No afirmes una exposición externa.","type":"short-answer","props":{"minWords":24,"placeholder":"Humberto Ak’abal… Obra… Aporte… Fuente: paquete de la lección…","model":"Humberto Ak’abal nació en Momostenango en 1952. Fue poeta k’iche’ y escribió en k’iche’ y español. Su obra difundió esa poesía. Fuente: paquete biográfico de la lección.","rubric":["Publico origen, obra y aporte","Uso solo el paquete de la lección","Dejo visible la fuente"]},"id":"s08-art-2-8"},{"fase":"aplicar","areas":["art"],"cnb":["art:4.3.2"],"ambito":"conocer","prompt":"¿Qué jerarquía visual ayuda a leer la ficha biográfica sin convertir la decoración en evidencia?","explain":"El nombre funciona como título; los hitos y la obra se agrupan en bloques breves; la fuente queda visible. La decoración no reemplaza los datos.","type":"choice","props":{"options":[{"id":"a","text":"Nombre destacado, hitos ordenados, imagen con pie y fuente visible"},{"id":"b","text":"Un título decorativo enorme y todos los datos en letra mínima","feedback":"La información queda subordinada a la decoración y no puede leerse."},{"id":"c","text":"Una imagen sin pie y hechos sin fuente","feedback":"La ficha pierde contexto y verificabilidad."}],"correct":["a"]},"id":"s08-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:4.3.2"],"prompt":"Publica y guarda una ficha biográfica con obra y fuente: ordena el procedimiento para una artista ficticia con datos verificados.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"e1","text":"Seleccionar un hecho respaldado por el paquete"},{"id":"e2","text":"Redactar origen, obra y aporte con claridad"},{"id":"e3","text":"Agregar la fuente visible"},{"id":"e4","text":"Guardar la ficha para compartirla como evidencia docente"}]},"id":"s08-art-2-10"},{"fase":"comprobar","areas":["art"],"cnb":["art:4.3.2"],"prompt":"Al publicar y compartir otra ficha biográfica con obra y fuente visible, ¿qué decisión evita convertir decoración en evidencia?","type":"choice","props":{"options":[{"id":"a","text":"Guardar origen, obra, aporte y fuente en campos legibles"},{"id":"b","text":"Compartir solo un dibujo sin datos"},{"id":"c","text":"Ocultar la fuente para ganar espacio"}],"correct":["a"]},"id":"s08-art-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["art"],"cnb":["art:4.3.2"],"type":"reflection","props":{"statements":["Investigo la vida de un artista con preguntas guía y fuentes confiables","Publico una ficha biográfica clara y con fuentes","Presento y escucho con respeto en un foro"],"commitments":["Publicaré mi ficha en el periódico mural","Agradeceré a la persona que entrevisté","Seguiré descubriendo artistas de mi comunidad"]},"id":"s08-art-2-12"}],"kind":"materia","area":"art","day":4}},{"missionId":"s08","version":"cnb-sexto-df1a7bec973c1d6f","lesson":{"id":"s08-l1-5","title":"Revisar un fragmento con precisión","icon":"ClipboardCheck","minutes":15,"gancho":"Una sola frase exagerada puede volver poco confiable un informe. ¿Qué cambiarías primero?","objetivos":["Revisar un fragmento breve para que conserve la fuente, el dato y una redacción clara"],"resumen":["En una revisión breve se compara el borrador con la fuente de la lección.","Primero se corrige el sentido: fuente visible, dato fiel y ninguna conclusión exagerada.","Después se corrige una forma concreta: concordancia, tilde, mayúscula o puntuación.","La tarea termina con el fragmento corregido; no exige rehacer un informe completo."],"media":{"id":"s08-l1-5-revision","kind":"animation","title":"Una revisión acotada","aspect":"16:9","duration":35,"alt":"Un fragmento breve se compara con una ficha de energía; una lupa marca una fuente ausente, un dato exagerado y un error de concordancia antes de mostrar dos oraciones corregidas.","brief":"Animación 2D de 35 s. A la izquierda aparece la Ficha B suministrada con “LED: 9 W”, “incandescente: 60 W” y “caso escolar simulado”. A la derecha, un borrador de dos oraciones. Una lupa marca solo tres problemas: falta atribución, aparece la exageración “elimina todo el consumo” y falta concordancia. El fragmento corregido conserva dos oraciones; no se agregan título, diagrama ni recopia. Narración en español. Target: public/media/s08-l1-5-revisión.mp4. Accesibilidad: subtítulos completos, transcripción y pausas para leer ambos textos."},"steps":[{"fase":"explorar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Paquete de la lección para revisar","prompt":"Lee la fuente y el borrador antes de cambiar una palabra.","type":"explain","props":{"icon":"FileSearch","body":"**Ficha B, paquete de la lección:** en condiciones comparables, una lámpara LED usa 9 W y una incandescente 60 W. Apagar luces en espacios vacíos evita uso innecesario. **Caso escolar simulado; no describe tu escuela.**\\n\\n**Borrador:** “Las lámparas LED usa 9 W y elimina todo el consumo”."},"id":"s08-l1-5-1"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"conocer","title":"Tres comprobaciones","prompt":"Observa la animación y abre las tarjetas.","type":"explain","props":{"icon":"ClipboardCheck","body":"Una revisión acotada corrige el contenido necesario y una forma lingüística, sin convertir la actividad en un informe nuevo.","reveal":[{"icon":"Quote","front":"1. Fuente","back":"Nombra la ficha: “Según la Ficha B…”. Así el lector sabe de dónde procede el dato."},{"icon":"Gauge","front":"2. Fidelidad","back":"Conserva 9 W y las condiciones comparables. Quita “elimina todo el consumo”, porque la fuente no lo afirma."},{"icon":"SpellCheck","front":"3. Claridad","back":"Corrige una forma concreta: “una lámpara LED **usa**” o “las lámparas LED **usan**”."}]},"id":"s08-l1-5-2"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","title":"Modelo: corregir solo lo necesario","prompt":"Compara el borrador inicial con la Ficha B de la lección.","type":"worked-example","props":{"icon":"Eraser","problem":"Borrador: “Las lámparas LED usa 9 W y elimina todo el consumo”.","steps":[{"text":"Agrego la atribución: **Según la Ficha B**."},{"text":"Mantengo el dato y su condición: **una lámpara LED usa 9 W en la comparación de la lección**."},{"text":"Quito “elimina todo el consumo”: excede la fuente."}],"answer":"“Según la Ficha B, una lámpara LED usa 9 W en la comparación de la lección”.","tip":"Fuente, fidelidad y claridad: tres comprobaciones sobre un fragmento breve."},"id":"s08-l1-5-3"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"En el borrador de la Ficha B, toca las partes que deben revisarse.","hint":"Busca la fuente ausente, la concordancia y una afirmación que la ficha no respalda.","explain":"Se agrega “Según la Ficha B”, se cambia “usa” por “usan” si el sujeto permanece plural y se elimina la afirmación absoluta.","type":"highlight","props":{"target":"partes por revisar","text":"{Las lámparas LED} {usa} 9 W y {elimina todo el consumo}."},"id":"s08-l1-5-4"},{"fase":"construir","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"La Ficha A dice: “Caso escolar simulado: 12,468 kWh; aproximado a millares: 12,000 kWh”. ¿Cuál revisión es fiel?","hint":"La revisión debe nombrar la fuente, conservar la unidad y no convertir el caso en un dato real.","explain":"La opción correcta atribuye ambos valores y mantiene el rótulo de caso simulado.","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha A, el caso escolar simulado registra 12,468 kWh, aproximadamente 12,000 kWh."},{"id":"b","text":"Nuestra escuela gastó exactamente 12,000 kWh.","feedback":"Convierte el caso en un dato real y presenta un valor redondeado como exacto."},{"id":"c","text":"La electricidad bajó mucho.","feedback":"No conserva el dato, la unidad ni la fuente."}],"correct":["a"]},"id":"s08-l1-5-5"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Revisa por tu cuenta este borrador: “El dato de 60 W demuestra cuánto dinero ahorró la escuela”. La Ficha B solo compara potencia y no informa ahorro monetario.","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha B, una lámpara usa 60 W en la comparación; la ficha no informa ahorro monetario."},{"id":"b","text":"La escuela ahorró mucho dinero con 60 W."},{"id":"c","text":"La electricidad ya no cuesta nada."}],"correct":["a"]},"id":"s08-l1-5-6"},{"fase":"aplicar","areas":["l1"],"cnb":["l1:8.2.7"],"ambito":"hacer","prompt":"Haz una revisión breve del borrador: “las luces vacías gasta energía y apagarlas garantiza un ahorro de Q500”. Usa solo la Ficha B de la lección: apagar luces en espacios vacíos evita uso innecesario; no informa dinero ahorrado.","type":"short-answer","props":{"minWords":18,"placeholder":"Según la Ficha B, … La ficha no informa …","model":"Según la Ficha B, las luces encendidas en espacios vacíos usan energía innecesariamente y conviene apagarlas. La ficha no informa cuánto dinero se ahorraría.","rubric":["Nombré la Ficha B","Conservé la recomendación de la lección","Quité la cantidad de dinero no respaldada","Corregí la concordancia del fragmento"]},"id":"s08-l1-5-7"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Revisa este borrador con una fuente nueva. La Ficha C dice: “Dos lámparas comparadas usan 11 W cada una”. ¿Cuál versión conserva fuente, dato y concordancia?","type":"choice","props":{"options":[{"id":"a","text":"Según la Ficha C, las dos lámparas comparadas usan 11 W cada una."},{"id":"b","text":"Las lámparas usa 11 W y son las mejores del país."},{"id":"c","text":"Una fuente dice que no consumen energía."}],"correct":["a"]},"id":"s08-l1-5-8"},{"fase":"comprobar","areas":["l1"],"cnb":["l1:8.2.7"],"prompt":"Revisa el borrador de una fuente distinta. Completa la versión fiel de la Ficha D: “Caso simulado: tres ventiladores usan 45 W cada uno”.","type":"fill-blank","props":{"text":"Según la [[Ficha D]], los tres ventiladores [[usan]] 45 [[W]] cada uno en el caso [[simulado]].","distractors":["usa","reales","Q","Ficha B"]},"id":"s08-l1-5-9"},{"fase":"reflexionar","areas":["l1"],"cnb":[],"ambito":"ser","prompt":"¿Qué comprobación te ayudó más al revisar el fragmento?","type":"reflection","props":{"statements":["Comparé el borrador con la fuente de la lección","Conservé el dato y su unidad","Quité una afirmación que la fuente no respaldaba","Corregí una forma lingüística concreta"],"commitments":["Revisaré primero el sentido y después la forma","Nombraré la fuente de cada dato"]},"id":"s08-l1-5-10"}],"kind":"materia","area":"l1","day":5}},{"missionId":"s08","version":"cnb-sexto-70afe50865c5c00d","lesson":{"id":"s08-cnt-3","title":"Cómo investiga la ciencia","icon":"FlaskConical","minutes":15,"gancho":"Tu abuelo dice que el frijol crece mejor con abono de hojas, y tu vecina dice que no hace diferencia. ¿Cómo podrías averiguar quién tiene razón?","objetivos":["Identificar los tipos de investigación: documental, de campo y de laboratorio"],"resumen":["Investigación documental: se buscan datos en libros, documentos, informes y fuentes confiables. De campo: se observa, mide o entrevista en el lugar donde ocurre el fenómeno. De laboratorio: se hacen experimentos en condiciones controladas.","El conocimiento científico busca mediciones precisas, afirmaciones respaldadas y procedimientos demostrables: al repetirlos se esperan resultados compatibles dentro de un margen explicado, no copias idénticas.","Pasos de una investigación: observar, preguntar, plantear una hipótesis, experimentar o recoger datos, analizar y concluir. La ciencia se corrige cuando aparecen pruebas nuevas."],"media":{"id":"s08-cnt-3-investigar","kind":"image","title":"Tres maneras de investigar","aspect":"16:9","alt":"Tres escenas: una niña consulta libros en la biblioteca municipal; un grupo mide la temperatura del agua de un río con un termómetro; dos niños comparan plantas de frijol en vasos en la mesa del aula.","brief":"Ilustración en tres paneles con estudiantes guatemaltecos de sexto grado (niñas y niños de distintos pueblos): (1) \\"Documental\\": una niña en la biblioteca municipal con libros e informes, tomando notas. (2) \\"De campo\\": un grupo junto a un río con un termómetro, una libreta y una cinta métrica; una niña entrevista a un agricultor. (3) \\"De laboratorio\\": en el aula, vasos con frijoles germinando, etiquetas \\"con luz\\" y \\"sin luz\\", una regla y una tabla de datos. Estilo cálido, colores claros. Target: public/media/s08-cnt-3-investigar.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","title":"Tres tipos de investigación","prompt":"Lee de dónde obtiene evidencia cada tipo de investigación.","type":"explain","props":{"icon":"Search","body":"La investigación puede ser **documental**, **de campo** o **de laboratorio**, según dónde y cómo obtiene evidencia."},"id":"s08-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","title":"Tres tipos de investigación","prompt":"Según **dónde** y **cómo** se busca la información, hay tres tipos de investigación. Observa la imagen de la lección y toca las tarjetas.","type":"explain","props":{"icon":"Search","body":"Muchas investigaciones combinan los tres tipos: primero se lee, luego se observa en el campo y se hacen pruebas.","reveal":[{"icon":"BookOpen","front":"Documental","back":"Se buscan datos en **libros, documentos, informes, mapas** o sitios confiables. Ejemplo: leer los informes del centro de salud sobre enfermedades del municipio."},{"icon":"MapPin","front":"De campo","back":"Se va **al lugar** donde ocurre el fenómeno para **observar, medir o entrevistar**. Ejemplo: medir la temperatura de un río cada día o entrevistar a agricultores."},{"icon":"FlaskConical","front":"De laboratorio","back":"Se hacen **experimentos** en **condiciones controladas**: se cambia una sola cosa y se mide qué pasa. Ejemplo: germinar frijoles con y sin luz."}]},"id":"s08-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","prompt":"Clasifica cada investigación según su tipo.","hint":"¿Se lee (documental), se va al lugar (campo) o se hace un experimento controlado (laboratorio)?","explain":"Documental: libros e informes. De campo: en el lugar real. De laboratorio: experimentos controlados.","type":"sort","props":{"buckets":[{"id":"doc","label":"Documental","icon":"BookOpen","color":"var(--area-l1)"},{"id":"cam","label":"De campo","icon":"MapPin","color":"var(--c-ok)"},{"id":"lab","label":"De laboratorio","icon":"FlaskConical","color":"var(--area-cnt)"}],"items":[{"id":"i1","text":"Revisar informes de lluvia con fuente","bucket":"doc"},{"id":"i2","text":"Medir la temperatura en el lugar del caso","bucket":"cam"},{"id":"i3","text":"Comparar en el aula dos bandejas bajo condiciones controladas","bucket":"lab"}]},"id":"s08-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","title":"Características del conocimiento científico","prompt":"No todo lo que se dice es conocimiento científico. Para serlo, debe cumplir tres características. Toca las tarjetas.","type":"explain","props":{"icon":"BadgeCheck","body":"Un rumor, una opinión o una creencia pueden ser importantes para las personas, pero **no** son conocimiento científico si no cumplen estas características.","reveal":[{"icon":"Ruler","front":"Exacto","back":"Usa **medidas precisas** con unidades: \\"la planta creció **4.5 cm** en 7 días\\", no \\"creció bastante\\"."},{"icon":"ShieldCheck","front":"Verdadero","back":"**Coincide con la realidad** que se observó y se comprobó. Si aparecen pruebas nuevas que lo contradicen, se **corrige**."},{"icon":"RefreshCw","front":"Demostrable","back":"Otras personas pueden **repetir** la investigación con el mismo protocolo y obtener **resultados compatibles** dentro de un margen explicado."}]},"id":"s08-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Une cada situación con la característica del conocimiento científico que muestra.","hint":"¿Hay una medida precisa? ¿Otros lo repitieron? ¿Se comprobó con la realidad?","explain":"Medir con unidades = exacto. Repetir y obtener lo mismo = demostrable. Comprobar con observaciones reales = verdadero.","type":"match","props":{"leftTitle":"Situación","rightTitle":"Característica","pairs":[{"id":"e","left":"Anotar que el agua del río estaba a 18 °C","leftIcon":"Thermometer","right":"Exacto"},{"id":"d","left":"Otro grado repite el protocolo y obtiene resultados compatibles","leftIcon":"RefreshCw","right":"Demostrable"},{"id":"v","left":"Lo que se afirma coincide con lo que se observó y comprobó en la realidad","leftIcon":"ShieldCheck","right":"Verdadero"}]},"id":"s08-cnt-3-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1","cnt:8.2.1"],"ambito":"hacer","title":"Ejemplo: una investigación de principio a fin","prompt":"Mira cómo el grupo de Andrea responde la pregunta del abono con una investigación. Los datos son **hipotéticos**.","media":{"id":"s08-cnt-3-frijoles","kind":"video","title":"El experimento de los frijoles","aspect":"16:9","duration":45,"alt":"Video en el aula: dos grupos de macetas iguales con frijol, unas con abono de hojas y otras sin él; durante tres semanas los estudiantes riegan igual, miden con regla y anotan en una tabla.","brief":"Video de 45 s (o animación en cámara rápida) en un aula guatemalteca: 10 macetas recicladas con frijol, 5 rotuladas \\"con abono de hojas\\" y 5 \\"sin abono\\"; misma luz, misma agua (vaso medidor). Cámara rápida de tres semanas de crecimiento. Estudiantes miden con regla y anotan en una tabla de cartulina. Al final, la tabla con promedios y la frase \\"Otro grado repitió el experimento\\". Narración en español con subtítulos. Materiales seguros: tierra, semillas, agua, regla. Target: public/media/s08-cnt-3-frijoles.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"type":"worked-example","props":{"icon":"FlaskConical","problem":"¿Crece más el frijol con abono de hojas que sin abono?","steps":[{"text":"**Documental e hipótesis**: leen una fuente y plantean que las plantas con abono crecerán más."},{"text":"**Experimento de laboratorio**: 5 macetas con abono y 5 sin abono; **todo lo demás igual** (semillas, luz, agua).","why":"Si cambiaran varias cosas a la vez, no sabrían cuál causó la diferencia."},{"text":"**Datos y conclusión**: miden 18 cm y 12 cm; otro grupo repite el protocolo y obtiene resultados compatibles, por lo que la evidencia es demostrable."}],"answer":"En este experimento, el frijol con abono creció en promedio **6 cm más**. El conocimiento es exacto (medido), verdadero (comprobado) y demostrable (repetido).","tip":"Una buena investigación cambia **una sola cosa** a la vez y mide con cuidado."},"id":"s08-cnt-3-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"hacer","prompt":"Ordena los pasos de una investigación científica.","hint":"Todo empieza con algo que te llama la atención y termina con una conclusión.","explain":"Observar → preguntar → hipótesis → experimentar o recoger datos → analizar → concluir.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"q1","text":"Observar algo que llama la atención","icon":"Eye"},{"id":"q2","text":"Hacer una pregunta","icon":"HelpCircle"},{"id":"q3","text":"Plantear una hipótesis (posible respuesta)","icon":"Lightbulb"},{"id":"q4","text":"Experimentar o recoger datos","icon":"FlaskConical"},{"id":"q5","text":"Analizar los resultados","icon":"BarChart3"},{"id":"q6","text":"Sacar una conclusión y compartirla","icon":"Megaphone"}]},"id":"s08-cnt-3-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Dos estudiantes reportan su experimento. Mario escribe: \\"La planta creció un montón\\". Lucía escribe: \\"La planta creció 4.5 cm en 7 días\\". ¿Qué característica del conocimiento científico cumple mejor el reporte de Lucía?","explain":"Lucía usa una **medida precisa con unidades y tiempo**: su dato es **exacto** y otros pueden compararlo.","type":"choice","props":{"options":[{"id":"a","text":"Exacto","icon":"Ruler"},{"id":"b","text":"Opinable","icon":"MessageCircle","feedback":"\\"Opinable\\" no es una característica del conocimiento científico."},{"id":"c","text":"Secreto","icon":"Lock","feedback":"La ciencia se comparte para que otros la comprueben."}],"correct":["a"]},"id":"s08-cnt-3-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.2.1"],"ambito":"conocer","prompt":"Repaso de la unidad: ¿es **conocimiento científico** o una **opinión o rumor**?","explain":"El conocimiento científico se basa en mediciones y pruebas que otros pueden repetir. Las opiniones y los rumores no se basan en pruebas, y algunos, como que los zancudos transmiten el VIH, la ciencia ya comprobó que son falsos.","type":"sort","props":{"buckets":[{"id":"cie","label":"Conocimiento científico","icon":"BadgeCheck","color":"var(--area-cnt)"},{"id":"opi","label":"Opinión o rumor","icon":"MessageCircle","color":"var(--c-maiz-strong)"}],"items":[{"id":"k1","text":"La mayoría de las células del cuerpo humano tienen 46 cromosomas; los gametos tienen 23","bucket":"cie"},{"id":"k2","text":"\\"Dicen que los zancudos transmiten el VIH\\"","bucket":"opi","feedback":"Es un rumor falso: la ciencia comprobó que los zancudos no transmiten el VIH."},{"id":"k3","text":"La Tierra se formó hace unos 4,500 millones de años, según mediciones de rocas","bucket":"cie"},{"id":"k4","text":"\\"El maíz morado es el más bonito\\"","bucket":"opi"},{"id":"k5","text":"En el experimento, el suelo con grama retuvo más agua que el suelo desnudo","bucket":"cie"}]},"id":"s08-cnt-3-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:8.1.1"],"ambito":"conocer","prompt":"Repaso de la semana 7: el grupo de Ixchel comparó en el aula dos bandejas de tierra, una con grama y otra sin ella, regándolas con la misma cantidad de agua. ¿Qué tipo de investigación hizo?","explain":"Hizo un **experimento controlado**: cambió una sola cosa (la grama) y mantuvo todo lo demás igual. Es una investigación **de laboratorio**.","type":"choice","props":{"options":[{"id":"a","text":"Documental","feedback":"No leyeron documentos: hicieron una prueba."},{"id":"b","text":"De campo","feedback":"No fueron a la montaña: recrearon el fenómeno en el aula, en condiciones controladas."},{"id":"c","text":"De laboratorio"}],"correct":["c"]},"id":"s08-cnt-3-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.1.1","cnt:8.2.1"],"prompt":"Un grupo mide en el río **18 °C** cada día con el mismo protocolo. ¿Qué tipo de investigación hace y qué vuelve exacta su evidencia?","type":"choice","props":{"options":[{"id":"a","text":"Documental; consultar una opinión"},{"id":"b","text":"De campo; registrar medida, unidad y protocolo"},{"id":"c","text":"De laboratorio; votar el resultado"}],"correct":["b"]},"id":"s08-cnt-3-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:8.2.1","cnt:8.1.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Si otras personas repiten un protocolo y obtienen resultados compatibles dentro del margen esperado, la evidencia es demostrable.","answer":true},{"text":"Leer informes y libros en la biblioteca es una investigación de laboratorio.","answer":false,"why":"Es una investigación documental."},{"text":"El conocimiento científico se corrige con pruebas nuevas y un buen experimento controla las variables.","answer":true}]},"id":"s08-cnt-3-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["cnt"],"cnb":[],"type":"reflection","props":{"statements":["Distingo las manifestaciones de la energía y sé cómo ahorrar electricidad","Explico las causas del calentamiento global y cómo ayudan los satélites","Diferencio investigación documental, de campo y de laboratorio","Reconozco un conocimiento exacto, verdadero y demostrable"],"commitments":["Seré \\"guardián de la energía\\" en mi casa","Haré un pequeño experimento y anotaré mis mediciones","Revisaré si lo que escucho es un dato comprobado o un rumor"]},"id":"s08-cnt-3-13"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s08","version":"cnb-sexto-1ef03c488197339b","lesson":{"id":"s08-ef-2","title":"Liderar con igualdad: todas y todos jugamos","icon":"Flag","minutes":15,"gancho":"En el recreo alguien dice: \\"Las niñas no juegan fútbol\\" o \\"Los niños no saltan cuerda\\". ¿Es justo? ¿Qué harías si tú fueras quien organiza el juego?","objetivos":["Dirigir una rutina breve con secuencia segura, igualdad de oportunidades y roles complementarios para mujeres y hombres"],"resumen":["Un buen líder explica las reglas con claridad, escucha, organiza turnos y equipos justos, anima a todos y da el ejemplo con juego limpio. Liderar es servir al grupo, no mandar a gritos.","Niñas y niños tienen los mismos derechos y oportunidades para jugar cualquier juego o deporte y para ser capitanas, capitanes, árbitras o árbitros.","La Declaración Universal de Derechos Humanos dice que todos los seres humanos nacen libres e iguales en dignidad y derechos. La Constitución de Guatemala (artículo 4) establece que el hombre y la mujer tienen iguales oportunidades y responsabilidades.","Complementariedad: cada persona aporta habilidades distintas; un equipo diverso es más fuerte. Equipos justos: contar 1-2, mezclar habilidades y rotar el liderazgo."],"media":{"id":"s08-ef-2-liderazgo","kind":"image","title":"Capitanas y capitanes","aspect":"16:9","alt":"En un patio escolar, una niña capitana explica las reglas a un equipo mixto en círculo; al lado, un niño arbitra un juego de salta cuerda donde saltan niñas y niños juntos.","brief":"Ilustración luminosa de un patio de escuela pública guatemalteca. Escena izquierda: una niña (brazalete de capitana) explica las reglas a un equipo mixto en círculo, todos atentos. Escena derecha: un niño con silbato arbitra salta cuerda; saltan niñas y niños juntos. Al fondo, un cartel \\"Todas y todos jugamos\\". Diversidad de pueblos (maya, garífuna, xinka, mestizo) y una niña en silla de ruedas participando. Sin estereotipos de colores por género. Target: public/media/s08-ef-2-liderazgo.jpg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y liderazgo","prompt":"Lee cómo se organiza una actividad física justa.","type":"explain","props":{"icon":"Users","body":"Niñas y niños, mujeres y hombres tienen iguales oportunidades para jugar y liderar. Rechazar estereotipos, abrir los mismos roles y combinar aportes complementarios protege sus derechos."},"id":"s08-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.1.12"],"ambito":"convivir","prompt":"¿Pueden las niñas jugar fútbol y ser capitanas? ¿Pueden los niños saltar cuerda?","explain":"**Sí, todas y todos.** Mujeres y hombres, niñas y niños tienen los mismos derechos e igualdad de oportunidades para jugar y liderar; los roles no dependen de estereotipos.","type":"choice","props":{"options":[{"id":"a","text":"Sí: cualquier persona puede jugar y liderar cualquier juego","icon":"Users"},{"id":"b","text":"No: cada juego es solo para niñas o solo para niños","icon":"X","feedback":"Esa idea es un estereotipo: limita a las personas y no tiene base."}],"correct":["a"]},"id":"s08-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","title":"¿Qué hace un buen líder en el juego?","prompt":"Liderar no es mandar: es **ayudar al grupo** a jugar mejor. Toca cada tarjeta.","type":"explain","props":{"icon":"Flag","body":"Cualquier persona puede aprender a liderar. Se practica **rotando** el papel de capitán, árbitro u organizador.","reveal":[{"icon":"MessageCircle","front":"Explica con claridad","back":"Cuenta las reglas en pocas palabras, muestra un ejemplo y pregunta: \\"¿Quedó claro?\\"."},{"icon":"Ear","front":"Escucha","back":"Toma en cuenta las ideas del grupo y a quienes hablan menos."},{"icon":"Scale","front":"Organiza con justicia","back":"Forma **equipos parejos**, da **turnos** a todos y cuida que nadie quede fuera."},{"icon":"ThumbsUp","front":"Anima y da el ejemplo","back":"Felicita el esfuerzo, anima a quien se equivoca y juega limpio. El grupo imita lo que ve."}]},"id":"s08-ef-2-3"},{"fase":"construir","areas":["ef","fc"],"cnb":["ef:4.1.12"],"ambito":"convivir","title":"Igualdad y derechos en el juego","prompt":"La igualdad en el juego no es solo \\"buena onda\\": es un **derecho**. Toca cada tarjeta.","type":"explain","props":{"icon":"Scale","body":"Cuando alguien queda fuera de un juego por ser niña, niño, de otro pueblo o por tener una discapacidad, se vulnera su derecho a jugar y a participar.","reveal":[{"icon":"Globe","front":"Derechos humanos","back":"La **Declaración Universal de Derechos Humanos** (artículo 1) dice: todos los seres humanos **nacen libres e iguales en dignidad y derechos**."},{"icon":"Landmark","front":"Constitución de Guatemala","back":"El **artículo 4** dice que en Guatemala todos los seres humanos son libres e iguales en dignidad y derechos, y que **el hombre y la mujer tienen iguales oportunidades y responsabilidades**."},{"icon":"Puzzle","front":"Complementariedad","back":"Cada persona aporta algo distinto: velocidad, puntería, estrategia, ánimo. Un equipo **diverso** se complementa y es más fuerte."},{"icon":"Users","front":"Igualdad de oportunidades","back":"Todas y todos pueden jugar, ser capitanes, arbitrar, elegir juego y recibir el balón. Si alguien necesita una adaptación, se hace."}]},"id":"s08-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","title":"Ejemplo resuelto: formar equipos justos","prompt":"Siempre que eligen equipos, las mismas personas quedan de últimas. Mira cómo lo resuelve Andrea, la capitana de turno.","type":"worked-example","props":{"icon":"Users","problem":"Hay 16 estudiantes (8 niñas y 8 niños) y van a jugar balonmano. Antes, los \\"mejores\\" escogían y siempre quedaban de últimas las mismas niñas y un niño que corre más lento.","steps":[{"text":"Andrea propone **contar 1-2** en la fila: los \\"1\\" forman un equipo y los \\"2\\" el otro.","why":"Nadie \\"escoge\\" a nadie: se evita que alguien se sienta rechazado."},{"text":"Revisa que cada equipo quede **mixto** y con habilidades mezcladas; si no, cambia a dos personas."},{"text":"Acuerda una regla nueva: **antes de lanzar a gol, el balón debe pasar por al menos 3 personas** del equipo.","why":"Así todas y todos tocan el balón, no solo los más rápidos."},{"text":"Nombra **capitanes rotativos**: cada 5 minutos, otra persona es capitana o capitán."}],"answer":"Con **conteo 1-2**, **equipos mixtos**, la regla de **3 pases** y **capitanes rotativos**, el juego es justo y todos participan.","tip":"Un buen líder pregunta al final: \\"¿Todos jugaron? ¿Qué podemos mejorar la próxima vez?\\"."},"id":"s08-ef-2-5"},{"fase":"construir","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"convivir","prompt":"Clasifica cada acción de un capitán o capitana: ¿es **buen liderazgo** o **no**?","hint":"Un buen líder incluye, escucha, organiza con justicia y da el ejemplo.","explain":"Liderar bien abre los mismos roles a mujeres y hombres: niñas y niños aportan habilidades complementarias; excluir por estereotipos no es liderazgo.","type":"sort","props":{"buckets":[{"id":"si","label":"Buen liderazgo","icon":"Flag","color":"var(--c-ok)"},{"id":"no","label":"No es buen liderazgo","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"x1","text":"Explicar las reglas y preguntar si quedaron claras","bucket":"si"},{"id":"x2","text":"Decidir solo, a gritos, sin escuchar a nadie","bucket":"no"},{"id":"x3","text":"Formar equipos mixtos contando 1-2","bucket":"si"},{"id":"x4","text":"Dejar fuera a las niñas \\"porque no saben\\"","bucket":"no"},{"id":"x5","text":"Animar a quien se equivocó","bucket":"si"},{"id":"x6","text":"Pasar el balón siempre a sus mejores amigos","bucket":"no"}]},"id":"s08-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"convivir","prompt":"Dirige una rutina breve sin equipo: explica “cuatro palmas suaves, cuatro gestos al frente y pausa”, comprueba el espacio y ofrece hacerla de pie o en una silla. **Ruta grupal opcional:** una persona dirige y otra confirma la señal de alto. **Ruta individual completa:** di o lee las instrucciones, modela la secuencia y usa la señal de pausa tú también. No afirmes que hubo rotación si trabajaste a solas.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"Antes de dirigir"},{"label":"Después de explicar y modelar","exercise":{"name":"Palmas y gestos dirigidos","icon":"Flag","seconds":45}},{"label":"Después de adaptar y cerrar","exercise":{"name":"Secuencia adaptable con pausa","icon":"Users","seconds":45}}]},"id":"s08-ef-2-7"},{"fase":"aplicar","areas":["ef","fc"],"cnb":["ef:4.1.12","ef:4.2.3"],"ambito":"convivir","prompt":"¿Qué harías si fueras quien organiza?","type":"dilemma","props":{"scene":{"icon":"Flag","text":"En el recreo organizan una **chamusca**. Un niño dice: \\"Las niñas no pueden jugar y tampoco pueden ser capitanas\\". **Lucía** y **Marta** querían jugar con los niños. Tú eres quien organiza hoy."},"options":[{"id":"a","icon":"EyeOff","text":"Quedarme callado para no tener problemas","consequence":"Lucía y Marta se quedan fuera. El grupo aprende que excluir \\"no pasa nada\\", y la injusticia se repite.","values":["Indiferencia"],"constructive":false},{"id":"b","icon":"Users","text":"Decir que todas y todos pueden jugar, formar equipos mixtos contando 1-2 y proponer que Lucía sea capitana de un equipo","consequence":"Se juega con equipos parejos. Lucía organiza bien a su equipo y varios compañeros se dan cuenta de que su idea era un estereotipo.","values":["Igualdad","Liderazgo","Derechos humanos"],"constructive":true},{"id":"c","icon":"MessageCircle","text":"Hablar con calma con el compañero: explicarle que la igualdad es un derecho e invitarlo a jugar en un equipo mixto","consequence":"El compañero no cambia de idea de inmediato, pero acepta jugar. Al final reconoce que el partido fue más parejo y divertido.","values":["Diálogo","Respeto","Igualdad"],"constructive":true}]},"id":"s08-ef-2-8"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3","ef:4.1.12"],"ambito":"conocer","prompt":"Aplica el liderazgo y rechaza el estereotipo: ordena una rutina donde mujeres y hombres, niñas y niños tengan igualdad de oportunidades para asumir roles y aportar habilidades complementarias.","explain":"Un liderazgo justo abre todos los roles, explica la secuencia, ofrece adaptación segura y combina aportes complementarios.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"a","text":"Abrir por igual a una niña o un niño el rol de dirigir"},{"id":"b","text":"Explicar dos pasos laterales y ofrecer gestos sentados"},{"id":"c","text":"Combinar a quien modela con quien cuida la señal de alto"},{"id":"d","text":"Dirigir dos repeticiones y cambiar los roles"}]},"id":"s08-ef-2-9"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:4.2.3"],"ambito":"hacer","prompt":"Guarda evidencia de cómo dirigiste la rutina: escribe la instrucción, la adaptación segura, tu rol y el orden usado. Indica si elegiste ruta individual o grupal.","explain":"La evidencia describe liderazgo realmente practicado en la lección, sin afirmar una rotación no observada.","type":"short-answer","props":{"minWords":22,"placeholder":"Ruta… Mi instrucción… Adaptación… Secuencia…","model":"Elegí la ruta individual. Expliqué cuatro palmas y cuatro gestos. Ofrecí hacerlos sentado, modelé la secuencia y terminé con la señal de pausa.","rubric":["Indico la ruta","Escribo una instrucción","Incluyo adaptación segura","Describo rol y secuencia"]},"id":"s08-ef-2-10"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y roles claros. Un niño afirma que solo los hombres deben dirigir. Para rechazar ese estereotipo y defender los derechos humanos, ¿qué instrucción da igualdad de oportunidades a mujeres y hombres y usa aportes complementarios?","type":"choice","props":{"options":[{"id":"a","text":"“Una niña y un niño alternan el rol de líder; una persona modela y otra cuida la señal. Cada aporte complementa al otro y se puede hacer sentado”"},{"id":"b","text":"“Los hombres lideran y las mujeres observan”"},{"id":"c","text":"“Todas hacen lo mismo, sin roles ni adaptación”"}],"correct":["a"]},"id":"s08-ef-2-11"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:4.1.12","ef:4.2.3"],"prompt":"Dirige una rutina con adaptación segura y una secuencia de roles. Ordénala para rechazar el estereotipo, proteger derechos humanos y dar igualdad de oportunidades a mujeres y hombres con participación complementaria.","type":"order","props":{"labels":{"start":"Inicio","end":"Cierre"},"items":[{"id":"e1","text":"Explicar que niñas y niños pueden asumir por igual cualquier rol"},{"id":"e2","text":"Asignar a una mujer el modelado y a un hombre la señal, con cambio posterior de roles"},{"id":"e3","text":"Ofrecer movimiento de pie o sentado para complementar capacidades"},{"id":"e4","text":"Dirigir dos repeticiones y cerrar con una señal segura"}]},"id":"s08-ef-2-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:4.2.3"],"type":"reflection","props":{"statements":["Juego y valoro juegos tradicionales de mi comunidad","Lidero un juego explicando reglas y formando equipos justos","Defiendo que todas y todos tengan las mismas oportunidades de jugar"],"commitments":["Enseñaré un juego tradicional a alguien más pequeño","Me ofreceré a ser líder o árbitro en el recreo","Invitaré a jugar a quien se queda fuera"]},"id":"s08-ef-2-13"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s08","version":"cnb-sexto-b73012a3aced6550","lesson":{"id":"s08-mat-3","title":"Convertir del sistema decimal al maya","icon":"ArrowRightLeft","minutes":15,"gancho":"Si el segundo nivel vale ×20, ¿cuánto vale el tercero? ¿Y el quinto? Con cinco niveles los mayas podían escribir números de más de tres millones.","objetivos":["Conocer el valor de los niveles del sistema vigesimal: ×1, ×20, ×400, ×8,000 y ×160,000"],"resumen":["Cada nivel vale 20 veces el de abajo: ×1, ×20, ×400, ×8,000 y ×160,000.","Para convertir: divide entre el valor del nivel más alto que quepa; el cociente va en ese nivel y el residuo se reparte en los niveles de abajo.","Si un nivel queda vacío, se escribe un caracol: 1,000 = 2 | 10 | 0.","Comprueba siempre multiplicando cada nivel por su valor y sumando."],"media":{"id":"s08-mat-3-niveles","kind":"animation","title":"Subiendo de nivel","aspect":"9:16","duration":45,"alt":"Una torre de cinco casillas que se llena de abajo hacia arriba; cada casilla muestra su valor: 1, 20, 400, 8,000 y 160,000.","brief":"Animación vertical 2D de 45 s. Una torre de 5 casillas apiladas se construye de abajo hacia arriba. En la primera caen granos de maíz uno por uno hasta 19; al caer el 20, los granos se juntan y \\"suben\\" como un solo punto al segundo nivel (rótulo ×20), y abajo aparece un caracol. Se repite más rápido: 20 puntos del segundo nivel suben a un punto del tercero (×400); luego ×8,000 y ×160,000. Al final se muestran los cinco valores. Narración en español: \\"cada nivel vale veinte veces el de abajo\\". Target: public/media/s08-mat-3-niveles.mp4. Accesibilidad: subtítulos completos, transcripción y pausa suficiente para lectura."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"conocer","title":"Un sistema vigesimal","prompt":"Mira la torre: cada nivel maya vale **20 veces** el nivel inferior.","type":"explain","props":{"icon":"Layers","body":"Los primeros valores son ×1, ×20 y ×400. El tercero vale 20 × 20 = **400**."},"id":"s08-mat-3-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"conocer","title":"El valor de los cinco niveles","prompt":"Cada nivel vale **20 veces** el de abajo. Toca cada tarjeta.","type":"explain","props":{"icon":"Layers","body":"De abajo hacia arriba: **×1 · ×20 · ×400 · ×8,000 · ×160,000**.","reveal":[{"icon":"Layers","front":"1.º y 2.º nivel","back":"×1 y ×20."},{"icon":"Layers","front":"3.er nivel","back":"20 × 20 = **400**."},{"icon":"Layers","front":"4.º y 5.º nivel","back":"400 × 20 = **8,000**; 8,000 × 20 = **160,000**."},{"icon":"CalendarDays","front":"Un dato","back":"Para contar objetos se usan estos valores. En el calendario de la Cuenta Larga, el tercer nivel valía 360 (18 × 20, un número cercano a los días de un año), pero esa es otra forma de contar. En esta lección usamos siempre 400."}]},"id":"s08-mat-3-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"hacer","title":"Ejemplo resuelto: 845","prompt":"Para convertir, empieza por el nivel **más alto que quepa** en el número.","media":{"id":"s08-mat-3-torre","kind":"diagram","title":"Cómo convertir 845 a numeral maya","aspect":"3:4","alt":"Columna con tres niveles: arriba dos puntos (2 × 400), en medio dos puntos (2 × 20) y abajo una barra (5 × 1); a la par, las divisiones.","brief":"Diagrama vertical con tres casillas apiladas. Casilla superior: dos puntos, rotulada \\"×400 → 800\\". Casilla media: dos puntos, rotulada \\"×20 → 40\\". Casilla inferior: una barra, rotulada \\"×1 → 5\\". A la derecha, los pasos: \\"845 ÷ 400 = 2, sobran 45\\"; \\"45 ÷ 20 = 2, sobran 5\\". Abajo, la comprobación \\"800 + 40 + 5 = 845\\". Puntos y barras color café maíz, caracol blanco con contorno. Fondo crema. Target: public/media/s08-mat-3-torre.svg. Accesibilidad: formato final 1600×900 px, contraste alto y descripción alternativa equivalente."},"type":"worked-example","props":{"icon":"Calculator","problem":"Convierte **845** a numeral maya.","steps":[{"text":"¿Cabe 8,000 en 845? No. El nivel más alto que cabe es el de **400**."},{"text":"845 ÷ 400 = **2**, sobran 45. → Tercer nivel: 2 (dos puntos).","why":"2 × 400 = 800; 845 − 800 = 45."},{"text":"45 ÷ 20 = **2**, sobran 5. → Segundo nivel: 2 (dos puntos)."},{"text":"Lo que sobra, **5**, va en el primer nivel (una barra)."},{"text":"Compruebo: 2 × 400 + 2 × 20 + 5 = 800 + 40 + 5 = 845 ✔"}],"answer":"845 = **2 | 2 | 5** (de arriba hacia abajo)."},"id":"s08-mat-3-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"hacer","prompt":"Convierte **523** a numeral maya.","hint":"523 ÷ 400 = 1, sobran 123. Luego 123 ÷ 20 = 6, sobran 3.","explain":"1 × 400 + 6 × 20 + 3 = 400 + 120 + 3 = 523. Niveles: 1 | 6 | 3.","type":"maya-number","props":{"mode":"build","target":523,"levels":3,"scaffold":true},"id":"s08-mat-3-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"hacer","title":"Ejemplo resuelto: un nivel con cero","prompt":"A veces un nivel queda vacío. Ahí va el caracol.","type":"worked-example","props":{"icon":"Shell","problem":"Convierte **1,000** a numeral maya.","steps":[{"text":"1,000 ÷ 400 = **2**, sobran 200. → Tercer nivel: 2."},{"text":"200 ÷ 20 = **10**, sobra 0. → Segundo nivel: 10 (dos barras)."},{"text":"Primer nivel: **0** → caracol.","why":"Sin el caracol, el numeral se leería como otro número."},{"text":"Compruebo: 800 + 200 + 0 = 1,000 ✔"}],"answer":"1,000 = **2 | 10 | 0**.","tip":"Otra forma: divide entre 20 una y otra vez. 1,000 ÷ 20 = 50, residuo 0 (primer nivel); 50 ÷ 20 = 2, residuo 10 (segundo nivel); queda 2 (tercer nivel)."},"id":"s08-mat-3-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:4.1.6"],"ambito":"hacer","prompt":"El año tiene **365** días. Convierte 365 a numeral maya.","hint":"¿Cabe 400 en 365? No. Empieza con el nivel del 20: 365 ÷ 20 = 18, sobran 5.","explain":"18 × 20 + 5 = 360 + 5 = 365. Niveles: 18 | 5 (tres barras y tres puntos arriba; una barra abajo).","type":"maya-number","props":{"mode":"build","target":365,"levels":2,"scaffold":true},"id":"s08-mat-3-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Supongamos que una escuela recolectó **2,030** botellas para reciclar. Escribe la cantidad con numeral maya.","explain":"2,030 ÷ 400 = 5, sobran 30; 30 ÷ 20 = 1, sobran 10. Niveles: 5 | 1 | 10. Compruebo: 2,000 + 20 + 10 = 2,030.","type":"maya-number","props":{"mode":"build","target":2030,"levels":3},"id":"s08-mat-3-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Un numeral tiene **cuatro niveles**. De arriba hacia abajo: **un punto** (×8,000), **tres puntos** (×400), **caracol** (×20) y **una barra y dos puntos** (×1). ¿Qué número es?","explain":"1 × 8,000 + 3 × 400 + 0 × 20 + 7 = 8,000 + 1,200 + 0 + 7 = 9,207.","type":"number-input","props":{"answer":9207,"misconceptions":[{"value":1207,"msg":"El punto del cuarto nivel vale 8,000, no 0. Revisa: ×1, ×20, ×400, ×8,000."},{"value":11,"msg":"Sumaste los símbolos sin multiplicar por el valor de cada nivel."}]},"id":"s08-mat-3-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Convierte **10,000** a numeral maya. Necesitarás cuatro niveles.","explain":"10,000 ÷ 8,000 = 1, sobran 2,000; 2,000 ÷ 400 = 5, sobra 0; los niveles del 20 y del 1 quedan en cero. Niveles: 1 | 5 | 0 | 0.","type":"maya-number","props":{"mode":"build","target":10000,"levels":4},"id":"s08-mat-3-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"Convierte **1,500** a numeral maya.","type":"maya-number","props":{"mode":"build","target":1500,"levels":3},"id":"s08-mat-3-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:4.1.6"],"prompt":"¿Qué niveles (de arriba hacia abajo) representan **850**?","type":"choice","props":{"options":[{"id":"a","text":"2 | 5 | 0"},{"id":"b","text":"2 | 2 | 10"},{"id":"c","text":"8 | 5 | 0"}],"correct":["b"]},"id":"s08-mat-3-11"}],"kind":"materia","area":"mat","day":3}}]`),o={mission:e,lessons:a};export{o as default,a as lessons,e as mission};
